function renderNoteImages(images) {
    const container = document.getElementById('note-images-container');
    container.innerHTML = '';
    images.forEach((imgObj, index) => {
        const src = typeof imgObj === 'string' ? imgObj : imgObj.src;
        const isStarred = typeof imgObj === 'object' && imgObj.starred;

        const wrap = document.createElement('div');
        wrap.classList.add('note-image-thumb-wrap');
        wrap.innerHTML = `
            <img src="${src}" class="note-image-thumb">
            <span class="star-chip" title="Star as Polaroid image"><i class="ph ${isStarred ? 'ph-star-fill' : 'ph-star'}"></i></span>
            <span class="delete-chip"><i class="ph ph-x"></i></span>
        `;
        wrap.querySelector('.note-image-thumb').addEventListener('click', () => openLightboxImage(src));
        wrap.querySelector('.star-chip').addEventListener('click', (e) => {
            e.stopPropagation();
            toggleStarImage(index);
        });
        wrap.querySelector('.delete-chip').addEventListener('click', (e) => {
            e.stopPropagation();
            removeNoteImage(index);
        });
        container.appendChild(wrap);
    });
}

function toggleStarImage(index) {
    if (!currentDay || !db.days[currentDay].noteImages) return;
    db.days[currentDay].noteImages = db.days[currentDay].noteImages.map((img, idx) => {
        const src = typeof img === 'string' ? img : img.src;
        return { src, starred: idx === index ? !(typeof img === 'object' && img.starred) : false };
    });
    renderNoteImages(db.days[currentDay].noteImages);
    scheduleSaveDay();
}
function addNoteImages(files) {
    if (!currentDay || !files || files.length === 0) return;
    if (!db.days[currentDay].noteImages) db.days[currentDay].noteImages = [];

    [...files].forEach(file => {
        if (!file.type || !file.type.startsWith('image/')) return;
        const reader = new FileReader();
        reader.onload = (e) => {
            db.days[currentDay].noteImages.push(e.target.result);
            renderNoteImages(db.days[currentDay].noteImages);
            scheduleSaveDay();
        };
        reader.readAsDataURL(file);
    });
}

function removeNoteImage(index) {
    if (!currentDay || !db.days[currentDay].noteImages) return;
    db.days[currentDay].noteImages.splice(index, 1);
    renderNoteImages(db.days[currentDay].noteImages);
    scheduleSaveDay();
}

