function extractYoutubeId(url) {
    if (!url) return null;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|shorts\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
}

// ==================== Text-to-Speech (Audio fields) ====================
// Escapes text for safe use inside an HTML attribute (e.g. data-tts-text="...").
function escapeHtmlAttr(str) {
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}

let ttsAudioEl = null;
function playTTSAudio(text, lang) {
    if (!text) return;
    if (ttsAudioEl) { ttsAudioEl.pause(); ttsAudioEl = null; }
    const url = `/api/tts?text=${encodeURIComponent(text)}&lang=${encodeURIComponent(lang || db.settings.ttsLang || 'ko')}`;
    ttsAudioEl = new Audio(url);
    ttsAudioEl.play().catch(err => console.error('TTS playback failed:', err));
}
window.playTTSAudio = playTTSAudio;

// Attaches click handlers to any TTS speaker buttons rendered into `root`
// (both the full-size quiz-card ones and the small inline chip/card ones).
function attachAudioPlayButtons(root) {
    if (!root) return;
    root.querySelectorAll('.audio-play-btn, .chip-audio-btn').forEach(btn => {
        if (btn.dataset.ttsBound) return;
        btn.dataset.ttsBound = '1';
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            playTTSAudio(btn.dataset.ttsText, btn.dataset.ttsLang);
        });
    });
}

// Returns the name of the first custom field configured as an "Audio" field, or null.
function getCategoryConfig(categoryName) {
    if (!db.settings.categorySettings || !db.settings.categorySettings[categoryName]) {
        return { fields: [] };
    }
    return db.settings.categorySettings[categoryName];
}

function getItemCategory(itemId) {
    const meta = db.phrase_meta[itemId];
    return meta ? meta.type : db.settings.categories[0];
}

function getAudioFieldName(categoryName) {
    const config = getCategoryConfig(categoryName);
    return (config.fields || []).find(f => f.toLowerCase().includes('audio')) || null;
}

function hasAudioFieldEnabled(categoryName) {
    const config = getCategoryConfig(categoryName);
    return config.enableAudio && !!getAudioFieldName(categoryName);
}

function getItemAudioText(itemId) {
    const cat = getItemCategory(itemId);
    const config = getCategoryConfig(cat);
    const meta = db.phrase_meta[itemId];
    const audioField = getAudioFieldName(cat);
    if (meta && audioField && meta.custom_fields && meta.custom_fields[audioField] && meta.custom_fields[audioField].trim()) {
        return meta.custom_fields[audioField].trim();
    }
    return itemId;
}

// Whether this log has an Audio field configured at all (gates whether we show
// speaker icons on chips/cards throughout the app).
function hasAudioFieldEnabled() {
    return !!getAudioFieldName();
}

// The text that should be spoken for a given item: its Audio field's value if
// set, otherwise falls back to the item's own name.
function getItemAudioText(itemId) {
    const meta = db.phrase_meta[itemId];
    const audioField = getAudioFieldName();
    if (meta && audioField && meta.custom_fields && meta.custom_fields[audioField] && meta.custom_fields[audioField].trim()) {
        return meta.custom_fields[audioField].trim();
    }
    return itemId;
}

// Builds a small inline speaker button (for chips/cards) that plays an item's pronunciation.
function buildItemAudioButtonHtml(itemId) {
    const text = getItemAudioText(itemId);
    return `<span class="chip-audio-btn audio-play-btn-sm" data-tts-text="${escapeHtmlAttr(text)}" data-tts-lang="${escapeHtmlAttr(db.settings.ttsLang || 'ko')}" title="Play pronunciation"><i class="ph ph-speaker-high"></i></span>`;
}

function extractYoutubeStart(url) {
    if (!url) return 0;
    let match = url.match(/[?&](?:t|start)=([^&#]+)/);
    if (!match) return 0;
    const raw = decodeURIComponent(match[1]);
    if (/^\d+$/.test(raw)) return parseInt(raw, 10);
    const timeMatch = raw.match(/^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/);
    if (timeMatch && (timeMatch[1] || timeMatch[2] || timeMatch[3])) {
        const h = parseInt(timeMatch[1] || '0', 10);
        const m = parseInt(timeMatch[2] || '0', 10);
        const s = parseInt(timeMatch[3] || '0', 10);
        return h * 3600 + m * 60 + s;
    }
    return 0;
}

function renderVideoSlot(url, containerEl, slotKey, baseClass) {
    if (!url) {
        containerEl.innerHTML = '';
        containerEl.className = 'hidden';
        if (currentDay) { db.days[currentDay][slotKey] = ''; scheduleSaveDay(); }
        return;
    }
    const videoId = extractYoutubeId(url);
    if (videoId) {
        containerEl.className = baseClass;
        const startSec = extractYoutubeStart(url);
        const startParam = startSec > 0 ? `&start=${startSec}` : '';
        containerEl.innerHTML = `<iframe src="https://www.youtube.com/embed/${videoId}?enablejsapi=0${startParam}" allowfullscreen></iframe>`;
        if (currentDay) { db.days[currentDay][slotKey] = url; scheduleSaveDay(); }
    } else {
        alert("Invalid YouTube URL");
    }
}

