function getDailyResourceDisplayTitle(resource, index = 0) {
    if (!resource) return `Resource ${index + 1}`;
    if (String(resource.title || '').trim()) return String(resource.title).trim();
    if (resource.type === 'yt') return 'YouTube';
    if (resource.type === 'tiktok') return 'TikTok';
    try {
        const url = new URL(resource.url || '');
        return url.hostname.replace(/^www\./, '') || `Resource ${index + 1}`;
    } catch (error) {
        return `Resource ${index + 1}`;
    }
}

function getDailyResourceDomain(resource) {
    try {
        return new URL(resource?.url || '').hostname.replace(/^www\./, '');
    } catch (error) {
        return String(resource?.url || '');
    }
}

function highlightDailyResource(index) {
    const target = document.getElementById(`daily-resource-${index}`);
    if (!target) return;
    target.scrollIntoView({ behavior: 'smooth', block: 'center' });
    target.classList.add('daily-resource-highlight');
    setTimeout(() => target.classList.remove('daily-resource-highlight'), 2400);
}

function renderResources(dayData) {
    const grid = document.getElementById('resources-grid');
    if (!grid) return;
    grid.innerHTML = '';
    const resources = dayData.resources || [];

    resources.forEach((res, idx) => {
        const card = document.createElement('div');
        card.classList.add('resource-card', res.type || 'link');
        card.id = `daily-resource-${idx}`;
        card.dataset.resourceIndex = String(idx);

        if (res.type === 'yt') {
            const startParam = res.start > 0 ? `&start=${res.start}` : '';
            card.innerHTML = `
                <iframe src="https://www.youtube.com/embed/${res.id}?controls=1${startParam}" allow="encrypted-media" allowfullscreen></iframe>
                <span class="resource-card-label">YouTube</span>
                <div class="resource-card-controls"><button class="resource-card-btn" data-action="delete" title="Remove"><i class="ph ph-trash"></i></button></div>`;
        } else if (res.type === 'tiktok') {
            card.innerHTML = `
                <iframe src="https://www.tiktok.com/embed/v2/${res.id}" allow="encrypted-media" allowfullscreen></iframe>
                <span class="resource-card-label">TikTok</span>
                <div class="resource-card-controls"><button class="resource-card-btn" data-action="delete" title="Remove"><i class="ph ph-trash"></i></button></div>`;
        } else {
            const title = getDailyResourceDisplayTitle(res, idx);
            const domain = getDailyResourceDomain(res);
            card.innerHTML = `
                <a class="daily-generic-resource-card" href="${escapeCustomHtml(res.url || '#')}" target="_blank" rel="noopener noreferrer" title="Open ${escapeCustomHtml(title)}">
                    <span class="daily-generic-resource-icon"><i class="ph ph-newspaper-clipping"></i></span>
                    <span class="daily-generic-resource-copy"><strong>${escapeCustomHtml(title)}</strong><small>${escapeCustomHtml(domain)}</small></span>
                    <i class="ph ph-arrow-square-out daily-generic-resource-open"></i>
                </a>
                <div class="resource-card-controls"><button class="resource-card-btn" data-action="delete" title="Remove"><i class="ph ph-trash"></i></button></div>`;
        }

        card.querySelector('[data-action="delete"]')?.addEventListener('click', () => {
            dayData.resources.splice(idx, 1);
            renderResources(dayData);
            scheduleSaveDay();
        });
        grid.appendChild(card);
    });
    requestAnimationFrame(syncNotesHeight);
}

async function addDailyResourceFromUrl(url) {
    if (!url || !currentDay) return false;
    if (!db.days[currentDay].resources) db.days[currentDay].resources = [];
    const ytId = extractYoutubeId(url);

    if (ytId) {
        db.days[currentDay].resources.push({ url, type: 'yt', id: ytId, start: extractYoutubeStart(url) });
    } else if (url.includes('tiktok.com')) {
        const match = url.match(/tiktok\.com\/.*\/video\/(\d+)/);
        if (match) db.days[currentDay].resources.push({ url, type: 'tiktok', id: match[1] });
        else db.days[currentDay].resources.push({ url, type: 'link', title: getDailyResourceDomain({ url }) });
    } else {
        let suggestedTitle = '';
        try { suggestedTitle = new URL(url).hostname.replace(/^www\./, ''); } catch (error) {}
        const values = await showAppFormModal({
            title: 'Add Media Resource',
            submitLabel: 'Add Resource',
            fields: [
                { name: 'title', label: 'Name', value: suggestedTitle, placeholder: 'Article, website, reference…' },
                { name: 'url', label: 'Link', type: 'url', value: url }
            ]
        });
        if (!values) return false;
        const finalUrl = String(values.url || url).trim();
        if (!finalUrl) return false;
        db.days[currentDay].resources.push({
            url: finalUrl,
            type: 'link',
            title: String(values.title || '').trim() || getDailyResourceDomain({ url: finalUrl })
        });
    }

    renderResources(db.days[currentDay]);
    scheduleSaveDay();
    return true;
}

