// ==================== QUIZ ENGINE ====================
let quizMode = 'anki';
let selectedQuizDays = new Set();
let selectedQuizTypes = new Set(['all']);
let activeQuizDeck = [];
let activeQuizIndex = 0;
let quizCardFlipped = false;
let learnQueue = []; // Queue for Quizlet Learn mode

document.querySelectorAll('.quiz-mode-btn').forEach(btn => {
    btn.addEventListener('click', () => {
        document.querySelectorAll('.quiz-mode-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        quizMode = btn.dataset.mode;
        
        document.getElementById('quiz-day-picker-section').classList.toggle('hidden', quizMode === 'anki');
        document.getElementById('anki-summary-box').classList.toggle('hidden', quizMode !== 'anki');
        
        if (quizMode !== 'anki' && selectedQuizDays.size === 0) renderQuizDayPicker();
        updateAvailableQuizTypes();
    });
});

function dayHasQuizItems(dayNumber) {
    const dayData = db.days[dayNumber];
    return dayData && dayData.phrases && dayData.phrases.length > 0;
}

function renderQuizDayPicker() {
    selectedQuizDays.clear();
    const grid = document.getElementById('quiz-day-grid');
    grid.innerHTML = '';
    const maxDay = Math.max(TOTAL_CURRICULUM_DAYS, ...Object.keys(db.days).map(Number).filter(n => !isNaN(n)), 0);
    
    for (let i = 1; i <= maxDay; i++) {
        const hasData = dayHasQuizItems(i);
        const box = document.createElement('div');
        box.classList.add('day-picker-box');
        box.innerText = i;
        
        if (!hasData) {
            box.classList.add('no-data');
        }

        box.addEventListener('click', () => {
            playClickSound();
            if (selectedQuizDays.has(i)) {
                selectedQuizDays.delete(i);
                box.classList.remove('selected');
            } else {
                selectedQuizDays.add(i);
                box.classList.add('selected');
            }
            updateAvailableQuizTypes();
        });
        
        grid.appendChild(box);
    }
}

// ---------------- Anki Algorithm ----------------
function processAnkiAnswer(rating) {
    const id = activeQuizDeck[activeQuizIndex];
    if (!db.srs) db.srs = {};
    const today = new Date().toISOString().slice(0, 10);
    
    let state = db.srs[id] || { status: 'New', step_index: 0, interval: 0, ease_factor: 2.5 };
    if (state.status === 'New') state.status = 'Learning';

    if (state.status === 'Learning') {
        if (rating === 'Again') {
            state.step_index = 0;
        } else if (rating === 'Hard') {
            // Keep step index same
        } else if (rating === 'Good') {
            state.step_index += 1;
            if (state.step_index >= 2) {
                state.status = 'Review';
                state.interval = 1;
            }
        } else if (rating === 'Easy') {
            state.status = 'Review';
            state.interval = 4;
        }
    } else if (state.status === 'Review') {
        if (rating === 'Again') {
            state.status = 'Learning';
            state.step_index = 0;
            state.ease_factor = Math.max(1.3, state.ease_factor - 0.20);
        } else if (rating === 'Hard') {
            state.interval = Math.max(1, Math.round(state.interval * 1.2));
            state.ease_factor = Math.max(1.3, state.ease_factor - 0.15);
        } else if (rating === 'Good') {
            state.interval = Math.max(1, Math.round(state.interval * state.ease_factor));
        } else if (rating === 'Easy') {
            state.interval = Math.max(1, Math.round(state.interval * state.ease_factor * 1.3));
            state.ease_factor = Math.max(1.3, state.ease_factor + 0.15);
        }
    }

    const d = new Date();
    if (state.status === 'Review') d.setDate(d.getDate() + state.interval);
    state.due = d.toISOString().slice(0, 10);
    
    db.srs[id] = state;
    saveDb();

    activeQuizIndex++;
    quizCardFlipped = false;
    showQuizCard();
}

function getDueSrsItems() {
    const today = new Date().toISOString().slice(0, 10);
    const loggedIds = new Set();
    Object.values(db.days).forEach(d => { if (d && d.phrases) d.phrases.forEach(id => loggedIds.add(id)); });
    return db.phrases.filter(id => loggedIds.has(id)).filter(item => {
        const state = db.srs[item];
        return !state || state.due <= today;
    });
}

function updateQuizUI() {
    renderQuizDayPicker();
    updateAvailableQuizTypes();
}

function updateAvailableQuizTypes() {
    const container = document.getElementById('quiz-type-filters');
    container.innerHTML = '';

    let availableItems = [];
    if (quizMode === 'anki') {
        availableItems = getDueSrsItems();

        // V57: today's newly due cards and older rollover cards are
        // shown separately, while both remain in the same review deck.
        const todayV57 = new Date().toISOString().slice(0, 10);
        const overdueCountV57 = availableItems.filter(id => {
            const due = db.srs?.[id]?.due;
            return !!due && due < todayV57;
        }).length;
        const dueTodayCountV57 = availableItems.length - overdueCountV57;

        const ankiSummaryV57 = document.getElementById('anki-summary-detail');
        if (ankiSummaryV57) {
            ankiSummaryV57.innerHTML = availableItems.length === 0
                ? "Nothing due right now!"
                : `<span class="anki-due-today-v57">${dueTodayCountV57} due today</span><span class="anki-summary-separator-v57"> · </span><span class="anki-overdue-v57">${overdueCountV57} overdue</span>`;
        }
    } else {
        const ids = new Set();
        selectedQuizDays.forEach(d => {
            if (db.days[d] && db.days[d].phrases) db.days[d].phrases.forEach(id => ids.add(id));
        });
        availableItems = [...ids];
    }

    availableItems = availableItems.filter(id =>
        !db.phrase_meta?.[id]?.hideFromQuizzesV59
    );

    const typeCounts = { 'all': availableItems.length };
    db.settings.categories.forEach(c => typeCounts[c] = 0);
    
    availableItems.forEach(id => {
        const meta = db.phrase_meta[id];
        if (meta && typeCounts[meta.type] !== undefined) typeCounts[meta.type]++;
    });

    ['all', ...db.settings.categories].forEach(cat => {
        const count = typeCounts[cat] || 0;
        const btn = document.createElement('button');
        btn.className = 'filter-tab';
        btn.innerText = `${cat === 'all' ? 'All Categories' : cat} (${count})`;
        
        if (count === 0) btn.classList.add('disabled');
        else {
            if (selectedQuizTypes.has(cat)) btn.classList.add('active');
            btn.addEventListener('click', () => {
                if (cat === 'all') {
                    selectedQuizTypes.clear();
                    selectedQuizTypes.add('all');
                } else {
                    selectedQuizTypes.delete('all');
                    if (selectedQuizTypes.has(cat)) {
                        selectedQuizTypes.delete(cat);
                        if (selectedQuizTypes.size === 0) selectedQuizTypes.add('all');
                    } else {
                        selectedQuizTypes.add(cat);
                    }
                }
                updateAvailableQuizTypes();
            });
        }
        container.appendChild(btn);
    });

    document.getElementById('start-quiz-btn').disabled = availableItems.length === 0;
    document.getElementById('start-quiz-btn').classList.toggle('disabled-btn', availableItems.length === 0);
}

document.getElementById('start-quiz-btn').addEventListener('click', () => {
    playClickSound();
    if (quizMode !== 'anki' && selectedQuizDays.size === 0) return alert('Pick at least one day.');

    let rawItems = quizMode === 'anki' ? getDueSrsItems() : [];
    if (quizMode !== 'anki') {
        const ids = new Set();
        selectedQuizDays.forEach(d => { if (db.days[d] && db.days[d].phrases) db.days[d].phrases.forEach(id => ids.add(id)); });
        rawItems = [...ids];
    }

    const filtered = rawItems.filter(id => {
        if (db.phrase_meta?.[id]?.hideFromQuizzesV59) return false;
        if (selectedQuizTypes.has('all')) return true;
        return selectedQuizTypes.has(db.phrase_meta[id]?.type);
    });

    if (filtered.length === 0) return alert("No items match filters.");

    activeQuizDeck = filtered.sort(() => Math.random() - 0.5);
    activeQuizIndex = 0;
    quizCardFlipped = false;
    
    // Initialize Learn Mode Queue
    if (quizMode === 'learn') {
        learnQueue = activeQuizDeck.map(id => ({ id, streak: 0 }));
    }

    document.getElementById('quiz-learn-title').innerText = quizMode.toUpperCase() + ' MODE';
    showQuizCard();
    switchView(quizLearnView);
});

// ---------------- Quizlet Learn Algorithm ----------------
// ---------------- Quizlet Learn Algorithm ----------------
let currentSlideIndex = 0;

function processLearnAnswer(isCorrect) {
    let current = learnQueue[0];
    if (isCorrect) {
        current.streak++;
        if (current.streak >= 2) {
            learnQueue.shift(); 
            activeQuizIndex++;
        } else {
            learnQueue.push(learnQueue.shift());
        }
    } else {
        current.streak = 0;
        let item = learnQueue.shift();
        learnQueue.splice(Math.min(2, learnQueue.length), 0, item);
    }
    quizCardFlipped = false;
    currentSlideIndex = 0;
    showQuizCard();
}

let currentCardSlideCount = 1;

function renderCardBackContent(meta) {
    const cat = meta.type || db.settings.categories[0];
    const config = getCategoryConfig(cat);
    const qFields = config.quizFields || config.fields || [];

    let slides = [];

    qFields.forEach(field => {
        const val = meta.custom_fields[field];
        if (!val) return;

        const lowerField = field.toLowerCase();
        const isVideo = lowerField.includes('video') || val.includes('youtube.com') || val.includes('youtu.be') || val.endsWith('.mp4');
        const isAudio = !isVideo && lowerField.includes('audio');

        if (isVideo) {
            const ytId = extractYoutubeId(val);
            if (ytId) {
                const startSec = extractYoutubeStart(val);
                const startParam = startSec > 0 ? `&start=${startSec}` : '';
                slides.push(`<div class="quiz-media-fullscreen"><iframe src="https://www.youtube.com/embed/${ytId}?autoplay=1${startParam}" allow="autoplay; encrypted-media" allowfullscreen></iframe></div>`);
            } else {
                slides.push(`<div class="quiz-media-fullscreen"><video src="${val}" autoplay controls playsinline></video></div>`);
            }
        } else if (isAudio) {
            const lang = escapeHtmlAttr(config.ttsLang || 'ko');
            slides.push(`
                <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; height:100%; gap:24px; padding:25px; text-align:center;">
                    <span style="font-size:2.6rem;">${val}</span>
                    <button class="audio-play-btn" data-tts-text="${escapeHtmlAttr(val)}" data-tts-lang="${lang}" title="Play pronunciation">
                        <i class="ph ph-speaker-high"></i>
                    </button>
                </div>`);
        } else {
            slides.push(`<div style="display:flex; align-items:center; justify-content:center; height:100%; font-size:1.8rem; padding:25px; text-align:center; overflow-y:auto;">${val}</div>`);
        }
    });

    if (slides.length === 0) {
        currentCardSlideCount = 1;
        return `<span style="font-size:1.8rem; color:#999;">(No back content configured for category "${cat}")</span>`;
    }

    currentCardSlideCount = slides.length;
    if (currentSlideIndex < 0) currentSlideIndex = slides.length - 1;
    if (currentSlideIndex >= slides.length) currentSlideIndex = 0;

    const dots = slides.length > 1
        ? `<div class="card-dots-row">${slides.map((_, i) =>
            `<span class="card-dot ${i === currentSlideIndex ? 'active' : ''}" onclick="event.stopPropagation(); switchSlide(${i})"></span>`
          ).join('')}</div>`
        : '';

    const arrows = slides.length > 1 ? `
        <button class="card-slide-arrow card-slide-prev" onclick="event.stopPropagation(); stepSlide(-1)"><i class="ph ph-caret-left"></i></button>
        <button class="card-slide-arrow card-slide-next" onclick="event.stopPropagation(); stepSlide(1)"><i class="ph ph-caret-right"></i></button>
    ` : '';

    return `
        <div class="card-slide-container">
            <div class="card-slider-wrapper">
                ${arrows}
                ${slides[currentSlideIndex]}
            </div>
            ${dots ? `<div class="card-footer-nav">${dots}</div>` : ''}
        </div>`;
}
window.switchSlide = function(idx) {
    currentSlideIndex = idx;
    showQuizCard();
}

window.stepSlide = function(delta) {
    currentSlideIndex += delta;
    if (currentSlideIndex < 0) currentSlideIndex = currentCardSlideCount - 1;
    if (currentSlideIndex >= currentCardSlideCount) currentSlideIndex = 0;
    showQuizCard();
}

// Inside openItemModal and add-phrase-library-btn handlers, replace field generation loops with:
function buildDynamicFieldsHtmlForCategory(catName, currentValues = {}) {
    const config = getCategoryConfig(catName);
    let html = '';
    config.fields.forEach(field => {
        const val = currentValues[field] || '';
        const isNote = field.toLowerCase().includes('note');
        const isAudio = field.toLowerCase().includes('audio');
        html += `
            <div class="modal-section mt-10">
                <span class="field-label">${field}</span>
                <div style="display:flex; gap:8px; align-items:${isNote ? 'flex-start' : 'center'};">
                    ${isNote ? `<textarea class="dynamic-edit-field" data-key="${field}" placeholder="${field}..." style="flex-grow:1;">${val}</textarea>`
                             : `<input type="text" class="dynamic-edit-field" data-key="${field}" value="${val}" placeholder="${field}..." style="flex-grow:1;">`}
                    ${isAudio ? `<button type="button" class="small-icon-btn audio-preview-btn" data-key="${field}" title="Preview pronunciation" style="flex-shrink:0; ${val.trim() ? '' : 'visibility:hidden;'}"><i class="ph ph-speaker-high"></i></button>` : ''}
                </div>
            </div>`;
    });
    return html;
}

function showQuizCard() {
    const area = document.getElementById('quiz-flashcard-area');
    
    if (quizMode === 'learn' && learnQueue.length === 0) {
        document.getElementById('quiz-set-label').innerText = `${activeQuizDeck.length} / ${activeQuizDeck.length}`;
        return showFinishScreen(area);
    } else if (quizMode !== 'learn' && activeQuizIndex >= activeQuizDeck.length) {
        document.getElementById('quiz-set-label').innerText = `${activeQuizDeck.length} / ${activeQuizDeck.length}`;
        return showFinishScreen(area);
    }

    const id = quizMode === 'learn' ? learnQueue[0].id : activeQuizDeck[activeQuizIndex];
    const meta = db.phrase_meta[id] || { custom_fields: {} };

    if (quizMode === 'flashcards' || quizMode === 'learn') {
        document.getElementById('quiz-set-label').innerText = `${activeQuizIndex + 1} / ${activeQuizDeck.length}`;
        
        if (quizMode === 'learn') {
            const backVals = Object.values(meta.custom_fields).filter(v => v && !v.includes('youtu') && !v.endsWith('.mp4'));
            const promptText = backVals.length > 0 ? backVals[0] : id;
            
            const options = [id];
            while (options.length < 4 && options.length < db.phrases.length) {
                const r = db.phrases[Math.floor(Math.random() * db.phrases.length)];
                if (!options.includes(r)) options.push(r);
            }
            options.sort(() => Math.random() - 0.5);

            area.innerHTML = `
                <div class="flashcard-wrap quiz-learn-compact-v38">
                    <div class="flashcard-mode-card quiz-learn-prompt-card-v38">${promptText}</div>
                    <div class="quiz-learn-options-v38">
                        ${options.map(opt => `<button class="icon-btn" onclick="processLearnAnswer('${opt}' === '${id}')">${opt}</button>`).join('')}
                    </div>
                </div>`;
            return;
        }

        // Standard Flashcards Mode
        const cardContent = quizCardFlipped ? renderCardBackContent(meta) : `<span style="font-size: 2.8rem;">${id}</span>`;
        
        area.innerHTML = `
            <div class="flashcard-mode-wrap">
                <div class="flashcard-mode-card" id="quiz-flip-front" style="padding:${quizCardFlipped ? '0' : '20px'};">
                    ${cardContent}
                </div>
                <div class="flashcard-hint-text">Tap the card to flip it</div>
                <div class="flashcard-nav-container">
                    <button class="flashcard-nav-btn" id="fc-prev" ${activeQuizIndex === 0 ? 'disabled' : ''}><i class="ph ph-arrow-left"></i></button>
                    <button class="flashcard-nav-btn" id="fc-next"><i class="ph ph-arrow-right"></i></button>
                </div>
            </div>`;
            
        document.getElementById('quiz-flip-front').addEventListener('click', (e) => {
            if (e.target.closest('.card-dot') || e.target.closest('.card-slide-arrow') || e.target.tagName === 'VIDEO' || e.target.tagName === 'IFRAME') return;
            quizCardFlipped = !quizCardFlipped; 
            currentSlideIndex = 0;
            showQuizCard(); 
        });
        
        document.getElementById('fc-prev').addEventListener('click', () => {
            if (activeQuizIndex > 0) { activeQuizIndex--; quizCardFlipped = false; currentSlideIndex = 0; showQuizCard(); }
        });
        
        document.getElementById('fc-next').addEventListener('click', () => {
            activeQuizIndex++; quizCardFlipped = false; currentSlideIndex = 0; showQuizCard();
        });
        attachAudioPlayButtons(area);
        return;
    }

    // Anki Mode (Simplified to Still Learning / Got It)
    document.getElementById('quiz-set-label').innerText = `${activeQuizIndex + 1} / ${activeQuizDeck.length}`;
    if (!quizCardFlipped) {
        area.innerHTML = `
            <div class="flashcard-wrap">
                <div class="flashcard-mode-card" id="quiz-flip-front">
                    <span style="font-size:2.8rem;">${id}</span>
                </div>
                <div class="flashcard-hint-text">Tap the card to flip it</div>
            </div>`;
        document.getElementById('quiz-flip-front').addEventListener('click', () => { quizCardFlipped = true; currentSlideIndex = 0; showQuizCard(); });
    } else {
        const backContent = renderCardBackContent(meta);
        area.innerHTML = `
            <div class="flashcard-wrap">
                <div class="flashcard-mode-card" style="padding:0;">
                    ${backContent}
                </div>
                <div style="display:flex; gap:15px; width:100%; max-width:500px; margin-top:20px;">
                    <button class="icon-btn still-learning-btn" style="flex:1; padding:12px;" onclick="processAnkiAnswer('Again')"><i class="ph ph-arrow-counter-clockwise"></i> Still Learning</button>
                    <button class="icon-btn got-it-btn" style="flex:1; padding:12px;" onclick="processAnkiAnswer('Good')"><i class="ph ph-check"></i> Got It!</button>
                </div>
            </div>`;
    }
    attachAudioPlayButtons(area);
}

function processAnkiAnswer(rating) {
    const id = activeQuizDeck[activeQuizIndex];
    if (!db.srs) db.srs = {};
    const today = new Date().toISOString().slice(0, 10);
    
    let state = db.srs[id] || { status: 'New', step_index: 0, interval: 1, ease_factor: 2.5 };
    
    // Simplified mapping for Still Learning (Again) vs Got It (Good)
    if (rating === 'Again') {
        state.status = 'Learning';
        state.interval = 1;
    } else {
        state.status = 'Review';
        state.interval = Math.max(1, Math.round((state.interval || 1) * state.ease_factor));
    }

    const d = new Date();
    d.setDate(d.getDate() + state.interval);
    state.due = d.toISOString().slice(0, 10);
    
    db.srs[id] = state;
    saveDb();

    activeQuizIndex++;
    quizCardFlipped = false;
    currentSlideIndex = 0;
    showQuizCard();
}

function showFinishScreen(area) {
    area.innerHTML = `
        <div class="set-complete-box">
            <h2><i class="ph ph-confetti"></i> Finished!</h2>
            <button class="icon-btn mt-10" onclick="updateQuizUI(); switchView(quizzesView);">Back to Quizzes</button>
        </div>`;
}
