function updateThemePickerSelection() {
    if (!themePicker) return;
    themePicker.querySelectorAll('.theme-picker-card').forEach(card => {
        card.classList.toggle('selected', card.dataset.theme === themePickerSelected);
    });
}


// ============================================================
// THEME SEARCH
// Uses the search field that already exists in template.html.
// No second search bar is created by JavaScript.
// ============================================================
const themeSearchInput = document.getElementById('theme-search-input');
const themeSearchClear = document.getElementById('theme-search-clear');
const themeSearchEmpty = document.getElementById('theme-search-empty');

function normalizeThemeSearchText(value) {
    return String(value || '')
        .toLowerCase()
        .replace(/^theme-/, '')
        .replace(/[-_]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

function filterThemePicker(searchValue = '') {
    if (!themePicker) return;

    const query = normalizeThemeSearchText(searchValue);
    let visibleCount = 0;

    themePicker.querySelectorAll('.theme-picker-card').forEach(card => {
        const idText = normalizeThemeSearchText(card.dataset.theme);
        const nameText = normalizeThemeSearchText(card.dataset.themeName);
        const matches = !query || idText.includes(query) || nameText.includes(query);

        card.classList.toggle('theme-search-hidden', !matches);
        if (matches) visibleCount++;
    });

    if (themeSearchEmpty) {
        themeSearchEmpty.classList.toggle('hidden', visibleCount !== 0);
    }

    if (themeSearchClear) {
        themeSearchClear.classList.toggle('hidden', !String(searchValue).trim());
    }
}

if (themeSearchInput && !themeSearchInput.dataset.themeSearchBound) {
    themeSearchInput.dataset.themeSearchBound = 'true';

    function scrollCurrentLogThemeIntoView() {
        if (!themePicker) return;

        const currentTheme =
            dailyThemeSelect?.value ||
            db.settings?.theme ||
            themePickerSelected ||
            'default';

        const currentCard =
            Array.from(
                themePicker.querySelectorAll(
                    '.theme-picker-card'
                )
            ).find(
                card =>
                    card.dataset.theme ===
                    currentTheme
            ) ||
            themePicker.querySelector(
                '.theme-picker-card.selected'
            );

        requestAnimationFrame(() => {
            currentCard?.scrollIntoView({
                block: 'center',
                behavior: 'instant'
            });
        });
    }

    themeSearchInput.addEventListener('input', () => {
        const previousValue =
            themeSearchInput.dataset
                .previousThemeSearchValue ||
            '';

        const currentValue =
            themeSearchInput.value;

        filterThemePicker(
            currentValue
        );

        // If the user backspaces the search all the way to empty,
        // immediately return the gallery to the theme currently applied.
        if (
            previousValue.trim() &&
            !currentValue.trim()
        ) {
            scrollCurrentLogThemeIntoView();
        }

        themeSearchInput.dataset
            .previousThemeSearchValue =
            currentValue;
    });

    themeSearchInput.addEventListener('keydown', async event => {
        if (event.key !== 'Enter') return;

        const visibleCards = Array.from(
            themePicker?.querySelectorAll('.theme-picker-card') || []
        ).filter(card => !card.classList.contains('theme-search-hidden'));

        if (visibleCards.length !== 1) return;

        event.preventDefault();

        const onlyCard = visibleCards[0];
        const themeValue = onlyCard.dataset.theme;
        if (!themeValue) return;

        themePickerSelected = themeValue;
        updateThemePickerSelection();
        await applyTheme(themeValue);

        // If the search has narrowed the gallery to exactly one theme,
        // Enter applies it and immediately exits Daily View Settings.
        if (dailySettingsModal) {
            dailySettingsModal.classList.add('hidden');
        }

        themeSearchInput.blur();
    });
}

if (themeSearchClear && themeSearchInput && !themeSearchClear.dataset.themeSearchBound) {
    themeSearchClear.dataset.themeSearchBound = 'true';
    themeSearchClear.addEventListener('click', () => {
        themeSearchInput.value = '';
        themeSearchInput.dataset
            .previousThemeSearchValue =
            '';

        filterThemePicker('');
        scrollCurrentLogThemeIntoView();
        themeSearchInput.focus();
    });
}

function createThemePickerCard(option) {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'theme-picker-card';
    card.dataset.theme = option.value;
    card.dataset.themeName = option.textContent.trim();
    card.dataset.themeCategory = option.parentElement?.tagName === 'OPTGROUP'
        ? option.parentElement.label
        : '';

    // Known themes use curated colors. Newly discovered themes get a
    // deterministic colorful preview instead of a blank/gray card.
    let preview = THEME_PREVIEWS[option.value];

    if (!preview) {
        const seed = Array.from(option.value || option.textContent || 'theme')
            .reduce((total, ch) => total + ch.charCodeAt(0), 0);

        const hueA = seed % 360;
        const hueB = (hueA + 42 + (seed % 58)) % 360;
        const hueAccent = (hueA + 190) % 360;

        preview = [
            `hsl(${hueA} 74% 84%)`,
            `hsl(${hueB} 70% 94%)`,
            `hsl(${hueAccent} 66% 48%)`
        ];
    }
    const [a, b, accent, dark] = preview;
    if (dark) card.classList.add('theme-dark');

    card.innerHTML = `
        <div class="theme-picker-preview"
             style="background:linear-gradient(135deg,${a},${b});--preview-accent:${accent};"></div>
        <div class="theme-picker-info">
            <span class="theme-picker-name"></span>
            <span class="theme-picker-hint">Click to apply</span>
        </div>
    `;

    card.querySelector('.theme-picker-name').textContent = option.textContent.trim();

    card.addEventListener('click', async () => {
        themePickerSelected = option.value;
        updateThemePickerSelection();
        await applyTheme(option.value);
    });

    return card;
}

function renderThemePicker() {
    if (!themePicker || !dailyThemeSelect) return;

    themePicker.innerHTML = '';

    let options = Array.from(dailyThemeSelect.querySelectorAll('option'));

    const removedThemeValues = new Set([
        'theme-candy',
        'theme-forest',
        'theme-blossom',
        'theme-80s',
        'theme-rainforest'
    ]);

    options = options.filter(option => !removedThemeValues.has(option.value));

    // Display name override requested by the user.
    options.forEach(option => {
        if (option.value === 'theme-water') {
            option.textContent = 'Sky Blue';
        }
    });

    // Pull these out first so they can be inserted in exact positions.
    const specialValues = new Set([
        'theme-water',
        'theme-whimsical',
        'theme-cloud'
    ]);

    const special = {};
    options = options.filter(option => {
        if (specialValues.has(option.value)) {
            special[option.value] = option;
            return false;
        }
        return true;
    });

    // Sky Blue goes immediately after Honey Gold.
    const honeyIndex = options.findIndex(option => option.value === 'theme-honey');
    if (special['theme-water']) {
        if (honeyIndex !== -1) {
            options.splice(honeyIndex + 1, 0, special['theme-water']);
        } else {
            options.push(special['theme-water']);
        }
    }

    // Whimsical goes immediately before Cloud Nine, and Cloud Nine sits
    // immediately after Noir: Noir -> Whimsical -> Cloud Nine.
    const noirIndex = options.findIndex(option => option.value === 'theme-noir');
    const noirInsert = [];

    if (special['theme-whimsical']) noirInsert.push(special['theme-whimsical']);
    if (special['theme-cloud']) noirInsert.push(special['theme-cloud']);

    if (noirInsert.length) {
        if (noirIndex !== -1) {
            options.splice(noirIndex + 1, 0, ...noirInsert);
        } else {
            options.push(...noirInsert);
        }
    }

    options.forEach(option => {
        themePicker.appendChild(createThemePickerCard(option));
    });

    themePickerSelected = dailyThemeSelect.value || 'default';
    updateThemePickerSelection();
    filterThemePicker(themeSearchInput?.value || '');
}

async function discoverThemesForPicker() {
    if (!dailyThemeSelect) return;

    const removedThemeValues = new Set([
        'theme-candy',
        'theme-forest',
        'theme-blossom',
        'theme-80s',
        'theme-rainforest'
    ]);

    // Optional manifest. Existing options remain the source of truth if it is absent.
    try {
        const response = await fetch('/themes/themes.json', { cache: 'no-store' });
        if (response.ok) {
            const themes = await response.json();
            if (Array.isArray(themes)) {
                themes.forEach(theme => {
                    if (!theme || !theme.id) return;
                    const value = theme.id.startsWith('theme-') ? theme.id : `theme-${theme.id}`;
                    if (removedThemeValues.has(value)) return;

                    const exists = Array.from(dailyThemeSelect.options).some(o => o.value === value);
                    if (!exists) {
                        const option = document.createElement('option');
                        option.value = value;
                        option.textContent = theme.name || value.replace(/^theme-/, '').replace(/[-_]/g, ' ');
                        dailyThemeSelect.appendChild(option);
                    }
                });
            }
        }
    } catch (error) {
        // Manifest is optional. Never break the settings UI if it is missing.
        console.info('Optional themes.json not available; using built-in theme options.');
    }

renderThemePicker();
}

async function applyTheme(themeValue, opts = {}) {
    const { persist = true } = opts;

    if (themeValue === 'theme-rainforest') {
        themeValue = 'default';
    }
    db.settings.theme = themeValue;
    if (persist) saveDb();
    if (dailyThemeSelect) dailyThemeSelect.value = themeValue || 'default';

    // Unmount whatever theme's JS module (falling leaves, particles, etc.) is currently active
    if (activeThemeModule && activeThemeModule.unmount) {
        activeThemeModule.unmount();
        activeThemeModule = null;
    }

    // Only ever touch theme-* classes on <body>
    Array.from(document.body.classList)
        .filter(c => c.startsWith('theme-'))
        .forEach(c => document.body.classList.remove(c));

    const existingLink = document.getElementById('dynamic-theme-css');

    if (!themeValue || themeValue === 'default') {
        if (existingLink) existingLink.remove();
        clearCustomBuiltTheme();
        return;
    }

    if (themeValue === 'theme-custom-builder') {
        if (existingLink) existingLink.remove();
        document.body.classList.add('theme-custom-builder');
        applyCustomBuiltTheme();
        if (typeof applyCursorChoice === 'function') applyCursorChoice();
        return;
    }

    clearCustomBuiltTheme();
    document.body.classList.add(themeValue);
    const themeName = themeValue.replace('theme-', '');

    let link = existingLink;
    if (!link) {
        link = document.createElement('link');
        link.id = 'dynamic-theme-css';
        link.rel = 'stylesheet';
        document.head.appendChild(link);
    }
    link.href = `/themes/${themeName}/theme-${themeName}.css`;
    // Re-assert the chosen cursor once the theme stylesheet finishes loading, in case
    // the theme's own CSS declares a conflicting `cursor` rule with equal specificity
    // that would otherwise win the !important tie-break by loading later in <head>.
    link.addEventListener('load', () => { if (typeof applyCursorChoice === 'function') applyCursorChoice(); }, { once: true });

    try {
        const module = await import(`/themes/${themeName}/theme-${themeName}.js`);
        if (module && module.mount) {
            activeThemeModule = module;
            activeThemeModule.mount();
        }
    } catch (e) {
        console.log(`No JS module needed for ${themeName}, applying CSS only.`);
    }
}

// NOTE: Theme is applied once real data has loaded from the server (see loadData()),
// not here at top-level — calling applyTheme() before loadData() resolves would run
// against the still-default in-memory db and immediately overwrite (via saveDb())
// whatever theme the user actually had saved, wiping it on every page load/refresh.

if (dailyThemeSelect) {
    dailyThemeSelect.addEventListener('change', (e) => applyTheme(e.target.value));
}
const dailyPolaroidSourceSelect = document.getElementById('daily-polaroid-source-select');
const dailyPolaroidSourceGroup = document.getElementById('daily-polaroid-source-group');
const dailySettingsClose = document.getElementById('daily-settings-close');

if (
    dailySettingsModal &&
    !dailySettingsModal.dataset.backdropCloseBound
) {
    dailySettingsModal.dataset.backdropCloseBound =
        'true';

    dailySettingsModal.addEventListener(
        'pointerdown',
        event => {
            if (
                event.target ===
                dailySettingsModal
            ) {
                dailySettingsModal.classList.add(
                    'hidden'
                );
            }
        }
    );
}



// ============================================================
// MOVABLE MULTILINGUAL VIRTUAL KEYBOARD
// Ctrl + K toggles it from any text input / textarea / contenteditable.
// ============================================================

const VIRTUAL_KEYBOARD_LANGUAGES = {
    korean: 'Korean',
    japanese: 'Japanese',
    spanish: 'Spanish',
    french: 'French',
    german: 'German',
    portuguese: 'Portuguese',
    english: 'English'
};

let virtualKeyboardTarget = null;
let virtualKeyboardSavedRange = null;
let virtualKeyboardShift = false;
let virtualKeyboardJapaneseKatakana = false;

const hangulInitials = [
    'ㄱ','ㄲ','ㄴ','ㄷ','ㄸ','ㄹ','ㅁ','ㅂ','ㅃ',
    'ㅅ','ㅆ','ㅇ','ㅈ','ㅉ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'
];

const hangulVowels = [
    'ㅏ','ㅐ','ㅑ','ㅒ','ㅓ','ㅔ','ㅕ','ㅖ','ㅗ',
    'ㅘ','ㅙ','ㅚ','ㅛ','ㅜ','ㅝ','ㅞ','ㅟ','ㅠ',
    'ㅡ','ㅢ','ㅣ'
];

const hangulFinals = [
    '',
    'ㄱ','ㄲ','ㄳ','ㄴ','ㄵ','ㄶ','ㄷ','ㄹ','ㄺ',
    'ㄻ','ㄼ','ㄽ','ㄾ','ㄿ','ㅀ','ㅁ','ㅂ','ㅄ',
    'ㅅ','ㅆ','ㅇ','ㅈ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'
];

const hangulCompoundVowels = {
    'ㅗㅏ': 'ㅘ',
    'ㅗㅐ': 'ㅙ',
    'ㅗㅣ': 'ㅚ',
    'ㅜㅓ': 'ㅝ',
    'ㅜㅔ': 'ㅞ',
    'ㅜㅣ': 'ㅟ',
    'ㅡㅣ': 'ㅢ'
};

const hangulSplitVowels =
    Object.fromEntries(
        Object.entries(
            hangulCompoundVowels
        ).map(([pair, value]) => [
            value,
            [pair[0], pair[1]]
        ])
    );

const hangulCompoundFinals = {
    'ㄱㅅ': 'ㄳ',
    'ㄴㅈ': 'ㄵ',
    'ㄴㅎ': 'ㄶ',
    'ㄹㄱ': 'ㄺ',
    'ㄹㅁ': 'ㄻ',
    'ㄹㅂ': 'ㄼ',
    'ㄹㅅ': 'ㄽ',
    'ㄹㅌ': 'ㄾ',
    'ㄹㅍ': 'ㄿ',
    'ㄹㅎ': 'ㅀ',
    'ㅂㅅ': 'ㅄ'
};

const hangulSplitFinals =
    Object.fromEntries(
        Object.entries(
            hangulCompoundFinals
        ).map(([pair, value]) => [
            value,
            [pair[0], pair[1]]
        ])
    );

const hangulDoubleInitials = {
    'ㄱㄱ': 'ㄲ',
    'ㄷㄷ': 'ㄸ',
    'ㅂㅂ': 'ㅃ',
    'ㅅㅅ': 'ㅆ',
    'ㅈㅈ': 'ㅉ'
};

const hangulSplitInitials =
    Object.fromEntries(
        Object.entries(
            hangulDoubleInitials
        ).map(([pair, value]) => [
            value,
            pair[0]
        ])
    );

let hangulComposition = {
    target: null,
    L: '',
    V: '',
    T: '',
    handle: null
};

function isVirtualKeyboardTextTarget(element) {
    if (!element) return false;

    if (element.isContentEditable) {
        return true;
    }

    if (element.tagName === 'TEXTAREA') {
        return true;
    }

    if (element.tagName !== 'INPUT') {
        return false;
    }

    return [
        'text',
        'search',
        'url',
        'email',
        'tel',
        'password'
    ].includes(
        String(element.type || 'text')
            .toLowerCase()
    );
}

function targetContainsRange(target, range) {
    if (!target || !range) return false;

    const container =
        range.commonAncestorContainer;

    return (
        container === target ||
        target.contains(container)
    );
}

document.addEventListener(
    'focusin',
    event => {
        if (
            isVirtualKeyboardTextTarget(
                event.target
            )
        ) {
            virtualKeyboardTarget =
                event.target;
        }
    }
);

document.addEventListener(
    'selectionchange',
    () => {
        const target =
            virtualKeyboardTarget;

        if (
            !target ||
            !target.isContentEditable
        ) {
            return;
        }

        const selection =
            window.getSelection();

        if (!selection.rangeCount) return;

        const range =
            selection.getRangeAt(0);

        if (
            targetContainsRange(
                target,
                range
            )
        ) {
            virtualKeyboardSavedRange =
                range.cloneRange();
        }
    }
);

function dispatchVirtualKeyboardInput(
    target,
    data = ''
) {
    target?.dispatchEvent(
        new InputEvent(
            'input',
            {
                bubbles: true,
                inputType: 'insertText',
                data
            }
        )
    );
}

function getContentEditableInsertRange(
    target
) {
    const selection =
        window.getSelection();

    if (
        selection.rangeCount &&
        targetContainsRange(
            target,
            selection.getRangeAt(0)
        )
    ) {
        return selection
            .getRangeAt(0)
            .cloneRange();
    }

    if (
        virtualKeyboardSavedRange &&
        targetContainsRange(
            target,
            virtualKeyboardSavedRange
        )
    ) {
        return virtualKeyboardSavedRange
            .cloneRange();
    }

    const range =
        document.createRange();

    range.selectNodeContents(target);
    range.collapse(false);

    return range;
}

function placeCaretAfterNode(node) {
    if (!node?.parentNode) return;

    const range =
        document.createRange();

    range.setStartAfter(node);
    range.collapse(true);

    const selection =
        window.getSelection();

    selection.removeAllRanges();
    selection.addRange(range);

    virtualKeyboardSavedRange =
        range.cloneRange();
}

function insertVirtualKeyboardText(
    text
) {
    const target =
        virtualKeyboardTarget;

    if (!isVirtualKeyboardTextTarget(target)) {
        return null;
    }

    target.focus({
        preventScroll: true
    });

    if (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA'
    ) {
        const start =
            target.selectionStart ??
            target.value.length;

        const end =
            target.selectionEnd ??
            start;

        target.setRangeText(
            text,
            start,
            end,
            'end'
        );

        dispatchVirtualKeyboardInput(
            target,
            text
        );

        return {
            kind: 'input',
            target,
            start,
            length: text.length
        };
    }

    const range =
        getContentEditableInsertRange(
            target
        );

    range.deleteContents();

    const node =
        document.createTextNode(text);

    range.insertNode(node);
    placeCaretAfterNode(node);

    dispatchVirtualKeyboardInput(
        target,
        text
    );

    return {
        kind: 'contenteditable',
        target,
        node
    };
}

function updateVirtualKeyboardHandle(
    handle,
    text
) {
    if (!handle) {
        return insertVirtualKeyboardText(
            text
        );
    }

    const target =
        handle.target;

    if (
        handle.kind === 'input'
    ) {
        target.setRangeText(
            text,
            handle.start,
            handle.start +
                handle.length,
            'end'
        );

        handle.length =
            text.length;

        dispatchVirtualKeyboardInput(
            target,
            text
        );

        return handle;
    }

    if (
        handle.kind ===
            'contenteditable' &&
        handle.node?.parentNode
    ) {
        handle.node.nodeValue =
            text;

        placeCaretAfterNode(
            handle.node
        );

        dispatchVirtualKeyboardInput(
            target,
            text
        );

        return handle;
    }

    return insertVirtualKeyboardText(
        text
    );
}

function removeVirtualKeyboardHandle(
    handle
) {
    if (!handle) return;

    const target =
        handle.target;

    if (handle.kind === 'input') {
        target.setRangeText(
            '',
            handle.start,
            handle.start +
                handle.length,
            'end'
        );

        dispatchVirtualKeyboardInput(
            target,
            ''
        );

        return;
    }

    if (
        handle.kind ===
            'contenteditable' &&
        handle.node?.parentNode
    ) {
        const parent =
            handle.node.parentNode;

        const previous =
            handle.node.previousSibling;

        handle.node.remove();

        const range =
            document.createRange();

        if (
            previous &&
            previous.nodeType ===
                Node.TEXT_NODE
        ) {
            range.setStart(
                previous,
                previous.nodeValue
                    ?.length || 0
            );
        } else {
            range.selectNodeContents(
                parent
            );
            range.collapse(false);
        }

        const selection =
            window.getSelection();

        selection.removeAllRanges();
        selection.addRange(range);

        virtualKeyboardSavedRange =
            range.cloneRange();

        dispatchVirtualKeyboardInput(
            target,
            ''
        );
    }
}

function resetHangulComposition() {
    hangulComposition = {
        target: virtualKeyboardTarget,
        L: '',
        V: '',
        T: '',
        handle: null
    };
}

function commitHangulComposition() {
    hangulComposition = {
        target: virtualKeyboardTarget,
        L: '',
        V: '',
        T: '',
        handle: null
    };
}

function composeHangulSyllable(
    L,
    V,
    T = ''
) {
    const li =
        hangulInitials.indexOf(L);

    const vi =
        hangulVowels.indexOf(V);

    const ti =
        hangulFinals.indexOf(T);

    if (
        li < 0 ||
        vi < 0 ||
        ti < 0
    ) {
        return `${L || ''}${V || ''}${T || ''}`;
    }

    return String.fromCharCode(
        0xAC00 +
        (
            (
                li * 21
            ) +
            vi
        ) * 28 +
        ti
    );
}

function getHangulCompositionText() {
    const {
        L,
        V,
        T
    } = hangulComposition;

    if (L && V) {
        return composeHangulSyllable(
            L,
            V,
            T
        );
    }

    return L || V || T || '';
}

function renderHangulComposition() {
    const text =
        getHangulCompositionText();

    if (!text) {
        if (
            hangulComposition.handle
        ) {
            removeVirtualKeyboardHandle(
                hangulComposition.handle
            );
        }

        hangulComposition.handle =
            null;

        return;
    }

    hangulComposition.handle =
        updateVirtualKeyboardHandle(
            hangulComposition.handle,
            text
        );
}

function ensureHangulTarget() {
    if (
        hangulComposition.target !==
        virtualKeyboardTarget
    ) {
        resetHangulComposition();
    }
}

function inputHangulJamo(jamo) {
    ensureHangulTarget();

    const isVowel =
        hangulVowels.includes(jamo);

    if (isVowel) {
        const {
            L,
            V,
            T
        } = hangulComposition;

        if (!L && !V) {
            hangulComposition.V =
                jamo;

            renderHangulComposition();
            return;
        }

        if (!L && V) {
            const combined =
                hangulCompoundVowels[
                    `${V}${jamo}`
                ];

            if (combined) {
                hangulComposition.V =
                    combined;

                renderHangulComposition();
                return;
            }

            commitHangulComposition();

            hangulComposition.V =
                jamo;

            renderHangulComposition();
            return;
        }

        if (L && !V) {
            hangulComposition.V =
                jamo;

            renderHangulComposition();
            return;
        }

        if (L && V && !T) {
            const combined =
                hangulCompoundVowels[
                    `${V}${jamo}`
                ];

            if (combined) {
                hangulComposition.V =
                    combined;

                renderHangulComposition();
                return;
            }

            commitHangulComposition();

            hangulComposition.V =
                jamo;

            renderHangulComposition();
            return;
        }

        if (L && V && T) {
            const oldFinal =
                T;

            const split =
                hangulSplitFinals[
                    oldFinal
                ];

            if (split) {
                hangulComposition.T =
                    split[0];

                renderHangulComposition();
                commitHangulComposition();

                hangulComposition.L =
                    split[1];

                hangulComposition.V =
                    jamo;

                renderHangulComposition();
                return;
            }

            hangulComposition.T = '';
            renderHangulComposition();
            commitHangulComposition();

            hangulComposition.L =
                oldFinal;

            hangulComposition.V =
                jamo;

            renderHangulComposition();
            return;
        }

        return;
    }

    const {
        L,
        V,
        T
    } = hangulComposition;

    if (!L && !V) {
        if (
            hangulInitials.includes(
                jamo
            )
        ) {
            hangulComposition.L =
                jamo;

            renderHangulComposition();
        } else {
            insertVirtualKeyboardText(
                jamo
            );
        }

        return;
    }

    if (!L && V) {
        commitHangulComposition();

        hangulComposition.L =
            jamo;

        renderHangulComposition();
        return;
    }

    if (L && !V) {
        const doubled =
            hangulDoubleInitials[
                `${L}${jamo}`
            ];

        if (doubled) {
            hangulComposition.L =
                doubled;

            renderHangulComposition();
            return;
        }

        commitHangulComposition();

        hangulComposition.L =
            jamo;

        renderHangulComposition();
        return;
    }

    if (L && V && !T) {
        if (
            hangulFinals.includes(
                jamo
            )
        ) {
            hangulComposition.T =
                jamo;

            renderHangulComposition();
            return;
        }

        commitHangulComposition();

        hangulComposition.L =
            jamo;

        renderHangulComposition();
        return;
    }

    if (L && V && T) {
        const combined =
            hangulCompoundFinals[
                `${T}${jamo}`
            ];

        if (combined) {
            hangulComposition.T =
                combined;

            renderHangulComposition();
            return;
        }

        commitHangulComposition();

        hangulComposition.L =
            jamo;

        renderHangulComposition();
    }
}

function backspaceHangulComposition() {
    ensureHangulTarget();

    const {
        L,
        V,
        T
    } = hangulComposition;

    if (T) {
        const split =
            hangulSplitFinals[T];

        hangulComposition.T =
            split
                ? split[0]
                : '';

        renderHangulComposition();
        return true;
    }

    if (V) {
        const split =
            hangulSplitVowels[V];

        hangulComposition.V =
            split
                ? split[0]
                : '';

        renderHangulComposition();
        return true;
    }

    if (L) {
        hangulComposition.L =
            hangulSplitInitials[L] ||
            '';

        renderHangulComposition();
        return true;
    }

    return false;
}

function backspaceVirtualKeyboardTarget() {
    const target =
        virtualKeyboardTarget;

    if (!isVirtualKeyboardTextTarget(target)) {
        return;
    }

    if (
        db.settings
            .virtualKeyboardLanguage ===
            'korean' &&
        backspaceHangulComposition()
    ) {
        return;
    }

    commitHangulComposition();

    if (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA'
    ) {
        const start =
            target.selectionStart ??
            target.value.length;

        const end =
            target.selectionEnd ??
            start;

        if (start !== end) {
            target.setRangeText(
                '',
                start,
                end,
                'end'
            );
        } else if (start > 0) {
            target.setRangeText(
                '',
                start - 1,
                start,
                'end'
            );
        }

        dispatchVirtualKeyboardInput(
            target,
            ''
        );

        return;
    }

    const range =
        getContentEditableInsertRange(
            target
        );

    if (!range.collapsed) {
        range.deleteContents();
    } else {
        const selection =
            window.getSelection();

        selection.removeAllRanges();
        selection.addRange(range);

        document.execCommand(
            'delete',
            false
        );
    }

    dispatchVirtualKeyboardInput(
        target,
        ''
    );
}

function insertVirtualKeyboardControl(
    value
) {
    commitHangulComposition();

    if (value === 'backspace') {
        backspaceVirtualKeyboardTarget();
        return;
    }

    if (value === 'space') {
        insertVirtualKeyboardText(' ');
        return;
    }

    if (value === 'enter') {
        const target =
            virtualKeyboardTarget;

        if (
            target?.tagName === 'TEXTAREA' ||
            target?.isContentEditable
        ) {
            insertVirtualKeyboardText('\n');
        }

        return;
    }

    insertVirtualKeyboardText(value);
}

function getVirtualKeyboardRows(language) {
    if (language === 'korean') {
        return [
            ['ㅂ','ㅈ','ㄷ','ㄱ','ㅅ','ㅛ','ㅕ','ㅑ','ㅐ','ㅔ'],
            ['ㅁ','ㄴ','ㅇ','ㄹ','ㅎ','ㅗ','ㅓ','ㅏ','ㅣ','ㅋ'],
            ['ㅌ','ㅊ','ㅍ','ㅠ','ㅜ','ㅡ','ㅃ','ㅉ','ㄸ','ㄲ'],
            ['ㅆ','ㅒ','ㅖ']
        ];
    }

    if (language === 'japanese') {
        const hira = [
            ['あ','い','う','え','お','か','き','く','け','こ'],
            ['さ','し','す','せ','そ','た','ち','つ','て','と'],
            ['な','に','ぬ','ね','の','は','ひ','ふ','へ','ほ'],
            ['ま','み','む','め','も','や','ゆ','よ','ら','り'],
            ['る','れ','ろ','わ','を','ん','ゃ','ゅ','ょ','っ'],
            ['ー','が','ぎ','ぐ','げ','ご','ざ','じ','ず','ぜ'],
            ['ぞ','だ','ぢ','づ','で','ど','ば','び','ぶ','べ'],
            ['ぼ','ぱ','ぴ','ぷ','ぺ','ぽ']
        ];

        if (!virtualKeyboardJapaneseKatakana) {
            return hira;
        }

        return hira.map(row =>
            row.map(char => {
                const code = char.charCodeAt(0);

                if (
                    code >= 0x3041 &&
                    code <= 0x3096
                ) {
                    return String.fromCharCode(
                        code + 0x60
                    );
                }

                return char;
            })
        );
    }

    const latinLayouts = {
        english: [
            ['q','w','e','r','t','y','u','i','o','p'],
            ['a','s','d','f','g','h','j','k','l'],
            ['z','x','c','v','b','n','m']
        ],
        spanish: [
            ['q','w','e','r','t','y','u','i','o','p'],
            ['a','s','d','f','g','h','j','k','l','ñ'],
            ['z','x','c','v','b','n','m'],
            ['á','é','í','ó','ú','ü','¿','¡']
        ],
        french: [
            ['a','z','e','r','t','y','u','i','o','p'],
            ['q','s','d','f','g','h','j','k','l','m'],
            ['w','x','c','v','b','n'],
            ['à','â','ç','é','è','ê','ë','î','ï','ô','ù','û','ü','ÿ','œ']
        ],
        german: [
            ['q','w','e','r','t','z','u','i','o','p'],
            ['a','s','d','f','g','h','j','k','l','ö'],
            ['y','x','c','v','b','n','m','ä','ü','ß']
        ],
        portuguese: [
            ['q','w','e','r','t','y','u','i','o','p'],
            ['a','s','d','f','g','h','j','k','l','ç'],
            ['z','x','c','v','b','n','m'],
            ['á','à','â','ã','é','ê','í','ó','ô','õ','ú']
        ]
    };

    const rows =
        latinLayouts[language] ||
        latinLayouts.english;

    if (!virtualKeyboardShift) {
        return rows;
    }

    return rows.map(row =>
        row.map(char =>
            char.toLocaleUpperCase()
        )
    );
}

function getVirtualKeyboardLanguage() {
    return (
        db.settings
            .virtualKeyboardLanguage ||
        'korean'
    );
}

function ensureVirtualKeyboardSettingsUI() {
    const cursorPicker =
        document.getElementById(
            'cursor-picker'
        );

    if (!cursorPicker) return;

    let section =
        document.getElementById(
            'virtual-keyboard-settings-section'
        );

    if (!section) {
        section =
            document.createElement('div');

        section.id =
            'virtual-keyboard-settings-section';

        section.className =
            'modal-section virtual-keyboard-settings-section';

        section.innerHTML = `
            <span class="field-label">
                Ctrl + K Keyboard
            </span>

            <select
                id="virtual-keyboard-language-select"
                aria-label="Virtual keyboard language"
            >
                ${Object.entries(
                    VIRTUAL_KEYBOARD_LANGUAGES
                ).map(
                    ([value, label]) =>
                        `<option value="${value}">${label}</option>`
                ).join('')}
            </select>

            <p class="progress-hint">
                Press Ctrl + K in any text box to open or close it.
            </p>
        `;

        const cursorSection =
            cursorPicker.closest(
                '.modal-section'
            ) ||
            cursorPicker.parentElement;

        cursorSection.insertAdjacentElement(
            'afterend',
            section
        );

        section
            .querySelector(
                '#virtual-keyboard-language-select'
            )
            ?.addEventListener(
                'change',
                event => {
                    db.settings
                        .virtualKeyboardLanguage =
                        event.target.value;

                    saveDb();
                    virtualKeyboardShift =
                        false;

                    virtualKeyboardJapaneseKatakana =
                        false;

                    commitHangulComposition();
                    renderVirtualKeyboard();
                }
            );
    }

    const select =
        document.getElementById(
            'virtual-keyboard-language-select'
        );

    if (select) {
        select.value =
            getVirtualKeyboardLanguage();
    }
}

function ensureVirtualKeyboard() {
    let keyboard =
        document.getElementById(
            'floating-language-keyboard'
        );

    if (keyboard) return keyboard;

    keyboard =
        document.createElement('div');

    keyboard.id =
        'floating-language-keyboard';

    keyboard.className =
        'floating-language-keyboard hidden';

    keyboard.innerHTML = `
        <div
            class="floating-keyboard-header"
            id="floating-keyboard-drag-handle"
        >
            <span class="floating-keyboard-grip" aria-hidden="true">
                <i class="ph ph-dots-six"></i>
            </span>

            <span
                id="floating-keyboard-title"
                class="floating-keyboard-title"
            ></span>

            <button
                type="button"
                id="floating-keyboard-close"
                class="floating-keyboard-close"
                title="Close keyboard"
                aria-label="Close keyboard"
            >
                <i class="ph ph-x"></i>
            </button>
        </div>

        <div
            id="floating-keyboard-keys"
            class="floating-keyboard-keys"
        ></div>

        <div
            id="floating-keyboard-language-panel"
            class="floating-keyboard-language-panel hidden"
        >
            <span>Language</span>

            <select
                id="floating-keyboard-language-select"
                aria-label="Keyboard language"
            >
                ${Object.entries(
                    VIRTUAL_KEYBOARD_LANGUAGES
                ).map(
                    ([value, label]) =>
                        `<option value="${value}">${label}</option>`
                ).join('')}
            </select>
        </div>
    `;

    document.body.appendChild(
        keyboard
    );

    keyboard
        .querySelector(
            '#floating-keyboard-close'
        )
        ?.addEventListener(
            'click',
            closeVirtualKeyboard
        );

    keyboard
        .querySelector(
            '#floating-keyboard-language-select'
        )
        ?.addEventListener(
            'change',
            event => {
                db.settings
                    .virtualKeyboardLanguage =
                    event.target.value;

                saveDb();

                virtualKeyboardShift =
                    false;

                virtualKeyboardJapaneseKatakana =
                    false;

                commitHangulComposition();
                renderVirtualKeyboard();
            }
        );

    const handle =
        keyboard.querySelector(
            '#floating-keyboard-drag-handle'
        );

    let dragState = null;

    handle.addEventListener(
        'pointerdown',
        event => {
            if (
                event.target.closest(
                    'button'
                )
            ) {
                return;
            }

            const rect =
                keyboard
                    .getBoundingClientRect();

            // Freeze the keyboard at its exact rendered position before
            // beginning the drag. This prevents the old translateX(-50%)
            // centering transform from causing the initial jump/offset.
            keyboard.style.transform =
                'none';

            keyboard.style.left =
                `${rect.left}px`;

            keyboard.style.top =
                `${rect.top}px`;

            keyboard.style.right =
                'auto';

            keyboard.style.bottom =
                'auto';

            dragState = {
                pointerId:
                    event.pointerId,
                offsetX:
                    event.clientX -
                    rect.left,
                offsetY:
                    event.clientY -
                    rect.top
            };

            handle.setPointerCapture(
                event.pointerId
            );

            keyboard.classList.add(
                'is-dragging'
            );

            event.preventDefault();
        }
    );

    handle.addEventListener(
        'pointermove',
        event => {
            if (
                !dragState ||
                dragState.pointerId !==
                    event.pointerId
            ) {
                return;
            }

            const width =
                keyboard.offsetWidth;

            const height =
                keyboard.offsetHeight;

            const maxLeft =
                Math.max(
                    8,
                    window.innerWidth -
                        width -
                        8
                );

            const maxTop =
                Math.max(
                    8,
                    window.innerHeight -
                        height -
                        8
                );

            const left =
                Math.max(
                    8,
                    Math.min(
                        maxLeft,
                        event.clientX -
                            dragState.offsetX
                    )
                );

            const top =
                Math.max(
                    8,
                    Math.min(
                        maxTop,
                        event.clientY -
                            dragState.offsetY
                    )
                );

            keyboard.style.left =
                `${left}px`;

            keyboard.style.top =
                `${top}px`;

            event.preventDefault();
        }
    );

    const stopDrag =
        event => {
            if (
                !dragState ||
                dragState.pointerId !==
                    event.pointerId
            ) {
                return;
            }

            try {
                handle.releasePointerCapture(
                    event.pointerId
                );
            } catch {}

            dragState = null;

            keyboard.classList.remove(
                'is-dragging'
            );
        };

    handle.addEventListener(
        'pointerup',
        stopDrag
    );

    handle.addEventListener(
        'pointercancel',
        stopDrag
    );

    return keyboard;
}

function renderVirtualKeyboard() {
    const keyboard =
        ensureVirtualKeyboard();

    const language =
        getVirtualKeyboardLanguage();

    const title =
        keyboard.querySelector(
            '#floating-keyboard-title'
        );

    const keys =
        keyboard.querySelector(
            '#floating-keyboard-keys'
        );

    const languageSelect =
        keyboard.querySelector(
            '#floating-keyboard-language-select'
        );

    if (languageSelect) {
        languageSelect.value =
            language;
    }

    title.textContent =
        VIRTUAL_KEYBOARD_LANGUAGES[
            language
        ] || 'Keyboard';

    keys.innerHTML = '';

    const rows =
        getVirtualKeyboardRows(
            language
        );

    rows.forEach(row => {
        const rowEl =
            document.createElement('div');

        rowEl.className =
            'floating-keyboard-row';

        row.forEach(value => {
            const button =
                document.createElement(
                    'button'
                );

            button.type = 'button';

            button.className =
                'floating-keyboard-key';

            button.textContent =
                value;

            button.addEventListener(
                'pointerdown',
                event => {
                    // Keep the text caret in the field the keyboard is typing into.
                    event.preventDefault();
                }
            );

            button.addEventListener(
                'click',
                () => {
                    if (
                        language ===
                        'korean'
                    ) {
                        inputHangulJamo(
                            value
                        );
                    } else {
                        commitHangulComposition();

                        insertVirtualKeyboardText(
                            value
                        );
                    }

                    if (
                        virtualKeyboardShift
                    ) {
                        virtualKeyboardShift =
                            false;

                        renderVirtualKeyboard();
                    }
                }
            );

            rowEl.appendChild(
                button
            );
        });

        keys.appendChild(rowEl);
    });

    const controls =
        document.createElement('div');

    controls.className =
        'floating-keyboard-row floating-keyboard-controls';

    if (
        language !== 'korean' &&
        language !== 'japanese'
    ) {
        const shift =
            document.createElement(
                'button'
            );

        shift.type = 'button';

        shift.className =
            'floating-keyboard-key floating-keyboard-control-key';

        shift.textContent =
            virtualKeyboardShift
                ? 'Shift ✓'
                : 'Shift';

        shift.addEventListener(
            'pointerdown',
            event =>
                event.preventDefault()
        );

        shift.addEventListener(
            'click',
            () => {
                virtualKeyboardShift =
                    !virtualKeyboardShift;

                renderVirtualKeyboard();
            }
        );

        controls.appendChild(
            shift
        );
    }

    if (
        language === 'japanese'
    ) {
        const kana =
            document.createElement(
                'button'
            );

        kana.type = 'button';

        kana.className =
            'floating-keyboard-key floating-keyboard-control-key';

        kana.textContent =
            virtualKeyboardJapaneseKatakana
                ? 'カナ → かな'
                : 'かな → カナ';

        kana.addEventListener(
            'pointerdown',
            event =>
                event.preventDefault()
        );

        kana.addEventListener(
            'click',
            () => {
                virtualKeyboardJapaneseKatakana =
                    !virtualKeyboardJapaneseKatakana;

                renderVirtualKeyboard();
            }
        );

        controls.appendChild(
            kana
        );
    }

    const makeControlButton = (
        className,
        labelHtml,
        title,
        action
    ) => {
        const button =
            document.createElement(
                'button'
            );

        button.type = 'button';

        button.className =
            `floating-keyboard-key floating-keyboard-control-key ${className || ''}`;

        button.innerHTML =
            labelHtml;

        if (title) {
            button.title = title;
            button.setAttribute(
                'aria-label',
                title
            );
        }

        button.addEventListener(
            'pointerdown',
            event =>
                event.preventDefault()
        );

        button.addEventListener(
            'click',
            action
        );

        controls.appendChild(
            button
        );

        return button;
    };

    makeControlButton(
        'floating-keyboard-space',
        'Space',
        'Space',
        () =>
            insertVirtualKeyboardControl(
                'space'
            )
    );

    makeControlButton(
        'floating-keyboard-backspace',
        '<i class="ph ph-backspace"></i>',
        'Backspace',
        () =>
            insertVirtualKeyboardControl(
                'backspace'
            )
    );

    makeControlButton(
        'floating-keyboard-settings',
        '<i class="ph ph-gear-six"></i>',
        'Keyboard settings',
        () => {
            const panel =
                keyboard.querySelector(
                    '#floating-keyboard-language-panel'
                );

            panel?.classList.toggle(
                'hidden'
            );
        }
    );

    makeControlButton(
        'floating-keyboard-enter',
        'Enter',
        'Enter',
        () =>
            insertVirtualKeyboardControl(
                'enter'
            )
    );

    keys.appendChild(
        controls
    );
}

function openVirtualKeyboard() {
    const active =
        document.activeElement;

    if (
        isVirtualKeyboardTextTarget(
            active
        )
    ) {
        virtualKeyboardTarget =
            active;
    }

    ensureVirtualKeyboard();
    renderVirtualKeyboard();

    const keyboard =
        document.getElementById(
            'floating-language-keyboard'
        );

    keyboard.classList.remove(
        'hidden'
    );
}

function closeVirtualKeyboard() {
    commitHangulComposition();

    document
        .getElementById(
            'floating-language-keyboard'
        )
        ?.classList.add(
            'hidden'
        );
}

function toggleVirtualKeyboard() {
    const keyboard =
        ensureVirtualKeyboard();

    if (
        keyboard.classList.contains(
            'hidden'
        )
    ) {
        openVirtualKeyboard();
    } else {
        closeVirtualKeyboard();
    }
}

document.addEventListener(
    'keydown',
    event => {
        if (
            event.ctrlKey &&
            !event.shiftKey &&
            !event.altKey &&
            !event.metaKey &&
            event.key.toLowerCase() ===
                'k'
        ) {
            event.preventDefault();
            event.stopPropagation();

            toggleVirtualKeyboard();
        }
    },
    true
);



// ============================================================
// SPLIT SETTINGS
// - Daily Logs gear: Daily Logs-only options.
// - Side-nav gear: app-wide Theme / Companion / Cursor / Shortcuts.
// ============================================================

function hideDailyOnlyControlsFromGlobalSettings() {
    if (!dailySettingsModal) return;

    // First undo the older implementation, which could hide an entire
    // shared modal section and accidentally take Theme / Companion /
    // Cursor with it.
    dailySettingsModal
        .querySelectorAll(
            '.global-settings-daily-only-hidden'
        )
        .forEach(element => {
            element.classList.remove(
                'global-settings-daily-only-hidden'
            );
        });

    // Explicitly make the three app-wide picker areas visible.
    [
        themePicker,
        document.getElementById(
            'companion-picker'
        ),
        document.getElementById(
            'cursor-picker'
        )
    ].forEach(element => {
        if (!element) return;

        element.classList.remove(
            'hidden'
        );

        const section =
            element.closest(
                '.modal-section'
            );

        section?.classList.remove(
            'hidden',
            'global-settings-daily-only-hidden'
        );

        if (section) {
            section.style.display = '';
        }

        element.style.display = '';
    });

    // Hide ONLY the Daily Logs view controls themselves.
    // Do not hide their whole parent section because older HTML
    // versions may share that section with the theme controls.
    if (dailyViewTypeSelect) {
        dailyViewTypeSelect.classList.add(
            'global-settings-daily-control'
        );

        const label =
            dailyViewTypeSelect.previousElementSibling;

        if (
            label &&
            (
                label.classList?.contains(
                    'field-label'
                ) ||
                label.tagName === 'LABEL'
            )
        ) {
            label.classList.add(
                'global-settings-daily-control'
            );
        }
    }

    if (dailyPolaroidSourceGroup) {
        dailyPolaroidSourceGroup.classList.add(
            'global-settings-daily-control'
        );
    }
}

