function showAppConfirm({
    title = 'Are you sure?',
    message = '',
    confirmLabel = 'Delete'
} = {}) {
    const modal =
        ensureAppConfirmModal();

    const titleEl =
        modal.querySelector(
            '#app-confirm-title'
        );

    const messageEl =
        modal.querySelector(
            '#app-confirm-message'
        );

    const accept =
        modal.querySelector(
            '#app-confirm-accept'
        );

    const cancel =
        modal.querySelector(
            '#app-confirm-cancel'
        );

    if (titleEl) {
        titleEl.textContent =
            title;
    }

    if (messageEl) {
        messageEl.textContent =
            message;
    }

    if (accept) {
        accept.innerHTML = `
            <i class="ph ph-trash"></i>
            ${escapeCustomHtml(confirmLabel)}
        `;
    }

    modal.classList.remove(
        'hidden'
    );

    return new Promise(resolve => {
        let finished = false;

        const cleanup = () => {
            accept?.removeEventListener(
                'click',
                onAccept
            );

            cancel?.removeEventListener(
                'click',
                onCancel
            );

            modal.removeEventListener(
                'pointerdown',
                onBackdrop
            );

            document.removeEventListener(
                'keydown',
                onKeydown
            );
        };

        const finish = value => {
            if (finished) return;
            finished = true;

            cleanup();

            modal.classList.add(
                'hidden'
            );

            resolve(value);
        };

        const onAccept =
            () => finish(true);

        const onCancel =
            () => finish(false);

        const onBackdrop =
            event => {
                if (event.target === modal) {
                    onCancel();
                }
            };

        const onKeydown =
            event => {
                if (event.key === 'Escape') {
                    event.preventDefault();
                    onCancel();
                }
            };

        accept?.addEventListener(
            'click',
            onAccept
        );

        cancel?.addEventListener(
            'click',
            onCancel
        );

        modal.addEventListener(
            'pointerdown',
            onBackdrop
        );

        document.addEventListener(
            'keydown',
            onKeydown
        );

        requestAnimationFrame(() => {
            cancel?.focus();
        });
    });
}

function showAppFormModal({
    title = 'Edit',
    fields = [],
    submitLabel = 'Done'
} = {}) {
    const modal = ensureAppPromptModal();
    const titleEl = modal.querySelector('#app-prompt-title');
    const fieldsEl = modal.querySelector('#app-prompt-fields');
    const submit = modal.querySelector('#app-prompt-submit');
    const cancel = modal.querySelector('#app-prompt-cancel');
    const close = modal.querySelector('#app-prompt-close');

    titleEl.textContent = title;
    submit.textContent = submitLabel;
    fieldsEl.innerHTML = '';

    const inputs = new Map();

    fields.forEach((field, index) => {
        const section = document.createElement('div');
        section.className = 'modal-section app-prompt-field';

        const label = document.createElement('span');
        label.className = 'field-label';
        label.textContent = field.label || field.name || `Field ${index + 1}`;
        section.appendChild(label);

        let input;

        if (field.type === 'textarea') {
            input = document.createElement('textarea');
            input.rows = field.rows || 4;
        } else if (field.type === 'select') {
            input = document.createElement('select');

            (field.options || []).forEach(option => {
                const item = document.createElement('option');

                if (typeof option === 'string') {
                    item.value = option;
                    item.textContent = option;
                } else {
                    item.value = option.value;
                    item.textContent = option.label;
                }

                input.appendChild(item);
            });
        } else {
            input = document.createElement('input');
            input.type = field.type || 'text';
        }

        input.dataset.fieldName = field.name;
        input.value = field.value ?? '';
        input.placeholder = field.placeholder || '';

        if (field.min !== undefined) input.min = field.min;
        if (field.max !== undefined) input.max = field.max;
        if (field.step !== undefined) input.step = field.step;

        section.appendChild(input);
        fieldsEl.appendChild(section);
        inputs.set(field.name, input);
    });

    modal.classList.remove('hidden');

    return new Promise(resolve => {
        let finished = false;

        const cleanup = () => {
            submit.removeEventListener('click', onSubmit);
            cancel.removeEventListener('click', onCancel);
            close.removeEventListener('click', onCancel);
            modal.removeEventListener('pointerdown', onBackdrop);
        };

        const finish = value => {
            if (finished) return;
            finished = true;
            cleanup();
            modal.classList.add('hidden');
            resolve(value);
        };

        const onSubmit = () => {
            const result = {};

            inputs.forEach((input, key) => {
                result[key] = input.value;
            });

            finish(result);
        };

        const onCancel = () => finish(null);

        const onBackdrop = event => {
            if (event.target === modal) onCancel();
        };

        submit.addEventListener('click', onSubmit);
        cancel.addEventListener('click', onCancel);
        close.addEventListener('click', onCancel);
        modal.addEventListener('pointerdown', onBackdrop);

        requestAnimationFrame(() => {
            const first = inputs.values().next().value;
            first?.focus();
            if (first?.select && first.tagName !== 'SELECT') first.select();
        });
    });
}

async function showAppPrompt({
    title = 'Edit',
    label = 'Value',
    value = '',
    placeholder = '',
    type = 'text',
    submitLabel = 'Done'
} = {}) {
    const result = await showAppFormModal({
        title,
        submitLabel,
        fields: [
            {
                name: 'value',
                label,
                value,
                placeholder,
                type
            }
        ]
    });

    return result ? result.value : null;
}


