function renderCustomTabIcon(icon) {
    if (icon === 'custom-skateboard') return CUSTOM_TAB_SKATEBOARD_SVG;
    return `<i class="ph ${escapeCustomHtml(icon || 'ph-squares-four')}"></i>`;
}

function ensureCustomTabIconSearch(input, picker) {
    if (!input || !picker || input.dataset.boundIconSearch) return;
    input.dataset.boundIconSearch = 'true';
    input.addEventListener('input', () => {
        const query = input.value.trim().toLocaleLowerCase();
        picker.querySelectorAll('.custom-tab-icon-choice').forEach(choice => {
            const label = String(choice.dataset.label || choice.title || '').toLocaleLowerCase();
            choice.classList.toggle('icon-search-hidden', !!query && !label.includes(query));
        });
    });
}

