let activeCustomTabId = null;
let customTabEditMode = false;
let draggedCustomComponentId = null;

function customId(prefix = 'custom') {
    return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function getCustomTabs() {
    if (!db.settings) db.settings = {};
    if (!Array.isArray(db.settings.customTabs)) db.settings.customTabs = [];
    return db.settings.customTabs;
}

function getCustomTab(tabId) {
    return getCustomTabs().find(tab => tab.id === tabId) || null;
}

function escapeCustomHtml(value) {
    return String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function initCustomTabs() {
    ensureCustomTabCreateModal();
    ensureCustomSideNavControls();
    renderCustomTabNavigation();
    renderAllCustomTabViews();
    ensureDailyCustomTabLinksUI();
    markSitePrimaryModalActions();
}


function ensureDailyLogsNavButton() {
    const nav = document.querySelector('.side-nav');
    if (!nav) return;

    let button = document.getElementById('open-daily-logs-nav-btn');

    if (!button) {
        button = document.createElement('button');
        button.id = 'open-daily-logs-nav-btn';
        button.type = 'button';
        button.className = 'icon-btn daily-logs-nav-btn';
        button.title = 'Daily Logs';
        button.setAttribute('aria-label', 'Daily Logs');
        button.innerHTML = '<i class="ph ph-calendar-blank"></i>';

        button.addEventListener('click', () => {
            activeCustomTabId = null;
            customTabEditMode = false;
            initGrid();
            switchView(gridView);
        });

        const home =
            nav.querySelector('a.icon-btn[href="/"]') ||
            nav.querySelector('a[href="/"]') ||
            nav.firstElementChild;

        if (home?.nextSibling) {
            nav.insertBefore(button, home.nextSibling);
        } else {
            nav.appendChild(button);
        }
    }
}


function ensureGlobalDailySettingsNavButton() {
    const nav = document.querySelector('.side-nav');
    if (!nav) return;

    let button =
        document.getElementById(
            'open-global-daily-settings-nav-btn'
        );

    if (!button) {
        button = document.createElement('button');
        button.id =
            'open-global-daily-settings-nav-btn';
        button.type = 'button';
        button.className =
            'icon-btn global-daily-settings-nav-btn';
        button.title = 'Theme Settings';
        button.setAttribute(
            'aria-label',
            'Theme Settings'
        );
        button.innerHTML =
            '<i class="ph ph-palette"></i>';

        button.addEventListener(
            'click',
            openGlobalThemeSettings
        );
    }

    let separator =
        document.getElementById(
            'side-nav-general-separator'
        );

    if (!separator) {
        separator =
            document.createElement('div');

        separator.id =
            'side-nav-general-separator';

        separator.className =
            'side-nav-general-separator';

        separator.setAttribute(
            'aria-hidden',
            'true'
        );
    }

    const home =
        nav.querySelector(
            'a.icon-btn[href="/"]'
        ) ||
        nav.querySelector(
            'a[href="/"]'
        ) ||
        nav.firstElementChild;

    // General controls:
    // Home
    // Palette / theme settings
    // divider
    //
    // Everything after the divider is specific to the current log.
    if (home) {
        nav.insertBefore(
            button,
            home.nextSibling
        );

        nav.insertBefore(
            separator,
            button.nextSibling
        );
    } else {
        nav.prepend(separator);
        nav.prepend(button);
    }

    const dailyButton =
        document.getElementById(
            'open-daily-logs-nav-btn'
        );

    if (dailyButton) {
        nav.insertBefore(
            dailyButton,
            separator.nextSibling
        );
    }
}

function ensureLogSpecificSideNavScrollRegion() {
    const nav =
        document.querySelector(
            '.side-nav'
        );

    const separator =
        document.getElementById(
            'side-nav-general-separator'
        );

    if (!nav || !separator) return null;

    let scrollRegion =
        document.getElementById(
            'side-nav-log-scroll'
        );

    if (!scrollRegion) {
        scrollRegion =
            document.createElement('div');

        scrollRegion.id =
            'side-nav-log-scroll';

        scrollRegion.className =
            'side-nav-log-scroll';

        const pinnedHost =
            document.getElementById(
                'custom-tab-pinned-host'
            );

        nav.insertBefore(
            scrollRegion,
            pinnedHost?.nextSibling || separator.nextSibling
        );
    }

    // Anything below the divider belongs to the current log and should
    // scroll together. The + button is intentionally NOT moved in here.
    Array.from(nav.children)
        .filter(child => {
            if (
                child === scrollRegion ||
                child === separator ||
                child.id ===
                    'add-custom-tab-btn' ||
                child.id ===
                    'custom-tab-pinned-host'
            ) {
                return false;
            }

            // Keep Home and the global palette button fixed above the divider.
            const separatorIndex =
                Array.from(
                    nav.children
                ).indexOf(separator);

            const childIndex =
                Array.from(
                    nav.children
                ).indexOf(child);

            return (
                separatorIndex >= 0 &&
                childIndex >
                    separatorIndex
            );
        })
        .forEach(child => {
            scrollRegion.appendChild(
                child
            );
        });

    return scrollRegion;
}

function getOffsetTopInside(element, ancestor) {
    let top = 0;
    let node = element;

    while (
        node &&
        node !== ancestor
    ) {
        top += node.offsetTop || 0;
        node = node.offsetParent;
    }

    return top;
}

function updateLogSpecificSideNavScrollState() {
    const scrollRegion =
        document.getElementById(
            'side-nav-log-scroll'
        );

    const customHost =
        document.getElementById(
            'custom-tab-nav-host'
        );

    if (!scrollRegion || !customHost) return;

    const customButtons =
        Array.from(
            customHost.querySelectorAll(
                '.custom-tab-nav-btn'
            )
        );

    const shouldScroll =
        customButtons.length > 3;

    scrollRegion.classList.toggle(
        'is-scrollable',
        shouldScroll
    );

    if (!shouldScroll) {
        scrollRegion.style.removeProperty(
            '--log-nav-scroll-height'
        );

        scrollRegion.scrollTop = 0;
        return;
    }

    requestAnimationFrame(() => {
        const firstHiddenCustom =
            customButtons[3];

        if (!firstHiddenCustom) return;

        const hostStyle =
            getComputedStyle(
                customHost
            );

        const gap =
            parseFloat(
                hostStyle.rowGap ||
                hostStyle.gap ||
                '25'
            ) || 25;

        // Use layout offsets, not viewport rectangles. Viewport rectangles
        // shift as the user scrolls and were causing the scroller height
        // to collapse after rerenders.
        const firstHiddenTop =
            getOffsetTopInside(
                firstHiddenCustom,
                scrollRegion
            );

        const visibleHeight =
            Math.max(
                80,
                firstHiddenTop - gap
            );

        scrollRegion.style.setProperty(
            '--log-nav-scroll-height',
            `${Math.ceil(visibleHeight)}px`
        );
    });
}

function ensureCustomSideNavControls() {
    const nav = document.querySelector('.side-nav');
    if (!nav) return;

    hideDailyOnlyControlsFromGlobalSettings();
    ensureGlobalShortcutsSection();
    ensureDailyLogsNavButton();
    ensureGlobalDailySettingsNavButton();

    const separator =
        document.getElementById(
            'side-nav-general-separator'
        );

    let pinnedNavHost =
        document.getElementById(
            'custom-tab-pinned-host'
        );

    if (!pinnedNavHost) {
        pinnedNavHost =
            document.createElement('div');
        pinnedNavHost.id =
            'custom-tab-pinned-host';
        pinnedNavHost.className =
            'custom-tab-pinned-host';
    }

    if (separator?.parentElement === nav) {
        nav.insertBefore(
            pinnedNavHost,
            separator.nextSibling
        );
    }

    const scrollRegion =
        ensureLogSpecificSideNavScrollRegion();

    ensureWeeklyReviewNavButton(scrollRegion);

    let customNavHost =
        document.getElementById(
            'custom-tab-nav-host'
        );

    if (!customNavHost) {
        customNavHost =
            document.createElement('div');

        customNavHost.id =
            'custom-tab-nav-host';

        customNavHost.className =
            'custom-tab-nav-host';
    }

    // Custom tabs are part of the log-specific scrolling group.
    (
        scrollRegion ||
        nav
    ).appendChild(
        customNavHost
    );

    let plus =
        document.getElementById(
            'add-custom-tab-btn'
        );

    if (!plus) {
        plus =
            document.createElement('button');

        plus.id =
            'add-custom-tab-btn';

        plus.type =
            'button';

        plus.className =
            'icon-btn custom-tab-plus-btn';

        plus.title =
            'Add custom tab';

        plus.setAttribute(
            'aria-label',
            'Add custom tab'
        );

        plus.innerHTML =
            '<i class="ph ph-plus"></i>';

        plus.addEventListener(
            'click',
            openCustomTabCreateModal
        );
    }

    // The + button always sits OUTSIDE the scroll container,
    // at the absolute bottom of the side navigation.
    nav.appendChild(plus);

    updateLogSpecificSideNavScrollState();
}

function toggleCustomTabPin(tabId) {
    const tab = getCustomTab(tabId);
    if (!tab) return;

    if (!tab.pinned) {
        const pinnedCount = getCustomTabs().filter(item => item.pinned).length;
        if (pinnedCount >= 2) {
            showFeatureToast('You can pin up to two custom tabs above the scroll area.');
            return;
        }
    }

    tab.pinned = !tab.pinned;
    saveDb();
    renderCustomTabNavigation();
    updateLogSpecificSideNavScrollState();
}

function createCustomTabNavButton(tab, host) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'icon-btn custom-tab-nav-btn';
    button.dataset.customTabId = tab.id;
    button.title = `${tab.name} — drag to reorder${tab.pinned ? ' · pinned' : ''}`;
    button.setAttribute('aria-label', tab.name);
    button.innerHTML = renderCustomTabIcon(tab.icon || 'ph-squares-four');
    button.draggable = true;

    if (tab.pinned) button.classList.add('custom-tab-nav-pinned');

    button.addEventListener('click', () => openCustomTab(tab.id));

    button.addEventListener('dragstart', event => {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/custom-tab-id', tab.id);
        button.classList.add('custom-tab-nav-dragging');
    });

    button.addEventListener('dragend', () => {
        button.classList.remove('custom-tab-nav-dragging');
        document.querySelectorAll('.custom-tab-nav-drop-target').forEach(el => el.classList.remove('custom-tab-nav-drop-target'));
    });

    button.addEventListener('dragover', event => {
        if (!event.dataTransfer.types.includes('text/custom-tab-id')) return;
        event.preventDefault();
        button.classList.add('custom-tab-nav-drop-target');
    });

    button.addEventListener('dragleave', () => button.classList.remove('custom-tab-nav-drop-target'));

    button.addEventListener('drop', event => {
        event.preventDefault();
        button.classList.remove('custom-tab-nav-drop-target');
        const draggedId = event.dataTransfer.getData('text/custom-tab-id');
        if (!draggedId || draggedId === tab.id) return;
        const rect = button.getBoundingClientRect();
        reorderCustomTab(draggedId, tab.id, event.clientY > rect.top + rect.height / 2);
    });

    button.addEventListener('contextmenu', event => {
        event.preventDefault();
        showCustomItemContextMenu(event.clientX, event.clientY, [
            {
                label: tab.pinned ? 'Unpin tab' : 'Pin above scroll',
                icon: tab.pinned ? 'ph-push-pin-slash' : 'ph-push-pin',
                action: () => toggleCustomTabPin(tab.id)
            },
            { label: 'Duplicate tab', icon: 'ph-copy', action: () => duplicateCustomTab(tab.id, { openAfter: false }) },
            { label: 'Tab settings', icon: 'ph-gear-six', action: () => openCustomTabSettingsModal(tab.id) }
        ]);
    });

    host.appendChild(button);
}

function renderCustomTabNavigation() {
    const host = document.getElementById('custom-tab-nav-host');
    const pinnedHost = document.getElementById('custom-tab-pinned-host');
    if (!host) return;

    host.innerHTML = '';
    if (pinnedHost) pinnedHost.innerHTML = '';

    getCustomTabs().forEach(tab => {
        const destination = tab.pinned && pinnedHost ? pinnedHost : host;
        createCustomTabNavButton(tab, destination);
    });

    pinnedHost?.classList.toggle('hidden', !pinnedHost.children.length);
    updateLogSpecificSideNavScrollState();
}

function renderAllCustomTabViews() {
    document.querySelectorAll('.custom-tab-view').forEach(view => view.remove());

    getCustomTabs().forEach(tab => {
        document.body.insertBefore(buildCustomTabView(tab), document.getElementById('companion-stage') || null);
    });
}

function buildCustomTabView(tab) {
    const view = document.createElement('div');
    view.id = `custom-tab-view-${tab.id}`;
    view.className = 'view custom-tab-view';
    view.dataset.customTabId = tab.id;

    view.innerHTML = `
        <div class="custom-tab-header">
            <div class="custom-tab-title-wrap">
                <h1 class="custom-tab-title">${escapeCustomHtml(tab.name)}</h1>
            </div>

            <div class="custom-tab-header-actions">
                <button type="button" class="small-icon-btn custom-tab-edit-btn" title="Edit tab">
                    <i class="ph ph-pencil-simple"></i>
                </button>
                <button type="button" class="small-icon-btn custom-tab-settings-btn" title="Tab settings">
                    <i class="ph ph-gear-six"></i>
                </button>
            </div>
        </div>

        <div class="custom-component-palette hidden" aria-label="Component palette"></div>

        <div class="custom-tab-builder-hint hidden">
            Drag components from above into the page. You can also drag existing components to reorder them.
        </div>

        <div class="custom-tab-canvas"></div>
    `;

    view.querySelector('.custom-tab-edit-btn').addEventListener('click', () => {
        activeCustomTabId = tab.id;
        customTabEditMode = !customTabEditMode;
        renderCustomTabView(tab.id);
    });

    view.querySelector('.custom-tab-settings-btn').addEventListener('click', () => {
        openCustomTabSettingsModal(tab.id);
    });

    return view;
}

function openCustomTab(tabId) {
    const tab = getCustomTab(tabId);
    const view = document.getElementById(`custom-tab-view-${tabId}`);
    if (!tab || !view) return;

    activeCustomTabId = tabId;
    customTabEditMode = false;
    renderCustomTabView(tabId);
    switchView(view);

    requestAnimationFrame(() => {
        const scrollRegion =
            document.getElementById(
                'side-nav-log-scroll'
            );

        const navButton =
            document.querySelector(
                `.custom-tab-nav-btn[data-custom-tab-id="${CSS.escape(String(tabId))}"]`
            );

        if (
            scrollRegion?.classList.contains(
                'is-scrollable'
            ) &&
            navButton
        ) {
            navButton.scrollIntoView({
                block: 'nearest',
                behavior: 'smooth'
            });
        }
    });
}

function renderCustomTabView(tabId) {
    const tab = getCustomTab(tabId);
    const view = document.getElementById(`custom-tab-view-${tabId}`);
    if (!tab || !view) return;

    const palette = view.querySelector('.custom-component-palette');
    const hint = view.querySelector('.custom-tab-builder-hint');
    const canvas = view.querySelector('.custom-tab-canvas');
    const editBtn = view.querySelector('.custom-tab-edit-btn');

    view.querySelector('.custom-tab-title').textContent = tab.name;
    editBtn.classList.toggle('active-builder-control', customTabEditMode);
    palette.classList.toggle('hidden', !customTabEditMode);
    hint.classList.toggle('hidden', !customTabEditMode);
    canvas.classList.toggle('is-editing', customTabEditMode);

    renderCustomComponentPalette(palette);
    renderCustomCanvas(tab, canvas);
}

function renderCustomComponentPalette(palette) {
    if (!palette) return;
    palette.innerHTML = '';

    CUSTOM_COMPONENT_LIBRARY.forEach(def => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'custom-component-palette-item';
        item.draggable = true;
        item.dataset.componentType = def.type;
        item.innerHTML = `<i class="ph ${def.icon}"></i><span>${def.label}</span>`;

        item.addEventListener('dragstart', e => {
            e.dataTransfer.effectAllowed = 'copy';
            e.dataTransfer.setData('text/custom-component-type', def.type);
            item.classList.add('dragging');
        });

        item.addEventListener('dragend', () => item.classList.remove('dragging'));

        // Click is also supported for accessibility/touch.
        item.addEventListener('click', () => {
            if (!activeCustomTabId) return;
            addCustomComponent(activeCustomTabId, def.type);
        });

        palette.appendChild(item);
    });
}


const CUSTOM_TITLE_BACKGROUND_TYPES = new Set([
    'heading',
    'cards',
    'polaroids',
    'checklist',
    'practiceLog',
    'progressMeter',
    'skillRatings',
    'vocabulary',
    'resources',
    'milestones',
    'projectGallery',
    'recipeTracker'
]);

function customComponentSupportsTitleBackground(component) {
    return !!component && CUSTOM_TITLE_BACKGROUND_TYPES.has(component.type);
}

function setCustomComponentTitleBackground(tabId, componentId, value) {
    const tab = getCustomTab(tabId);
    const component = tab?.components?.find(entry => entry.id === componentId);
    if (!component) return;

    component.titleBackground =
        /^#[0-9a-f]{6}$/i.test(String(value || ''))
            ? value
            : 'none';

    saveDb();
    renderCustomTabView(tabId);
}

function openCustomTitleBackgroundMenu(anchor, tabId, componentId) {
    const tab = getCustomTab(tabId);
    const component = tab?.components?.find(entry => entry.id === componentId);
    if (!component) return;

    const rect = anchor.getBoundingClientRect();

    showCustomItemContextMenu(rect.right, rect.bottom + 4, [
        {
            label: 'Choose title color',
            icon: 'ph-palette',
            action: () => {
                const picker = document.createElement('input');
                picker.type = 'color';

                const current = String(component.titleBackground || '');
                picker.value = /^#[0-9a-f]{6}$/i.test(current)
                    ? current
                    : '#ffffff';

                picker.style.position = 'fixed';
                picker.style.left = '-9999px';
                picker.style.opacity = '0';

                picker.addEventListener('input', () => {
                    setCustomComponentTitleBackground(
                        tabId,
                        componentId,
                        picker.value
                    );
                });

                picker.addEventListener('change', () => picker.remove(), { once: true });
                document.body.appendChild(picker);
                picker.click();
            }
        },
        {
            label: 'Remove title background',
            icon: 'ph-x-circle',
            action: () => {
                setCustomComponentTitleBackground(tabId, componentId, 'none');
            }
        }
    ]);
}

function defaultCustomComponent(type) {
    const id = customId('component');

    switch (type) {
        case 'heading':
            return { id, type, text: 'New Heading', titleBackground: 'none' };

        case 'text':
            return { id, type, text: 'Add your text here.' };

        case 'search':
            return { id, type, placeholder: 'Search this tab...' };

        case 'cards':
            return {
                id,
                type,
                title: 'Cards',
                titleBackground: 'none',
                items: [
                    { id: customId('card'), title: 'Card One', body: 'Click edit to customize this card.' },
                    { id: customId('card'), title: 'Card Two', body: 'You can add as many cards as you want.' }
                ]
            };

        case 'polaroids':
            return {
                id,
                type,
                title: 'Polaroids',
                titleBackground: 'none',
                layout: 'normal',
                items: [
                    { id: customId('polaroid'), mediaType: 'image', image: '', youtubeUrl: '', mp4Url: '', pdfUrl: '', caption: 'Memory One' },
                    { id: customId('polaroid'), mediaType: 'image', image: '', youtubeUrl: '', mp4Url: '', pdfUrl: '', caption: 'Memory Two' }
                ]
            };

        case 'checklist':
            return {
                id,
                type,
                title: 'Checklist',
                titleBackground: 'none',
                items: [
                    { id: customId('check'), text: 'First item', done: false, completedAt: null },
                    { id: customId('check'), text: 'Second item', done: false, completedAt: null }
                ]
            };

        case 'practiceLog':
            return {
                id,
                type,
                title: 'Practice Log',
                titleBackground: 'none',
                entries: []
            };

        case 'progressMeter':
            return {
                id,
                type,
                title: 'Progress',
                titleBackground: 'none',
                current: 0,
                target: 10,
                unit: 'sessions'
            };

        case 'skillRatings':
            return {
                id,
                type,
                title: 'Skill Ratings',
                titleBackground: 'none',
                items: []
            };

        case 'vocabulary':
            return {
                id,
                type,
                title: 'Vocabulary',
                titleBackground: 'none',
                items: []
            };

        case 'resources':
            return {
                id,
                type,
                title: 'Resources',
                titleBackground: 'none',
                items: []
            };

        case 'dailyLogCollection':
            return {
                id,
                type,
                title: 'Daily Log Collection',
                titleBackground: 'none',
                sources: ['resources', 'videos', 'images', 'notes'],
                newestFirst: true
            };

        case 'milestones':
            return {
                id,
                type,
                title: 'Milestones',
                titleBackground: 'none',
                items: []
            };

        case 'projectGallery':
            return {
                id,
                type,
                title: 'Project Gallery',
                titleBackground: 'none',
                items: []
            };

        case 'recipeTracker':
            return {
                id,
                type,
                title: 'Recipe Tracker',
                titleBackground: 'none',
                items: []
            };

        case 'divider':
            return { id, type };

        case 'spacer':
            return { id, type, height: 36 };

        default:
            return { id, type: 'text', text: 'New component' };
    }
}

function addCustomComponent(tabId, type, index = null) {
    const tab = getCustomTab(tabId);
    if (!tab) return;
    if (!Array.isArray(tab.components)) tab.components = [];

    const component = defaultCustomComponent(type);

    if (index === null || index < 0 || index > tab.components.length) {
        tab.components.push(component);
    } else {
        tab.components.splice(index, 0, component);
    }

    saveDb();
    renderCustomTabView(tabId);
}

function renderCustomCanvas(tab, canvas) {
    if (!canvas) return;

    canvas.innerHTML = '';

    if (!Array.isArray(tab.components)) tab.components = [];

    if (!tab.components.length) {
        const empty = document.createElement('div');
        empty.className = 'custom-tab-empty-state';
        empty.innerHTML = customTabEditMode
            ? '<i class="ph ph-hand-grabbing"></i><strong>Drag your first component here</strong><span>Search bars, cards, polaroids, text, and more.</span>'
            : '<i class="ph ph-layout"></i><strong>This tab is empty</strong><span>Click the pencil to start building it.</span>';
        canvas.appendChild(empty);
    }

    tab.components.forEach((component, index) => {
        const wrapper = document.createElement('section');
        const titleBackground = String(component.titleBackground || 'none');
        const hasTitleBackground = /^#[0-9a-f]{6}$/i.test(titleBackground);

        wrapper.className =
            `custom-tab-component custom-component-${component.type}` +
            (hasTitleBackground ? ' custom-title-bg-color' : '');
        wrapper.dataset.componentId = component.id;

        if (hasTitleBackground) {
            wrapper.style.setProperty('--custom-title-bg', titleBackground);

            const hex = titleBackground.slice(1);
            const r = parseInt(hex.slice(0, 2), 16);
            const g = parseInt(hex.slice(2, 4), 16);
            const b = parseInt(hex.slice(4, 6), 16);
            const luminance = 0.299 * r + 0.587 * g + 0.114 * b;

            wrapper.style.setProperty(
                '--custom-title-fg',
                luminance > 160 ? '#000000' : '#ffffff'
            );
        }
        wrapper.draggable = customTabEditMode;

        if (customTabEditMode) {
            wrapper.classList.add('builder-component');

            const controls = document.createElement('div');
            controls.className = 'custom-component-controls';
            controls.innerHTML = `
                <span class="custom-drag-handle" title="Drag to reorder">
                    <i class="ph ph-dots-six-vertical"></i>
                </span>
                <button type="button" class="custom-component-edit" title="Edit component">
                    <i class="ph ph-pencil-simple"></i>
                </button>
                <button type="button" class="custom-component-duplicate" title="Duplicate component">
                    <i class="ph ph-copy"></i>
                </button>
                <button type="button" class="custom-component-delete" title="Move component to Trash">
                    <i class="ph ph-trash"></i>
                </button>
            `;
            wrapper.appendChild(controls);

            controls.querySelector('.custom-component-edit').addEventListener('click', e => {
                e.stopPropagation();
                editCustomComponent(tab.id, component.id);
            });

            controls.querySelector('.custom-component-duplicate')?.addEventListener('click', e => {
                e.stopPropagation();
                duplicateCustomComponent(tab.id, component.id);
            });

            if (customComponentSupportsTitleBackground(component)) {
                const titleStyleButton = document.createElement('button');
                titleStyleButton.type = 'button';
                titleStyleButton.className = 'custom-component-title-style';
                titleStyleButton.title = 'Title background';
                titleStyleButton.setAttribute('aria-label', 'Choose title background');
                titleStyleButton.innerHTML = '<i class="ph ph-paint-bucket"></i>';

                titleStyleButton.addEventListener('click', e => {
                    e.stopPropagation();
                    openCustomTitleBackgroundMenu(
                        titleStyleButton,
                        tab.id,
                        component.id
                    );
                });

                controls.insertBefore(
                    titleStyleButton,
                    controls.querySelector('.custom-component-delete')
                );
            }

            controls.querySelector('.custom-component-delete').addEventListener('click', e => {
                e.stopPropagation();
                deleteCustomComponent(tab.id, component.id);
            });

            wrapper.addEventListener('dragstart', e => {
                draggedCustomComponentId = component.id;
                e.dataTransfer.effectAllowed = 'move';
                e.dataTransfer.setData('text/custom-existing-component', component.id);
                wrapper.classList.add('dragging');
            });

            wrapper.addEventListener('dragend', () => {
                draggedCustomComponentId = null;
                wrapper.classList.remove('dragging');
            });
        }

        const content = document.createElement('div');
        content.className = 'custom-component-content';
        renderCustomComponentContent(tab, component, content);
        wrapper.appendChild(content);

        addCustomDropHandlers(wrapper, tab.id, index);
        canvas.appendChild(wrapper);
    });

    // End-of-canvas drop zone.
    if (customTabEditMode) {
        const endZone = document.createElement('div');
        endZone.className = 'custom-drop-zone custom-drop-zone-end';
        endZone.innerHTML = '<span>Drop component here</span>';

        endZone.addEventListener('dragover', e => {
            e.preventDefault();
            endZone.classList.add('drag-over');
        });

        endZone.addEventListener('dragleave', () => endZone.classList.remove('drag-over'));

        endZone.addEventListener('drop', e => {
            e.preventDefault();
            endZone.classList.remove('drag-over');
            handleCustomDrop(e, tab.id, tab.components.length);
        });

        canvas.appendChild(endZone);
    }
}

function addCustomDropHandlers(wrapper, tabId, index) {
    if (!customTabEditMode) return;

    wrapper.addEventListener('dragover', e => {
        e.preventDefault();
        wrapper.classList.add('drag-over');
    });

    wrapper.addEventListener('dragleave', () => wrapper.classList.remove('drag-over'));

    wrapper.addEventListener('drop', e => {
        e.preventDefault();
        e.stopPropagation();
        wrapper.classList.remove('drag-over');

        const rect = wrapper.getBoundingClientRect();
        const targetIndex = e.clientY > rect.top + rect.height / 2 ? index + 1 : index;
        handleCustomDrop(e, tabId, targetIndex);
    });
}

function handleCustomDrop(event, tabId, targetIndex) {
    const newType = event.dataTransfer.getData('text/custom-component-type');
    const existingId = event.dataTransfer.getData('text/custom-existing-component');

    if (newType) {
        addCustomComponent(tabId, newType, targetIndex);
        return;
    }

    if (existingId) {
        moveCustomComponent(tabId, existingId, targetIndex);
    }
}

function moveCustomComponent(tabId, componentId, targetIndex) {
    const tab = getCustomTab(tabId);
    if (!tab || !Array.isArray(tab.components)) return;

    const oldIndex = tab.components.findIndex(component => component.id === componentId);
    if (oldIndex < 0) return;

    const [component] = tab.components.splice(oldIndex, 1);

    if (oldIndex < targetIndex) targetIndex--;
    targetIndex = Math.max(0, Math.min(targetIndex, tab.components.length));

    tab.components.splice(targetIndex, 0, component);
    saveDb();
    renderCustomTabView(tabId);
}

async function deleteCustomComponent(tabId, componentId) {
    const tab = getCustomTab(tabId);
    if (!tab) return;

    const componentIndex = (tab.components || []).findIndex(component => component.id === componentId);
    if (componentIndex < 0) return;

    const component = tab.components[componentIndex];
    const confirmed = await showAppConfirm({
        title: 'Move component to Trash?',
        message: `“${getCustomComponentLabel(component)}” can be restored later from Trash.`,
        confirmLabel: 'Move to Trash'
    });
    if (!confirmed) return;

    moveCustomComponentToTrash(tab, componentIndex);
    saveDb();
    renderCustomTabView(tabId);
}

function renderCustomComponentContent(tab, component, content) {
    switch (component.type) {
        case 'heading':
            content.innerHTML = `<h2 class="custom-user-heading">${escapeCustomHtml(component.text || 'Heading')}</h2>`;
            break;

        case 'text':
            content.innerHTML = `<div class="custom-user-text">${escapeCustomHtml(component.text || '').replace(/\n/g, '<br>')}</div>`;
            break;

        case 'search':
            content.innerHTML = `
                <div class="custom-user-search-wrap">
                    <i class="ph ph-magnifying-glass"></i>
                    <input
                        type="text"
                        class="custom-user-search"
                        placeholder="${escapeCustomHtml(component.placeholder || 'Search this tab...')}"
                        aria-label="${escapeCustomHtml(component.placeholder || 'Search this tab')}"
                    >
                    <button type="button" class="custom-user-search-clear hidden" aria-label="Clear search">
                        <i class="ph ph-x"></i>
                    </button>
                </div>
            `;

            const input = content.querySelector('.custom-user-search');
            const clear = content.querySelector('.custom-user-search-clear');

            input.addEventListener('input', () => {
                clear.classList.toggle('hidden', !input.value);
                filterCustomTabItems(tab.id, input.value);
            });

            clear.addEventListener('click', () => {
                input.value = '';
                clear.classList.add('hidden');
                filterCustomTabItems(tab.id, '');
                input.focus();
            });
            break;

        case 'cards':
            renderCustomCards(tab, component, content);
            break;

        case 'polaroids':
            renderCustomPolaroids(tab, component, content);
            break;

        case 'checklist':
            renderCustomChecklist(tab, component, content);
            break;

        case 'practiceLog':
            renderPracticeLog(tab, component, content);
            break;

        case 'progressMeter':
            renderProgressMeter(tab, component, content);
            break;

        case 'skillRatings':
            renderSkillRatings(tab, component, content);
            break;

        case 'vocabulary':
            renderVocabulary(tab, component, content);
            break;

        case 'resources':
            renderResourceLinks(tab, component, content);
            break;

        case 'dailyLogCollection':
            renderDailyLogCollection(tab, component, content);
            break;

        case 'milestones':
            renderMilestones(tab, component, content);
            break;

        case 'projectGallery':
            renderProjectGallery(tab, component, content);
            break;

        case 'recipeTracker':
            renderRecipeTracker(tab, component, content);
            break;

        case 'divider':
            content.innerHTML = '<hr class="custom-user-divider">';
            break;

        case 'spacer':
            content.innerHTML = `<div class="custom-user-spacer" style="height:${Math.max(12, Number(component.height) || 36)}px"></div>`;
            break;

        default:
            content.textContent = 'Unsupported component';
    }
}

function renderCustomCards(tab, component, content) {
    const items = Array.isArray(component.items) ? component.items : [];

    content.innerHTML = `
        <div class="custom-collection-header">
            <h2>${escapeCustomHtml(component.title || 'Cards')}</h2>
            <button type="button" class="small-icon-btn add-custom-card" title="Add card">
                <i class="ph ph-plus"></i>
            </button>
        </div>
        <div class="custom-card-grid"></div>
    `;

    const grid = content.querySelector('.custom-card-grid');

    items.forEach(item => {
        const card = document.createElement('article');
        card.className = 'custom-user-card custom-searchable-item custom-content-editable';
        card.dataset.searchText = `${item.title || ''} ${item.body || ''}`.toLowerCase();
        card.dataset.customItemId = item.id;
        card.title = 'Right-click to edit or remove';

        card.innerHTML = `
            <h3>${escapeCustomHtml(item.title || 'Untitled Card')}</h3>
            <p>${escapeCustomHtml(item.body || '').replace(/\n/g, '<br>')}</p>
        `;

        card.addEventListener('contextmenu', event => {
            event.preventDefault();
            showCustomItemContextMenu(event.clientX, event.clientY, [
                {
                    label: 'Edit card',
                    icon: 'ph-pencil-simple',
                    action: () => editCustomCardItem(tab.id, component.id, item.id)
                },
                {
                    label: 'Delete card',
                    icon: 'ph-trash',
                    danger: true,
                    action: () => {
                        if (!confirm('Delete this card?')) return;
                        component.items = component.items.filter(entry => entry.id !== item.id);
                        saveDb();
                        renderCustomTabView(tab.id);
                    }
                }
            ]);
        });

        grid.appendChild(card);
    });

    content.querySelector('.add-custom-card')?.addEventListener('click', () => {
        const newItem = {
            id: customId('card'),
            title: 'New Card',
            body: 'Add a description.'
        };
        component.items.push(newItem);
        saveDb();
        renderCustomTabView(tab.id);

        // Immediately allow content entry without entering layout edit mode.
        setTimeout(() => editCustomCardItem(tab.id, component.id, newItem.id), 0);
    });
}


function getPolaroidYouTubeId(url) {
    const value = String(url || '').trim();
    if (!value) return '';

    // Reuse the app's existing YouTube parser when available.
    try {
        if (typeof extractYoutubeId === 'function') {
            const parsed = extractYoutubeId(value);
            if (parsed) return parsed;
        }
    } catch (e) {}

    const patterns = [
        /youtu\.be\/([A-Za-z0-9_-]{6,})/,
        /youtube\.com\/watch\?.*v=([A-Za-z0-9_-]{6,})/,
        /youtube\.com\/shorts\/([A-Za-z0-9_-]{6,})/,
        /youtube\.com\/embed\/([A-Za-z0-9_-]{6,})/
    ];

    for (const pattern of patterns) {
        const match = value.match(pattern);
        if (match?.[1]) return match[1];
    }

    return '';
}

function getPolaroidMediaType(item) {
    if (item?.mediaType) return item.mediaType;
    if (item?.pdfUrl) return 'pdf';
    if (item?.youtubeUrl) return 'youtube';
    if (item?.mp4Url) return 'mp4';
    if (item?.image) return 'image';
    return 'none';
}

function renderPolaroidMediaHtml(item) {
    const mediaType = getPolaroidMediaType(item);

    if (mediaType === 'youtube') {
        const youtubeUrl = item.youtubeUrl || item.mediaUrl || '';
        const videoId = getPolaroidYouTubeId(youtubeUrl);

        if (videoId) {
            const embedUrl =
                `https://www.youtube.com/embed/${encodeURIComponent(videoId)}` +
                `?autoplay=1&mute=1&loop=1&playlist=${encodeURIComponent(videoId)}` +
                `&playsinline=1&rel=0`;

            return `
                <iframe
                    class="custom-polaroid-youtube"
                    src="${escapeCustomHtml(embedUrl)}"
                    title="${escapeCustomHtml(item.caption || 'YouTube video')}"
                    allow="autoplay; encrypted-media; picture-in-picture"
                    allowfullscreen
                ></iframe>
            `;
        }
    }

    if (mediaType === 'mp4') {
        const src = item.mp4Url || item.mediaUrl || '';
        if (src) {
            return `
                <video
                    class="custom-polaroid-video"
                    src="${escapeCustomHtml(src)}"
                    autoplay
                    muted
                    loop
                    playsinline
                    controls
                    preload="metadata"
                ></video>
            `;
        }
    }

    if (mediaType === 'pdf') {
        const src = item.pdfUrl || item.mediaUrl || '';
        if (src) {
            const previewSrc =
                src.startsWith('data:')
                    ? src
                    : `${src}${src.includes('#') ? '' : '#toolbar=0&navpanes=0&scrollbar=0'}`;

            return `
                <iframe
                    class="custom-polaroid-pdf"
                    src="${escapeCustomHtml(previewSrc)}"
                    title="${escapeCustomHtml(item.caption || 'PDF preview')}"
                    loading="lazy"
                ></iframe>
            `;
        }
    }

    if (item?.image) {
        return `
            <img
                src="${escapeCustomHtml(item.image)}"
                alt="${escapeCustomHtml(item.caption || 'Polaroid image')}"
            >
        `;
    }

    return `<div class="custom-polaroid-placeholder"><i class="ph ph-image"></i></div>`;
}

async function promptForPolaroidUrl(type, existingValue = '') {
    const isYouTube = type === 'youtube';
    const isPdf = type === 'pdf';

    const result = await showAppFormModal({
        title:
            isYouTube
                ? 'Add YouTube Video'
                : isPdf
                    ? 'Link a PDF'
                    : 'Add MP4 Video',
        submitLabel: 'Add',
        fields: [
            {
                name: 'url',
                label:
                    isYouTube
                        ? 'YouTube URL'
                        : isPdf
                            ? 'PDF URL'
                            : 'MP4 URL',
                type: 'url',
                value:
                    existingValue ||
                    (
                        isYouTube
                            ? 'https://www.youtube.com/watch?v='
                            : 'https://'
                    ),
                placeholder:
                    isYouTube
                        ? 'https://www.youtube.com/watch?v=…'
                        : isPdf
                            ? 'https://example.com/file.pdf'
                            : 'https://example.com/video.mp4'
            }
        ]
    });

    if (!result) return null;

    const trimmed = String(result.url || '').trim();
    if (!trimmed) return null;

    if (isYouTube && !getPolaroidYouTubeId(trimmed)) {
        const retry = await showAppFormModal({
            title: 'That YouTube link is not valid',
            submitLabel: 'Try Again',
            fields: [
                {
                    name: 'url',
                    label: 'Paste a YouTube watch, Shorts, youtu.be, or embed URL',
                    type: 'url',
                    value: trimmed
                }
            ]
        });

        if (!retry) return null;

        const next = String(retry.url || '').trim();
        return getPolaroidYouTubeId(next) ? next : null;
    }

    return trimmed;
}

async function addPolaroidPhotoFiles(tab, component, files) {
    const selectedFiles = Array.from(files || []);
    if (!selectedFiles.length) return;

    for (const file of selectedFiles) {
        const image = await customImageFileToDataUrl(file);
        if (!image) continue;

        component.items.push({
            id: customId('polaroid'),
            mediaType: 'image',
            image,
            youtubeUrl: '',
            mp4Url: '',
            pdfUrl: '',
            caption: file.name.replace(/\.[^.]+$/, '') || 'New Polaroid'
        });
    }

    saveDb();
    renderCustomTabView(tab.id);
}

async function addPolaroidUrlItem(tab, component, mediaType) {
    const url = await promptForPolaroidUrl(mediaType);
    if (!url) return;

    const defaultCaption =
        mediaType === 'youtube'
            ? 'YouTube Video'
            : mediaType === 'pdf'
                ? 'PDF'
                : 'Video';

    const caption = await showAppPrompt({
        title: 'Polaroid Caption',
        label: 'Caption',
        value: defaultCaption,
        submitLabel: 'Add'
    });

    if (caption === null) return;

    const item = {
        id: customId('polaroid'),
        mediaType,
        image: '',
        youtubeUrl: mediaType === 'youtube' ? url : '',
        mp4Url: mediaType === 'mp4' ? url : '',
        pdfUrl: mediaType === 'pdf' ? url : '',
        caption: caption.trim() || defaultCaption
    };

    component.items.push(item);
    saveDb();
    renderCustomTabView(tab.id);
}

function customFileToDataUrl(file) {
    return new Promise(resolve => {
        if (!file) {
            resolve('');
            return;
        }

        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => resolve('');
        reader.readAsDataURL(file);
    });
}

async function addPolaroidPdfFiles(tab, component, files) {
    const selectedFiles = Array.from(files || []);
    if (!selectedFiles.length) return;

    for (const file of selectedFiles) {
        const isPdf =
            file.type === 'application/pdf' ||
            /\.pdf$/i.test(file.name || '');

        if (!isPdf) continue;

        const pdfUrl = await customFileToDataUrl(file);
        if (!pdfUrl) continue;

        component.items.push({
            id: customId('polaroid'),
            mediaType: 'pdf',
            image: '',
            youtubeUrl: '',
            mp4Url: '',
            pdfUrl,
            caption: file.name.replace(/\.pdf$/i, '') || 'PDF'
        });
    }

    saveDb();
    renderCustomTabView(tab.id);
}

function openPolaroidAddMenu(anchor, tab, component, fileInput, pdfInput) {
    const rect = anchor.getBoundingClientRect();

    showCustomItemContextMenu(rect.right, rect.bottom + 4, [
        {
            label: 'Upload photo',
            icon: 'ph-image',
            action: () => {
                fileInput.value = '';
                fileInput.click();
            }
        },
        {
            label: 'Add YouTube video',
            icon: 'ph-youtube-logo',
            action: () => addPolaroidUrlItem(tab, component, 'youtube')
        },
        {
            label: 'Add MP4 video',
            icon: 'ph-video',
            action: () => addPolaroidUrlItem(tab, component, 'mp4')
        },
        {
            label: 'Upload PDF',
            icon: 'ph-file-pdf',
            action: () => {
                pdfInput.value = '';
                pdfInput.click();
            }
        },
        {
            label: 'Link PDF',
            icon: 'ph-link',
            action: () => addPolaroidUrlItem(tab, component, 'pdf')
        }
    ]);
}

async function replacePolaroidMedia(tabId, componentId, itemId, mediaType) {
    const tab = getCustomTab(tabId);
    const component = tab?.components?.find(entry => entry.id === componentId);
    const item = component?.items?.find(entry => entry.id === itemId);
    if (!item) return;

    if (mediaType === 'image' || mediaType === 'pdf-upload') {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = mediaType === 'image' ? 'image/*' : 'application/pdf,.pdf';
        input.className = 'hidden';

        input.addEventListener('change', async () => {
            const file = input.files?.[0];
            if (!file) {
                input.remove();
                return;
            }

            const value =
                mediaType === 'image'
                    ? await customImageFileToDataUrl(file)
                    : await customFileToDataUrl(file);

            input.remove();
            if (!value) return;

            item.mediaType = mediaType === 'image' ? 'image' : 'pdf';
            item.image = mediaType === 'image' ? value : '';
            item.youtubeUrl = '';
            item.mp4Url = '';
            item.pdfUrl = mediaType === 'pdf-upload' ? value : '';

            saveDb();
            renderCustomTabView(tabId);
        });

        document.body.appendChild(input);
        input.click();
        return;
    }

    const existing =
        mediaType === 'youtube'
            ? (item.youtubeUrl || '')
            : mediaType === 'pdf'
                ? (item.pdfUrl || '')
                : (item.mp4Url || '');

    const url = await promptForPolaroidUrl(mediaType, existing);
    if (!url) return;

    item.mediaType = mediaType;
    item.image = '';
    item.youtubeUrl = mediaType === 'youtube' ? url : '';
    item.mp4Url = mediaType === 'mp4' ? url : '';
    item.pdfUrl = mediaType === 'pdf' ? url : '';

    saveDb();
    renderCustomTabView(tabId);
}

function renderCustomPolaroids(tab, component, content) {
    const items = Array.isArray(component.items) ? component.items : [];
    const layout = ['normal', 'vertical', 'horizontal'].includes(component.layout)
        ? component.layout
        : 'normal';

    component.layout = layout;

    content.innerHTML = `
        <div class="custom-collection-header">
            <h2>${escapeCustomHtml(component.title || 'Polaroids')}</h2>

            <div class="custom-polaroid-header-actions">
                ${customTabEditMode ? `
                    <select class="custom-polaroid-layout-select" aria-label="Polaroid shape">
                        <option value="normal" ${layout === 'normal' ? 'selected' : ''}>Normal</option>
                        <option value="vertical" ${layout === 'vertical' ? 'selected' : ''}>Vertical</option>
                        <option value="horizontal" ${layout === 'horizontal' ? 'selected' : ''}>Horizontal</option>
                    </select>
                ` : ''}

                <button
                    type="button"
                    class="small-icon-btn add-custom-polaroid"
                    title="Add photo, video, or PDF"
                >
                    <i class="ph ph-plus"></i>
                </button>
            </div>
        </div>

        <input
            type="file"
            class="custom-polaroid-file-input hidden"
            accept="image/*"
            multiple
        >

        <input
            type="file"
            class="custom-polaroid-pdf-input hidden"
            accept="application/pdf,.pdf"
            multiple
        >

        <div class="custom-polaroid-grid custom-polaroid-layout-${layout}"></div>
    `;

    const grid = content.querySelector('.custom-polaroid-grid');
    const fileInput = content.querySelector('.custom-polaroid-file-input');
    const pdfInput = content.querySelector('.custom-polaroid-pdf-input');
    const layoutSelect = content.querySelector('.custom-polaroid-layout-select');
    const addButton = content.querySelector('.add-custom-polaroid');

    items.forEach(item => {
        const polaroid = document.createElement('article');
        polaroid.className =
            'custom-user-polaroid custom-searchable-item custom-content-editable';

        polaroid.dataset.searchText = `${item.caption || ''}`.toLowerCase();
        polaroid.dataset.customItemId = item.id;
        polaroid.title = 'Right-click to edit, replace media, or remove';

        polaroid.innerHTML = `
            <div class="custom-polaroid-media">
                ${renderPolaroidMediaHtml(item)}
            </div>
            <div class="custom-polaroid-caption">
                ${escapeCustomHtml(item.caption || 'Untitled')}
            </div>
        `;

        polaroid.addEventListener('contextmenu', event => {
            event.preventDefault();

            showCustomItemContextMenu(event.clientX, event.clientY, [
                {
                    label: 'Edit caption',
                    icon: 'ph-pencil-simple',
                    action: async () => {
                        const caption = await showAppPrompt({
                            title: 'Edit Polaroid Caption',
                            label: 'Caption',
                            value: item.caption || ''
                        });

                        if (caption === null) return;

                        item.caption = caption.trim() || 'Untitled';
                        saveDb();
                        renderCustomTabView(tab.id);
                    }
                },
                {
                    label: 'Replace with photo',
                    icon: 'ph-image',
                    action: () => {
                        replacePolaroidMedia(
                            tab.id,
                            component.id,
                            item.id,
                            'image'
                        );
                    }
                },
                {
                    label: 'Replace with YouTube',
                    icon: 'ph-youtube-logo',
                    action: () => {
                        replacePolaroidMedia(
                            tab.id,
                            component.id,
                            item.id,
                            'youtube'
                        );
                    }
                },
                {
                    label: 'Replace with MP4',
                    icon: 'ph-video',
                    action: () => {
                        replacePolaroidMedia(
                            tab.id,
                            component.id,
                            item.id,
                            'mp4'
                        );
                    }
                },
                {
                    label: 'Replace with uploaded PDF',
                    icon: 'ph-file-pdf',
                    action: () => {
                        replacePolaroidMedia(
                            tab.id,
                            component.id,
                            item.id,
                            'pdf-upload'
                        );
                    }
                },
                {
                    label: 'Replace with linked PDF',
                    icon: 'ph-link',
                    action: () => {
                        replacePolaroidMedia(
                            tab.id,
                            component.id,
                            item.id,
                            'pdf'
                        );
                    }
                },
                {
                    label: 'Delete polaroid',
                    icon: 'ph-trash',
                    danger: true,
                    action: () => {
                        if (!confirm('Delete this polaroid?')) return;

                        component.items =
                            component.items.filter(
                                entry => entry.id !== item.id
                            );

                        saveDb();
                        renderCustomTabView(tab.id);
                    }
                }
            ]);
        });

        grid.appendChild(polaroid);
    });

    layoutSelect?.addEventListener('change', () => {
        component.layout = layoutSelect.value;
        saveDb();
        renderCustomTabView(tab.id);
    });

    addButton?.addEventListener('click', () => {
        openPolaroidAddMenu(addButton, tab, component, fileInput, pdfInput);
    });

    fileInput.addEventListener('change', async () => {
        await addPolaroidPhotoFiles(
            tab,
            component,
            fileInput.files
        );
    });

    pdfInput.addEventListener('change', async () => {
        await addPolaroidPdfFiles(
            tab,
            component,
            pdfInput.files
        );
    });
}

function renderCustomChecklist(tab, component, content) {
    const items = Array.isArray(component.items) ? component.items : [];

    content.innerHTML = `
        <div class="custom-collection-header">
            <h2>${escapeCustomHtml(component.title || 'Checklist')}</h2>
            <button type="button" class="small-icon-btn add-custom-check" title="Add checklist item">
                <i class="ph ph-plus"></i>
            </button>
        </div>
        <div class="custom-checklist"></div>
    `;

    const list = content.querySelector('.custom-checklist');

    const sortedItems = items.slice().sort((a, b) => {
        if (!!a.done !== !!b.done) return a.done ? 1 : -1;
        if (a.done && b.done) {
            return String(a.completedAt || '').localeCompare(String(b.completedAt || ''));
        }
        return 0;
    });

    sortedItems.forEach(item => {
        const row = document.createElement('label');
        row.className =
            `custom-check-row custom-searchable-item custom-content-editable${item.done ? ' done' : ''}`;
        row.dataset.searchText = String(item.text || '').toLowerCase();
        row.dataset.customItemId = item.id;
        row.title = 'Right-click to edit or remove';

        const completedDate = item.done && item.completedAt
            ? new Date(item.completedAt).toLocaleDateString('en-US', {
                month: 'short',
                day: 'numeric',
                year: 'numeric'
            })
            : '';

        row.innerHTML = `
            <input type="checkbox" ${item.done ? 'checked' : ''}>
            <span class="custom-check-text">${escapeCustomHtml(item.text || 'Checklist item')}</span>
            ${completedDate ? `<span class="custom-check-date">${escapeCustomHtml(completedDate)}</span>` : ''}
        `;

        row.querySelector('input').addEventListener('change', e => {
            item.done = e.target.checked;
            item.completedAt = item.done ? new Date().toISOString() : null;
            saveDb();
            renderCustomTabView(tab.id);
        });

        row.addEventListener('contextmenu', event => {
            event.preventDefault();
            showCustomItemContextMenu(event.clientX, event.clientY, [
                {
                    label: 'Edit item',
                    icon: 'ph-pencil-simple',
                    action: () => {
                        const value = prompt('Checklist item:', item.text || '');
                        if (value !== null && value.trim()) {
                            item.text = value.trim();
                            saveDb();
                            renderCustomTabView(tab.id);
                        }
                    }
                },
                {
                    label: 'Delete item',
                    icon: 'ph-trash',
                    danger: true,
                    action: () => {
                        if (!confirm('Delete this checklist item?')) return;
                        component.items = component.items.filter(entry => entry.id !== item.id);
                        saveDb();
                        renderCustomTabView(tab.id);
                    }
                }
            ]);
        });

        list.appendChild(row);
    });

    content.querySelector('.add-custom-check')?.addEventListener('click', () => {
        const value = prompt('New checklist item:', '');
        if (value === null || !value.trim()) return;

        component.items.push({
            id: customId('check'),
            text: value.trim(),
            done: false,
            completedAt: null
        });

        saveDb();
        renderCustomTabView(tab.id);
    });
}


function learningSectionHeader(component, addClass, addTitle = 'Add') {
    return `
        <div class="custom-collection-header">
            <h2>${escapeCustomHtml(component.title || 'Section')}</h2>
            <button type="button" class="small-icon-btn ${addClass}" title="${escapeCustomHtml(addTitle)}">
                <i class="ph ph-plus"></i>
            </button>
        </div>
    `;
}

function renderPracticeLog(tab, component, content) {
    if (!Array.isArray(component.entries)) component.entries = [];

    content.innerHTML = `
        ${learningSectionHeader(component, 'add-practice-entry', 'Add practice session')}
        <div class="learning-practice-log"></div>
    `;

    const list = content.querySelector('.learning-practice-log');

    component.entries.slice().reverse().forEach(entry => {
        const row = document.createElement('article');
        row.className = 'learning-log-entry custom-searchable-item custom-content-editable';
        row.dataset.searchText = `${entry.date || ''} ${entry.minutes || ''} ${entry.focus || ''} ${entry.notes || ''}`.toLowerCase();
        row.dataset.customItemId = entry.id;
        row.title = 'Right-click to edit or remove';
        row.innerHTML = `
            <div class="learning-log-main">
                <strong>${escapeCustomHtml(entry.focus || 'Practice')}</strong>
                <span>${escapeCustomHtml(entry.date || '')}</span>
            </div>
            <div class="learning-log-meta">${Number(entry.minutes) || 0} min</div>
            ${entry.notes ? `<p>${escapeCustomHtml(entry.notes)}</p>` : ''}
        `;

        row.addEventListener('contextmenu', e => {
            e.preventDefault();
            showCustomItemContextMenu(e.clientX, e.clientY, [
                {
                    label: 'Edit session',
                    icon: 'ph-pencil-simple',
                    action: () => editPracticeEntry(tab, component, entry)
                },
                {
                    label: 'Delete session',
                    icon: 'ph-trash',
                    danger: true,
                    action: () => {
                        component.entries = component.entries.filter(x => x.id !== entry.id);
                        saveDb();
                        renderCustomTabView(tab.id);
                    }
                }
            ]);
        });

        list.appendChild(row);
    });

    content.querySelector('.add-practice-entry').addEventListener('click', () => {
        const focus = prompt('What did you practice?', '');
        if (focus === null) return;
        const minutes = Number(prompt('How many minutes?', '30') || 0);
        const notes = prompt('Notes (optional):', '') ?? '';

        component.entries.push({
            id: customId('practice'),
            date: new Date().toISOString().slice(0, 10),
            minutes: Math.max(0, minutes),
            focus: focus.trim() || 'Practice',
            notes
        });

        saveDb();
        renderCustomTabView(tab.id);
    });
}

function editPracticeEntry(tab, component, entry) {
    const focus = prompt('What did you practice?', entry.focus || '');
    if (focus === null) return;
    const minutes = Number(prompt('Minutes:', String(entry.minutes || 0)) || 0);
    const notes = prompt('Notes:', entry.notes || '');
    if (notes === null) return;

    entry.focus = focus.trim() || 'Practice';
    entry.minutes = Math.max(0, minutes);
    entry.notes = notes;
    saveDb();
    renderCustomTabView(tab.id);
}

function renderProgressMeter(tab, component, content) {
    const current = Math.max(0, Number(component.current) || 0);
    const target = Math.max(1, Number(component.target) || 1);
    const percent = Math.min(100, Math.round((current / target) * 100));

    content.innerHTML = `
        <div class="custom-collection-header">
            <h2>${escapeCustomHtml(component.title || 'Progress')}</h2>
            <div class="learning-inline-actions">
                <button type="button" class="small-icon-btn progress-minus" title="Subtract one">
                    <i class="ph ph-minus"></i>
                </button>
                <button type="button" class="small-icon-btn progress-plus" title="Add one">
                    <i class="ph ph-plus"></i>
                </button>
            </div>
        </div>

        <div class="learning-progress-card custom-content-editable" title="Right-click to edit goal">
            <div class="learning-progress-number">
                <strong>${current}</strong>
                <span>/ ${target} ${escapeCustomHtml(component.unit || '')}</span>
            </div>
            <div class="learning-progress-track">
                <div class="learning-progress-fill" style="width:${percent}%"></div>
            </div>
            <div class="learning-progress-percent">${percent}%</div>
        </div>
    `;

    const saveValue = value => {
        component.current = Math.max(0, value);
        saveDb();
        renderCustomTabView(tab.id);
    };

    content.querySelector('.progress-minus').addEventListener('click', () => saveValue(current - 1));
    content.querySelector('.progress-plus').addEventListener('click', () => saveValue(current + 1));

    content.querySelector('.learning-progress-card').addEventListener('contextmenu', e => {
        e.preventDefault();
        showCustomItemContextMenu(e.clientX, e.clientY, [
            {
                label: 'Edit progress goal',
                icon: 'ph-pencil-simple',
                action: () => {
                    const title = prompt('Progress title:', component.title || 'Progress');
                    if (title === null) return;
                    const targetValue = Number(prompt('Target amount:', String(target)) || target);
                    const unit = prompt('Unit (sessions, recipes, tricks, lessons, etc.):', component.unit || '');
                    if (unit === null) return;

                    component.title = title.trim() || 'Progress';
                    component.target = Math.max(1, targetValue);
                    component.unit = unit.trim();
                    saveDb();
                    renderCustomTabView(tab.id);
                }
            }
        ]);
    });
}

function renderSkillRatings(tab, component, content) {
    if (!Array.isArray(component.items)) component.items = [];

    content.innerHTML = `
        ${learningSectionHeader(component, 'add-skill-rating', 'Add skill')}
        <div class="learning-skill-list"></div>
    `;

    const list = content.querySelector('.learning-skill-list');

    component.items.forEach(item => {
        const row = document.createElement('div');
        row.className = 'learning-skill-row custom-searchable-item custom-content-editable';
        row.dataset.searchText = `${item.name || ''}`.toLowerCase();
        row.dataset.customItemId = item.id;
        row.title = 'Right-click to edit or remove';

        const rating = Math.max(1, Math.min(5, Number(item.rating) || 1));
        row.innerHTML = `
            <span>${escapeCustomHtml(item.name || 'Skill')}</span>
            <div class="learning-stars" aria-label="${rating} out of 5">
                ${Array.from({length:5}, (_, i) => `<i class="ph ${i < rating ? 'ph-star-fill' : 'ph-star'}"></i>`).join('')}
            </div>
        `;

        row.addEventListener('contextmenu', e => {
            e.preventDefault();
            showCustomItemContextMenu(e.clientX, e.clientY, [
                {
                    label: 'Edit rating',
                    icon: 'ph-pencil-simple',
                    action: () => {
                        const name = prompt('Skill:', item.name || '');
                        if (name === null) return;
                        const value = Number(prompt('Confidence 1-5:', String(rating)) || rating);
                        item.name = name.trim() || 'Skill';
                        item.rating = Math.max(1, Math.min(5, value));
                        saveDb();
                        renderCustomTabView(tab.id);
                    }
                },
                {
                    label: 'Delete skill',
                    icon: 'ph-trash',
                    danger: true,
                    action: () => {
                        component.items = component.items.filter(x => x.id !== item.id);
                        saveDb();
                        renderCustomTabView(tab.id);
                    }
                }
            ]);
        });

        list.appendChild(row);
    });

    content.querySelector('.add-skill-rating').addEventListener('click', () => {
        const name = prompt('Skill name:', '');
        if (name === null || !name.trim()) return;
        const rating = Number(prompt('Confidence 1-5:', '1') || 1);

        component.items.push({
            id: customId('skill'),
            name: name.trim(),
            rating: Math.max(1, Math.min(5, rating))
        });

        saveDb();
        renderCustomTabView(tab.id);
    });
}

