function editVocabularyItem(tab, component, item) {
    const term = prompt('Word / phrase:', item.term || '');
    if (term === null) return;
    const meaning = prompt('Meaning / translation:', item.meaning || '');
    if (meaning === null) return;
    const note = prompt('Pronunciation, example, or note:', item.note || '');
    if (note === null) return;

    item.term = term.trim() || 'Term';
    item.meaning = meaning;
    item.note = note;
    saveDb();
    renderCustomTabView(tab.id);
}

