function pruneBlankCustomTabIconChoices(picker) {
    if (!picker) return;

    const prune = () => {
        const seen = new Set();

        picker
            .querySelectorAll(
                '.custom-tab-icon-choice'
            )
            .forEach(choice => {
                const iconName =
                    choice.dataset.icon;

                if (iconName === 'custom-skateboard') {
                    seen.add(iconName);
                    return;
                }

                const icon =
                    choice.querySelector('i');

                // Remove duplicate icon choices.
                if (seen.has(iconName)) {
                    choice.remove();
                    return;
                }

                seen.add(iconName);

                const content =
                    icon
                        ? getComputedStyle(
                            icon,
                            '::before'
                        ).content
                        : '';

                const blank =
                    !content ||
                    content === 'none' ||
                    content === 'normal' ||
                    content === '""';

                if (blank) {
                    choice.remove();
                }
            });

        if (
            !picker.querySelector(
                '.custom-tab-icon-choice.selected'
            )
        ) {
            picker
                .querySelector(
                    '.custom-tab-icon-choice'
                )
                ?.classList.add(
                    'selected'
                );
        }
    };

    // Phosphor's stylesheet may finish after this modal is first built.
    requestAnimationFrame(prune);
    setTimeout(prune, 300);
}

function ensureCustomTabCreateModal() {
    if (document.getElementById('custom-tab-create-modal')) return;

    const modal = document.createElement('div');
    modal.id = 'custom-tab-create-modal';
    modal.className = 'modal-overlay hidden custom-tab-modal';

    modal.innerHTML = `
        <div class="modal-box custom-tab-modal-box">
            <div class="modal-header">
                <h2>Create Tab</h2>
                <button type="button" class="small-icon-btn custom-tab-create-close"><i class="ph ph-x"></i></button>
            </div>

            <div class="modal-section">
                <span class="field-label">Tab Name</span>
                <input id="custom-tab-name-input" type="text" maxlength="28" placeholder="My Tab">
            </div>

            <div class="modal-section">
                <span class="field-label">Icon</span>
                <div class="theme-search-wrap custom-icon-search-box">
                    <i class="ph ph-magnifying-glass"></i>
                    <input
                        id="custom-tab-icon-search"
                        class="theme-search-input"
                        type="search"
                        placeholder="Search icons…"
                        autocomplete="off"
                    >
                </div>
                <div id="custom-tab-icon-picker" class="custom-tab-icon-picker"></div>
            </div>

            <div class="modal-section custom-tab-daily-source-section">
                <span class="field-label">Start with Daily Log content</span>
                <p class="custom-tab-create-hint">Optional — automatically collect things you have saved across Daily Logs into this tab.</p>
                <div class="custom-tab-daily-source-grid">
                    <label><input type="checkbox" value="resources"> <i class="ph ph-link"></i> Media Resources</label>
                    <label><input type="checkbox" value="videos"> <i class="ph ph-video"></i> Videos</label>
                    <label><input type="checkbox" value="images"> <i class="ph ph-image"></i> Images</label>
                    <label><input type="checkbox" value="pdfs"> <i class="ph ph-file-pdf"></i> PDFs</label>
                    <label><input type="checkbox" value="notes"> <i class="ph ph-note-pencil"></i> Notes</label>
                    <label><input type="checkbox" value="textFields"> <i class="ph ph-textbox"></i> Other Text Fields</label>
                    <label><input type="checkbox" value="audio"> <i class="ph ph-waveform"></i> Audio</label>
                    <label><input type="checkbox" value="knowledge"> <i class="ph ph-books"></i> Knowledge Items</label>
                </div>
            </div>

            <div class="modal-section custom-tab-connections-option-v32">
                <span class="field-label">Daily Log Connections</span>
                <p class="custom-tab-create-hint">Optional — add a visual map of how your Daily Logs connect to one another.</p>
                <label class="custom-tab-connections-toggle-v32">
                    <input type="checkbox" id="custom-tab-add-connections-map">
                    <span><i class="ph ph-graph"></i> Add Daily Log Connections Map</span>
                </label>
            </div>

            <button type="button" id="custom-tab-create-confirm" data-enter-submit="true" class="icon-btn custom-tab-primary-btn">
                <i class="ph ph-plus"></i>
                Create Tab
            </button>
        </div>
    `;

    document.body.appendChild(modal);

    const picker = modal.querySelector('#custom-tab-icon-picker');
    CUSTOM_TAB_ICON_CHOICES.forEach(([icon, label], index) => {
        const choice = document.createElement('button');
        choice.type = 'button';
        choice.className = `custom-tab-icon-choice${index === 0 ? ' selected' : ''}`;
        choice.dataset.icon = icon;
        choice.dataset.label = label;
        choice.title = label;
        choice.setAttribute('aria-label', label);
        choice.innerHTML = renderCustomTabIcon(icon);
        choice.addEventListener('click', () => {
            picker.querySelectorAll('.custom-tab-icon-choice').forEach(item => item.classList.remove('selected'));
            choice.classList.add('selected');
        });
        picker.appendChild(choice);
    });

    pruneBlankCustomTabIconChoices(picker);
    ensureCustomTabIconSearch(
        modal.querySelector('#custom-tab-icon-search'),
        picker
    );

    modal.querySelector('.custom-tab-create-close').addEventListener('click', closeCustomTabCreateModal);
    modal.addEventListener('click', e => {
        if (e.target === modal) closeCustomTabCreateModal();
    });

    modal.querySelector('#custom-tab-create-confirm').addEventListener('click', createCustomTabFromModal);
}

function openCustomTabCreateModal() {
    const modal = document.getElementById('custom-tab-create-modal');
    if (!modal) return;

    const input = modal.querySelector('#custom-tab-name-input');
    input.value = '';

    const iconSearch = modal.querySelector('#custom-tab-icon-search');
    if (iconSearch) {
        iconSearch.value = '';
        modal.querySelectorAll('.custom-tab-icon-choice').forEach(choice =>
            choice.classList.remove('icon-search-hidden')
        );
    }

    const choices = modal.querySelectorAll('.custom-tab-icon-choice');
    choices.forEach((choice, index) => choice.classList.toggle('selected', index === 0));

    modal.querySelectorAll('.custom-tab-daily-source-grid input[type="checkbox"]').forEach(input => {
        input.checked = false;
    });

    
    const connectionMapToggleV32 =
        modal.querySelector('#custom-tab-add-connections-map');
    if (connectionMapToggleV32) connectionMapToggleV32.checked = false;

    modal.classList.remove('hidden');
    setTimeout(() => input.focus(), 0);
}

function closeCustomTabCreateModal() {
    document.getElementById('custom-tab-create-modal')?.classList.add('hidden');
}

function createCustomTabFromModal() {
    const modal = document.getElementById('custom-tab-create-modal');
    const input = modal?.querySelector('#custom-tab-name-input');
    if (!modal || !input) return;

    const name = input.value.trim() || 'My Tab';
    const icon = modal.querySelector('.custom-tab-icon-choice.selected')?.dataset.icon || 'ph-squares-four';

    const chosenDailySources = Array.from(
        modal.querySelectorAll('.custom-tab-daily-source-grid input[type="checkbox"]:checked')
    ).map(input => input.value);

    const tab = {
        id: customId('tab'),
        name,
        icon,
        components: []
    };

    if (chosenDailySources.length) {
        tab.components.push({
            ...defaultCustomComponent('dailyLogCollection'),
            sources: chosenDailySources
        });
    }

    if (modal.querySelector('#custom-tab-add-connections-map')?.checked) {
        tab.components.push({
            id: customId('component'),
            type: 'dailyConnectionsGraph',
            title: 'Daily Log Connections',
            titleBackground: 'none'
        });
    }

    getCustomTabs().push(tab);
    saveDb();

    closeCustomTabCreateModal();
    renderCustomTabNavigation();

    const view = buildCustomTabView(tab);
    document.body.insertBefore(view, document.getElementById('companion-stage') || null);

    activeCustomTabId = tab.id;
    customTabEditMode = false;
    renderCustomTabView(tab.id);
    switchView(view);
}

