let featureCommandPaletteIndex = -1;

function featureCustomItemSearchLabel(component, item) {
    try {
        if (typeof getCustomItemLabel === 'function') {
            return getCustomItemLabel(component, item);
        }
    } catch (error) {}

    return item?.title || item?.name || item?.text || item?.term || item?.focus || component?.title || component?.type || 'Item';
}

function featureOpenCustomItem(tabId, itemId) {
    openCustomTab(tabId);
    requestAnimationFrame(() => {
        const view = document.getElementById(`custom-tab-view-${tabId}`);
        const target = view?.querySelector(`[data-custom-item-id="${CSS.escape(String(itemId))}"]`);
        if (!target) return;
        target.scrollIntoView({ behavior: 'smooth', block: 'center' });
        target.classList.add('global-search-target-highlight');
        setTimeout(() => target.classList.remove('global-search-target-highlight'), 1800);
    });
}

