function ensureGlobalCommandPalette() {
    let modal = document.getElementById('global-command-palette');
    if (modal) return modal;

    modal = document.createElement('div');
    modal.id = 'global-command-palette';
    modal.className = 'modal-overlay hidden global-command-palette';
    modal.innerHTML = `
        <div class="global-command-box" role="dialog" aria-modal="true" aria-label="Global Search">
            <div class="global-command-input-wrap">
                <i class="ph ph-magnifying-glass"></i>
                <input type="search" class="global-command-input" placeholder="Search Daily Logs, Knowledge Base, tabs, or type a command…" autocomplete="off">
                <kbd>Esc</kbd>
            </div>
            <div class="global-command-results"></div>
            <div class="global-command-footer"><span><kbd>↑</kbd><kbd>↓</kbd> Navigate</span><span><kbd>Enter</kbd> Open</span><span><kbd>Ctrl</kbd> + <kbd>P</kbd> Search</span></div>
        </div>
    `;

    document.body.appendChild(modal);
    const input = modal.querySelector('.global-command-input');

    input.addEventListener('input', () => renderGlobalCommandResults(input.value));
    input.addEventListener('keydown', event => {
        const rows = Array.from(modal.querySelectorAll('.global-command-result'));
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            featureCommandPaletteIndex = Math.min(rows.length - 1, featureCommandPaletteIndex + 1);
            updateGlobalCommandSelection(rows);
        } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            featureCommandPaletteIndex = Math.max(0, featureCommandPaletteIndex - 1);
            updateGlobalCommandSelection(rows);
        } else if (event.key === 'Enter') {
            event.preventDefault();
            rows[featureCommandPaletteIndex >= 0 ? featureCommandPaletteIndex : 0]?.click();
        } else if (event.key === 'Escape') {
            event.preventDefault();
            closeGlobalCommandPalette();
        }
    });

    modal.addEventListener('pointerdown', event => {
        if (event.target === modal) closeGlobalCommandPalette();
    });

    return modal;
}

function updateGlobalCommandSelection(rows) {
    rows.forEach((row, index) => row.classList.toggle('selected', index === featureCommandPaletteIndex));
    rows[featureCommandPaletteIndex]?.scrollIntoView({ block: 'nearest' });
}

function renderGlobalCommandResults(query = '') {
    const modal = ensureGlobalCommandPalette();
    const host = modal.querySelector('.global-command-results');
    const normalized = String(query || '').trim().toLocaleLowerCase();
    const terms = normalized.split(/\s+/).filter(Boolean);

    const results = getGlobalSearchIndex()
        .map(entry => {
            const haystack = `${entry.title} ${entry.detail || ''} ${entry.search || ''}`.toLocaleLowerCase();
            const matches = terms.every(term => haystack.includes(term));
            let score = 0;
            if (!normalized) score = entry.kind === 'Command' ? 30 : 1;
            else if (entry.title.toLocaleLowerCase().startsWith(normalized)) score = 100;
            else if (entry.title.toLocaleLowerCase().includes(normalized)) score = 70;
            else if (matches) score = 30;
            return { entry, matches: !normalized || matches, score };
        })
        .filter(result => result.matches)
        .sort((a, b) => b.score - a.score)
        .slice(0, 60)
        .map(result => result.entry);

    host.innerHTML = '';
    featureCommandPaletteIndex = results.length ? 0 : -1;

    if (!results.length) {
        host.innerHTML = `<div class="feature-empty-state global-command-empty"><i class="ph ph-magnifying-glass"></i><strong>No results</strong><span>Try a tab name, Day number, Knowledge Base item, or command.</span></div>`;
        return;
    }

    results.forEach((entry, index) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = `global-command-result${index === 0 ? ' selected' : ''}`;
        button.innerHTML = `
            <span class="global-command-result-icon">${entry.customSvg || `<i class="ph ${escapeCustomHtml(entry.icon || 'ph-magnifying-glass')}"></i>`}</span>
            <span class="global-command-result-copy"><strong>${escapeCustomHtml(entry.title)}</strong><small>${escapeCustomHtml(entry.detail || '')}</small></span>
            <span class="global-command-result-kind">${escapeCustomHtml(entry.kind)}</span>
        `;
        button.addEventListener('mouseenter', () => {
            featureCommandPaletteIndex = index;
            updateGlobalCommandSelection(Array.from(host.querySelectorAll('.global-command-result')));
        });
        button.addEventListener('click', () => {
            closeGlobalCommandPalette();
            entry.action?.();
        });
        host.appendChild(button);
    });
}

function openGlobalCommandPalette() {
    dailySettingsModal?.classList.add('hidden');
    const modal = ensureGlobalCommandPalette();
    const input = modal.querySelector('.global-command-input');
    modal.classList.remove('hidden');
    input.value = '';
    renderGlobalCommandResults('');
    requestAnimationFrame(() => input.focus());
}

function closeGlobalCommandPalette() {
    document.getElementById('global-command-palette')?.classList.add('hidden');
}

function bindGlobalCommandShortcut() {
    if (document.documentElement.dataset.globalCommandShortcutBound) return;
    document.documentElement.dataset.globalCommandShortcutBound = 'true';

    document.addEventListener('keydown', event => {
        if (event.repeat || !event.ctrlKey || event.shiftKey || event.altKey || event.metaKey || event.code !== 'KeyP') return;

        const target = event.target;
        const typing = target instanceof HTMLElement && (target.matches('textarea, [contenteditable="true"], [contenteditable=""]') || target.isContentEditable);
        if (typing) return;

        event.preventDefault();
        const modal = ensureGlobalCommandPalette();
        if (modal.classList.contains('hidden')) openGlobalCommandPalette();
        else closeGlobalCommandPalette();
    });
}

