function makeInlineGlobalSearchSnippetV2(text, query, radius = 55) {
    const source = String(text || '').replace(/\s+/g, ' ').trim();
    const needle = String(query || '').trim();
    if (!source) return '';
    if (!needle) return source.length > 120 ? `${source.slice(0, 120)}…` : source;

    const index = source.toLocaleLowerCase().indexOf(needle.toLocaleLowerCase());
    if (index < 0) return source.length > 120 ? `${source.slice(0, 120)}…` : source;

    const start = Math.max(0, index - radius);
    const end = Math.min(source.length, index + needle.length + radius);
    return `${start > 0 ? '…' : ''}${source.slice(start, end)}${end < source.length ? '…' : ''}`;
}

function inlineGlobalSearchSnippetHtmlV2(text, query) {
    const snippet = makeInlineGlobalSearchSnippetV2(text, query);
    const needle = String(query || '').trim();
    if (!snippet) return '';
    if (!needle) return escapeCustomHtml(snippet);

    const index = snippet.toLocaleLowerCase().indexOf(needle.toLocaleLowerCase());
    if (index < 0) return escapeCustomHtml(snippet);

    const before = snippet.slice(0, index);
    const hit = snippet.slice(index, index + needle.length);
    const after = snippet.slice(index + needle.length);
    return `${escapeCustomHtml(before)}<mark>${escapeCustomHtml(hit)}</mark>${escapeCustomHtml(after)}`;
}

function getInlineGlobalSearchEntriesV2(query) {
    const normalized = String(query || '').trim().toLocaleLowerCase();
    if (!normalized) return [];
    const results = [];

    Object.keys(db.days || {})
        .map(Number)
        .filter(day => Number.isFinite(day) && day > 0)
        .sort((a, b) => b - a)
        .forEach(day => {
            const data = db.days[day] || {};
            const notes = featureStripHtml(data.notes || '');

            if (notes.toLocaleLowerCase().includes(normalized)) {
                results.push({
                    kind: 'Daily Log', icon: 'ph-note', title: `Day ${day} · Notes`, detail: formatDate(day),
                    preview: notes, day, sourceType: 'notes', query
                });
            }

            collectTextFieldsFromDay(data).forEach(field => {
                if (!field.text.toLocaleLowerCase().includes(normalized)) return;
                results.push({
                    kind: 'Daily Log', icon: 'ph-text-t',
                    title: `Day ${day} · ${field.label || 'Text Field'}`, detail: formatDate(day),
                    preview: field.text, day, sourceType: 'text', sourceValue: field.text, query
                });
            });

            (data.resources || []).forEach((resource, index) => {
                const title = getDailyResourceDisplayTitle(resource, index);
                const haystack = `${title} ${resource?.url || ''}`.toLocaleLowerCase();
                if (!haystack.includes(normalized)) return;
                results.push({
                    kind: 'Media Resource',
                    icon: resource?.type === 'yt' ? 'ph-youtube-logo' : resource?.type === 'tiktok' ? 'ph-video' : 'ph-newspaper-clipping',
                    title: `Day ${day} · ${title}`, detail: resource?.url || '', preview: `${title} ${resource?.url || ''}`,
                    day, sourceType: 'resource', resourceIndex: index, query
                });
            });

            (data.phrases || []).forEach(itemId => {
                const meta = db.phrase_meta?.[itemId] || {};
                const fieldText = Object.values(meta.custom_fields || {}).join(' ');
                const parts = (meta.parts || []).map(part => part.label || '').join(' ');
                const haystack = `${itemId} ${fieldText} ${parts}`.toLocaleLowerCase();
                if (!haystack.includes(normalized)) return;
                results.push({
                    kind: 'Knowledge Base', icon: 'ph-books', title: itemId, detail: `Referenced in Day ${day}`,
                    preview: `${itemId} ${fieldText} ${parts}`, action: () => openItemModal(itemId, false)
                });
            });
        });

    getCustomTabs().forEach(tab => {
        if (String(tab.name || '').toLocaleLowerCase().includes(normalized)) {
            results.push({
                kind: 'Custom Tab', icon: tab.icon === 'custom-skateboard' ? 'ph-layout' : (tab.icon || 'ph-layout'),
                customSvg: tab.icon === 'custom-skateboard' ? CUSTOM_TAB_SKATEBOARD_SVG : '', title: tab.name || 'Custom Tab',
                detail: `${(tab.components || []).length} components`, action: () => openCustomTab(tab.id)
            });
        }

        (tab.components || []).forEach(component => {
            const candidates = [
                ...(Array.isArray(component.items) ? component.items : []),
                ...(Array.isArray(component.entries) ? component.entries : [])
            ];
            candidates.forEach(item => {
                const label = featureCustomItemSearchLabel(component, item);
                const valueText = Object.values(item || {}).filter(value => typeof value === 'string').join(' ');
                const haystack = `${tab.name || ''} ${component.title || ''} ${label} ${valueText}`.toLocaleLowerCase();
                if (!haystack.includes(normalized)) return;
                results.push({
                    kind: tab.name || 'Custom Tab', icon: 'ph-square', title: label,
                    detail: component.title || component.type || 'Item', preview: valueText,
                    action: () => featureOpenCustomItem(tab.id, item.id)
                });
            });
        });
    });

    return results.slice(0, 80);
}

function focusInlineGlobalDailyMatchV2(entry) {
    const query = String(entry?.query || '').trim();
    if (!query) return;

    if (entry.sourceType === 'resource') {
        highlightDailyResource(Number(entry.resourceIndex));
        return;
    }

    if (entry.sourceType === 'notes') {
        const notes = document.getElementById('log-notes');
        if (!notes) return;
        notes.scrollIntoView({ behavior: 'smooth', block: 'center' });
        notes.classList.add('daily-search-hit-target');
        selectTextInsideContentEditable(notes, query);
        setTimeout(() => notes.classList.remove('daily-search-hit-target'), 2400);
        return;
    }

    const candidates = Array.from(logView.querySelectorAll(
        'input[type="text"], input[type="url"], input[type="search"], textarea'
    ));

    let input = entry.sourceValue
        ? candidates.find(element => String(element.value || '') === String(entry.sourceValue))
        : null;

    if (!input) {
        input = candidates.find(element => String(element.value || '').toLocaleLowerCase().includes(query.toLocaleLowerCase()));
    }

    if (!input) {
        focusDailySearchMatch(query);
        return;
    }

    input.closest('.hidden')?.classList.remove('hidden');
    const start = String(input.value || '').toLocaleLowerCase().indexOf(query.toLocaleLowerCase());
    input.scrollIntoView({ behavior: 'smooth', block: 'center' });
    input.focus({ preventScroll: true });
    if (start >= 0 && typeof input.setSelectionRange === 'function') {
        input.setSelectionRange(start, start + query.length);
    }
    input.classList.add('daily-search-hit-target');
    setTimeout(() => input.classList.remove('daily-search-hit-target'), 2400);
}

function openInlineGlobalSearchEntryV2(entry) {
    if (entry.action) {
        entry.action();
        return;
    }
    if (!entry.day) return;
    openDayLog(Number(entry.day));
    requestAnimationFrame(() => requestAnimationFrame(() => focusInlineGlobalDailyMatchV2(entry)));
}

function renderInlineGlobalSearchResultsV2(query = '') {
    const host = document.getElementById('daily-global-search-results');
    if (!host) return;
    const normalized = String(query || '').trim();
    host.innerHTML = '';

    if (!normalized) {
        host.classList.add('hidden');
        return;
    }

    const results = getInlineGlobalSearchEntriesV2(normalized);
    host.classList.remove('hidden');

    if (!results.length) {
        host.innerHTML = `<div class="daily-global-search-empty"><i class="ph ph-magnifying-glass"></i><span>No global results for “${escapeCustomHtml(normalized)}”.</span></div>`;
        return;
    }

    results.forEach(entry => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'daily-global-search-result';
        const preview = entry.preview ? inlineGlobalSearchSnippetHtmlV2(entry.preview, normalized) : '';
        button.innerHTML = `
            <span class="daily-global-result-icon">${entry.customSvg || `<i class="ph ${escapeCustomHtml(entry.icon || 'ph-magnifying-glass')}"></i>`}</span>
            <span class="daily-global-result-copy">
                <strong>${escapeCustomHtml(entry.title || '')}</strong>
                <small>${escapeCustomHtml(entry.detail || '')}</small>
                ${preview ? `<span class="daily-global-result-preview">${preview}</span>` : ''}
            </span>
            <span class="daily-global-result-kind">${escapeCustomHtml(entry.kind || '')}</span>`;
        button.addEventListener('click', () => {
            host.classList.add('hidden');
            openInlineGlobalSearchEntryV2(entry);
        });
        host.appendChild(button);
    });
}

function ensureDailyLogSearchUI() {
    if (!daysGrid) return;

    let wrap = document.getElementById('daily-log-search-wrap');
    if (!wrap) {
        wrap = document.createElement('div');
        wrap.id = 'daily-log-search-wrap';
        daysGrid.insertAdjacentElement('beforebegin', wrap);
    }

    wrap.className = 'daily-log-search-wrap daily-dual-search-wrap';

    if (!wrap.querySelector('#daily-global-search-input')) {
        wrap.innerHTML = `
            <div class="daily-search-column">
                <div class="daily-log-search-box">
                    <i class="ph ph-calendar-blank"></i>
                    <input id="daily-log-search-input" type="search" placeholder="Search Daily Logs…" autocomplete="off" spellcheck="false">
                    <button type="button" id="daily-log-search-clear" class="daily-log-search-clear hidden" title="Clear Daily Logs search" aria-label="Clear Daily Logs search"><i class="ph ph-x"></i></button>
                </div>
                <span id="daily-log-search-count" class="daily-log-search-count"></span>
            </div>
            <div class="daily-search-column daily-global-search-column">
                <div class="daily-log-search-box daily-global-search-box">
                    <i class="ph ph-magnifying-glass"></i>
                    <input id="daily-global-search-input" type="text" placeholder="Search everything…" autocomplete="off" spellcheck="false">
                    <button type="button" id="daily-global-search-clear" class="daily-log-search-clear hidden" title="Clear global search" aria-label="Clear global search"><i class="ph ph-x"></i></button>
                </div>
                <div id="daily-global-search-results" class="daily-global-search-results hidden"></div>
            </div>`;

        const dailyInput = wrap.querySelector('#daily-log-search-input');
        const dailyClear = wrap.querySelector('#daily-log-search-clear');
        dailyInput.addEventListener('input', () => {
            dailyLogSearchQuery = dailyInput.value;
            dailyClear.classList.toggle('hidden', !dailyLogSearchQuery);
            initGrid();
        });
        dailyClear.addEventListener('click', () => {
            dailyLogSearchQuery = '';
            dailyInput.value = '';
            dailyClear.classList.add('hidden');
            initGrid();
            dailyInput.focus();
        });

        const globalInput = wrap.querySelector('#daily-global-search-input');
        const globalClear = wrap.querySelector('#daily-global-search-clear');
        globalInput.addEventListener('input', () => {
            inlineGlobalSearchQueryV2 = globalInput.value;
            globalClear.classList.toggle('hidden', !inlineGlobalSearchQueryV2);
            renderInlineGlobalSearchResultsV2(inlineGlobalSearchQueryV2);
        });
        globalInput.addEventListener('keydown', event => {
            if (event.key !== 'Enter' || event.repeat) return;
            const first = document.querySelector('#daily-global-search-results .daily-global-search-result');
            if (!first) return;
            event.preventDefault();
            first.click();
        });
        globalClear.addEventListener('click', () => {
            inlineGlobalSearchQueryV2 = '';
            globalInput.value = '';
            globalClear.classList.add('hidden');
            renderInlineGlobalSearchResultsV2('');
            globalInput.focus();
        });
    }

    const dailyInput = document.getElementById('daily-log-search-input');
    const globalInput = document.getElementById('daily-global-search-input');
    const hiddenBySetting = !!db.settings.hideDailyLogSearch;
    wrap.classList.toggle('hidden', hiddenBySetting);

    if (hiddenBySetting) {
        dailyLogSearchQuery = '';
        inlineGlobalSearchQueryV2 = '';
        if (dailyInput) dailyInput.value = '';
        if (globalInput) globalInput.value = '';
        wrap.querySelectorAll('.daily-log-search-clear').forEach(button => button.classList.add('hidden'));
        renderInlineGlobalSearchResultsV2('');
    } else {
        if (dailyInput && dailyInput.value !== dailyLogSearchQuery) dailyInput.value = dailyLogSearchQuery;
        if (globalInput && globalInput.value !== inlineGlobalSearchQueryV2) globalInput.value = inlineGlobalSearchQueryV2;
    }
}

function focusInlineGlobalSearchV2() {
    initGrid();
    switchView(gridView);
    requestAnimationFrame(() => {
        const input = document.getElementById('daily-global-search-input');
        input?.focus();
        input?.select();
    });
}

function bindGlobalCommandShortcut() {
    if (document.documentElement.dataset.globalCommandShortcutBoundV2) return;
    document.documentElement.dataset.globalCommandShortcutBoundV2 = 'true';

    document.addEventListener('keydown', event => {
        if (event.repeat || !event.ctrlKey || event.shiftKey || event.altKey || event.metaKey || event.code !== 'KeyP') return;
        const target = event.target;
        const typing = target instanceof HTMLElement &&
            (target.matches('textarea, [contenteditable="true"], [contenteditable=""]') || target.isContentEditable);
        if (typing) return;
        event.preventDefault();
        focusInlineGlobalSearchV2();
    });
}

// ============================================================
// TRASH + WEEKLY REVIEW AS REAL SIDE-NAV TABS
