function getThemeBuilderDraft(modal) {
    const draft = {
        ...FEATURE_SUITE_DEFAULT_THEME,
        ...CUSTOM_THEME_MEDIA_DEFAULTS_V3,
        backgroundSvgs:
            Array.isArray(
                modal._themeBackgroundSvgs
            )
                ? modal._themeBackgroundSvgs
                : []
    };

    modal
        .querySelectorAll(
            '[data-theme-key]'
        )
        .forEach(input => {
            const key =
                input.dataset.themeKey;

            draft[key] =
                input.type === 'range' ||
                input.type === 'number'
                    ? Number(
                        input.value
                    )
                    : input.value;
        });

    draft.backgroundImage =
        modal._themeBackgroundImage ||
        '';

    draft.backgroundImageName =
        modal._themeBackgroundImageName ||
        '';

    draft.introAudio =
        modal._themeIntroAudio ||
        '';

    draft.introAudioName =
        modal._themeIntroAudioName ||
        '';

    draft.audioPlayMode =
        getThemeAudioMode(
            modal
        );

    draft.audioStart =
        parseThemeTimecode(
            modal
                .querySelector(
                    '.theme-builder-audio-start'
                )
                ?.value,
            0
        );

    draft.audioEnd =
        parseThemeTimecode(
            modal
                .querySelector(
                    '.theme-builder-audio-end'
                )
                ?.value,
            Math.max(
                1,
                draft.audioStart + 20
            )
        );

    draft.audioFade =
        !!modal
            .querySelector(
                '.theme-builder-audio-fade'
            )
            ?.checked;

    return draft;
}

async function confirmDeleteThemeBuilderSvg(
    modal,
    index
) {
    const svg =
        modal._themeBackgroundSvgs?.[
            index
        ];

    if (!svg) return;

    const confirmed =
        await showAppConfirm({
            title:
                'Delete this SVG?',
            message:
                `“${svg.name || `SVG ${index + 1}`}” will be removed from this custom theme.`,
            confirmLabel:
                'Delete SVG'
        });

    if (!confirmed) return;

    modal
        ._themeBackgroundSvgs
        .splice(
            index,
            1
        );

    renderThemeBuilderSvgListV2(
        modal
    );

    updateThemeBuilderPreview(
        modal
    );

    await deleteThemeBuilderProjectAsset(
        svg.url
    );
}

function renderThemeBuilderSvgListV2(
    modal
) {
    const host =
        modal.querySelector(
            '.theme-builder-svg-list'
        );

    if (!host) return;

    const svgs =
        Array.isArray(
            modal._themeBackgroundSvgs
        )
            ? modal._themeBackgroundSvgs
            : [];

    const count =
        modal.querySelector(
            '.theme-builder-svg-count'
        );

    if (count) {
        count.textContent =
            `${svgs.length} SVG${svgs.length === 1 ? '' : 's'}`;
    }

    host.innerHTML = '';

    if (!svgs.length) {
        host.innerHTML = `
            <button
                type="button"
                class="theme-builder-svg-empty theme-builder-svg-add-empty"
            >
                <i class="ph ph-file-svg"></i>
                <strong>No SVGs uploaded yet</strong>
                <span>Click here or “Add Artwork” to choose some.</span>
            </button>
        `;

        host
            .querySelector(
                '.theme-builder-svg-add-empty'
            )
            ?.addEventListener(
                'click',
                () =>
                    modal
                        .querySelector(
                            '.theme-builder-svg-file'
                        )
                        ?.click()
            );

        return;
    }

    svgs.forEach(
        (svg, index) => {
            const card =
                document.createElement(
                    'article'
                );

            card.className =
                'theme-builder-svg-card';

            card.dataset.svgIndex =
                String(index);

            card.title =
                'Right-click to delete';

            card.innerHTML = `
                <div class="theme-builder-svg-card-preview">
                    ${renderThemeBuilderSvgAsset(svg)}
                </div>

                <div class="theme-builder-svg-card-copy">
                    <strong>${escapeCustomHtml(svg.name || `SVG ${index + 1}`)}</strong>
                    <small>Right-click to delete</small>
                </div>

                <button
                    type="button"
                    class="small-icon-btn theme-builder-svg-remove"
                    title="Delete SVG"
                    aria-label="Delete SVG"
                >
                    <i class="ph ph-x"></i>
                </button>
            `;

            card
                .querySelector(
                    '.theme-builder-svg-remove'
                )
                ?.addEventListener(
                    'click',
                    event => {
                        event.stopPropagation();

                        confirmDeleteThemeBuilderSvg(
                            modal,
                            index
                        );
                    }
                );

            card.addEventListener(
                'contextmenu',
                event => {
                    event.preventDefault();

                    showCustomItemContextMenu(
                        event.clientX,
                        event.clientY,
                        [
                            {
                                label:
                                    'Delete SVG',
                                icon:
                                    'ph-trash',
                                danger:
                                    true,
                                action:
                                    () =>
                                        confirmDeleteThemeBuilderSvg(
                                            modal,
                                            index
                                        )
                            }
                        ]
                    );
                }
            );

            host.appendChild(
                card
            );
        }
    );

    const addCard =
        document.createElement(
            'button'
        );

    addCard.type = 'button';
    addCard.className =
        'theme-builder-svg-card theme-builder-svg-add-card';

    addCard.innerHTML = `
        <i class="ph ph-plus"></i>
        <strong>Add more SVGs</strong>
    `;

    addCard.addEventListener(
        'click',
        () =>
            modal
                .querySelector(
                    '.theme-builder-svg-file'
                )
                ?.click()
    );

    host.appendChild(
        addCard
    );
}

function updateThemeBuilderPreview(
    modal
) {
    const draft =
        getThemeBuilderDraft(
            modal
        );

    const preview =
        modal.querySelector(
            '.theme-builder-preview'
        );

    const card =
        modal.querySelector(
            '.theme-builder-preview-card'
        );

    const button =
        card?.querySelector(
            'button'
        );

    const chip =
        card?.querySelector(
            '.theme-builder-preview-chip'
        );

    const progress =
        card?.querySelector(
            '.theme-builder-preview-progress span'
        );

    if (!preview || !card) return;

    preview.style.backgroundColor =
        draft.background;

    preview.style.backgroundImage =
        draft.backgroundImage
            ? `linear-gradient(rgba(255,255,255,.08), rgba(255,255,255,.08)), url("${draft.backgroundImage}")`
            : 'none';

    preview.style.backgroundSize =
        'cover';

    preview.style.backgroundPosition =
        'center';

    preview.style.color =
        draft.text;

    preview.style.fontFamily =
        CUSTOM_THEME_FONT_STACKS[
            draft.font
        ] ||
        CUSTOM_THEME_FONT_STACKS.hand;

    card.style.background =
        draft.surface;

    card.style.color =
        draft.text;

    card.style.borderColor =
        draft.border;

    card.style.borderRadius =
        `${draft.radius}px`;

    card.style.boxShadow =
        `${draft.shadow}px ${draft.shadow}px 0 ${draft.border}`;

    if (button) {
        button.style.background =
            draft.accent;

        button.style.color =
            getReadableTextColor(
                draft.accent
            );

        button.style.borderColor =
            draft.border;

        button.style.borderRadius =
            `${Math.max(4, draft.radius - 4)}px`;
    }

    if (chip) {
        chip.style.background =
            `${draft.accent}22`;

        chip.style.color =
            draft.text;
    }

    if (progress) {
        progress.style.background =
            draft.accent;
    }

    modal
        .querySelectorAll(
            '[data-theme-output]'
        )
        .forEach(output => {
            output.textContent =
                String(
                    draft[
                        output.dataset.themeOutput
                    ]
                );
        });

    const backgroundStatus =
        modal.querySelector(
            '.theme-builder-background-status'
        );

    if (backgroundStatus) {
        backgroundStatus.textContent =
            draft.backgroundImage
                ? 'Background image is included in the saved theme.'
                : 'No background image';
    }

    const backgroundName =
        modal.querySelector(
            '.theme-builder-background-name'
        );

    if (backgroundName) {
        backgroundName.textContent =
            draft.backgroundImage
                ? (
                    draft.backgroundImageName ||
                    'Saved background image'
                )
                : 'No image selected';
    }

    const audioStatus =
        modal.querySelector(
            '.theme-builder-audio-status'
        );

    if (audioStatus) {
        if (!draft.introAudio) {
            audioStatus.textContent =
                'No intro audio';
        } else if (
            draft.audioPlayMode ===
            'full'
        ) {
            audioStatus.textContent =
                `Audio ready · full file${draft.audioFade ? ' · fade at end' : ''}`;
        } else {
            audioStatus.textContent =
                `Audio ready · ${formatThemeTimecode(draft.audioStart)}–${formatThemeTimecode(draft.audioEnd)}${draft.audioFade ? ' · fade' : ''}`;
        }
    }

    const audioName =
        modal.querySelector(
            '.theme-builder-audio-name'
        );

    if (audioName) {
        audioName.textContent =
            draft.introAudio
                ? (
                    draft.introAudioName ||
                    'Saved audio'
                )
                : 'No audio selected';
    }
}

function populateThemeBuilder(
    modal,
    theme
) {
    const merged = {
        ...FEATURE_SUITE_DEFAULT_THEME,
        ...CUSTOM_THEME_MEDIA_DEFAULTS_V3,
        ...theme,
        backgroundSvgs:
            Array.isArray(
                theme?.backgroundSvgs
            )
                ? theme.backgroundSvgs
                : []
    };

    const colors = [
        ['Page Background', 'background'],
        ['Cards / Surface', 'surface'],
        ['Main Text', 'text'],
        ['Borders', 'border'],
        ['Accent', 'accent'],
        ['Muted Text', 'muted']
    ];

    modal
        .querySelector(
            '.theme-builder-color-grid'
        ).innerHTML =
        colors
            .map(
                ([label, key]) =>
                    themeBuilderField(
                        label,
                        key,
                        merged[key]
                    )
            )
            .join('');

    modal
        .querySelector(
            '.theme-builder-sliders'
        ).innerHTML =
        themeBuilderField(
            'Corner Radius',
            'radius',
            merged.radius,
            'range'
        ) +
        themeBuilderField(
            'Shadow Size',
            'shadow',
            merged.shadow,
            'range'
        );

    modal
        .querySelector(
            '[data-theme-key="name"]'
        ).value =
        merged.name;

    modal
        .querySelector(
            '[data-theme-key="font"]'
        ).value =
        merged.font;

    modal._themeBackgroundImage =
        merged.backgroundImage ||
        '';

    modal._themeBackgroundImageName =
        merged.backgroundImageName ||
        '';

    modal._themeBackgroundProjectPath =
        merged.backgroundImageProjectPath ||
        '';

    modal._themeIntroAudio =
        merged.introAudio ||
        '';

    modal._themeIntroAudioName =
        merged.introAudioName ||
        '';

    modal._themeAudioProjectPath =
        merged.introAudioProjectPath ||
        '';

    modal._themeBackgroundSvgs =
        merged.backgroundSvgs.map(
            item => ({
                ...item
            })
        );

    const mode =
        merged.audioPlayMode ===
        'segment'
            ? 'segment'
            : 'full';

    modal
        .querySelectorAll(
            'input[name="theme-builder-audio-mode"]'
        )
        .forEach(input => {
            input.checked =
                input.value ===
                mode;

            input.onchange =
                () =>
                    syncThemeAudioModeUi(
                        modal
                    );
        });

    modal
        .querySelector(
            '.theme-builder-audio-start'
        ).value =
        formatThemeTimecode(
            merged.audioStart
        );

    modal
        .querySelector(
            '.theme-builder-audio-end'
        ).value =
        formatThemeTimecode(
            merged.audioEnd
        );

    modal
        .querySelector(
            '.theme-builder-audio-fade'
        ).checked =
        merged.audioFade !== false;

    modal
        .querySelectorAll(
            'input[data-theme-key], select[data-theme-key]'
        )
        .forEach(input => {
            input.oninput =
                () => {
                    const hexInput =
                        modal.querySelector(
                            `[data-theme-hex="${CSS.escape(input.dataset.themeKey)}"]`
                        );

                    if (
                        input.type ===
                            'color' &&
                        hexInput
                    ) {
                        hexInput.value =
                            input.value;
                    }

                    updateThemeBuilderPreview(
                        modal
                    );
                };
        });

    modal
        .querySelectorAll(
            '[data-theme-hex]'
        )
        .forEach(input => {
            input.onchange =
                () => {
                    const value =
                        input.value.trim();

                    if (
                        !/^#[0-9a-f]{6}$/i.test(
                            value
                        )
                    ) {
                        return;
                    }

                    const picker =
                        modal.querySelector(
                            `input[type="color"][data-theme-key="${CSS.escape(input.dataset.themeHex)}"]`
                        );

                    if (picker) {
                        picker.value =
                            value;
                    }

                    updateThemeBuilderPreview(
                        modal
                    );
                };
        });

    const startInput =
        modal.querySelector(
            '.theme-builder-audio-start'
        );

    const endInput =
        modal.querySelector(
            '.theme-builder-audio-end'
        );

    [
        startInput,
        endInput
    ].forEach(input => {
        input?.addEventListener(
            'input',
            () => {
                input.value =
                    input.value.replace(
                        /[^\d:]/g,
                        ''
                    );

                updateThemeBuilderPreview(
                    modal
                );
            }
        );

        input?.addEventListener(
            'blur',
            () => {
                if (
                    isValidThemeTimecode(
                        input.value
                    )
                ) {
                    input.value =
                        formatThemeTimecode(
                            parseThemeTimecode(
                                input.value
                            )
                        );
                }

                updateThemeBuilderPreview(
                    modal
                );
            }
        );
    });

    const backgroundFile =
        modal.querySelector(
            '.theme-builder-background-file'
        );

    modal
        .querySelector(
            '.theme-builder-background-choose'
        ).onclick =
        () =>
            backgroundFile.click();

    backgroundFile.onchange =
        async () => {
            const file =
                backgroundFile.files?.[0];

            if (!file) return;

            const saved =
                await uploadThemeBuilderAssetToProject(
                    file,
                    'background'
                );

            if (!saved) {
                backgroundFile.value = '';
                return;
            }

            const oldUrl =
                modal._themeBackgroundImage;

            modal._themeBackgroundImage =
                saved.url;

            modal._themeBackgroundImageName =
                file.name;

            modal._themeBackgroundProjectPath =
                saved.projectPath ||
                '';

            updateThemeBuilderPreview(
                modal
            );

            if (
                oldUrl &&
                oldUrl !== saved.url
            ) {
                deleteThemeBuilderProjectAsset(
                    oldUrl
                );
            }

            showFeatureToast(
                `Saved image to ${saved.projectPath || saved.url}`
            );
        };

    modal
        .querySelector(
            '.theme-builder-background-clear'
        ).onclick =
        async () => {
            const oldUrl =
                modal._themeBackgroundImage;

            modal._themeBackgroundImage =
                '';

            modal._themeBackgroundImageName =
                '';

            modal._themeBackgroundProjectPath =
                '';

            backgroundFile.value =
                '';

            updateThemeBuilderPreview(
                modal
            );

            await deleteThemeBuilderProjectAsset(
                oldUrl
            );
        };

    const audioFile =
        modal.querySelector(
            '.theme-builder-audio-file'
        );

    modal
        .querySelector(
            '.theme-builder-audio-choose'
        ).onclick =
        () =>
            audioFile.click();

    audioFile.onchange =
        async () => {
            const file =
                audioFile.files?.[0];

            if (!file) return;

            const saved =
                await uploadThemeBuilderAssetToProject(
                    file,
                    'audio'
                );

            if (!saved) {
                audioFile.value = '';
                return;
            }

            const oldUrl =
                modal._themeIntroAudio;

            modal._themeIntroAudio =
                saved.url;

            modal._themeIntroAudioName =
                file.name;

            modal._themeAudioProjectPath =
                saved.projectPath ||
                '';

            updateThemeBuilderPreview(
                modal
            );

            if (
                oldUrl &&
                oldUrl !== saved.url
            ) {
                deleteThemeBuilderProjectAsset(
                    oldUrl
                );
            }

            showFeatureToast(
                `Saved audio to ${saved.projectPath || saved.url}`
            );
        };

    modal
        .querySelector(
            '.theme-builder-audio-clear'
        ).onclick =
        async () => {
            const oldUrl =
                modal._themeIntroAudio;

            modal._themeIntroAudio =
                '';

            modal._themeIntroAudioName =
                '';

            modal._themeAudioProjectPath =
                '';

            audioFile.value =
                '';

            updateThemeBuilderPreview(
                modal
            );

            await deleteThemeBuilderProjectAsset(
                oldUrl
            );
        };

    modal
        .querySelector(
            '.theme-builder-audio-fade'
        ).onchange =
        () =>
            updateThemeBuilderPreview(
                modal
            );

    const svgFile =
        modal.querySelector(
            '.theme-builder-svg-file'
        );

    modal
        .querySelector(
            '.theme-builder-svg-choose'
        ).onclick =
        () =>
            svgFile.click();

    svgFile.onchange =
        async () => {
            const files =
                Array.from(
                    svgFile.files ||
                    []
                );

            let savedCount = 0;

            for (
                const file of files
            ) {
                const saved =
                    await uploadThemeBuilderAssetToProject(
                        file,
                        'svg'
                    );

                if (!saved) {
                    continue;
                }

                modal
                    ._themeBackgroundSvgs
                    .push({
                        name:
                            file.name,
                        url:
                            saved.url,
                        projectPath:
                            saved.projectPath ||
                            ''
                    });

                savedCount += 1;
            }

            svgFile.value = '';

            renderThemeBuilderSvgListV2(
                modal
            );

            updateThemeBuilderPreview(
                modal
            );

            if (savedCount) {
                showFeatureToast(
                    `Saved ${savedCount} SVG${savedCount === 1 ? '' : 's'} into public/svg.`
                );
            }
        };

    renderThemeBuilderSvgListV2(
        modal
    );

    syncThemeAudioModeUi(
        modal
    );

    updateThemeBuilderPreview(
        modal
    );
}

function openThemeBuilder() {
    const modal =
        ensureThemeBuilderModal();

    populateThemeBuilder(
        modal,
        {
            ...getCustomThemeSettings()
        }
    );

    // V34: legacy Reset button was removed; no Reset handler is attached.

    modal
        .querySelector(
            '.theme-builder-save'
        ).onclick =
        async () => {
            const mode =
                getThemeAudioMode(
                    modal
                );

            if (
                mode === 'segment'
            ) {
                const startText =
                    modal
                        .querySelector(
                            '.theme-builder-audio-start'
                        )
                        ?.value;

                const endText =
                    modal
                        .querySelector(
                            '.theme-builder-audio-end'
                        )
                        ?.value;

                if (
                    !isValidThemeTimecode(
                        startText
                    ) ||
                    !isValidThemeTimecode(
                        endText
                    )
                ) {
                    showFeatureToast(
                        'Use the 00:00 format for the audio start and end.'
                    );
                    return;
                }

                const start =
                    parseThemeTimecode(
                        startText
                    );

                const end =
                    parseThemeTimecode(
                        endText
                    );

                if (end <= start) {
                    showFeatureToast(
                        'The audio end time has to be after the start time.'
                    );
                    return;
                }
            }

            const draft =
                getThemeBuilderDraft(
                    modal
                );

            db.settings.customTheme = {
                ...FEATURE_SUITE_DEFAULT_THEME,
                ...CUSTOM_THEME_MEDIA_DEFAULTS_V3,
                ...draft
            };

            db.settings.customThemeDeleted =
                false;

            db.settings.deletedThemes =
                (
                    db.settings.deletedThemes ||
                    []
                ).filter(
                    value =>
                        value !==
                        'theme-custom-builder'
                );

            db.settings.theme =
                'theme-custom-builder';

            ensureCustomThemePickerOption();

            await saveDb();

            await applyTheme(
                'theme-custom-builder',
                {
                    persist: false
                }
            );

            if (dailyThemeSelect) {
                dailyThemeSelect.value =
                    'theme-custom-builder';
            }

            themePickerSelected =
                'theme-custom-builder';

            renderThemePicker();

            modal.classList.add(
                'hidden'
            );

            showFeatureToast(
                'Custom theme saved and applied.'
            );
        };

    modal.classList.remove(
        'hidden'
    );
}

// ------------------------------------------------------------
// Unlimited animated SVG runtime
// ------------------------------------------------------------

function mountCustomThemeBackgroundSvgsV2(
    theme
) {
    const svgs =
        Array.isArray(
            theme.backgroundSvgs
        )
            ? theme.backgroundSvgs
            : [];

    if (!svgs.length) return;

    const stage =
        document.createElement(
            'div'
        );

    stage.id =
        'custom-theme-background-stage';

    stage.className =
        'custom-theme-background-stage';

    svgs.forEach(
        (svg, index) => {
            const item =
                document.createElement(
                    'div'
                );

            item.className =
                'custom-theme-background-svg';

            const left =
                5 +
                (
                    (
                        index * 31 +
                        11
                    ) %
                    90
                );

            const top =
                7 +
                (
                    (
                        index * 47 +
                        19
                    ) %
                    84
                );

            item.style.left =
                `${left}%`;

            item.style.top =
                `${top}%`;

            item.style.setProperty(
                '--custom-svg-delay',
                `${(index % 13) * -0.42}s`
            );

            item.style.setProperty(
                '--custom-svg-rotate',
                `${((index % 2) ? -1 : 1) * (4 + (index % 9) * 3)}deg`
            );

            item.style.setProperty(
                '--custom-svg-scale',
                String(
                    0.78 +
                    (index % 5) *
                        0.08
                )
            );

            item.innerHTML =
                String(
                    svg?.markup ||
                    ''
                );

            stage.appendChild(
                item
            );
        }
    );

    document.body.prepend(
        stage
    );
}

// ------------------------------------------------------------
// Full-audio or time-range playback
// ------------------------------------------------------------

function clearCustomThemeRuntimeMediaV2() {
    document
        .getElementById(
            'custom-theme-background-stage'
        )
        ?.remove();

    if (customThemeIntroStopTimerV2) {
        clearTimeout(
            customThemeIntroStopTimerV2
        );
    }

    if (customThemeIntroFadeTimerV2) {
        clearInterval(
            customThemeIntroFadeTimerV2
        );
    }

    if (
        customThemeIntroFadeStartTimerV3
    ) {
        clearTimeout(
            customThemeIntroFadeStartTimerV3
        );
    }

    customThemeIntroStopTimerV2 =
        null;

    customThemeIntroFadeTimerV2 =
        null;

    customThemeIntroFadeStartTimerV3 =
        null;

    if (customThemeIntroAudioV2) {
        try {
            customThemeIntroAudioV2.pause();
            customThemeIntroAudioV2.currentTime =
                0;
        } catch (error) {}

        customThemeIntroAudioV2 =
            null;
    }
}

function startCustomThemeAudioFadeV3(
    audio,
    durationMs
) {
    if (
        !audio ||
        durationMs <= 0
    ) {
        return;
    }

    const started =
        performance.now();

    customThemeIntroFadeTimerV2 =
        setInterval(
            () => {
                if (
                    customThemeIntroAudioV2 !==
                    audio
                ) {
                    clearInterval(
                        customThemeIntroFadeTimerV2
                    );

                    customThemeIntroFadeTimerV2 =
                        null;

                    return;
                }

                const progress =
                    Math.min(
                        1,
                        (
                            performance.now() -
                            started
                        ) /
                        durationMs
                    );

                audio.volume =
                    Math.max(
                        0,
                        1 - progress
                    );

                if (
                    progress >= 1
                ) {
                    clearInterval(
                        customThemeIntroFadeTimerV2
                    );

                    customThemeIntroFadeTimerV2 =
                        null;
                }
            },
            50
        );
}

function scheduleCustomThemeAudioEndV3(
    audio,
    playbackSeconds,
    shouldStop,
    shouldFade
) {
    if (
        !Number.isFinite(
            playbackSeconds
        ) ||
        playbackSeconds <= 0
    ) {
        return;
    }

    const totalMs =
        playbackSeconds *
        1000;

    if (
        shouldFade &&
        totalMs > 700
    ) {
        const fadeMs =
            Math.min(
                1800,
                Math.max(
                    500,
                    totalMs * 0.22
                )
            );

        customThemeIntroFadeStartTimerV3 =
            setTimeout(
                () => {
                    if (
                        customThemeIntroAudioV2 ===
                        audio
                    ) {
                        startCustomThemeAudioFadeV3(
                            audio,
                            fadeMs
                        );
                    }
                },
                Math.max(
                    0,
                    totalMs - fadeMs
                )
            );
    }

    if (shouldStop) {
        customThemeIntroStopTimerV2 =
            setTimeout(
                () => {
                    if (
                        customThemeIntroAudioV2 !==
                        audio
                    ) {
                        return;
                    }

                    audio.pause();
                    audio.volume = 1;
                },
                totalMs
            );
    }
}

function playCustomThemeIntroAudioV2(
    theme
) {
    const src =
        String(
            theme.introAudio ||
            ''
        );

    if (!src) return;

    const mode =
        theme.audioPlayMode ===
        'segment'
            ? 'segment'
            : 'full';

    const audio =
        new Audio(src);

    audio.preload =
        'metadata';

    audio.volume = 1;

    customThemeIntroAudioV2 =
        audio;

    const start =
        Math.max(
            0,
            Number(
                theme.audioStart
            ) || 0
        );

    const end =
        Math.max(
            start + 0.1,
            Number(
                theme.audioEnd
            ) || start + 20
        );

    const seekSegmentStart =
        () => {
            if (
                mode !==
                'segment'
            ) {
                return;
            }

            try {
                const duration =
                    Number.isFinite(
                        audio.duration
                    )
                        ? audio.duration
                        : start + 1;

                audio.currentTime =
                    Math.min(
                        start,
                        Math.max(
                            0,
                            duration - 0.05
                        )
                    );
            } catch (error) {}
        };

    if (
        mode ===
        'segment'
    ) {
        seekSegmentStart();
    }

    audio.play().catch(
        () => {}
    );

    audio.addEventListener(
        'loadedmetadata',
        () => {
            if (
                customThemeIntroAudioV2 !==
                audio
            ) {
                return;
            }

            if (
                mode ===
                'segment'
            ) {
                seekSegmentStart();

                const actualEnd =
                    Number.isFinite(
                        audio.duration
                    )
                        ? Math.min(
                            end,
                            audio.duration
                        )
                        : end;

                const duration =
                    Math.max(
                        0.1,
                        actualEnd -
                        Math.min(
                            start,
                            actualEnd
                        )
                    );

                scheduleCustomThemeAudioEndV3(
                    audio,
                    duration,
                    true,
                    !!theme.audioFade
                );
            } else if (
                Number.isFinite(
                    audio.duration
                )
            ) {
                scheduleCustomThemeAudioEndV3(
                    audio,
                    audio.duration,
                    false,
                    !!theme.audioFade
                );
            }
        },
        {
            once: true
        }
    );

    if (
        audio.readyState >= 1
    ) {
        if (
            mode ===
            'segment'
        ) {
            seekSegmentStart();

            const actualEnd =
                Number.isFinite(
                    audio.duration
                )
                    ? Math.min(
                        end,
                        audio.duration
                    )
                    : end;

            scheduleCustomThemeAudioEndV3(
                audio,
                Math.max(
                    0.1,
                    actualEnd -
                    Math.min(
                        start,
                        actualEnd
                    )
                ),
                true,
                !!theme.audioFade
            );
        } else if (
            Number.isFinite(
                audio.duration
            )
        ) {
            scheduleCustomThemeAudioEndV3(
                audio,
                audio.duration,
                false,
                !!theme.audioFade
            );
        }
    }

    audio.addEventListener(
        'ended',
        () => {
            if (
                customThemeIntroAudioV2 ===
                audio
            ) {
                audio.volume = 1;
            }
        }
    );
}

// ------------------------------------------------------------
// Media Resources -> Trash
// ------------------------------------------------------------

function moveDailyResourceToTrash(
    dayData,
    resourceIndex
) {
    if (
        !dayData ||
        !Array.isArray(
            dayData.resources
        ) ||
        resourceIndex < 0 ||
        resourceIndex >=
            dayData.resources.length
    ) {
        return;
    }

    normalizeFeatureSuiteSettings();

    const [
        resource
    ] =
        dayData.resources.splice(
            resourceIndex,
            1
        );

    const dayNumber =
        Number(currentDay) ||
        null;

    const entry = {
        deletedAt:
            new Date().toISOString(),
        day:
            dayNumber,
        originalIndex:
            resourceIndex,
        resource:
            JSON.parse(
                JSON.stringify(
                    resource
                )
            )
    };

    getFeatureTrash()
        .resources
        .unshift(
            entry
        );

    saveDb();

    renderResources(
        dayData
    );

    showFeatureToast(
        `Moved “${getDailyResourceDisplayTitle(resource, resourceIndex)}” to Trash.`,
        'Undo',
        () => {
            const trash =
                getFeatureTrash()
                    .resources;

            const index =
                trash.indexOf(
                    entry
                );

            if (index < 0) return;

            trash.splice(
                index,
                1
            );

            if (
                !Array.isArray(
                    dayData.resources
                )
            ) {
                dayData.resources =
                    [];
            }

            dayData.resources.splice(
                Math.max(
                    0,
                    Math.min(
                        resourceIndex,
                        dayData.resources.length
                    )
                ),
                0,
                entry.resource
            );

            saveDb();

            renderResources(
                dayData
            );
        }
    );
}

function getDailyResourceNoteIconClass(
    resource
) {
    if (
        resource?.type ===
        'yt'
    ) {
        return 'ph-youtube-logo';
    }

    if (
        resource?.type ===
        'tiktok'
    ) {
        return 'ph-tiktok-logo';
    }

    return 'ph-link';
}

function upgradeDailyResourceNoteIcons() {
    const notes =
        document.getElementById(
            'log-notes'
        );

    if (!notes) return;

    const resources =
        currentDay
            ? (
                db.days[currentDay]
                    ?.resources ||
                []
            )
            : [];

    notes
        .querySelectorAll(
            'a[data-resource-index]'
        )
        .forEach(link => {
            const savedUrl =
                String(
                    link.dataset.resourceUrl ||
                    ''
                );

            let resource =
                savedUrl
                    ? resources.find(
                        item =>
                            String(
                                item?.url ||
                                ''
                            ) ===
                            savedUrl
                    )
                    : null;

            if (!resource) {
                resource =
                    resources[
                        Number(
                            link.dataset.resourceIndex
                        )
                    ];
            }

            if (!resource) return;

            link.dataset.resourceType =
                resource.type ||
                'link';

            link.innerHTML =
                `<i class="ph ${getDailyResourceNoteIconClass(resource)}"></i>`;
        });
}

function renderResources(dayData) {
    const grid =
        document.getElementById(
            'resources-grid'
        );

    if (!grid) return;

    grid.innerHTML = '';

    const resources =
        dayData.resources ||
        [];

    resources.forEach(
        (res, idx) => {
            const card =
                document.createElement(
                    'div'
                );

            card.classList.add(
                'resource-card',
                res.type ||
                'link'
            );

            card.id =
                `daily-resource-${idx}`;

            card.dataset.resourceIndex =
                String(idx);

            if (
                res.type ===
                'yt'
            ) {
                const startParam =
                    res.start > 0
                        ? `&start=${res.start}`
                        : '';

                card.innerHTML = `
                    <iframe
                        src="https://www.youtube.com/embed/${res.id}?controls=1${startParam}"
                        allow="encrypted-media"
                        allowfullscreen
                    ></iframe>

                    <span class="resource-card-label">
                        YouTube
                    </span>

                    <div class="resource-card-controls">
                        <button
                            class="resource-card-btn"
                            data-action="delete"
                            title="Move to Trash"
                        >
                            <i class="ph ph-trash"></i>
                        </button>
                    </div>
                `;
            } else if (
                res.type ===
                'tiktok'
            ) {
                card.innerHTML = `
                    <iframe
                        src="https://www.tiktok.com/embed/v2/${res.id}"
                        allow="encrypted-media"
                        allowfullscreen
                    ></iframe>

                    <span class="resource-card-label">
                        TikTok
                    </span>

                    <div class="resource-card-controls">
                        <button
                            class="resource-card-btn"
                            data-action="delete"
                            title="Move to Trash"
                        >
                            <i class="ph ph-trash"></i>
                        </button>
                    </div>
                `;
            } else {
                const title =
                    getDailyResourceDisplayTitle(
                        res,
                        idx
                    );

                const domain =
                    getDailyResourceDomain(
                        res
                    );

                card.innerHTML = `
                    <a
                        class="daily-generic-resource-card"
                        href="${escapeCustomHtml(res.url || '#')}"
                        target="_blank"
                        rel="noopener noreferrer"
                        title="Open ${escapeCustomHtml(title)}"
                    >
                        <span class="daily-generic-resource-icon">
                            <i class="ph ph-newspaper-clipping"></i>
                        </span>

                        <span class="daily-generic-resource-copy">
                            <strong>${escapeCustomHtml(title)}</strong>
                            <small>${escapeCustomHtml(domain)}</small>
                        </span>

                        <i class="ph ph-arrow-square-out daily-generic-resource-open"></i>
                    </a>

                    <div class="resource-card-controls">
                        <button
                            class="resource-card-btn"
                            data-action="delete"
                            title="Move to Trash"
                        >
                            <i class="ph ph-trash"></i>
                        </button>
                    </div>
                `;
            }

            card
                .querySelector(
                    '[data-action="delete"]'
                )
                ?.addEventListener(
                    'click',
                    () =>
                        moveDailyResourceToTrash(
                            dayData,
                            idx
                        )
                );

            grid.appendChild(
                card
            );
        }
    );

    upgradeDailyResourceNoteIcons();

    requestAnimationFrame(
        syncNotesHeight
    );
}

// ------------------------------------------------------------
// Trash tab now includes Media Resources
// ------------------------------------------------------------

function ensureTrashViewV2() {
    let view =
        document.getElementById(
            'feature-trash-view'
        );

    if (view) return view;

    view =
        document.createElement(
            'div'
        );

    view.id =
        'feature-trash-view';

    view.className =
        'view feature-trash-view';

    view.innerHTML = `
        <header class="feature-page-header">
            <div>
                <span class="weekly-review-eyebrow">Recover deleted content</span>
                <h1>Trash</h1>
                <p>
                    Restore tabs, components, Knowledge Base items, and Media Resources.
                </p>
            </div>

            <button
                type="button"
                class="small-icon-btn feature-trash-view-empty"
                title="Empty Trash"
            >
                <i class="ph ph-trash"></i>
            </button>
        </header>

        <div class="feature-trash-view-list"></div>
    `;

    document.body.insertBefore(
        view,
        document.getElementById(
            'companion-stage'
        ) ||
        null
    );

    view
        .querySelector(
            '.feature-trash-view-empty'
        )
        .addEventListener(
            'click',
            async () => {
                const trash =
                    getFeatureTrash();

                const total =
                    trash.tabs.length +
                    trash.components.length +
                    trash.kbItems.length +
                    trash.resources.length;

                if (!total) return;

                const confirmed =
                    await showAppConfirm({
                        title:
                            'Empty Trash?',
                        message:
                            'Everything in this log’s Trash will be permanently deleted.',
                        confirmLabel:
                            'Empty Trash'
                    });

                if (!confirmed) return;

                trash.tabs = [];
                trash.components = [];
                trash.kbItems = [];
                trash.resources = [];

                saveDb();

                renderTrashViewV2();
            }
        );

    return view;
}

function renderTrashViewV2() {
    const view =
        ensureTrashViewV2();

    const list =
        view.querySelector(
            '.feature-trash-view-list'
        );

    const trash =
        getFeatureTrash();

    list.innerHTML = '';

    const groups = [
        [
            'Tabs',
            trash.tabs,
            entry =>
                entry.tab?.name ||
                'Untitled Tab',
            'tab'
        ],
        [
            'Components',
            trash.components,
            entry =>
                `${entry.component?.title || entry.component?.text || entry.component?.type || 'Component'} · ${entry.tabName || 'Tab'}`,
            'component'
        ],
        [
            'Knowledge Base',
            trash.kbItems,
            entry =>
                entry.itemId ||
                'Knowledge Item',
            'kb'
        ],
        [
            'Media Resources',
            trash.resources,
            entry =>
                getDailyResourceDisplayTitle(
                    entry.resource,
                    entry.originalIndex
                ),
            'resource'
        ]
    ];

    let total = 0;

    groups.forEach(
        ([
            label,
            entries,
            getLabel,
            type
        ]) => {
            if (!entries.length) {
                return;
            }

            total +=
                entries.length;

            const section =
                document.createElement(
                    'section'
                );

            section.className =
                'feature-trash-group weekly-review-section';

            section.innerHTML = `
                <h3>${escapeCustomHtml(label)}</h3>
                <div class="feature-trash-group-list"></div>
            `;

            const host =
                section.querySelector(
                    '.feature-trash-group-list'
                );

            entries.forEach(
                (entry, index) => {
                    const row =
                        document.createElement(
                            'article'
                        );

                    row.className =
                        'feature-trash-row';

                    const when =
                        entry.deletedAt
                            ? new Date(
                                entry.deletedAt
                            ).toLocaleString()
                            : '';

                    const detail =
                        type ===
                        'resource'
                            ? `Day ${entry.day || '?'} · ${getDailyResourceDomain(entry.resource)}`
                            : when;

                    row.innerHTML = `
                        <div class="feature-trash-copy">
                            <strong>${escapeCustomHtml(getLabel(entry))}</strong>
                            <small>${escapeCustomHtml(detail)}</small>
                            ${
                                type ===
                                'resource'
                                    ? `<small>${escapeCustomHtml(when)}</small>`
                                    : ''
                            }
                        </div>

                        <div class="feature-trash-actions">
                            <button
                                type="button"
                                class="small-icon-btn feature-restore"
                                title="Restore"
                            >
                                <i class="ph ph-arrow-counter-clockwise"></i>
                            </button>

                            <button
                                type="button"
                                class="small-icon-btn feature-delete-permanent"
                                title="Delete permanently"
                            >
                                <i class="ph ph-trash"></i>
                            </button>
                        </div>
                    `;

                    row
                        .querySelector(
                            '.feature-restore'
                        )
                        .addEventListener(
                            'click',
                            () => {
                                if (
                                    type ===
                                    'tab'
                                ) {
                                    const [
                                        restored
                                    ] =
                                        trash.tabs.splice(
                                            index,
                                            1
                                        );

                                    const tabs =
                                        getCustomTabs();

                                    const desired =
                                        Number.isFinite(
                                            Number(
                                                restored.originalIndex
                                            )
                                        )
                                            ? Number(
                                                restored.originalIndex
                                            )
                                            : tabs.length;

                                    tabs.splice(
                                        Math.max(
                                            0,
                                            Math.min(
                                                desired,
                                                tabs.length
                                            )
                                        ),
                                        0,
                                        restored.tab
                                    );

                                    saveDb();
                                    renderCustomTabNavigation();
                                    renderAllCustomTabViews();
                                    updateLogSpecificSideNavScrollState();
                                } else if (
                                    type ===
                                    'component'
                                ) {
                                    const targetTab =
                                        getCustomTab(
                                            entry.tabId
                                        );

                                    if (!targetTab) {
                                        showFeatureToast(
                                            'Restore the original tab first.'
                                        );
                                        return;
                                    }

                                    const [
                                        restored
                                    ] =
                                        trash.components.splice(
                                            index,
                                            1
                                        );

                                    if (
                                        !Array.isArray(
                                            targetTab.components
                                        )
                                    ) {
                                        targetTab.components =
                                            [];
                                    }

                                    const desired =
                                        Number.isFinite(
                                            Number(
                                                restored.originalIndex
                                            )
                                        )
                                            ? Number(
                                                restored.originalIndex
                                            )
                                            : targetTab.components.length;

                                    targetTab.components.splice(
                                        Math.max(
                                            0,
                                            Math.min(
                                                desired,
                                                targetTab.components.length
                                            )
                                        ),
                                        0,
                                        restored.component
                                    );

                                    saveDb();
                                    renderCustomTabView(
                                        targetTab.id
                                    );
                                } else if (
                                    type ===
                                    'kb'
                                ) {
                                    const [
                                        restored
                                    ] =
                                        trash.kbItems.splice(
                                            index,
                                            1
                                        );

                                    const desired =
                                        Number.isFinite(
                                            Number(
                                                restored.originalIndex
                                            )
                                        )
                                            ? Number(
                                                restored.originalIndex
                                            )
                                            : db.phrases.length;

                                    db.phrases.splice(
                                        Math.max(
                                            0,
                                            Math.min(
                                                desired,
                                                db.phrases.length
                                            )
                                        ),
                                        0,
                                        restored.itemId
                                    );

                                    db.phrase_meta[
                                        restored.itemId
                                    ] =
                                        restored.meta ||
                                        {};

                                    saveDb();
                                    renderPhrasesLibrary();
                                } else {
                                    const [
                                        restored
                                    ] =
                                        trash.resources.splice(
                                            index,
                                            1
                                        );

                                    const day =
                                        Number(
                                            restored.day
                                        );

                                    if (!db.days[day]) {
                                        db.days[day] = {};
                                    }

                                    if (
                                        !Array.isArray(
                                            db.days[day].resources
                                        )
                                    ) {
                                        db.days[day].resources =
                                            [];
                                    }

                                    const desired =
                                        Number.isFinite(
                                            Number(
                                                restored.originalIndex
                                            )
                                        )
                                            ? Number(
                                                restored.originalIndex
                                            )
                                            : db.days[day].resources.length;

                                    db.days[day].resources.splice(
                                        Math.max(
                                            0,
                                            Math.min(
                                                desired,
                                                db.days[day].resources.length
                                            )
                                        ),
                                        0,
                                        restored.resource
                                    );

                                    saveDb();

                                    if (
                                        Number(currentDay) ===
                                        day
                                    ) {
                                        renderResources(
                                            db.days[day]
                                        );
                                    }
                                }

                                renderTrashViewV2();
                            }
                        );

                    row
                        .querySelector(
                            '.feature-delete-permanent'
                        )
                        .addEventListener(
                            'click',
                            async () => {
                                const confirmed =
                                    await showAppConfirm({
                                        title:
                                            'Delete permanently?',
                                        message:
                                            `“${getLabel(entry)}” cannot be restored after this.`,
                                        confirmLabel:
                                            'Delete Permanently'
                                    });

                                if (!confirmed) return;

                                entries.splice(
                                    index,
                                    1
                                );

                                saveDb();

                                renderTrashViewV2();
                            }
                        );

                    host.appendChild(
                        row
                    );
                }
            );

            list.appendChild(
                section
            );
        }
    );

    if (!total) {
        list.innerHTML = `
            <div class="feature-empty-state feature-trash-page-empty">
                <i class="ph ph-trash"></i>
                <strong>Trash is empty</strong>
                <span>
                    Deleted tabs, components, Knowledge Base items, and Media Resources will show up here.
                </span>
            </div>
        `;
    }

    view
        .querySelector(
            '.feature-trash-view-empty'
        ).disabled =
        !total;
}

// ------------------------------------------------------------
// Notes media-resource icons: YouTube / TikTok / Link
// ------------------------------------------------------------

function renderNotesResourceChoicesV2() {
    const popup =
        document.getElementById(
            'notes-link-popup'
        );

    if (!popup) return;

    let host =
        popup.querySelector(
            '.notes-media-resource-choices'
        );

    if (!host) {
        host =
            document.createElement(
                'div'
            );

        host.className =
            'notes-media-resource-choices';

        popup.appendChild(
            host
        );
    }

    host.innerHTML = '';

    const resources =
        currentDay
            ? (
                db.days[currentDay]
                    ?.resources ||
                []
            )
            : [];

    if (!resources.length) {
        host.innerHTML = `
            <div class="notes-media-resource-empty">
                No Media Resources on this day yet.
            </div>
        `;

        return;
    }

    const heading =
        document.createElement(
            'span'
        );

    heading.className =
        'notes-resource-choice-heading';

    heading.textContent =
        'Or link to a Media Resource from this day';

    host.appendChild(
        heading
    );

    resources.forEach(
        (resource, index) => {
            const button =
                document.createElement(
                    'button'
                );

            button.type = 'button';

            button.className =
                'notes-media-resource-choice';

            button.innerHTML = `
                <i class="ph ${getDailyResourceNoteIconClass(resource)}"></i>

                <span>
                    <strong>${escapeCustomHtml(getDailyResourceDisplayTitle(resource, index))}</strong>
                    <small>${escapeCustomHtml(getDailyResourceDomain(resource))}</small>
                </span>
            `;

            button.addEventListener(
                'click',
                () => {
                    if (!slashRange) return;

                    insertMediaResourceIconAtRangeV2(
                        slashRange,
                        index
                    );

                    if (currentDay) {
                        db.days[currentDay].notes =
                            document.getElementById(
                                'log-notes'
                            ).innerHTML;

                        scheduleSaveDay();
                    }

                    closeNotesLinkPopup();

                    document
                        .getElementById(
                            'log-notes'
                        )
                        ?.focus();
                }
            );

            host.appendChild(
                button
            );
        }
    );
}

function insertMediaResourceIconAtRangeV2(
    range,
    resourceIndex
) {
    if (!range) return;

    const resource =
        currentDay
            ? db.days[currentDay]
                ?.resources?.[
                    resourceIndex
                ]
            : null;

    if (!resource) return;

    const icon =
        document.createElement(
            'a'
        );

    icon.href =
        `#daily-resource-${resourceIndex}`;

    icon.dataset.resourceIndex =
        String(
            resourceIndex
        );

    icon.dataset.resourceUrl =
        String(
            resource.url ||
            ''
        );

    icon.dataset.resourceType =
        resource.type ||
        'link';

    icon.className =
        'notes-link-icon daily-resource-notes-link';

    icon.title =
        `Jump to ${getDailyResourceDisplayTitle(resource, resourceIndex)}`;

    icon.contentEditable =
        'false';

    icon.innerHTML =
        `<i class="ph ${getDailyResourceNoteIconClass(resource)}"></i>`;

    range.deleteContents();
    range.insertNode(
        icon
    );

    const space =
        document.createTextNode(
            '\u00A0'
        );

    range.setStartAfter(
        icon
    );

    range.insertNode(
        space
    );

    range.setStartAfter(
        space
    );

    range.collapse(
        true
    );

    const selection =
        window.getSelection();

    selection.removeAllRanges();

    selection.addRange(
        range
    );
}

function insertMediaResourceIconAtRange(
    range,
    resourceIndex
) {
    insertMediaResourceIconAtRangeV2(
        range,
        resourceIndex
    );
}


// ============================================================
// GLOBAL SEARCH BORDER + ESCAPE MODAL FIX
// ============================================================

function forceDailyGlobalSearchInputBorderless() {
    const input = document.getElementById('daily-global-search-input');
    if (!input) return;

    [
        ['border', '0'],
        ['border-width', '0'],
        ['border-style', 'none'],
        ['outline', '0'],
        ['box-shadow', 'none'],
        ['background', 'transparent'],
        ['background-color', 'transparent'],
        ['border-radius', '0'],
        ['appearance', 'none'],
        ['-webkit-appearance', 'none']
    ].forEach(([property, value]) => {
        input.style.setProperty(property, value, 'important');
    });
}

function closeTopVisibleModalWithEscape() {
    const modals = Array.from(
        document.querySelectorAll('.modal-overlay:not(.hidden)')
    );
    const modal = modals[modals.length - 1];
    if (!modal) return false;

    const selectors = [
        '#app-confirm-cancel',
        '#app-prompt-cancel',
        '.custom-tab-create-close',
        '.custom-tab-settings-close',
        '.daily-collection-close',
        '.daily-custom-tab-picker-close',
        '.backup-restore-close',
        '.feature-trash-close',
        '.theme-builder-close',
        '.kb-category-create-close',
        '.kb-field-create-close',
        '#daily-logs-local-settings-close',
        '#developer-mode-close',
        '.close-btn',
        '[id$="-close"]',
        '[id*="close"]'
    ];

    const closeControl = selectors
        .map(selector => modal.querySelector(selector))
        .find(Boolean);

    if (closeControl) closeControl.click();
    else modal.classList.add('hidden');

    return true;
}

if (!document.documentElement.dataset.modalEscapeEverywhereBound) {
    document.documentElement.dataset.modalEscapeEverywhereBound = 'true';

    document.addEventListener('keydown', event => {
        if (event.key !== 'Escape' || event.repeat) return;

        if (closeTopVisibleModalWithEscape()) {
            event.preventDefault();
            event.stopPropagation();
        }
    });
}

requestAnimationFrame(forceDailyGlobalSearchInputBorderless);

document.addEventListener('focusin', event => {
    if (event.target?.id === 'daily-global-search-input') {
        forceDailyGlobalSearchInputBorderless();
    }
});


// ============================================================
// THEME BUILDER PROJECT ASSET STORAGE
// New uploads are copied into the real project folders by server.js.
// ============================================================

async function readThemeAssetAsDataUrlForProject(file) {
    return new Promise(resolve => {
        if (!file) {
            resolve('');
            return;
        }

        const reader = new FileReader();

        reader.onload =
            () =>
                resolve(
                    String(
                        reader.result ||
                        ''
                    )
                );

        reader.onerror =
            () =>
                resolve('');

        reader.readAsDataURL(
            file
        );
    });
}

async function checkThemeBuilderAssetServer() {
    try {
        const response = await fetch('/api/theme-assets-status', {
            method: 'GET',
            cache: 'no-store'
        });

        if (!response.ok) {
            return {
                ok: false,
                message:
                    'The Theme Builder file-save endpoint is not active. Replace the project root server.js with the updated server.js and restart the Node server.'
            };
        }

        const result = await response.json().catch(() => ({}));

        if (result?.feature !== 'theme-assets') {
            return {
                ok: false,
                message:
                    'The running server is an older version. Replace server.js and restart the Node server.'
            };
        }

        return { ok: true };
    } catch (error) {
        return {
            ok: false,
            message:
                'Could not reach the local Node server. Make sure server.js is running, then try again.'
        };
    }
}

async function uploadThemeBuilderAssetToProject(
    file,
    kind
) {
    if (!file) return null;

    const serverStatus =
        await checkThemeBuilderAssetServer();

    if (!serverStatus.ok) {
        showFeatureToast(
            serverStatus.message
        );
        return null;
    }

    const dataUrl =
        await readThemeAssetAsDataUrlForProject(
            file
        );

    if (!dataUrl) {
        showFeatureToast(
            `Could not read “${file.name}”.`
        );
        return null;
    }

    let response;

    try {
        response = await fetch(
            `/api/theme-assets/${encodeURIComponent(HOBBY)}`,
            {
                method: 'POST',
                headers: {
                    'Content-Type':
                        'application/json'
                },
                body: JSON.stringify({
                    kind,
                    fileName: file.name,
                    dataUrl
                })
            }
        );
    } catch (error) {
        showFeatureToast(
            'The local server connection failed while saving the file.'
        );
        return null;
    }

    const rawText = await response.text();
    let result = {};

    try {
        result = rawText
            ? JSON.parse(rawText)
            : {};
    } catch (error) {
        result = {};
    }

    if (!response.ok) {
        let message =
            result.message ||
            `Could not save “${file.name}” into the project.`;

        if (response.status === 404) {
            message =
                'The Theme Builder upload endpoint was not found. Replace the project root server.js with the updated server.js and restart Node.';
        } else if (response.status === 413) {
            message =
                result.message ||
                `“${file.name}” is too large to upload.`;
        } else if (!result.message && rawText) {
            message =
                `Server error ${response.status} while saving “${file.name}”.`;
        }

        showFeatureToast(message);
        console.error(
            'Theme Builder asset upload failed:',
            response.status,
            rawText
        );
        return null;
    }

    if (!result.url || !result.projectPath) {
        showFeatureToast(
            'The server saved an incomplete Theme Builder response. Restart the updated server.js and try again.'
        );
        return null;
    }

    return result;
}

async function deleteThemeBuilderProjectAsset(
    url
) {
    const value =
        String(url || '');

    if (
        !value ||
        value.startsWith('data:') ||
        value.startsWith('blob:')
    ) {
        return true;
    }

    try {
        const response =
            await fetch(
                `/api/theme-assets/${encodeURIComponent(HOBBY)}`,
                {
                    method: 'DELETE',
                    headers: {
                        'Content-Type':
                            'application/json'
                    },
                    body:
                        JSON.stringify({
                            url: value
                        })
                }
            );

        if (!response.ok) {
            const result =
                await response
                    .json()
                    .catch(
                        () => ({})
                    );

            showFeatureToast(
                result.message ||
                'Could not remove the old Theme Builder file from the project.'
            );

            return false;
        }

        return true;
    } catch (error) {
        showFeatureToast(
            'Could not remove the old Theme Builder file from the project.'
        );

        return false;
    }
}

function renderThemeBuilderSvgAsset(
    svg
) {
    if (svg?.url) {
        return `
            <img
                src="${escapeCustomHtml(svg.url)}"
                alt=""
                draggable="false"
            >
        `;
    }

    return String(
        svg?.markup ||
        ''
    );
}



function getThemeBuilderDraft(modal) {
    const draft = {
        ...FEATURE_SUITE_DEFAULT_THEME,
        ...CUSTOM_THEME_MEDIA_DEFAULTS_V3,
        backgroundSvgs:
            Array.isArray(
                modal._themeBackgroundSvgs
            )
                ? modal._themeBackgroundSvgs
                : []
    };

    modal
        .querySelectorAll(
            '[data-theme-key]'
        )
        .forEach(input => {
            const key =
                input.dataset.themeKey;

            draft[key] =
                input.type === 'range' ||
                input.type === 'number'
                    ? Number(
                        input.value
                    )
                    : input.value;
        });

    draft.backgroundImage =
        modal._themeBackgroundImage ||
        '';

    draft.backgroundImageName =
        modal._themeBackgroundImageName ||
        '';

    draft.backgroundImageProjectPath =
        modal._themeBackgroundProjectPath ||
        '';

    draft.introAudio =
        modal._themeIntroAudio ||
        '';

    draft.introAudioName =
        modal._themeIntroAudioName ||
        '';

    draft.introAudioProjectPath =
        modal._themeAudioProjectPath ||
        '';

    draft.audioPlayMode =
        getThemeAudioMode(
            modal
        );

    draft.audioStart =
        parseThemeTimecode(
            modal
                .querySelector(
                    '.theme-builder-audio-start'
                )
                ?.value,
            0
        );

    draft.audioEnd =
        parseThemeTimecode(
            modal
                .querySelector(
                    '.theme-builder-audio-end'
                )
                ?.value,
            Math.max(
                1,
                draft.audioStart + 20
            )
        );

    draft.audioFade =
        !!modal
            .querySelector(
                '.theme-builder-audio-fade'
            )
            ?.checked;

    return draft;
}

// URL-backed SVGs live as real files under public/svg, while old embedded
// custom themes remain backwards-compatible.
function mountCustomThemeBackgroundSvgsV2(
    theme
) {
    const svgs =
        Array.isArray(
            theme.backgroundSvgs
        )
            ? theme.backgroundSvgs
            : [];

    if (!svgs.length) return;

    const stage =
        document.createElement(
            'div'
        );

    stage.id =
        'custom-theme-background-stage';

    stage.className =
        'custom-theme-background-stage';

    svgs.forEach(
        (svg, index) => {
            const item =
                document.createElement(
                    'div'
                );

            item.className =
                'custom-theme-background-svg';

            const left =
                5 +
                (
                    (
                        index * 31 +
                        11
                    ) %
                    90
                );

            const top =
                7 +
                (
                    (
                        index * 47 +
                        19
                    ) %
                    84
                );

            item.style.left =
                `${left}%`;

            item.style.top =
                `${top}%`;

            item.style.setProperty(
                '--custom-svg-delay',
                `${(index % 13) * -0.42}s`
            );

            item.style.setProperty(
                '--custom-svg-rotate',
                `${((index % 2) ? -1 : 1) * (4 + (index % 9) * 3)}deg`
            );

            item.style.setProperty(
                '--custom-svg-scale',
                String(
                    0.78 +
                    (index % 5) *
                        0.08
                )
            );

            if (svg?.url) {
                const image =
                    document.createElement(
                        'img'
                    );

                image.src =
                    svg.url;

                image.alt =
                    '';

                image.draggable =
                    false;

                item.appendChild(
                    image
                );
            } else {
                item.innerHTML =
                    String(
                        svg?.markup ||
                        ''
                    );
            }

            stage.appendChild(
                item
            );
        }
    );

    document.body.prepend(
        stage
    );
}



