function pseudoRandomThemePreviewV10(
    seed,
    index,
    salt = 0
) {
    const raw =
        Math.sin(
            (
                seed *
                    9973 +
                index *
                    7919 +
                salt *
                    104729
            ) *
                12.9898
        ) *
        43758.5453;

    return (
        raw -
        Math.floor(
            raw
        )
    );
}

function themeSideSlotsV10() {
    return [
        [4, 10],
        [4, 25],
        [4, 40],
        [4, 55],
        [4, 70],
        [4, 85],
        [96, 10],
        [96, 25],
        [96, 40],
        [96, 55],
        [96, 70],
        [96, 85],
        [15, 5],
        [30, 5],
        [45, 5],
        [60, 5],
        [75, 5],
        [90, 5],
        [15, 95],
        [30, 95],
        [45, 95],
        [60, 95],
        [75, 95],
        [90, 95]
    ];
}

function getPreviewSvgAssignmentsV10(
    modal,
    draft
) {
    const svgs =
        draft.backgroundSvgs ||
        [];

    if (
        !svgs.length
    ) {
        return [];
    }

    if (
        !Number.isFinite(
            modal._themePreviewDistributionSeedV10
        )
    ) {
        modal._themePreviewDistributionSeedV10 =
            Math.random() *
            100000;
    }

    const seed =
        modal._themePreviewDistributionSeedV10;

    let refs =
        svgs.map(
            (svg, originalIndex) => ({
                svg,
                originalIndex
            })
        );

    if (
        draft.svgDistribution ===
        'side-random'
    ) {
        refs =
            refs
                .map(
                    (entry, index) => ({
                        ...entry,
                        order:
                            pseudoRandomThemePreviewV10(
                                seed,
                                index,
                                77
                            )
                    })
                )
                .sort(
                    (a, b) =>
                        a.order -
                        b.order
                );
    }

    const sideSlots =
        themeSideSlotsV10();

    return refs.map(
        (
            entry,
            displayIndex
        ) => {
            if (
                draft.svgDistribution ===
                'random'
            ) {
                return {
                    ...entry,
                    left:
                        7 +
                        pseudoRandomThemePreviewV10(
                            seed,
                            displayIndex,
                            11
                        ) *
                            86,
                    top:
                        7 +
                        pseudoRandomThemePreviewV10(
                            seed,
                            displayIndex,
                            23
                        ) *
                            86
                };
            }

            const slot =
                sideSlots[
                    displayIndex %
                    sideSlots.length
                ];

            return {
                ...entry,
                left:
                    slot[0],
                top:
                    slot[1]
            };
        }
    );
}

function playSingleThemeHoverSoundV10(
    url,
    volume = 0.72
) {
    if (!url) return;

    const audio =
        new Audio(
            url
        );

    audio.volume =
        volume;

    customThemeHoverAudiosV10
        .add(
            audio
        );

    const clean =
        () =>
            customThemeHoverAudiosV10
                .delete(
                    audio
                );

    audio.addEventListener(
        'ended',
        clean,
        {
            once: true
        }
    );

    audio.play()
        .catch(
            clean
        );
}

function chooseThemeHoverSoundUrlV10(
    theme,
    svg
) {
    if (
        !theme.svgHoverSoundsEnabled
    ) {
        return '';
    }

    const sounds =
        Array.isArray(
            theme.svgHoverSounds
        )
            ? theme.svgHoverSounds
            : [];

    if (
        !sounds.length
    ) {
        return '';
    }

    if (
        theme.svgHoverSoundMode ===
        'mapped'
    ) {
        return (
            svg?.hoverSoundUrl ||
            ''
        );
    }

    const picked =
        sounds[
            Math.floor(
                Math.random() *
                sounds.length
            )
        ];

    return (
        picked?.url ||
        ''
    );
}

