function getRuntimeSvgAssignmentsV10(
    theme
) {
    const svgs =
        Array.isArray(
            theme.backgroundSvgs
        )
            ? theme.backgroundSvgs
                .map(
                    (svg, originalIndex) => ({
                        svg:
                            ensureSvgAdvancedDefaultsV10({
                                ...svg
                            }),
                        originalIndex
                    })
                )
            : [];

    if (
        theme.svgDistribution ===
        'side-random'
    ) {
        for (
            let index =
                svgs.length - 1;
            index >
                0;
            index--
        ) {
            const swapIndex =
                Math.floor(
                    Math.random() *
                    (index + 1)
                );

            [
                svgs[index],
                svgs[swapIndex]
            ] = [
                svgs[swapIndex],
                svgs[index]
            ];
        }
    }

    const slots =
        themeSideSlotsV10();

    return svgs.map(
        (
            entry,
            displayIndex
        ) => {
            if (
                theme.svgDistribution ===
                'random'
            ) {
                return {
                    ...entry,
                    left:
                        6 +
                        Math.random() *
                            88,
                    top:
                        6 +
                        Math.random() *
                            88
                };
            }

            const slot =
                slots[
                    displayIndex %
                    slots.length
                ];

            return {
                ...entry,
                left:
                    slot[0],
                top:
                    slot[1]
            };
        }
    );
}

