// Keep the theme source complete even when a newly added theme folder
// was not already present in the hidden select.
async function hydrateThemeSourceFromManifestV10() {
    if (
        !dailyThemeSelect ||
        dailyThemeSelect.dataset
            .manifestHydratedV10 ===
            'true'
    ) {
        return;
    }

    dailyThemeSelect.dataset
        .manifestHydratedV10 =
        'true';

    try {
        const response =
            await fetch(
                '/themes/themes.json',
                {
                    cache:
                        'no-store'
                }
            );

        if (
            !response.ok
        ) {
            return;
        }

        const manifest =
            await response.json();

        if (
            !Array.isArray(
                manifest
            )
        ) {
            return;
        }

        manifest.forEach(
            theme => {
                if (
                    !theme?.id
                ) {
                    return;
                }

                const rawId =
                    String(
                        theme.id
                    );

                const value =
                    rawId.startsWith(
                        'theme-'
                    )
                        ? rawId
                        : `theme-${rawId}`;

                const exists =
                    Array.from(
                        dailyThemeSelect
                            .options
                    ).some(
                        option =>
                            option.value ===
                            value
                    );

                if (
                    exists
                ) {
                    return;
                }

                const option =
                    document.createElement(
                        'option'
                    );

                option.value =
                    value;

                option.textContent =
                    theme.name ||
                    rawId
                        .replace(
                            /^theme-/,
                            ''
                        )
                        .replace(
                            /[-_]+/g,
                            ' '
                        )
                        .replace(
                            /\b\w/g,
                            char =>
                                char.toUpperCase()
                        );

                dailyThemeSelect.appendChild(
                    option
                );
            }
        );

        renderThemePicker();
    } catch {}
}

setTimeout(
    hydrateThemeSourceFromManifestV10,
    0
);



// ============================================================
// THEME BUILDER V11 — CLEAR UI + RELIABLE LIVE PREVIEW
// - strong tab-icon color
// - exact hover preview
// - one default SVG animation with optional per-SVG overrides
// - scene presets inspired by the uploaded legacy theme patterns
// - no dropdown required for preview navigation
// ============================================================

const CUSTOM_THEME_V11_DEFAULTS = {
    svgDefaultAnimation: 'float',
    svgScenePreset: 'scatter'
};

const THEME_SVG_ANIMATION_OPTIONS_V11 = [
    ['float', 'Float'],
    ['bob', 'Bob Up & Down'],
    ['drift', 'Slow Drift'],
    ['travel', 'Travel Across'],
    ['fall', 'Fall / Rain'],
    ['spin', 'Slow Spin'],
    ['pulse', 'Pulse'],
    ['still', 'Still']
];

const THEME_SCENE_PRESETS_V11 = [
    ['scatter', 'Float Scatter'],
    ['edge', 'Edge Collage'],
    ['swim', 'Swim Lanes'],
    ['rain', 'Falling / Digital Rain'],
    ['custom', 'Custom']
];

function themeBuilderAnimationLabelV11(
    value
) {
    return (
        THEME_SVG_ANIMATION_OPTIONS_V11
            .find(
                option =>
                    option[0] ===
                    value
            )?.[1] ||
        'Float'
    );
}

function inferSvgDefaultAnimationV11(
    theme
) {
    if (
        THEME_SVG_ANIMATION_OPTIONS_V11
            .some(
                option =>
                    option[0] ===
                    theme?.svgDefaultAnimation
            )
    ) {
        return theme.svgDefaultAnimation;
    }

    const counts =
        new Map();

    (
        theme?.backgroundSvgs ||
        []
    ).forEach(
        svg => {
            const value =
                svg?.animation;

            if (
                THEME_SVG_ANIMATION_OPTIONS_V11
                    .some(
                        option =>
                            option[0] ===
                            value
                    )
            ) {
                counts.set(
                    value,
                    (
                        counts.get(
                            value
                        ) ||
                        0
                    ) +
                    1
                );
            }
        }
    );

    let best =
        'float';

    let bestCount =
        -1;

    counts.forEach(
        (
            count,
            value
        ) => {
            if (
                count >
                bestCount
            ) {
                best =
                    value;
                bestCount =
                    count;
            }
        }
    );

    return best;
}

function normalizeSvgOverrideV11(
    svg,
    defaultAnimation
) {
    const copy =
        ensureSvgAdvancedDefaultsV10({
            ...svg
        });

    if (
        !Object.prototype
            .hasOwnProperty.call(
                copy,
                'animationOverride'
            )
    ) {
        copy.animationOverride =
            (
                copy.animation &&
                copy.animation !==
                    defaultAnimation
            )
                ? copy.animation
                : '';
    }

    if (
        !THEME_SVG_ANIMATION_OPTIONS_V11
            .some(
                option =>
                    option[0] ===
                    copy.animationOverride
            )
    ) {
        copy.animationOverride =
            '';
    }

    copy.animation =
        copy.animationOverride ||
        defaultAnimation;

    return copy;
}

function getEffectiveSvgAnimationV11(
    svg,
    defaultAnimation
) {
    const override =
        svg?.animationOverride;

    if (
        THEME_SVG_ANIMATION_OPTIONS_V11
            .some(
                option =>
                    option[0] ===
                    override
            )
    ) {
        return override;
    }

    if (
        THEME_SVG_ANIMATION_OPTIONS_V11
            .some(
                option =>
                    option[0] ===
                    defaultAnimation
            )
    ) {
        return defaultAnimation;
    }

    return 'float';
}

const getThemeBuilderDraftBeforeV11 =
    getThemeBuilderDraft;

getThemeBuilderDraft =
    function(
        modal
    ) {
        const draft = {
            ...CUSTOM_THEME_V11_DEFAULTS,
            ...getThemeBuilderDraftBeforeV11(
                modal
            )
        };

        const defaultAnimation =
            modal
                .querySelector(
                    '.theme-builder-svg-default-animation'
                )
                ?.value ||
            draft.svgDefaultAnimation ||
            'float';

        draft.svgDefaultAnimation =
            THEME_SVG_ANIMATION_OPTIONS_V11
                .some(
                    option =>
                        option[0] ===
                        defaultAnimation
                )
                ? defaultAnimation
                : 'float';

        draft.svgScenePreset =
            modal
                .querySelector(
                    '.theme-builder-svg-scene-preset'
                )
                ?.value ||
            draft.svgScenePreset ||
            'scatter';

        const distribution =
            modal
                .querySelector(
                    '.theme-builder-svg-distribution'
                )
                ?.value;

        if (
            [
                'random',
                'side-fixed',
                'side-random',
                'lanes',
                'columns'
            ].includes(
                distribution
            )
        ) {
            draft.svgDistribution =
                distribution;
        }

        draft.backgroundSvgs =
            (
                modal._themeBackgroundSvgs ||
                []
            ).map(
                svg => {
                    const normalized =
                        normalizeSvgOverrideV11(
                            svg,
                            draft.svgDefaultAnimation
                        );

                    normalized.animation =
                        getEffectiveSvgAnimationV11(
                            normalized,
                            draft.svgDefaultAnimation
                        );

                    return normalized;
                }
            );

        return draft;
    };

function applySvgScenePresetV11(
    modal,
    preset
) {
    const defaultAnimation =
        modal.querySelector(
            '.theme-builder-svg-default-animation'
        );

    const distribution =
        modal.querySelector(
            '.theme-builder-svg-distribution'
        );

    const map = {
        scatter: {
            animation:
                'float',
            distribution:
                'random'
        },
        edge: {
            animation:
                'float',
            distribution:
                'side-fixed'
        },
        swim: {
            animation:
                'travel',
            distribution:
                'lanes'
        },
        rain: {
            animation:
                'fall',
            distribution:
                'columns'
        }
    };

    const config =
        map[preset];

    if (!config) {
        return;
    }

    if (defaultAnimation) {
        defaultAnimation.value =
            config.animation;
    }

    if (distribution) {
        distribution.value =
            config.distribution;
    }

    modal._themeBackgroundSvgs =
        (
            modal._themeBackgroundSvgs ||
            []
        ).map(
            svg => ({
                ...svg,
                animation:
                    svg.animationOverride ||
                    config.animation
            })
        );

    modal._themePreviewDistributionSeedV10 =
        Math.random() *
        100000;

    renderThemeBuilderSvgListV2(
        modal
    );

    updateThemeBuilderPreview(
        modal
    );
}

