function installThemeBuilderSectionTabsV11(
    modal
) {
    const host =
        modal.querySelector(
            '.theme-builder-controls'
        );

    if (!host) {
        return;
    }

    host
        .querySelector(
            '.theme-builder-section-tabs-v11'
        )
        ?.remove();

    const tabs =
        document.createElement(
            'nav'
        );

    tabs.className =
        'theme-builder-section-tabs-v11';

    tabs.setAttribute(
        'aria-label',
        'Theme Builder sections'
    );

    const sections = [
        ['colors', 'Colors', 'ph-palette'],
        ['background', 'Background', 'ph-image'],
        ['audio', 'Audio', 'ph-music-notes'],
        ['svgs', 'Images', 'ph-images']
    ];

    tabs.innerHTML =
        sections
            .map(
                (
                    [
                        id,
                        label,
                        icon
                    ]
                ) => `
                    <button
                        type="button"
                        data-theme-builder-panel="${id}"
                    >
                        <i class="ph ${icon}"></i>
                        <span>${label}</span>
                    </button>
                `
            )
            .join('');

    host.prepend(
        tabs
    );

    const children =
        Array.from(
            host.children
        ).filter(
            child =>
                child !==
                tabs
        );

    children.forEach(
        child => {
            let panel =
                'colors';

            if (
                child.matches(
                    '.theme-builder-background-controls'
                ) ||
                child.querySelector(
                    '.theme-builder-background-file'
                )
            ) {
                panel =
                    'background';
            } else if (
                child.querySelector(
                    '.theme-builder-audio-file'
                )
            ) {
                panel =
                    'audio';
            } else if (
                child.matches(
                    '.theme-builder-svg-section'
                ) ||
                child.querySelector(
                    '.theme-builder-svg-file'
                )
            ) {
                panel =
                    'svgs';
            }

            child.dataset
                .themeBuilderPanelGroup =
                panel;
        }
    );

    const showPanel =
        panel => {
            modal._themeBuilderUiPanelV11 =
                panel;

            tabs
                .querySelectorAll(
                    'button'
                )
                .forEach(
                    button => {
                        button.classList.toggle(
                            'active',
                            button.dataset
                                .themeBuilderPanel ===
                                panel
                        );
                    }
                );

            children.forEach(
                child => {
                    child.classList.toggle(
                        'theme-builder-panel-hidden-v11',
                        child.dataset
                            .themeBuilderPanelGroup !==
                            panel
                    );
                }
            );
        };

    tabs
        .querySelectorAll(
            'button'
        )
        .forEach(
            button => {
                button.addEventListener(
                    'click',
                    () =>
                        showPanel(
                            button.dataset
                                .themeBuilderPanel
                        )
                );
            }
        );

    showPanel(
        modal._themeBuilderUiPanelV11 ||
        'colors'
    );
}

