function laneAssignmentsV11(
    refs
) {
    const laneCount =
        Math.max(
            1,
            Math.min(
                11,
                refs.length
            )
        );

    return refs.map(
        (
            entry,
            index
        ) => ({
            ...entry,
            left:
                index %
                    2 ===
                0
                    ? 12
                    : 88,
            top:
                7 +
                (
                    index %
                    laneCount
                ) *
                    (
                        86 /
                        Math.max(
                            1,
                            laneCount -
                                1
                        )
                    )
        })
    );
}

function columnAssignmentsV11(
    refs
) {
    const count =
        Math.max(
            1,
            Math.min(
                12,
                refs.length
            )
        );

    return refs.map(
        (
            entry,
            index
        ) => ({
            ...entry,
            left:
                7 +
                (
                    index %
                    count
                ) *
                    (
                        86 /
                        Math.max(
                            1,
                            count -
                                1
                        )
                    ),
            top:
                8 +
                (
                    index *
                    17
                ) %
                    76
        })
    );
}

