function applyThemeBuilderInteractionVarsV12(
    target,
    draft
) {
    if (!target) {
        return;
    }

    const surface =
        draft.surface ||
        '#ffffff';

    const hoverSolid =
        mixThemeColorsV12(
            draft.hoverColor,
            surface,
            draft.hoverOpacity
        );

    const variables = {
        '--custom-theme-hover-solid':
            hoverSolid,
        '--custom-theme-kb-category-bg':
            draft.kbCategoryBackgroundColor,
        '--custom-theme-kb-category-text':
            draft.kbCategoryTextColor,
        '--custom-theme-kb-category-hover-bg':
            draft.kbCategoryHoverBackgroundColor,
        '--custom-theme-kb-category-hover-text':
            draft.kbCategoryHoverTextColor
    };

    Object.entries(
        variables
    ).forEach(
        (
            [
                name,
                value
            ]
        ) => {
            target.style.setProperty(
                name,
                value,
                'important'
            );
        }
    );
}

function prepareThemeBuilderDayPreviewV12(
    modal
) {
    const canvas =
        modal.querySelector(
            '.theme-builder-live-canvas'
        );

    const page =
        canvas?.querySelector(
            '.theme-builder-live-page'
        );

    if (
        !canvas ||
        !page ||
        canvas.dataset
            .previewSourceId !==
            'log-view'
    ) {
        return;
    }

    const day =
        Math.max(
            1,
            Number(
                modal
                    ._themeBuilderPreviewDay
            ) ||
                currentDay ||
                1
        );

    const dayData =
        db.days?.[day] ||
        {};

    const badge =
        page.querySelector(
            '[data-preview-original-id="current-day-badge"]'
        );

    if (badge) {
        badge.textContent =
            String(day);
    }

    const date =
        page.querySelector(
            '[data-preview-original-id="current-date-title"]'
        );

    if (date) {
        try {
            date.textContent =
                formatDate(
                    day
                );
        } catch {
            date.textContent =
                `Day ${day}`;
        }
    }

    const notes =
        page.querySelector(
            '[data-preview-original-id="log-notes"]'
        );

    if (notes) {
        notes.innerHTML =
            dayData.notes ||
            '';
    }

    const phrases =
        page.querySelector(
            '[data-preview-original-id="phrases-container"]'
        );

    if (phrases) {
        phrases.innerHTML =
            (
                dayData.phrases ||
                []
            )
                .slice(
                    0,
                    8
                )
                .map(
                    phrase => `
                        <div class="chip">
                            <div class="kb-day-item-title-row">
                                <button
                                    type="button"
                                    class="kb-day-item-main"
                                    tabindex="-1"
                                >
                                    <span class="kb-day-item-title">
                                        ${escapeKnowledgeHtml(phrase)}
                                    </span>
                                </button>
                            </div>
                        </div>
                    `
                )
                .join('');
    }

    const tools =
        page.querySelector(
            '[data-preview-original-id="tools-container"]'
        );

    if (tools) {
        tools.innerHTML =
            (
                dayData.tools ||
                []
            )
                .slice(
                    0,
                    8
                )
                .map(
                    name => `
                        <div class="tool-row">
                            <i class="ph ph-wrench"></i>
                            <span class="tool-row-name">
                                ${escapeKnowledgeHtml(name)}
                            </span>
                        </div>
                    `
                )
                .join('');
    }
}

function bindThemeBuilderDayCardsV12(
    modal
) {
    const canvas =
        modal.querySelector(
            '.theme-builder-live-canvas'
        );

    if (
        !canvas ||
        canvas.dataset
            .previewSourceId !==
            'grid-view'
    ) {
        return;
    }

    const page =
        canvas.querySelector(
            '.theme-builder-live-page'
        );

    if (!page) {
        return;
    }

    page
        .querySelectorAll(
            '[data-day]'
        )
        .forEach(
            element => {
                const day =
                    Number(
                        element.dataset
                            .day
                    );

                if (
                    !Number.isFinite(
                        day
                    ) ||
                    day <
                        1
                ) {
                    return;
                }

                const clickable =
                    element.matches(
                        '.polaroid-card'
                    )
                        ? element
                        : (
                            element.querySelector(
                                '.day-box'
                            ) ||
                            element
                        );

                clickable.classList.add(
                    'theme-builder-preview-day-clickable-v12'
                );

                clickable.addEventListener(
                    'click',
                    event => {
                        event.preventDefault();
                        event.stopPropagation();

                        modal._themeBuilderPreviewDay =
                            day;

                        modal._themeBuilderPreviewSourceId =
                            'log-view';

                        rebuildActualThemeBuilderPreviewV5(
                            modal
                        );
                    }
                );
            }
        );
}

