// ============================================================
// THEME BUILDER V17 — KNOWLEDGE CATEGORY PREVIEW FIX
// IMPORTANT: cloned preview IDs are removed by stripThemeBuilderCloneIdsV5.
// The original #library-filter-tabs becomes
// [data-preview-original-id="library-filter-tabs"].
// This preview layer therefore styles the CLONED controls directly.
// ============================================================

function getThemeBuilderPreviewCategoriesV17(
    modal
) {
    const page =
        modal?.querySelector(
            '.theme-builder-live-page'
        );

    if (!page) {
        return [];
    }

    return Array.from(
        page.querySelectorAll(
            [
                '[data-preview-original-id="library-filter-tabs"] .filter-tab',
                '.kb-category-grid-item'
            ].join(',')
        )
    );
}

function isThemeBuilderPreviewCategorySelectedV17(
    element
) {
    return (
        element.classList.contains(
            'active'
        ) ||
        element.getAttribute(
            'aria-selected'
        ) ===
            'true' ||
        element.dataset
            .themeBuilderPreviewCategorySelectedV16 ===
            'true' ||
        element.dataset
            .themeBuilderPreviewCategorySelectedV17 ===
            'true'
    );
}

function applyThemeBuilderPreviewCategoryStateV17(
    modal,
    element,
    forcedState = ''
) {
    if (
        !modal ||
        !element
    ) {
        return;
    }

    const draft =
        getThemeBuilderDraft(
            modal
        );

    const selected =
        forcedState ===
            'selected' ||
        (
            !forcedState &&
            isThemeBuilderPreviewCategorySelectedV17(
                element
            )
        );

    const hovered =
        !selected &&
        (
            forcedState ===
                'hover' ||
            (
                !forcedState &&
                element.matches(
                    ':hover'
                )
            )
        );

    let background;
    let text;
    let border;
    let shadow;

    if (selected) {
        background =
            draft.kbCategoryFocusBackgroundColor ||
            draft.kbCategoryBackgroundColor ||
            '#171717';

        text =
            draft.kbCategoryFocusTextColor ||
            draft.kbCategoryTextColor ||
            '#ffffff';

        border =
            draft.kbCategoryFocusBorderColor ||
            draft.border ||
            '#171717';

        shadow =
            `inset 0 -3px 0 ${border}`;
    } else if (hovered) {
        background =
            draft.kbCategoryHoverBackgroundColor ||
            draft.hoverColor ||
            draft.kbCategoryBackgroundColor ||
            '#d9d2ff';

        text =
            draft.kbCategoryHoverTextColor ||
            draft.kbCategoryTextColor ||
            draft.text ||
            '#171717';

        border =
            draft.border ||
            'transparent';

        shadow =
            'none';
    } else {
        background =
            draft.kbCategoryBackgroundColor ||
            draft.surface ||
            '#ffffff';

        text =
            draft.kbCategoryTextColor ||
            draft.text ||
            '#171717';

        border =
            draft.border ||
            'transparent';

        shadow =
            'none';
    }

    [
        ['background', background],
        ['background-color', background],
        ['background-image', 'none'],
        ['color', text],
        ['-webkit-text-fill-color', text],
        ['border-color', border],
        ['box-shadow', shadow]
    ].forEach(
        (
            [
                property,
                value
            ]
        ) => {
            element.style.setProperty(
                property,
                value,
                'important'
            );
        }
    );

    element
        .querySelectorAll(
            'span, strong, small, i, svg'
        )
        .forEach(
            child => {
                child.style.setProperty(
                    'color',
                    'inherit',
                    'important'
                );

                child.style.setProperty(
                    '-webkit-text-fill-color',
                    'currentColor',
                    'important'
                );

                if (
                    child.matches(
                        'i, svg'
                    )
                ) {
                    child.style.setProperty(
                        'stroke',
                        'currentColor',
                        'important'
                    );
                }
            }
        );
}

function refreshThemeBuilderPreviewCategoriesV17(
    modal
) {
    getThemeBuilderPreviewCategoriesV17(
        modal
    ).forEach(
        element =>
            applyThemeBuilderPreviewCategoryStateV17(
                modal,
                element
            )
    );
}

function bindThemeBuilderPreviewCategoriesV17(
    modal
) {
    const categories =
        getThemeBuilderPreviewCategoriesV17(
            modal
        );

    categories.forEach(
        element => {
            if (
                element.dataset
                    .themeBuilderCategoryV17Bound ===
                'true'
            ) {
                applyThemeBuilderPreviewCategoryStateV17(
                    modal,
                    element
                );

                return;
            }

            element.dataset
                .themeBuilderCategoryV17Bound =
                'true';

            element.addEventListener(
                'pointerenter',
                () => {
                    if (
                        isThemeBuilderPreviewCategorySelectedV17(
                            element
                        )
                    ) {
                        applyThemeBuilderPreviewCategoryStateV17(
                            modal,
                            element,
                            'selected'
                        );
                    } else {
                        applyThemeBuilderPreviewCategoryStateV17(
                            modal,
                            element,
                            'hover'
                        );
                    }
                }
            );

            element.addEventListener(
                'pointerleave',
                () => {
                    applyThemeBuilderPreviewCategoryStateV17(
                        modal,
                        element
                    );
                }
            );

            element.addEventListener(
                'focus',
                () => {
                    applyThemeBuilderPreviewCategoryStateV17(
                        modal,
                        element,
                        'selected'
                    );
                }
            );

            element.addEventListener(
                'blur',
                () => {
                    applyThemeBuilderPreviewCategoryStateV17(
                        modal,
                        element
                    );
                }
            );

            element.addEventListener(
                'click',
                event => {
                    event.preventDefault();
                    event.stopPropagation();

                    categories.forEach(
                        other => {
                            other.dataset
                                .themeBuilderPreviewCategorySelectedV17 =
                                'false';

                            other.dataset
                                .themeBuilderPreviewCategorySelectedV16 =
                                'false';

                            other.classList.remove(
                                'active'
                            );

                            other.setAttribute(
                                'aria-selected',
                                'false'
                            );

                            applyThemeBuilderPreviewCategoryStateV17(
                                modal,
                                other,
                                'normal'
                            );
                        }
                    );

                    element.dataset
                        .themeBuilderPreviewCategorySelectedV17 =
                        'true';

                    element.classList.add(
                        'active'
                    );

                    element.setAttribute(
                        'aria-selected',
                        'true'
                    );

                    applyThemeBuilderPreviewCategoryStateV17(
                        modal,
                        element,
                        'selected'
                    );
                }
            );

            applyThemeBuilderPreviewCategoryStateV17(
                modal,
                element
            );
        }
    );
}

