function ensureCustomPolaroidViewerV19() {
    let modal =
        document.getElementById(
            'custom-polaroid-viewer-v19'
        );

    if (modal) {
        return modal;
    }

    modal =
        document.createElement(
            'div'
        );

    modal.id =
        'custom-polaroid-viewer-v19';

    modal.className =
        'modal-overlay hidden custom-polaroid-viewer-v19';

    modal.innerHTML = `
        <div class="custom-polaroid-viewer-box-v19">
            <button
                type="button"
                class="small-icon-btn custom-polaroid-viewer-close-v19"
                title="Close"
                aria-label="Close"
            >
                <i class="ph ph-x"></i>
            </button>

            <div class="custom-polaroid-viewer-media-v19"></div>
            <div class="custom-polaroid-viewer-caption-v19"></div>
        </div>
    `;

    document.body.appendChild(
        modal
    );

    const close =
        () => {
            modal.classList.add(
                'hidden'
            );

            const media =
                modal.querySelector(
                    '.custom-polaroid-viewer-media-v19'
                );

            if (media) {
                media.innerHTML =
                    '';
            }
        };

    modal
        .querySelector(
            '.custom-polaroid-viewer-close-v19'
        )
        ?.addEventListener(
            'click',
            close
        );

    modal.addEventListener(
        'pointerdown',
        event => {
            if (
                event.target ===
                modal
            ) {
                close();
            }
        }
    );

    document.addEventListener(
        'keydown',
        event => {
            if (
                event.key ===
                    'Escape' &&
                !modal.classList.contains(
                    'hidden'
                )
            ) {
                event.preventDefault();
                close();
            }
        }
    );

    modal._closeCustomPolaroidViewerV19 =
        close;

    return modal;
}

function openCustomPolaroidViewerV19(
    item
) {
    const modal =
        ensureCustomPolaroidViewerV19();

    const media =
        modal.querySelector(
            '.custom-polaroid-viewer-media-v19'
        );

    const caption =
        modal.querySelector(
            '.custom-polaroid-viewer-caption-v19'
        );

    if (
        !media ||
        !caption
    ) {
        return;
    }

    media.innerHTML =
        renderPolaroidMediaHtml(
            item
        );

    caption.textContent =
        item.caption ||
        'Untitled';

    modal.classList.remove(
        'hidden'
    );
}

