// ------------------------------------------------------------
// RICHER SVG PLACEMENT — SAFE CENTERED COORDINATES
// ------------------------------------------------------------

function themePreviewRandomV20(
    seed,
    index,
    salt = 0
) {
    const raw =
        Math.sin(
            (
                seed *
                    0.913 +
                index *
                    17.171 +
                salt *
                    31.337
            ) *
                12.9898
        ) *
        43758.5453123;

    return raw -
        Math.floor(
            raw
        );
}

function shuffledThemeEntriesV20(
    entries,
    seed = null
) {
    const result =
        entries.map(
            entry => ({
                ...entry
            })
        );

    for (
        let index =
            result.length -
                1;
        index >
            0;
        index--
    ) {
        const value =
            seed ===
                null
                ? Math.random()
                : themePreviewRandomV20(
                    seed,
                    index,
                    491
                );

        const swap =
            Math.floor(
                value *
                (
                    index +
                    1
                )
            );

        [
            result[index],
            result[swap]
        ] = [
            result[swap],
            result[index]
        ];
    }

    return result;
}

function themePlacementSlotsV20(
    mode
) {
    const leftRight = [
        [11, 16],
        [12, 34],
        [10, 55],
        [13, 76],
        [12, 88],
        [89, 15],
        [88, 32],
        [90, 52],
        [87, 72],
        [89, 87]
    ];

    const topBottom = [
        [16, 12],
        [34, 11],
        [54, 13],
        [73, 10],
        [88, 13],
        [15, 88],
        [33, 89],
        [52, 87],
        [71, 90],
        [87, 87]
    ];

    const corners = [
        [13, 14],
        [27, 12],
        [12, 28],
        [87, 14],
        [73, 12],
        [88, 29],
        [13, 86],
        [27, 88],
        [12, 72],
        [87, 86],
        [73, 88],
        [88, 71]
    ];

    if (
        mode ===
        'top-bottom'
    ) {
        return topBottom;
    }

    if (
        mode ===
        'corners'
    ) {
        return corners;
    }

    return leftRight;
}

function getThemeBuilderPreviewPlacementV20(
    modal,
    draft
) {
    if (
        !Number.isFinite(
            modal._themePreviewDistributionSeedV10
        )
    ) {
        modal._themePreviewDistributionSeedV10 =
            Math.random() *
            100000;
    }

    const seed =
        modal._themePreviewDistributionSeedV10;

    let entries =
        (
            draft.backgroundSvgs ||
            []
        ).map(
            (
                svg,
                originalIndex
            ) => ({
                svg:
                    ensureSvgAdvancedDefaultsV10(
                        svg
                    ),
                originalIndex
            })
        );

    const mode =
        draft.svgDistribution ||
        'random';

    if (
        [
            'side-random',
            'all-edges-random'
        ].includes(
            mode
        )
    ) {
        entries =
            shuffledThemeEntriesV20(
                entries,
                seed
            );
    }

    const slots =
        themePlacementSlotsV20(
            mode
        );

    return entries.map(
        (
            entry,
            index
        ) => {
            const rand =
                salt =>
                    themePreviewRandomV20(
                        seed,
                        index,
                        salt
                    );

            if (
                mode ===
                'wide-random'
            ) {
                return {
                    ...entry,
                    left:
                        9 +
                        rand(11) *
                            82,
                    top:
                        10 +
                        rand(17) *
                            80
                };
            }

            if (
                mode ===
                'center-cluster'
            ) {
                return {
                    ...entry,
                    left:
                        29 +
                        rand(21) *
                            42,
                    top:
                        25 +
                        rand(27) *
                            50
                };
            }

            if (
                mode ===
                'all-edges-random'
            ) {
                const edge =
                    Math.floor(
                        rand(31) *
                        4
                    );

                const along =
                    13 +
                    rand(37) *
                        74;

                if (
                    edge ===
                    0
                ) {
                    return {
                        ...entry,
                        left:
                            along,
                        top:
                            11 +
                            rand(39) *
                                3
                    };
                }

                if (
                    edge ===
                    1
                ) {
                    return {
                        ...entry,
                        left:
                            87 +
                            rand(41) *
                                3,
                        top:
                            along
                    };
                }

                if (
                    edge ===
                    2
                ) {
                    return {
                        ...entry,
                        left:
                            along,
                        top:
                            87 +
                            rand(43) *
                                3
                    };
                }

                return {
                    ...entry,
                    left:
                        10 +
                        rand(47) *
                            3,
                    top:
                        along
                };
            }

            if (
                [
                    'side-fixed',
                    'side-random',
                    'top-bottom',
                    'corners'
                ].includes(
                    mode
                )
            ) {
                const slot =
                    slots[
                        index %
                        slots.length
                    ];

                const jitter =
                    mode ===
                        'side-random'
                        ? 2.6
                        : 1.2;

                return {
                    ...entry,
                    left:
                        slot[0] +
                        (
                            rand(53) -
                            .5
                        ) *
                            jitter,
                    top:
                        slot[1] +
                        (
                            rand(59) -
                            .5
                        ) *
                            jitter
                };
            }

            // Organic scatter: centered safe zone, not upper-left biased.
            return {
                ...entry,
                left:
                    13 +
                    rand(61) *
                        74,
                top:
                    14 +
                    rand(67) *
                        72
            };
        }
    );
}

