function openThemeBuilderKnowledgeSettingsPreviewV20(
    modal
) {
    if (
        typeof renderSettings ===
        'function'
    ) {
        renderSettings();
    }

    const real =
        document.getElementById(
            'settings-modal'
        );

    const realBox =
        real?.querySelector(
            '.modal-box'
        );

    if (!realBox) {
        return;
    }

    const overlay =
        createThemeBuilderPreviewSettingsShellV20(
            modal,
            'Knowledge Base Settings'
        );

    const content =
        overlay?.querySelector(
            '.theme-builder-preview-settings-content-v20'
        );

    if (!content) {
        return;
    }

    const clone =
        realBox.cloneNode(
            true
        );

    clone
        .querySelector(
            '.modal-header'
        )
        ?.remove();

    clone.removeAttribute(
        'id'
    );

    clone
        .querySelectorAll(
            '[id]'
        )
        .forEach(
            element => {
                element.dataset
                    .previewOriginalId =
                    element.id;

                element.removeAttribute(
                    'id'
                );
            }
        );

    clone.classList.add(
        'theme-builder-preview-cloned-settings-v20'
    );

    content.appendChild(
        clone
    );

    clone
        .querySelectorAll(
            '.kb-view-btn'
        )
        .forEach(
            button => {
                button.addEventListener(
                    'click',
                    event => {
                        event.preventDefault();

                        clone
                            .querySelectorAll(
                                '.kb-view-btn'
                            )
                            .forEach(
                                item =>
                                    item.classList.remove(
                                        'active'
                                    )
                            );

                        button.classList.add(
                            'active'
                        );

                        const hideRow =
                            clone.querySelector(
                                '[data-preview-original-id="settings-hide-categories-row"]'
                            );

                        hideRow?.classList.toggle(
                            'hidden',
                            button.dataset
                                .view !==
                                'polaroid'
                        );
                    }
                );
            }
        );

    clone
        .querySelectorAll(
            '[data-preview-original-id="settings-category-tabs"] .filter-tab'
        )
        .forEach(
            tab => {
                tab.addEventListener(
                    'click',
                    event => {
                        event.preventDefault();

                        tab.parentElement
                            ?.querySelectorAll(
                                '.filter-tab'
                            )
                            .forEach(
                                item =>
                                    item.classList.remove(
                                        'active'
                                    )
                            );

                        tab.classList.add(
                            'active'
                        );
                    }
                );
            }
        );
}

