function stripReadyToReviewPreviewBoxV23(
    modal
) {
    const page =
        modal?.querySelector(
            '.theme-builder-live-page'
        );

    if (!page) {
        return;
    }

    const candidates =
        Array.from(
            page.querySelectorAll(
                [
                    'div',
                    'section',
                    'article',
                    'aside',
                    'span',
                    'p',
                    'strong',
                    'button'
                ].join(',')
            )
        )
        .filter(
            element => {
                const text =
                    String(
                        element.textContent ||
                        ''
                    )
                        .replace(
                            /\s+/g,
                            ' '
                        )
                        .trim()
                        .toLowerCase();

                return (
                    text ===
                        'ready to review' ||
                    text.startsWith(
                        'ready to review '
                    )
                );
            }
        )
        .sort(
            (
                a,
                b
            ) =>
                a.children.length -
                b.children.length
        );

    if (!candidates.length) {
        return;
    }

    const label =
        candidates[0];

    label.classList.add(
        'theme-builder-ready-review-clean-v23'
    );

    // Sometimes the current page renders the message inside a one-purpose
    // wrapper/card. Clean that wrapper only in the preview too.
    let parent =
        label.parentElement;

    for (
        let depth =
            0;
        parent &&
            depth <
                2;
        depth++,
        parent =
            parent.parentElement
    ) {
        const normalized =
            String(
                parent.textContent ||
                ''
            )
                .replace(
                    /\s+/g,
                    ' '
                )
                .trim()
                .toLowerCase();

        if (
            normalized ===
                String(
                    label.textContent ||
                    ''
                )
                    .replace(
                        /\s+/g,
                        ' '
                    )
                    .trim()
                    .toLowerCase()
        ) {
            parent.classList.add(
                'theme-builder-ready-review-clean-v23'
            );
        } else {
            break;
        }
    }
}

