// ============================================================
// THEME PICKER V24 — CUSTOM THEMES ALWAYS LAST
// Built-in themes stay first. Custom-created themes are grouped after
// every built-in theme, preserving the order they already have in the
// picker/select (creation order), and the + card remains the final item.
// ============================================================

function moveCustomThemeCardsToEndV24() {
    if (!themePicker) {
        return;
    }

    const createCard =
        themePicker.querySelector(
            '.theme-picker-create-card'
        );

    const customCards =
        Array.from(
            themePicker.querySelectorAll(
                '.theme-picker-card'
            )
        ).filter(
            card => {
                const value =
                    String(
                        card.dataset.theme ||
                        ''
                    );

                return (
                    value ===
                        'theme-custom-builder' ||
                    value.startsWith(
                        'theme-custom-builder-'
                    ) ||
                    card.classList.contains(
                        'theme-picker-custom-theme'
                    )
                );
            }
        );

    // appendChild moves existing nodes without recreating them, so all
    // click/right-click handlers and the relative order of custom themes
    // are preserved.
    customCards.forEach(
        card => {
            if (createCard) {
                themePicker.insertBefore(
                    card,
                    createCard
                );
            } else {
                themePicker.appendChild(
                    card
                );
            }
        }
    );

    // The create-theme + is always the very last thing in the gallery.
    if (createCard) {
        themePicker.appendChild(
            createCard
        );
    }
}

const renderThemePickerBeforeV24 =
    renderThemePicker;

renderThemePicker =
    function() {
        renderThemePickerBeforeV24();

        moveCustomThemeCardsToEndV24();
    };

// Also repair the current already-rendered gallery once on load.
requestAnimationFrame(
    moveCustomThemeCardsToEndV24
);



// ============================================================
// THEME BUILDER V25 — EDIT EVERY THEME
// Built-in/default themes remain their original themes, but Theme Builder
// edits are saved as per-theme overrides. Nothing in the original theme
// CSS/JS folders is destroyed.
// ============================================================

let themeOverrideApplySuppressedV25 =
    false;

function ensureThemeOverridesV25() {
    if (!db.settings) {
        db.settings = {};
    }

    if (
        !db.settings.themeOverrides ||
        typeof db.settings.themeOverrides !==
            'object' ||
        Array.isArray(
            db.settings.themeOverrides
        )
    ) {
        db.settings.themeOverrides =
            {};
    }

    return db.settings.themeOverrides;
}

function getThemeOverrideV25(
    themeId
) {
    if (
        !themeId ||
        themeId ===
            'theme-custom-builder'
    ) {
        return null;
    }

    return (
        ensureThemeOverridesV25()[
            themeId
        ] ||
        null
    );
}

function parseThemeCssColorV25(
    value,
    fallback
) {
    const text =
        String(value || '')
            .trim();

    if (
        /^#[0-9a-f]{6}$/i.test(
            text
        )
    ) {
        return text;
    }

    if (
        /^#[0-9a-f]{3}$/i.test(
            text
        )
    ) {
        return (
            '#' +
            text
                .slice(1)
                .split('')
                .map(
                    char =>
                        char + char
                )
                .join('')
        );
    }

    const match =
        text.match(
            /rgba?\(\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)/i
        );

    if (match) {
        const hex =
            value =>
                Math.max(
                    0,
                    Math.min(
                        255,
                        Math.round(
                            Number(value) ||
                            0
                        )
                    )
                )
                    .toString(16)
                    .padStart(
                        2,
                        '0'
                    );

        return (
            '#' +
            hex(match[1]) +
            hex(match[2]) +
            hex(match[3])
        );
    }

    return fallback;
}

function captureCurrentThemeBuilderBaseV25(
    themeId,
    themeName
) {
    const rootStyle =
        getComputedStyle(
            document.documentElement
        );

    const bodyStyle =
        getComputedStyle(
            document.body
        );

    const sampleSurface =
        document.querySelector(
            [
                '.view.active .modal-section',
                '.view.active .day-box',
                '.view.active .filter-tab',
                '.view.active .phrase-card',
                '.view.active'
            ].join(',')
        );

    const surfaceStyle =
        sampleSurface
            ? getComputedStyle(
                sampleSurface
            )
            : bodyStyle;

    const preview =
        typeof THEME_PREVIEWS !==
            'undefined'
            ? THEME_PREVIEWS[
                themeId
            ]
            : null;

    const background =
        parseThemeCssColorV25(
            rootStyle.getPropertyValue(
                '--custom-theme-page-bg'
            ) ||
            bodyStyle.backgroundColor,
            preview?.[0] ||
            '#f4f1ff'
        );

    const surface =
        parseThemeCssColorV25(
            rootStyle.getPropertyValue(
                '--white'
            ) ||
            surfaceStyle.backgroundColor,
            preview?.[1] ||
            '#ffffff'
        );

    const text =
        parseThemeCssColorV25(
            rootStyle.getPropertyValue(
                '--black'
            ) ||
            bodyStyle.color,
            '#171717'
        );

    const muted =
        parseThemeCssColorV25(
            rootStyle.getPropertyValue(
                '--muted-text'
            ),
            '#6b7280'
        );

    const accent =
        parseThemeCssColorV25(
            rootStyle.getPropertyValue(
                '--custom-theme-accent'
            ),
            preview?.[2] ||
            text
        );

    const thinBorder =
        rootStyle.getPropertyValue(
            '--thin-border'
        );

    const borderColorMatch =
        String(
            thinBorder ||
            ''
        ).match(
            /(#[0-9a-f]{3,8}|rgba?\([^)]+\))/i
        );

    const border =
        parseThemeCssColorV25(
            borderColorMatch?.[1],
            text
        );

    const radius =
        Math.max(
            0,
            Math.min(
                30,
                parseFloat(
                    rootStyle.getPropertyValue(
                        '--border-radius'
                    )
                ) ||
                parseFloat(
                    surfaceStyle.borderRadius
                ) ||
                0
            )
        );

    return {
        ...FEATURE_SUITE_DEFAULT_THEME,
        ...CUSTOM_THEME_MEDIA_DEFAULTS_V3,
        ...CUSTOM_THEME_VISUAL_DEFAULTS_V4,
        ...THEME_BUILDER_NAV_DEFAULTS_V6,
        ...CUSTOM_THEME_ADVANCED_DEFAULTS_V10,
        ...CUSTOM_THEME_V11_DEFAULTS,
        ...CUSTOM_THEME_V12_DEFAULTS,
        ...CUSTOM_THEME_V13_DEFAULTS,
        ...CUSTOM_THEME_V15_DEFAULTS,
        ...CUSTOM_THEME_V19_DEFAULTS,
        ...CUSTOM_THEME_V20_DEFAULTS,

        name:
            themeName ||
            (
                themeId ===
                    'default'
                    ? 'Default'
                    : String(
                        themeId ||
                        'Theme'
                    )
                        .replace(
                            /^theme-/,
                            ''
                        )
                        .replace(
                            /[-_]+/g,
                            ' '
                        )
                        .replace(
                            /\b\w/g,
                            char =>
                                char.toUpperCase()
                        )
            ),

        background,
        surface,
        text,
        border,
        accent,
        muted,
        radius,

        tabIconColor:
            parseThemeCssColorV25(
                rootStyle.getPropertyValue(
                    '--custom-theme-tab-icon-color'
                ),
                text
            ),

        tabTitleColor:
            parseThemeCssColorV25(
                rootStyle.getPropertyValue(
                    '--custom-theme-tab-title-color'
                ),
                text
            ),

        backButtonColor:
            parseThemeCssColorV25(
                rootStyle.getPropertyValue(
                    '--custom-theme-back-button-color'
                ),
                text
            ),

        backgroundSvgs:
            []
    };
}

function waitForThemeCssV25(
    themeId
) {
    if (
        !themeId ||
        themeId ===
            'default' ||
        themeId ===
            'theme-custom-builder'
    ) {
        return Promise.resolve();
    }

    const link =
        document.getElementById(
            'dynamic-theme-css'
        );

    if (
        !link ||
        link.sheet
    ) {
        return new Promise(
            resolve =>
                requestAnimationFrame(
                    () =>
                        requestAnimationFrame(
                            resolve
                        )
                )
        );
    }

    return new Promise(
        resolve => {
            let finished =
                false;

            const done =
                () => {
                    if (finished) {
                        return;
                    }

                    finished =
                        true;

                    resolve();
                };

            link.addEventListener(
                'load',
                done,
                {
                    once: true
                }
            );

            setTimeout(
                done,
                700
            );
        }
    );
}

function validateThemeBuilderBeforeSaveV25(
    modal
) {
    if (
        getThemeAudioMode(
            modal
        ) !==
        'segment'
    ) {
        return true;
    }

    const startText =
        modal
            .querySelector(
                '.theme-builder-audio-start'
            )
            ?.value;

    const endText =
        modal
            .querySelector(
                '.theme-builder-audio-end'
            )
            ?.value;

    if (
        !isValidThemeTimecode(
            startText
        ) ||
        !isValidThemeTimecode(
            endText
        )
    ) {
        showFeatureToast(
            'Use the 00:00 format for the audio start and end.'
        );

        return false;
    }

    if (
        parseThemeTimecode(
            endText
        ) <=
        parseThemeTimecode(
            startText
        )
    ) {
        showFeatureToast(
            'The audio end time has to be after the start time.'
        );

        return false;
    }

    return true;
}

async function saveThemeOverrideV25(
    modal
) {
    if (
        !validateThemeBuilderBeforeSaveV25(
            modal
        )
    ) {
        return;
    }

    const themeId =
        modal.dataset
            .themeBuilderEditingThemeV25;

    if (
        !themeId ||
        themeId ===
            'theme-custom-builder'
    ) {
        return;
    }

    const draft =
        getThemeBuilderDraft(
            modal
        );

    ensureThemeOverridesV25()[
        themeId
    ] = {
        ...draft
    };

    db.settings.theme =
        themeId;

    await saveDb();

    modal._themeEditSavedV25 =
        true;

    themeOverrideApplySuppressedV25 =
        false;

    await applyTheme(
        themeId,
        {
            persist:
                false
        }
    );

    if (dailyThemeSelect) {
        dailyThemeSelect.value =
            themeId;
    }

    themePickerSelected =
        themeId;

    renderThemePicker();

    modal.classList.add(
        'hidden'
    );

    dailySettingsModal?.classList.add(
        'hidden'
    );

    showFeatureToast(
        `Saved edits to “${draft.name || 'theme'}”.`
    );
}

async function restoreThemeAfterCanceledEditV25(
    modal
) {
    if (
        !modal ||
        modal._themeEditSavedV25 ||
        !modal.dataset
            .themeBuilderEditingThemeV25
    ) {
        return;
    }

    const previous =
        modal._themeEditPreviousThemeV25 ||
        db.settings.theme ||
        'default';

    modal.dataset
        .themeBuilderEditingThemeV25 =
        '';

    themeOverrideApplySuppressedV25 =
        false;

    await applyTheme(
        previous,
        {
            persist:
                false
        }
    );

    db.settings.theme =
        previous;

    if (dailyThemeSelect) {
        dailyThemeSelect.value =
            previous;
    }

    themePickerSelected =
        previous;
}

function bindThemeBuilderEditCancelV25(
    modal
) {
    if (
        modal.dataset
            .themeBuilderEditCancelBoundV25 ===
        'true'
    ) {
        return;
    }

    modal.dataset
        .themeBuilderEditCancelBoundV25 =
        'true';

    const closeButton =
        modal.querySelector(
            '.theme-builder-close'
        );

    closeButton?.addEventListener(
        'click',
        () => {
            restoreThemeAfterCanceledEditV25(
                modal
            );
        }
    );

    modal.addEventListener(
        'pointerdown',
        event => {
            if (
                event.target ===
                modal
            ) {
                setTimeout(
                    () => {
                        if (
                            modal.classList.contains(
                                'hidden'
                            )
                        ) {
                            restoreThemeAfterCanceledEditV25(
                                modal
                            );
                        }
                    },
                    0
                );
            }
        }
    );
}

async function openAnyThemeInBuilderV25(
    themeId,
    themeName
) {
    if (
        themeId ===
        'theme-custom-builder'
    ) {
        openExistingCustomThemeFromPickerV7();
        return;
    }

    const modal =
        ensureThemeBuilderModal();

    const previousTheme =
        db.settings.theme ||
        'default';

    modal._themeEditPreviousThemeV25 =
        previousTheme;

    modal._themeEditSavedV25 =
        false;

    modal.dataset
        .themeBuilderEditingThemeV25 =
        themeId;

    modal.dataset
        .themeBuilderMode =
        'edit-existing-theme';

    bindThemeBuilderEditCancelV25(
        modal
    );

    // Load the original theme WITHOUT its saved Builder override so the
    // initial Builder values are based on the real theme itself.
    themeOverrideApplySuppressedV25 =
        true;

    await applyTheme(
        themeId,
        {
            persist:
                false
        }
    );

    await waitForThemeCssV25(
        themeId
    );

    const base =
        captureCurrentThemeBuilderBaseV25(
            themeId,
            themeName
        );

    const existingOverride =
        getThemeOverrideV25(
            themeId
        );

    const editTheme = {
        ...base,
        ...(existingOverride ||
            {}),
        name:
            existingOverride?.name ||
            themeName ||
            base.name
    };

    themeOverrideApplySuppressedV25 =
        false;

    // Restore the DB's actual selection while keeping the edit theme
    // visually loaded behind the Builder for its real-page clone.
    db.settings.theme =
        previousTheme;

    populateThemeBuilder(
        modal,
        editTheme
    );

    // V29: the old Reset button was intentionally removed in V28.
    // Built-in editing must not depend on that removed control.
    const legacyResetButtonV29 =
        modal.querySelector(
            '.theme-builder-reset'
        );

    if (legacyResetButtonV29) {
        legacyResetButtonV29.onclick =
            () => {
                populateThemeBuilder(
                    modal,
                    {
                        ...base,
                        name:
                            themeName ||
                            base.name
                    }
                );
            };
    }

    modal
        .querySelector(
            '.theme-builder-save'
        ).onclick =
        () =>
            saveThemeOverrideV25(
                modal
            );

    modal.classList.remove(
        'hidden'
    );

    requestAnimationFrame(
        () => {
            modal
                .querySelector(
                    '[data-theme-key="name"]'
                )
                ?.focus();
        }
    );
}

const applyThemeBeforeOverridesV25 =
    applyTheme;

applyTheme =
    async function(
        themeValue,
        opts = {}
    ) {
        await applyThemeBeforeOverridesV25(
            themeValue,
            opts
        );

        if (
            themeOverrideApplySuppressedV25 ||
            themeValue ===
                'theme-custom-builder'
        ) {
            return;
        }

        const override =
            getThemeOverrideV25(
                themeValue ||
                'default'
            );

        if (!override) {
            return;
        }

        // Keep the original theme CSS/JS mounted, then layer the Builder
        // variables/components on top of it.
        document.body.classList.add(
            'theme-custom-builder'
        );

        applyCustomBuiltTheme(
            override
        );

        if (
            typeof applyCursorChoice ===
            'function'
        ) {
            applyCursorChoice();
        }
    };

const createThemePickerCardBeforeEditAllV25 =
    createThemePickerCard;

createThemePickerCard =
    function(
        option
    ) {
        const card =
            createThemePickerCardBeforeEditAllV25(
                option
            );

        if (!card) {
            return card;
        }

        const themeId =
            option.value;

        const getDisplayName =
            () =>
                getThemeOverrideV25(
                    themeId
                )?.name ||
                option.textContent.trim();

        const nameNode =
            card.querySelector(
                '.theme-picker-name'
            );

        if (
            nameNode &&
            themeId !==
                'theme-custom-builder'
        ) {
            nameNode.textContent =
                getDisplayName();

            card.dataset.themeName =
                getDisplayName();
        }

        const hint =
            card.querySelector(
                '.theme-picker-hint'
            );

        if (hint) {
            hint.textContent =
                themeId ===
                    'default'
                    ? 'Click to apply · Right-click to edit'
                    : 'Click to apply · Right-click for options';
        }

        // Capture phase intentionally replaces older delete-only context menus.
        card.addEventListener(
            'contextmenu',
            event => {
                event.preventDefault();
                event.stopImmediatePropagation();

                const actions = [
                    {
                        label:
                            'Edit Theme',
                        icon:
                            'ph-pencil-simple',
                        action:
                            () =>
                                openAnyThemeInBuilderV25(
                                    themeId,
                                    getDisplayName()
                                )
                    }
                ];

                if (
                    themeId !==
                    'default'
                ) {
                    actions.push({
                        label:
                            'Delete Theme',
                        icon:
                            'ph-trash',
                        danger:
                            true,
                        action:
                            () =>
                                deleteThemeFromPickerV2(
                                    themeId,
                                    getDisplayName()
                                )
                    });
                }

                showCustomItemContextMenu(
                    event.clientX,
                    event.clientY,
                    actions
                );
            },
            {
                capture:
                    true
            }
        );

        return card;
    };

const renderThemePickerBeforeEditAllV25 =
    renderThemePicker;

renderThemePicker =
    function() {
        ensureThemeOverridesV25();

        renderThemePickerBeforeEditAllV25();

        // Preserve V24's ordering rule after applying edited display names.
        moveCustomThemeCardsToEndV24();
    };



// ============================================================
// THEME BUILDER V26 — FINAL BACK-BUTTON TRANSPARENCY
// + REFERENCE-STYLE SVG COMPOSITIONS + OVERLAP CONTROL
// ============================================================

const CUSTOM_THEME_V26_DEFAULTS = {
    svgAllowOverlap: false
};

// ------------------------------------------------------------
// BACK ARROWS: NEVER A FILLED / OPAQUE BUTTON
// ------------------------------------------------------------

function getBackButtonTargetV26(
    element
) {
    if (
        !element ||
        typeof element.closest !==
            'function'
    ) {
        return null;
    }

    return element.closest(
        [
            '.header-back-btn',
            '.custom-tab-back-btn',
            'button[id*="back" i]',
            'button[class*="back-btn" i]',
            'button[aria-label*="back" i]',
            'button[title*="back" i]',
            '[data-preview-original-id*="back" i]',
            '[data-preview-original-id="close-tools-btn"]',
            '[data-preview-original-id="close-phrases-btn"]',
            '[data-preview-original-id="close-quizzes-btn"]',
            '[data-preview-original-id="fc-prev"]',
            '#close-tools-btn',
            '#close-phrases-btn',
            '#close-quizzes-btn',
            '#fc-prev'
        ].join(',')
    );
}

function forceBackButtonTransparentV26(
    button
) {
    if (!button) {
        return;
    }

    [
        'background',
        'background-color',
        'background-image',
        'box-shadow',
        'filter',
        'backdrop-filter',
        '-webkit-backdrop-filter',
        'outline'
    ].forEach(
        property => {
            button.style.setProperty(
                property,
                property ===
                    'outline'
                    ? 'none'
                    : property.includes(
                        'filter'
                    )
                        ? 'none'
                        : property ===
                            'box-shadow'
                            ? 'none'
                            : property ===
                                'background-image'
                                ? 'none'
                                : 'transparent',
                'important'
            );
        }
    );

    button.style.setProperty(
        'border-color',
        'transparent',
        'important'
    );
}

function forceAllBackButtonsTransparentV26(
    root =
        document
) {
    root
        .querySelectorAll?.(
            [
                '.header-back-btn',
                '.custom-tab-back-btn',
                'button[id*="back" i]',
                'button[class*="back-btn" i]',
                'button[aria-label*="back" i]',
                'button[title*="back" i]',
                '[data-preview-original-id*="back" i]',
                '[data-preview-original-id="close-tools-btn"]',
                '[data-preview-original-id="close-phrases-btn"]',
                '[data-preview-original-id="close-quizzes-btn"]',
                '[data-preview-original-id="fc-prev"]',
                '#close-tools-btn',
                '#close-phrases-btn',
                '#close-quizzes-btn',
                '#fc-prev'
            ].join(',')
        )
        .forEach(
            forceBackButtonTransparentV26
        );
}

[
    'pointerover',
    'pointerenter',
    'focusin',
    'mousedown',
    'touchstart'
].forEach(
    eventName => {
        document.addEventListener(
            eventName,
            event => {
                const button =
                    getBackButtonTargetV26(
                        event.target
                    );

                if (button) {
                    forceBackButtonTransparentV26(
                        button
                    );
                }
            },
            true
        );
    }
);

const backButtonObserverV26 =
    new MutationObserver(
        records => {
            records.forEach(
                record => {
                    record.addedNodes
                        .forEach(
                            node => {
                                if (
                                    node.nodeType !==
                                    1
                                ) {
                                    return;
                                }

                                const button =
                                    getBackButtonTargetV26(
                                        node
                                    );

                                if (button) {
                                    forceBackButtonTransparentV26(
                                        button
                                    );
                                }

                                forceAllBackButtonsTransparentV26(
                                    node
                                );
                            }
                        );
                }
            );
        }
    );

if (
    document.documentElement
) {
    backButtonObserverV26.observe(
        document.documentElement,
        {
            childList:
                true,
            subtree:
                true
        }
    );
}

requestAnimationFrame(
    () =>
        forceAllBackButtonsTransparentV26()
);

// ------------------------------------------------------------
// SVG PLACEMENT UI
// ------------------------------------------------------------

function normalizeSvgPlacementModeV26(
    value
) {
    const legacyMap = {
        random:
            'balanced-spread',
        'wide-random':
            'random-safe',
        'center-cluster':
            'mixed-scene',
        corners:
            'corner-garden',
        'side-fixed':
            'winter-sides',
        'side-random':
            'random-edges-safe',
        'top-bottom':
            'snoopy-frame',
        'all-edges-random':
            'random-edges-safe',
        lanes:
            'winx-stage',
        columns:
            'winx-stage'
    };

    const normalized =
        legacyMap[
            value
        ] ||
        value;

    return [
        'balanced-spread',
        'snoopy-frame',
        'winter-sides',
        'winx-stage',
        'corner-garden',
        'mixed-scene',
        'random-safe',
        'random-edges-safe'
    ].includes(
        normalized
    )
        ? normalized
        : 'balanced-spread';
}

function ensureThemeBuilderPlacementUiV26(
    modal,
    theme = {}
) {
    const select =
        modal.querySelector(
            '.theme-builder-svg-distribution'
        );

    if (!select) {
        return;
    }

    const field =
        select.closest(
            '.theme-builder-field'
        );

    const title =
        field?.querySelector(
            ':scope > span'
        );

    if (title) {
        title.textContent =
            'Decoration Placement';
    }

    const current =
        normalizeSvgPlacementModeV26(
            theme.svgDistribution ||
            select.value
        );

    select.innerHTML = `
        <option value="balanced-spread">
            Balanced scatter · spacious
        </option>

        <option value="snoopy-frame">
            Snoopy-style frame
        </option>

        <option value="winter-sides">
            Winter-style side framing
        </option>

        <option value="winx-stage">
            Winx-style spread
        </option>

        <option value="corner-garden">
            Corners + edge accents
        </option>

        <option value="mixed-scene">
            Mixed scene · edges + center
        </option>

        <option value="random-safe">
            Random scatter · rerolls
        </option>

        <option value="random-edges-safe">
            Random edges · rerolls
        </option>
    `;

    select.value =
        current;

    let overlapRow =
        modal.querySelector(
            '.theme-builder-svg-overlap-row-v26'
        );

    if (!overlapRow) {
        const holder =
            document.createElement(
                'div'
            );

        holder.innerHTML =
            themeBuilderToggleRowV4({
                className:
                    'theme-builder-svg-overlap-row-v26',
                title:
                    'Allow SVG Overlap',
                detail:
                    'Off keeps stickers separated. On allows stickers to cross over each other.',
                checked:
                    !!theme.svgAllowOverlap
            });

        overlapRow =
            holder.firstElementChild;

        field?.insertAdjacentElement(
            'afterend',
            overlapRow
        );
    }

    const overlapInput =
        overlapRow.querySelector(
            'input'
        );

    overlapInput.classList.add(
        'theme-builder-svg-overlap-enabled-v26'
    );

    overlapInput.checked =
        !!theme.svgAllowOverlap;

    if (
        overlapInput.dataset
            .themeBuilderV26Bound !==
        'true'
    ) {
        overlapInput.dataset
            .themeBuilderV26Bound =
            'true';

        overlapInput.addEventListener(
            'change',
            () => {
                modal._themePreviewDistributionSeedV10 =
                    Math.random() *
                    100000;

                updateThemeBuilderPreview(
                    modal
                );
            }
        );
    }

    if (
        select.dataset
            .themeBuilderPlacementV26 !==
        'true'
    ) {
        select.dataset
            .themeBuilderPlacementV26 =
            'true';

        select.addEventListener(
            'change',
            () => {
                modal._themePreviewDistributionSeedV10 =
                    Math.random() *
                    100000;

                updateThemeBuilderPreview(
                    modal
                );
            }
        );
    }
}

const getThemeBuilderDraftBeforeV26 =
    getThemeBuilderDraft;

getThemeBuilderDraft =
    function(
        modal
    ) {
        const draft = {
            ...CUSTOM_THEME_V26_DEFAULTS,
            ...getThemeBuilderDraftBeforeV26(
                modal
            )
        };

        const select =
            modal?.querySelector(
                '.theme-builder-svg-distribution'
            );

        if (select) {
            draft.svgDistribution =
                normalizeSvgPlacementModeV26(
                    select.value
                );
        }

        draft.svgAllowOverlap =
            !!modal
                ?.querySelector(
                    '.theme-builder-svg-overlap-enabled-v26'
                )
                ?.checked;

        return draft;
    };

// ------------------------------------------------------------
// REFERENCE-STYLE PLACEMENT ENGINE
// ------------------------------------------------------------

function placementRandomV26(
    seed,
    index,
    salt
) {
    if (
        Number.isFinite(
            seed
        )
    ) {
        return themePreviewRandomV20(
            seed,
            index,
            salt
        );
    }

    return Math.random();
}

function jitterPointV26(
    point,
    amount,
    rand,
    index
) {
    return {
        x:
            point[0] +
            (
                rand(
                    index,
                    71
                ) -
                .5
            ) *
                amount,
        y:
            point[1] +
            (
                rand(
                    index,
                    79
                ) -
                .5
            ) *
                amount
    };
}

function clampPlacementPointV26(
    point
) {
    return {
        x:
            Math.max(
                6,
                Math.min(
                    94,
                    point.x
                )
            ),
        y:
            Math.max(
                10,
                Math.min(
                    92,
                    point.y
                )
            )
    };
}

function shufflePlacementPointsV26(
    points,
    rand
) {
    const result =
        points.map(
            point => ({
                ...point
            })
        );

    for (
        let index =
            result.length -
                1;
        index >
            0;
        index--
    ) {
        const swap =
            Math.floor(
                rand(
                    index,
                    101
                ) *
                (
                    index +
                    1
                )
            );

        [
            result[index],
            result[swap]
        ] = [
            result[swap],
            result[index]
        ];
    }

    return result;
}

function makeReferenceCandidatesV26(
    mode,
    count,
    rand
) {
    // Snoopy reference: a loose frame around the page with many positions
    // down both sides and a few top/bottom accents.
    const snoopy = [
        [7,16],[8,28],[8,42],[9,57],[10,72],[12,87],
        [20,21],[19,38],[20,58],[23,86],
        [93,16],[92,30],[92,45],[91,61],[89,78],[87,88],
        [81,21],[82,41],[80,62],[78,87],
        [32,89],[51,91],[70,89],[50,18]
    ];

    // Winter reference: asymmetric left/right framing plus a lower-center
    // accent, deliberately avoiding the central title/control region.
    const winter = [
        [9,23],[21,40],[10,65],[22,83],
        [91,22],[79,40],[90,64],[78,83],
        [50,87],[34,88],[66,88]
    ];

    // Winx reference: generous horizontal/vertical separation with slight
    // imperfections instead of perfect lanes.
    const winx = [
        [9,31],[32,32],[68,32],[91,31],
        [9,57],[32,58],[68,58],[91,57],
        [11,82],[37,83],[63,83],[89,82]
    ];

    const corners = [
        [11,18],[25,16],[13,32],
        [89,18],[75,16],[87,32],
        [12,83],[27,87],[15,69],
        [88,83],[73,87],[85,69],
        [50,88],[50,17]
    ];

    const mixed = [
        [10,24],[25,19],[43,27],[67,20],[89,28],
        [17,51],[48,48],[81,51],
        [10,77],[31,82],[60,76],[88,80],
        [24,65],[72,62]
    ];

    let base;

    if (
        mode ===
        'snoopy-frame'
    ) {
        base =
            snoopy;
    } else if (
        mode ===
        'winter-sides'
    ) {
        base =
            winter;
    } else if (
        mode ===
        'winx-stage'
    ) {
        base =
            winx;
    } else if (
        mode ===
        'corner-garden'
    ) {
        base =
            corners;
    } else if (
        mode ===
        'mixed-scene'
    ) {
        base =
            mixed;
    } else {
        base =
            [];
    }

    const candidates = [];

    base.forEach(
        (
            point,
            index
        ) => {
            candidates.push(
                clampPlacementPointV26(
                    jitterPointV26(
                        point,
                        mode ===
                            'winx-stage'
                            ? 2.1
                            : 3.4,
                        rand,
                        index
                    )
                )
            );
        }
    );

    // If there are more SVGs than reference slots, add many compatible
    // candidates instead of recycling a slot and stacking stickers.
    const extraCount =
        Math.max(
            90,
            count *
                12
        );

    for (
        let index =
            0;
        index <
            extraCount;
        index++
    ) {
        const a =
            rand(
                index,
                131
            );

        const b =
            rand(
                index,
                137
            );

        let point;

        if (
            mode ===
                'snoopy-frame'
        ) {
            const edge =
                Math.floor(
                    a *
                    4
                );

            if (
                edge ===
                    0
            ) {
                point = {
                    x:
                        7 +
                        b *
                            16,
                    y:
                        16 +
                        rand(
                            index,
                            139
                        ) *
                            72
                };
            } else if (
                edge ===
                    1
            ) {
                point = {
                    x:
                        77 +
                        b *
                            16,
                    y:
                        16 +
                        rand(
                            index,
                            149
                        ) *
                            72
                };
            } else if (
                edge ===
                    2
            ) {
                point = {
                    x:
                        18 +
                        b *
                            64,
                    y:
                        15 +
                        rand(
                            index,
                            151
                        ) *
                            7
                };
            } else {
                point = {
                    x:
                        18 +
                        b *
                            64,
                    y:
                        83 +
                        rand(
                            index,
                            157
                        ) *
                            7
                };
            }
        } else if (
            mode ===
                'winter-sides'
        ) {
            const side =
                a <
                    .5;

            point = {
                x:
                    side
                        ? 8 +
                            b *
                                18
                        : 74 +
                            b *
                                18,
                y:
                    19 +
                    rand(
                        index,
                        163
                    ) *
                        68
            };
        } else if (
            mode ===
                'winx-stage'
        ) {
            const columns = [
                9,
                32,
                68,
                91
            ];

            const rows = [
                31,
                58,
                82
            ];

            point = {
                x:
                    columns[
                        index %
                        columns.length
                    ] +
                    (
                        b -
                        .5
                    ) *
                        3,
                y:
                    rows[
                        Math.floor(
                            index /
                            columns.length
                        ) %
                        rows.length
                    ] +
                    (
                        rand(
                            index,
                            167
                        ) -
                        .5
                    ) *
                        3
            };
        } else if (
            mode ===
                'corner-garden'
        ) {
            const quadrant =
                Math.floor(
                    a *
                    4
                );

            point = {
                x:
                    quadrant %
                        2 ===
                        0
                        ? 8 +
                            b *
                                25
                        : 67 +
                            b *
                                25,
                y:
                    quadrant <
                        2
                        ? 14 +
                            rand(
                                index,
                                173
                            ) *
                                25
                        : 64 +
                            rand(
                                index,
                                179
                            ) *
                                25
            };
        } else {
            point = {
                x:
                    9 +
                    b *
                        82,
                y:
                    16 +
                    rand(
                        index,
                        181
                    ) *
                        72
            };
        }

        candidates.push(
            clampPlacementPointV26(
                point
            )
        );
    }

    return candidates;
}

function makeRandomCandidatesV26(
    mode,
    count,
    rand
) {
    const candidates = [];

    const total =
        Math.max(
            240,
            count *
                28
        );

    for (
        let index =
            0;
        index <
            total;
        index++
    ) {
        if (
            mode ===
            'random-edges-safe'
        ) {
            const edge =
                Math.floor(
                    rand(
                        index,
                        191
                    ) *
                    4
                );

            const along =
                13 +
                rand(
                    index,
                    193
                ) *
                    74;

            if (
                edge ===
                    0
            ) {
                candidates.push({
                    x:
                        along,
                    y:
                        13 +
                        rand(
                            index,
                            197
                        ) *
                            8
                });
            } else if (
                edge ===
                    1
            ) {
                candidates.push({
                    x:
                        79 +
                        rand(
                            index,
                            199
                        ) *
                            12,
                    y:
                        along
                });
            } else if (
                edge ===
                    2
            ) {
                candidates.push({
                    x:
                        along,
                    y:
                        80 +
                        rand(
                            index,
                            211
                        ) *
                            10
                });
            } else {
                candidates.push({
                    x:
                        9 +
                        rand(
                            index,
                            223
                        ) *
                            12,
                    y:
                        along
                });
            }
        } else {
            candidates.push({
                x:
                    9 +
                    rand(
                        index,
                        227
                    ) *
                        82,
                y:
                    15 +
                    rand(
                        index,
                        229
                    ) *
                        74
            });
        }
    }

    return candidates.map(
        clampPlacementPointV26
    );
}

function makeBalancedCandidatesV26(
    count,
    rand
) {
    const candidates = [];

    const cols =
        Math.max(
            4,
            Math.ceil(
                Math.sqrt(
                    Math.max(
                        count,
                        8
                    ) *
                    1.55
                )
            )
        );

    const rows =
        Math.max(
            3,
            Math.ceil(
                Math.max(
                    count,
                    8
                ) /
                cols *
                1.45
            )
        );

    for (
        let row =
            0;
        row <
            rows;
        row++
    ) {
        for (
            let col =
                0;
            col <
                cols;
            col++
        ) {
            const index =
                row *
                    cols +
                col;

            const stagger =
                row %
                    2
                    ? .36
                    : 0;

            candidates.push({
                x:
                    10 +
                    (
                        col +
                        .5 +
                        stagger
                    ) /
                        (
                            cols +
                            .35
                        ) *
                        80 +
                    (
                        rand(
                            index,
                            233
                        ) -
                        .5
                    ) *
                        3.6,
                y:
                    15 +
                    (
                        row +
                        .5
                    ) /
                        rows *
                        73 +
                    (
                        rand(
                            index,
                            239
                        ) -
                        .5
                    ) *
                        4
            });
        }
    }

    // Add some irregular alternatives so the final result does not read as a grid.
    return candidates.concat(
        makeRandomCandidatesV26(
            'random-safe',
            count,
            rand
        ).slice(
            0,
            Math.max(
                80,
                count *
                    8
            )
        )
    );
}

function placementOverlapV26(
    a,
    b,
    scale
) {
    // The preview artwork is ~105px square on a 1280x760 logical canvas.
    // Use rectangular separation because equal percentage distance in X/Y
    // does not correspond to equal physical pixels.
    const neededX =
        8.9 *
        scale +
        1.8;

    const neededY =
        14.3 *
        scale +
        2.0;

    return (
        Math.abs(
            a.x -
            b.x
        ) <
            neededX &&
        Math.abs(
            a.y -
            b.y
        ) <
            neededY
    );
}

function placementDistanceV26(
    a,
    b
) {
    // Weight Y slightly less because the preview is wider than it is tall.
    const dx =
        a.x -
        b.x;

    const dy =
        (
            a.y -
            b.y
        ) *
        1.25;

    return (
        dx *
            dx +
        dy *
            dy
    );
}

function chooseSpreadPointsV26(
    candidates,
    count,
    {
        allowOverlap,
        scale,
        rand
    }
) {
    if (
        !count ||
        !candidates.length
    ) {
        return [];
    }

    const pool =
        shufflePlacementPointsV26(
            candidates,
            rand
        );

    if (allowOverlap) {
        return pool.slice(
            0,
            count
        );
    }

    const selected = [];

    // Begin away from the exact center so the composition does not clump
    // around the title/control region.
    let first =
        pool[0];

    let firstScore =
        -Infinity;

    pool.forEach(
        point => {
            const dx =
                point.x -
                50;

            const dy =
                point.y -
                50;

            const score =
                dx *
                    dx +
                dy *
                    dy *
                    .75;

            if (
                score >
                firstScore
            ) {
                first =
                    point;

                firstScore =
                    score;
            }
        }
    );

    selected.push(
        first
    );

    while (
        selected.length <
            count &&
        pool.length
    ) {
        let best =
            null;

        let bestScore =
            -Infinity;

        let foundCollisionFree =
            false;

        pool.forEach(
            point => {
                if (
                    selected.includes(
                        point
                    )
                ) {
                    return;
                }

                const collides =
                    selected.some(
                        chosen =>
                            placementOverlapV26(
                                point,
                                chosen,
                                scale
                            )
                    );

                const nearestDistance =
                    Math.min(
                        ...selected.map(
                            chosen =>
                                placementDistanceV26(
                                    point,
                                    chosen
                                )
                        )
                    );

                if (
                    !collides
                ) {
                    if (
                        !foundCollisionFree ||
                        nearestDistance >
                            bestScore
                    ) {
                        foundCollisionFree =
                            true;

                        best =
                            point;

                        bestScore =
                            nearestDistance;
                    }

                    return;
                }

                if (
                    !foundCollisionFree &&
                    nearestDistance >
                        bestScore
                ) {
                    best =
                        point;

                    bestScore =
                        nearestDistance;
                }
            }
        );

        if (!best) {
            break;
        }

        selected.push(
            best
        );
    }

    return selected;
}

function buildThemePlacementPointsV26(
    mode,
    count,
    {
        seed =
            null,
        allowOverlap =
            false,
        svgGlobalScale =
            100
    } = {}
) {
    const normalized =
        normalizeSvgPlacementModeV26(
            mode
        );

    const rand =
        (
            index,
            salt
        ) =>
            placementRandomV26(
                seed,
                index,
                salt
            );

    let candidates;

    if (
        normalized ===
            'balanced-spread'
    ) {
        candidates =
            makeBalancedCandidatesV26(
                count,
                rand
            );
    } else if (
        [
            'random-safe',
            'random-edges-safe'
        ].includes(
            normalized
        )
    ) {
        candidates =
            makeRandomCandidatesV26(
                normalized,
                count,
                rand
            );
    } else {
        candidates =
            makeReferenceCandidatesV26(
                normalized,
                count,
                rand
            );
    }

    return chooseSpreadPointsV26(
        candidates,
        count,
        {
            allowOverlap,
            scale:
                Math.max(
                    .5,
                    Math.min(
                        2.2,
                        (
                            Number(
                                svgGlobalScale
                            ) ||
                            100
                        ) /
                            100
                    )
                ),
            rand
        }
    );
}

function makePlacementEntriesV26(
    theme
) {
    return (
        theme.backgroundSvgs ||
        []
    ).map(
        (
            svg,
            originalIndex
        ) => ({
            svg:
                ensureSvgAdvancedDefaultsV10({
                    ...svg
                }),
            originalIndex
        })
    );
}

getPreviewSvgAssignmentsV10 =
    function(
        modal,
        draft
    ) {
        if (
            !Number.isFinite(
                modal._themePreviewDistributionSeedV10
            )
        ) {
            modal._themePreviewDistributionSeedV10 =
                Math.random() *
                100000;
        }

        const entries =
            makePlacementEntriesV26(
                draft
            );

        const points =
            buildThemePlacementPointsV26(
                draft.svgDistribution,
                entries.length,
                {
                    seed:
                        modal
                            ._themePreviewDistributionSeedV10,
                    allowOverlap:
                        !!draft
                            .svgAllowOverlap,
                    svgGlobalScale:
                        draft
                            .svgGlobalScale
                }
            );

        return entries.map(
            (
                entry,
                index
            ) => ({
                ...entry,
                left:
                    points[
                        index
                    ]?.x ??
                    50,
                top:
                    points[
                        index
                    ]?.y ??
                    50
            })
        );
    };

getRuntimeSvgAssignmentsV10 =
    function(
        theme
    ) {
        const entries =
            makePlacementEntriesV26(
                theme
            );

        const points =
            buildThemePlacementPointsV26(
                theme.svgDistribution,
                entries.length,
                {
                    seed:
                        null,
                    allowOverlap:
                        !!theme
                            .svgAllowOverlap,
                    svgGlobalScale:
                        theme
                            .svgGlobalScale
                }
            );

        return entries.map(
            (
                entry,
                index
            ) => ({
                ...entry,
                left:
                    points[
                        index
                    ]?.x ??
                    50,
                top:
                    points[
                        index
                    ]?.y ??
                    50
            })
        );
    };

