// ============================================================
// THEME BUILDER V30
// - Built-in themes preview their REAL background/decoration layer
// - Built-in SVG/audio assets are discovered and surfaced in the Builder
// - Transparent computed backgrounds no longer become black
// - Theme gallery can duplicate ANY theme
// - Duplicates are real independent theme entries and stay at the bottom
// ============================================================

// ------------------------------------------------------------
// FIX: transparent computed backgrounds must never become #000000.
// ------------------------------------------------------------

const parseThemeCssColorBeforeV30 =
    parseThemeCssColorV25;

parseThemeCssColorV25 =
    function(
        value,
        fallback
    ) {
        const text =
            String(
                value ||
                ''
            )
                .trim();

        const rgba =
            text.match(
                /rgba\(\s*[\d.]+\s*,\s*[\d.]+\s*,\s*[\d.]+\s*,\s*([\d.]+)\s*\)/i
            );

        if (
            rgba &&
            Number(
                rgba[1]
            ) <=
                .03
        ) {
            return fallback;
        }

        if (
            text ===
            'transparent'
        ) {
            return fallback;
        }

        return parseThemeCssColorBeforeV30(
            value,
            fallback
        );
    };

// ------------------------------------------------------------
// BUILT-IN SOURCE / RUNTIME INSPECTION
// ------------------------------------------------------------

function getBuiltInThemeNameV30(
    themeId
) {
    return String(
        themeId ||
        ''
    )
        .replace(
            /^theme-/,
            ''
        )
        .trim();
}

function isBuiltInThemeIdV30(
    themeId
) {
    return (
        !!themeId &&
        themeId !==
            'theme-custom-builder' &&
        !String(
            themeId
        ).startsWith(
            'theme-custom-builder-'
        )
    );
}

function getBuiltInThemeRootsV30(
    themeId
) {
    const name =
        getBuiltInThemeNameV30(
            themeId
        );

    if (!name) {
        return [];
    }

    const exactIds =
        new Set([
            `${name}-background`,
            `${name}-theme-background`,
            `theme-${name}-background`,
            `${name}-scene`,
            `${name}-stage`,
            `${name}-decor`
        ]);

    const candidates =
        Array.from(
            document.body
                ?.children ||
                []
        )
            .filter(
                element => {
                    if (
                        element.id ===
                            'theme-builder-modal' ||
                        element.id ===
                            'custom-theme-background-stage'
                    ) {
                        return false;
                    }

                    const id =
                        String(
                            element.id ||
                            ''
                        )
                            .toLowerCase();

                    const classes =
                        String(
                            element.className ||
                            ''
                        )
                            .toLowerCase();

                    if (
                        exactIds.has(
                            id
                        )
                    ) {
                        return true;
                    }

                    if (
                        id.includes(
                            name.toLowerCase()
                        ) &&
                        /(background|scene|stage|decor|particles|art)/.test(
                            id
                        )
                    ) {
                        return true;
                    }

                    if (
                        classes.includes(
                            name.toLowerCase()
                        ) &&
                        /(background|scene|stage|decor|particles|art)/.test(
                            classes
                        )
                    ) {
                        return true;
                    }

                    return false;
                }
            );

    if (
        candidates.length
    ) {
        return candidates;
    }

    // Most hand-built themes use a single direct-child *-background root.
    // At this point the previous theme module has already been unmounted,
    // so a remaining background root is a safe fallback.
    return Array.from(
        document.body
            ?.children ||
            []
    )
        .filter(
            element => {
                const id =
                    String(
                        element.id ||
                        ''
                    )
                        .toLowerCase();

                return (
                    id.endsWith(
                        '-background'
                    ) &&
                    id !==
                        'custom-theme-background-stage'
                );
            }
        );
}

function serializeThemeRootV30(
    root
) {
    const clone =
        root.cloneNode(
            true
        );

    // cloneNode does not copy a canvas bitmap. Preserve canvas-based
    // decorations as images when possible.
    const originals =
        Array.from(
            root.querySelectorAll(
                'canvas'
            )
        );

    const clones =
        Array.from(
            clone.querySelectorAll(
                'canvas'
            )
        );

    originals.forEach(
        (
            canvas,
            index
        ) => {
            const target =
                clones[index];

            if (!target) {
                return;
            }

            try {
                const image =
                    document.createElement(
                        'img'
                    );

                image.src =
                    canvas.toDataURL(
                        'image/png'
                    );

                image.alt =
                    '';

                image.style.cssText =
                    target.getAttribute(
                        'style'
                    ) ||
                    '';

                image.className =
                    target.className ||
                    '';

                target.replaceWith(
                    image
                );
            } catch {}
        }
    );

    clone
        .querySelectorAll(
            'audio, video'
        )
        .forEach(
            element =>
                element.remove()
        );

    return clone.outerHTML;
}

function captureBuiltInRuntimeSnapshotV30(
    themeId
) {
    const bodyStyle =
        getComputedStyle(
            document.body
        );

    const roots =
        getBuiltInThemeRootsV30(
            themeId
        );

    return {
        themeId,

        background:
            bodyStyle.background,

        backgroundColor:
            bodyStyle.backgroundColor,

        backgroundImage:
            bodyStyle.backgroundImage,

        roots:
            roots.map(
                serializeThemeRootV30
            )
    };
}

function themeAssetFileNameV30(
    url,
    fallback =
        'Theme Asset'
) {
    try {
        const pathname =
            new URL(
                url,
                location.href
            ).pathname;

        return decodeURIComponent(
            pathname
                .split('/')
                .pop() ||
                fallback
        );
    } catch {
        return fallback;
    }
}

function uniqueThemeAssetsV30(
    assets
) {
    const seen =
        new Set();

    return (
        assets ||
        []
    ).filter(
        asset => {
            const key =
                String(
                    asset?.url ||
                    asset?.markup ||
                    asset?.name ||
                    ''
                );

            if (
                !key ||
                seen.has(
                    key
                )
            ) {
                return false;
            }

            seen.add(
                key
            );

            return true;
        }
    );
}

function collectRuntimeSvgAssetsV30(
    roots
) {
    const assets =
        [];

    (
        roots ||
        []
    ).forEach(
        root => {
            root
                .querySelectorAll(
                    'img[src], object[data]'
                )
                .forEach(
                    element => {
                        const source =
                            element.getAttribute(
                                'src'
                            ) ||
                            element.getAttribute(
                                'data'
                            ) ||
                            '';

                        if (
                            !/\.svg(?:$|[?#])/i.test(
                                source
                            )
                        ) {
                            return;
                        }

                        const absolute =
                            new URL(
                                source,
                                location.href
                            );

                        assets.push({
                            name:
                                themeAssetFileNameV30(
                                    absolute.href
                                ),
                            url:
                                absolute.pathname +
                                absolute.search,
                            animation:
                                'float',
                            introBop:
                                true,
                            hoverSoundUrl:
                                '',
                            inheritedBuiltInV30:
                                true
                        });
                    }
                );

            root
                .querySelectorAll(
                    'svg'
                )
                .forEach(
                    (
                        svg,
                        index
                    ) => {
                        const markup =
                            svg.outerHTML;

                        if (
                            !markup
                        ) {
                            return;
                        }

                        assets.push({
                            name:
                                `Built-in SVG ${index + 1}`,
                            markup,
                            animation:
                                'float',
                            introBop:
                                true,
                            hoverSoundUrl:
                                '',
                            inheritedBuiltInV30:
                                true
                        });
                    }
                );
        }
    );

    return uniqueThemeAssetsV30(
        assets
    );
}

async function fetchThemeSourceV30(
    themeId
) {
    const name =
        getBuiltInThemeNameV30(
            themeId
        );

    if (
        !name ||
        themeId ===
            'default'
    ) {
        return {
            js:
                '',
            css:
                ''
        };
    }

    const urls = {
        js:
            `/themes/${encodeURIComponent(name)}/theme-${encodeURIComponent(name)}.js`,
        css:
            `/themes/${encodeURIComponent(name)}/theme-${encodeURIComponent(name)}.css`
    };

    const result = {
        js:
            '',
        css:
            ''
    };

    await Promise.all(
        Object.entries(
            urls
        ).map(
            async ([
                key,
                url
            ]) => {
                try {
                    const response =
                        await fetch(
                            url,
                            {
                                cache:
                                    'no-store'
                            }
                        );

                    if (
                        response.ok
                    ) {
                        result[key] =
                            await response.text();
                    }
                } catch {}
            }
        )
    );

    return result;
}

function analyzeThemeSourceV30(
    themeId,
    source
) {
    const name =
        getBuiltInThemeNameV30(
            themeId
        );

    const jsText =
        String(
            source?.js ||
            ''
        );

    const cssText =
        String(
            source?.css ||
            ''
        );

    const allText =
        `${jsText}\n${cssText}`;

    const svgAssets =
        [];

    const absoluteSvgRegex =
        /["'`](\/svg\/[^"'`]+?\.svg(?:\?[^"'`]*)?)["'`]/gi;

    let match;

    while (
        (
            match =
                absoluteSvgRegex.exec(
                    allText
                )
        )
    ) {
        svgAssets.push({
            name:
                themeAssetFileNameV30(
                    match[1]
                ),
            url:
                match[1],
            animation:
                'float',
            introBop:
                true,
            hoverSoundUrl:
                '',
            inheritedBuiltInV30:
                true
        });
    }

    // Many theme modules keep just filenames in an ASSETS array and build
    // /svg/theme-name/<filename> later.
    const bareSvgRegex =
        /["'`]([^"'`\/]+\.svg(?:\?[^"'`]*)?)["'`]/gi;

    while (
        (
            match =
                bareSvgRegex.exec(
                    jsText
                )
        )
    ) {
        const file =
            match[1];

        svgAssets.push({
            name:
                themeAssetFileNameV30(
                    file
                ),
            url:
                `/svg/theme-${encodeURIComponent(name)}/${file}`,
            animation:
                'float',
            introBop:
                true,
            hoverSoundUrl:
                '',
            inheritedBuiltInV30:
                true
        });
    }

    const soundMatches =
        [];

    const soundRegex =
        /["'`](\/sounds\/[^"'`]+?\.(?:mp3|wav|ogg|m4a|aac)(?:\?[^"'`]*)?)["'`]/gi;

    while (
        (
            match =
                soundRegex.exec(
                    jsText
                )
        )
    ) {
        const start =
            Math.max(
                0,
                match.index -
                    260
            );

        const end =
            Math.min(
                jsText.length,
                soundRegex.lastIndex +
                    260
            );

        const context =
            jsText
                .slice(
                    start,
                    end
                )
                .toLowerCase();

        let introScore =
            0;

        if (
            /intro|opening|song|music/.test(
                context
            )
        ) {
            introScore +=
                5;
        }

        if (
            /hover/.test(
                context
            )
        ) {
            introScore -=
                4;
        }

        soundMatches.push({
            url:
                match[1],
            context,
            introScore
        });
    }

    const uniqueSounds =
        Array.from(
            new Map(
                soundMatches.map(
                    sound => [
                        sound.url,
                        sound
                    ]
                )
            ).values()
        );

    const intro =
        [...uniqueSounds]
            .sort(
                (
                    a,
                    b
                ) =>
                    b.introScore -
                    a.introScore
            )[0] ||
        null;

    const hoverSounds =
        uniqueSounds
            .filter(
                sound =>
                    sound.url !==
                        intro?.url &&
                    /hover|sound|sfx|effect/.test(
                        sound.context
                    )
            )
            .map(
                sound => ({
                    name:
                        themeAssetFileNameV30(
                            sound.url,
                            'Built-in Sound'
                        ),
                    url:
                        sound.url,
                    inheritedBuiltInV30:
                        true
                })
            );

    const endMatch =
        jsText.match(
            /(?:INTRO|SONG|AUDIO)[A-Z0-9_]*END[A-Z0-9_]*\s*=\s*(\d+(?:\.\d+)?)/i
        );

    const fadeMatch =
        jsText.match(
            /(?:INTRO|SONG|AUDIO)[A-Z0-9_]*FADE[A-Z0-9_]*(?:START)?[A-Z0-9_]*\s*=\s*(\d+(?:\.\d+)?)/i
        );

    return {
        svgAssets:
            uniqueThemeAssetsV30(
                svgAssets
            ),

        introAudio:
            intro?.url ||
            '',

        introAudioName:
            intro
                ? themeAssetFileNameV30(
                    intro.url,
                    'Built-in Intro Audio'
                )
                : '',

        hoverSounds,

        audioPlayMode:
            endMatch
                ? 'segment'
                : 'full',

        audioStart:
            0,

        audioEnd:
            endMatch
                ? Number(
                    endMatch[1]
                )
                : 20,

        audioFade:
            !!fadeMatch
    };
}

function installBuiltInAssetNoteV30(
    modal,
    details
) {
    modal
        .querySelectorAll(
            '.theme-builder-built-in-note-v30'
        )
        .forEach(
            element =>
                element.remove()
        );

    const svgSection =
        modal.querySelector(
            '.theme-builder-svg-list'
        )
            ?.closest(
                'section'
            );

    if (
        svgSection &&
        details.svgCount
    ) {
        const note =
            document.createElement(
                'div'
            );

        note.className =
            'theme-builder-built-in-note-v30';

        note.innerHTML = `
            <i class="ph ph-sparkle"></i>
            <span>
                ${details.svgCount} built-in decoration${details.svgCount === 1 ? '' : 's'} loaded from this theme.
            </span>
        `;

        svgSection
            .querySelector(
                '.theme-builder-control-heading, .theme-builder-media-heading'
            )
            ?.insertAdjacentElement(
                'afterend',
                note
            );
    }

    const audioSection =
        modal.querySelector(
            '.theme-builder-audio-status'
        )
            ?.closest(
                'section'
            );

    if (
        audioSection &&
        details.audio
    ) {
        const note =
            document.createElement(
                'div'
            );

        note.className =
            'theme-builder-built-in-note-v30';

        note.innerHTML = `
            <i class="ph ph-music-notes"></i>
            <span>
                Built-in intro audio detected: ${escapeCustomHtml(details.audio)}
            </span>
        `;

        audioSection
            .querySelector(
                '.theme-builder-control-heading, .theme-builder-media-heading'
            )
            ?.insertAdjacentElement(
                'afterend',
                note
            );
    }
}

function bindBuiltInAssetDirtyTrackingV30(
    modal
) {
    if (
        modal.dataset
            .builtInAssetDirtyTrackingV30 ===
        'true'
    ) {
        return;
    }

    modal.dataset
        .builtInAssetDirtyTrackingV30 =
        'true';

    const mark =
        event => {
            if (
                !modal.dataset
                    .themeBuilderBuiltInSourceV30
            ) {
                return;
            }

            const target =
                event.target;

            if (
                !target ||
                target.nodeType !==
                    1
            ) {
                return;
            }

            if (
                target.matches(
                    '[data-theme-key="background"], [data-theme-hex="background"], .theme-builder-background-file, .theme-builder-background-clear'
                )
            ) {
                modal._builtInBackgroundDirtyV30 =
                    true;
            }

            if (
                target.closest(
                    [
                        '.theme-builder-svg-row',
                        '.theme-builder-svg-controls-v10',
                        '.theme-builder-svg-global-controls-v19',
                        '.theme-builder-svg-overlap-row-v26'
                    ].join(',')
                ) ||
                target.matches(
                    '.theme-builder-svg-file, .theme-builder-svg-distribution'
                )
            ) {
                modal._builtInArtDirtyV30 =
                    true;
            }

            if (
                target.closest(
                    '.theme-builder-audio-controls, .theme-builder-audio-section'
                ) ||
                target.matches(
                    '.theme-builder-audio-file, .theme-builder-audio-clear'
                )
            ) {
                modal._builtInAudioDirtyV30 =
                    true;
            }
        };

    modal.addEventListener(
        'input',
        mark,
        true
    );

    modal.addEventListener(
        'change',
        mark,
        true
    );

    modal.addEventListener(
        'click',
        mark,
        true
    );
}

function mountBuiltInRuntimePreviewV30(
    modal
) {
    const canvas =
        modal.querySelector(
            '.theme-builder-live-canvas'
        );

    if (!canvas) {
        return;
    }

    canvas
        .querySelector(
            '.theme-builder-built-in-runtime-v30'
        )
        ?.remove();

    const snapshot =
        modal._builtInRuntimeSnapshotV30;

    if (
        !snapshot ||
        modal._builtInArtDirtyV30
    ) {
        return;
    }

    const layer =
        document.createElement(
            'div'
        );

    layer.className =
        'theme-builder-built-in-runtime-v30';

    (
        snapshot.roots ||
        []
    ).forEach(
        markup => {
            const template =
                document.createElement(
                    'template'
                );

            template.innerHTML =
                markup.trim();

            const root =
                template.content
                    .firstElementChild;

            if (!root) {
                return;
            }

            root.classList.add(
                'theme-builder-built-in-root-v30'
            );

            root.style.setProperty(
                'position',
                'absolute',
                'important'
            );

            root.style.setProperty(
                'inset',
                '0',
                'important'
            );

            root.style.setProperty(
                'width',
                '100%',
                'important'
            );

            root.style.setProperty(
                'height',
                '100%',
                'important'
            );

            root.style.setProperty(
                'display',
                'block',
                'important'
            );

            root.style.setProperty(
                'overflow',
                'hidden',
                'important'
            );

            root.style.setProperty(
                'pointer-events',
                'none',
                'important'
            );

            root.style.setProperty(
                'z-index',
                '0',
                'important'
            );

            layer.appendChild(
                root
            );
        }
    );

    canvas.prepend(
        layer
    );

    // When showing the exact built-in art, do not also draw the same
    // discovered SVGs through the custom-theme SVG stage.
    canvas
        .querySelector(
            '.theme-builder-live-art-stage'
        )
        ?.remove();
}

function syncBuiltInPreviewBackgroundV30(
    modal
) {
    const canvas =
        modal.querySelector(
            '.theme-builder-live-canvas'
        );

    const snapshot =
        modal._builtInRuntimeSnapshotV30;

    if (
        !canvas ||
        !snapshot ||
        modal._builtInBackgroundDirtyV30
    ) {
        return;
    }

    if (
        snapshot.background &&
        snapshot.background !==
            'rgba(0, 0, 0, 0) none repeat scroll 0% 0% / auto padding-box border-box'
    ) {
        canvas.style.setProperty(
            'background',
            snapshot.background,
            'important'
        );
    } else {
        if (
            snapshot.backgroundColor
        ) {
            canvas.style.setProperty(
                'background-color',
                snapshot.backgroundColor,
                'important'
            );
        }

        if (
            snapshot.backgroundImage &&
            snapshot.backgroundImage !==
                'none'
        ) {
            canvas.style.setProperty(
                'background-image',
                snapshot.backgroundImage,
                'important'
            );
        }
    }
}

async function hydrateBuiltInThemeEditorV30(
    modal,
    themeId,
    themeName
) {
    if (
        !modal ||
        !isBuiltInThemeIdV30(
            themeId
        )
    ) {
        return;
    }

    const runtimeRoots =
        getBuiltInThemeRootsV30(
            themeId
        );

    const runtimeSnapshot =
        captureBuiltInRuntimeSnapshotV30(
            themeId
        );

    const runtimeSvgAssets =
        collectRuntimeSvgAssetsV30(
            runtimeRoots
        );

    const source =
        await fetchThemeSourceV30(
            themeId
        );

    const sourceInfo =
        analyzeThemeSourceV30(
            themeId,
            source
        );

    const existingOverride =
        getThemeOverrideV25(
            themeId
        );

    const currentDraft =
        getThemeBuilderDraft(
            modal
        );

    const sourceSvgs =
        uniqueThemeAssetsV30([
            ...runtimeSvgAssets,
            ...sourceInfo.svgAssets
        ]);

    const overrideSvgs =
        Array.isArray(
            existingOverride?.backgroundSvgs
        )
            ? existingOverride.backgroundSvgs
            : [];

    const useSourceSvgs =
        !overrideSvgs.length;

    const inheritedSvgs =
        sourceSvgs.map(
            svg => ({
                ...svg,
                inheritedBuiltInV30:
                    true
            })
        );

    const introFromOverride =
        String(
            existingOverride?.introAudio ||
            ''
        );

    const useSourceAudio =
        !introFromOverride;

    const merged = {
        ...currentDraft,

        name:
            existingOverride?.name ||
            themeName ||
            currentDraft.name,

        backgroundSvgs:
            useSourceSvgs
                ? inheritedSvgs
                : overrideSvgs,

        introAudio:
            useSourceAudio
                ? sourceInfo.introAudio
                : introFromOverride,

        introAudioName:
            useSourceAudio
                ? sourceInfo.introAudioName
                : (
                    existingOverride
                        ?.introAudioName ||
                    currentDraft
                        .introAudioName
                ),

        audioPlayMode:
            useSourceAudio
                ? sourceInfo.audioPlayMode
                : (
                    existingOverride
                        ?.audioPlayMode ||
                    currentDraft
                        .audioPlayMode
                ),

        audioStart:
            useSourceAudio
                ? sourceInfo.audioStart
                : (
                    existingOverride
                        ?.audioStart ??
                    currentDraft
                        .audioStart
                ),

        audioEnd:
            useSourceAudio
                ? sourceInfo.audioEnd
                : (
                    existingOverride
                        ?.audioEnd ??
                    currentDraft
                        .audioEnd
                ),

        audioFade:
            useSourceAudio
                ? sourceInfo.audioFade
                : !!existingOverride
                    ?.audioFade,

        svgHoverSounds:
            (
                existingOverride
                    ?.svgHoverSounds
                    ?.length
            )
                ? existingOverride
                    .svgHoverSounds
                : sourceInfo
                    .hoverSounds
    };

    modal.dataset
        .themeBuilderBuiltInSourceV30 =
        themeId;

    modal._builtInRuntimeSnapshotV30 =
        runtimeSnapshot;

    modal._builtInBackgroundDirtyV30 =
        false;

    modal._builtInArtDirtyV30 =
        !!(
            existingOverride
                ?.replaceBuiltInDecorationsV30 ||
            overrideSvgs.length
        );

    modal._builtInAudioDirtyV30 =
        false;

    modal._builtInInheritedSvgKeysV30 =
        new Set(
            inheritedSvgs.map(
                svg =>
                    String(
                        svg.url ||
                        svg.markup ||
                        ''
                    )
            )
        );

    modal._builtInInheritedAudioV30 =
        sourceInfo.introAudio ||
        '';

    populateThemeBuilder(
        modal,
        merged
    );

    installBuiltInAssetNoteV30(
        modal,
        {
            svgCount:
                inheritedSvgs.length,
            audio:
                sourceInfo
                    .introAudioName
        }
    );

    bindBuiltInAssetDirtyTrackingV30(
        modal
    );

    rebuildActualThemeBuilderPreviewV5(
        modal
    );

    forceAllBackButtonsTransparentV26(
        modal
    );
}

// Built-in SVG files are inherited project assets. Removing one from an
// edited theme must NEVER delete the source theme's real SVG file.
const confirmDeleteThemeBuilderSvgBeforeV30 =
    confirmDeleteThemeBuilderSvg;

confirmDeleteThemeBuilderSvg =
    async function(
        modal,
        index
    ) {
        const svg =
            modal
                ._themeBackgroundSvgs?.[
                    index
                ];

        if (
            !svg
                ?.inheritedBuiltInV30
        ) {
            return confirmDeleteThemeBuilderSvgBeforeV30(
                modal,
                index
            );
        }

        const confirmed =
            await showAppConfirm({
                title:
                    'Remove this SVG from your edit?',
                message:
                    `“${svg.name || `SVG ${index + 1}`}” will be hidden by this edited theme. The original built-in asset will not be deleted.`,
                confirmLabel:
                    'Remove from Edit'
            });

        if (!confirmed) {
            return;
        }

        modal._builtInArtDirtyV30 =
            true;

        modal
            ._themeBackgroundSvgs
            .splice(
                index,
                1
            );

        renderThemeBuilderSvgListV2(
            modal
        );

        updateThemeBuilderPreview(
            modal
        );
    };

// Keep inherited source assets out of the saved override unless the user
// actually changed SVG behavior. This prevents the original art from being
// duplicated on top of itself after Save & Apply.
const saveThemeOverrideBeforeV30 =
    saveThemeOverrideV25;

saveThemeOverrideV25 =
    async function(
        modal
    ) {
        const themeId =
            modal?.dataset
                .themeBuilderEditingThemeV25;

        const builtInSource =
            modal?.dataset
                .themeBuilderBuiltInSourceV30;

        await saveThemeOverrideBeforeV30(
            modal
        );

        if (
            !themeId ||
            !builtInSource ||
            themeId !==
                builtInSource
        ) {
            return;
        }

        const override =
            ensureThemeOverridesV25()[
                themeId
            ];

        if (!override) {
            return;
        }

        if (
            !modal
                ._builtInArtDirtyV30
        ) {
            override.backgroundSvgs =
                [];

            override.replaceBuiltInDecorationsV30 =
                false;
        } else {
            override.backgroundSvgs =
                (
                    override.backgroundSvgs ||
                    []
                ).map(
                    svg => {
                        const copy = {
                            ...svg
                        };

                        delete copy
                            .inheritedBuiltInV30;

                        return copy;
                    }
                );

            override.replaceBuiltInDecorationsV30 =
                true;
        }

        if (
            !modal
                ._builtInAudioDirtyV30 &&
            override.introAudio ===
                modal
                    ._builtInInheritedAudioV30
        ) {
            override.introAudio =
                '';

            override.introAudioName =
                '';

            override.introAudioProjectPath =
                '';
        }

        await saveDb();

        await applyTheme(
            themeId,
            {
                persist:
                    false
            }
        );
    };

