// V36 — THEME BUILDER IMAGE UPLOAD + PNG RENDERING FIX
// The user-facing UI says "Images". SVG + PNG both render through the
// same generic artwork pipeline in the Builder preview and applied theme.
// ============================================================

function getThemeImageKindV36(asset) {
    const source =
        String(
            asset?.url ||
            asset?.name ||
            ''
        )
            .split('?')[0]
            .split('#')[0]
            .toLowerCase();

    if (
        source.endsWith('.png') ||
        asset?.assetType ===
            'png'
    ) {
        return 'png';
    }

    return 'svg';
}

function renderThemeImageAssetV36(asset) {
    if (
        asset?.url
    ) {
        return `
            <img
                class="theme-decoration-image-v36 theme-decoration-${getThemeImageKindV36(asset)}-v36"
                src="${escapeCustomHtml(asset.url)}"
                alt=""
                draggable="false"
                decoding="async"
            >
        `;
    }

    return String(
        asset?.markup ||
        ''
    );
}

// Make the generic renderer authoritative for both SVG and PNG.
renderThemeBuilderSvgAsset =
    renderThemeImageAssetV36;

function polishThemeImageUploadUiV36(modal) {
    if (!modal) {
        return;
    }

    const input =
        modal.querySelector(
            '.theme-builder-svg-file'
        );

    if (input) {
        input.accept =
            '.svg,.png,image/svg+xml,image/png';

        input.setAttribute(
            'aria-label',
            'Upload images'
        );
    }

    const heading =
        modal.querySelector(
            '.theme-builder-svg-section .theme-builder-media-heading strong'
        );

    if (heading) {
        heading.textContent =
            'Theme Images';
    }

    const detail =
        modal.querySelector(
            '.theme-builder-svg-section .theme-builder-media-heading small'
        );

    if (detail) {
        detail.textContent =
            'Upload SVG or PNG images for the theme background.';
    }

    const choose =
        modal.querySelector(
            '.theme-builder-svg-choose'
        );

    if (choose) {
        choose.innerHTML =
            '<i class="ph ph-upload-simple"></i> Upload Images';
    }

    const count =
        modal.querySelector(
            '.theme-builder-svg-count'
        );

    if (count) {
        const amount =
            modal
                ._themeBackgroundSvgs
                ?.length ||
            0;

        count.textContent =
            `${amount} image${amount === 1 ? '' : 's'}`;
    }

    const addMore =
        modal.querySelector(
            '.theme-builder-svg-add-card strong'
        );

    if (addMore) {
        addMore.textContent =
            'Upload more images';
    }

    const empty =
        modal.querySelector(
            '.theme-builder-svg-empty'
        );

    if (empty) {
        const strong =
            empty.querySelector(
                'strong'
            );

        const small =
            empty.querySelector(
                'span, small'
            );

        if (strong) {
            strong.textContent =
                'Upload images';
        }

        if (small) {
            small.textContent =
                'SVG and PNG files are supported.';
        }
    }
}

async function uploadThemeImagesV36(
    modal,
    input
) {
    const files =
        Array.from(
            input.files ||
            []
        );

    if (!files.length) {
        return;
    }

    for (
        const file of files
    ) {
        const lowerName =
            String(
                file.name ||
                ''
            )
                .toLowerCase();

        const valid =
            file.type ===
                'image/png' ||
            file.type ===
                'image/svg+xml' ||
            lowerName.endsWith(
                '.png'
            ) ||
            lowerName.endsWith(
                '.svg'
            );

        if (!valid) {
            showFeatureToast(
                `“${file.name}” is not an SVG or PNG image.`
            );

            continue;
        }

        const saved =
            await uploadThemeBuilderAssetToProject(
                file,
                'svg'
            );

        if (!saved) {
            continue;
        }

        modal
            ._themeBackgroundSvgs
            .push({
                name:
                    file.name,
                url:
                    saved.url,
                projectPath:
                    saved.projectPath ||
                    '',
                assetType:
                    lowerName.endsWith(
                        '.png'
                    ) ||
                    file.type ===
                        'image/png'
                        ? 'png'
                        : 'svg'
            });
    }

    input.value =
        '';

    renderThemeBuilderSvgListV2(
        modal
    );

    polishThemeImageUploadUiV36(
        modal
    );

    updateThemeBuilderPreview(
        modal
    );
}

function bindThemeImageUploadV36(modal) {
    const input =
        modal?.querySelector(
            '.theme-builder-svg-file'
        );

    const choose =
        modal?.querySelector(
            '.theme-builder-svg-choose'
        );

    if (
        !input ||
        !choose
    ) {
        return;
    }

    // Replace the old SVG-only handler instead of stacking another handler.
    choose.onclick =
        () =>
            input.click();

    input.onchange =
        () =>
            uploadThemeImagesV36(
                modal,
                input
            );
}

