// ------------------------------------------------------------
// File-like multi-selection for Theme Images
// ------------------------------------------------------------

function ensureThemeImageSelectionV37(modal) {
    if (!modal) {
        return new Set();
    }

    if (
        !(modal._themeImageSelectionV37 instanceof Set)
    ) {
        modal._themeImageSelectionV37 =
            new Set();
    }

    return modal._themeImageSelectionV37;
}

function selectedThemeImageIndexesV37(modal) {
    return Array.from(
        ensureThemeImageSelectionV37(
            modal
        )
    )
        .map(Number)
        .filter(Number.isFinite)
        .sort((a, b) => a - b);
}

function refreshThemeImageSelectionV37(modal) {
    const selected =
        ensureThemeImageSelectionV37(
            modal
        );

    modal
        .querySelectorAll(
            '.theme-builder-svg-card[data-svg-index]'
        )
        .forEach(
            card => {
                card.classList.toggle(
                    'theme-image-selected-v37',
                    selected.has(
                        Number(
                            card.dataset
                                .svgIndex
                        )
                    )
                );
            }
        );
}

function selectSingleThemeImageV37(
    modal,
    index
) {
    const selected =
        ensureThemeImageSelectionV37(
            modal
        );

    selected.clear();
    selected.add(index);

    modal._themeImageSelectionAnchorV37 =
        index;

    refreshThemeImageSelectionV37(
        modal
    );
}

function toggleThemeImageSelectionV37(
    modal,
    index
) {
    const selected =
        ensureThemeImageSelectionV37(
            modal
        );

    if (selected.has(index)) {
        selected.delete(index);
    } else {
        selected.add(index);
    }

    modal._themeImageSelectionAnchorV37 =
        index;

    refreshThemeImageSelectionV37(
        modal
    );
}

function selectThemeImageRangeV37(
    modal,
    index
) {
    const selected =
        ensureThemeImageSelectionV37(
            modal
        );

    const anchor =
        Number.isFinite(
            Number(
                modal._themeImageSelectionAnchorV37
            )
        )
            ? Number(
                modal._themeImageSelectionAnchorV37
            )
            : index;

    const start =
        Math.min(
            anchor,
            index
        );

    const end =
        Math.max(
            anchor,
            index
        );

    selected.clear();

    for (
        let i = start;
        i <= end;
        i++
    ) {
        selected.add(i);
    }

    refreshThemeImageSelectionV37(
        modal
    );
}

async function deleteSelectedThemeImagesV37(
    modal,
    explicitIndexes = null
) {
    const indexes =
        (
            explicitIndexes ||
            selectedThemeImageIndexesV37(
                modal
            )
        )
            .map(Number)
            .filter(Number.isFinite)
            .sort((a, b) => b - a);

    if (!indexes.length) {
        return;
    }

    const confirmed =
        await showAppConfirm({
            title:
                indexes.length === 1
                    ? 'Delete this image?'
                    : `Delete ${indexes.length} images?`,
            message:
                indexes.length === 1
                    ? 'This image will be removed from the theme.'
                    : 'The selected images will be removed from the theme.',
            confirmLabel:
                indexes.length === 1
                    ? 'Delete Image'
                    : 'Delete Images'
        });

    if (!confirmed) {
        return;
    }

    const assets =
        modal._themeBackgroundSvgs ||
        [];

    const toDelete =
        indexes
            .map(
                index =>
                    assets[index]
            )
            .filter(Boolean);

    // Delete project files where appropriate, matching the old single-delete behavior.
    for (const asset of toDelete) {
        const projectPath =
            asset?.projectPath ||
            '';

        if (
            projectPath &&
            !asset?.inheritedBuiltInV30
        ) {
            try {
                await deleteThemeBuilderAssetFromProject(
                    projectPath
                );
            } catch {}
        }
    }

    indexes.forEach(
        index => {
            assets.splice(
                index,
                1
            );
        }
    );

    modal._themeImageSelectionV37 =
        new Set();

    modal._themeImageSelectionAnchorV37 =
        null;

    if (
        modal.dataset
            .themeBuilderBuiltInSourceV30
    ) {
        modal._builtInArtDirtyV30 =
            true;
    }

    renderThemeBuilderSvgListV2(
        modal
    );

    updateThemeBuilderPreview(
        modal
    );
}

function showThemeImageContextMenuV37(
    modal,
    event,
    index
) {
    const selected =
        ensureThemeImageSelectionV37(
            modal
        );

    if (!selected.has(index)) {
        selectSingleThemeImageV37(
            modal,
            index
        );
    }

    const count =
        selectedThemeImageIndexesV37(
            modal
        ).length;

    showCustomItemContextMenu(
        event.clientX,
        event.clientY,
        [
            {
                label:
                    count > 1
                        ? `Delete ${count} Images`
                        : 'Delete Image',
                icon:
                    'ph-trash',
                danger:
                    true,
                action:
                    () =>
                        deleteSelectedThemeImagesV37(
                            modal
                        )
            }
        ]
    );
}

function bindThemeImageFileSelectionV37(
    modal
) {
    const host =
        modal?.querySelector(
            '.theme-builder-svg-list'
        );

    if (
        !host ||
        host.dataset
            .fileSelectionV37 ===
            'true'
    ) {
        refreshThemeImageSelectionV37(
            modal
        );
        return;
    }

    host.dataset
        .fileSelectionV37 =
        'true';

    let marquee =
        null;

    let dragging =
        false;

    let startX =
        0;

    let startY =
        0;

    host.addEventListener(
        'click',
        event => {
            const card =
                event.target.closest(
                    '.theme-builder-svg-card[data-svg-index]'
                );

            if (!card) {
                return;
            }

            const index =
                Number(
                    card.dataset.svgIndex
                );

            if (event.shiftKey) {
                selectThemeImageRangeV37(
                    modal,
                    index
                );
            } else if (
                event.ctrlKey ||
                event.metaKey
            ) {
                toggleThemeImageSelectionV37(
                    modal,
                    index
                );
            } else {
                selectSingleThemeImageV37(
                    modal,
                    index
                );
            }
        },
        true
    );

    host.addEventListener(
        'contextmenu',
        event => {
            const card =
                event.target.closest(
                    '.theme-builder-svg-card[data-svg-index]'
                );

            if (!card) {
                return;
            }

            event.preventDefault();
            event.stopImmediatePropagation();

            showThemeImageContextMenuV37(
                modal,
                event,
                Number(
                    card.dataset.svgIndex
                )
            );
        },
        true
    );

    host.addEventListener(
        'pointerdown',
        event => {
            if (
                event.button !== 0 ||
                event.target.closest(
                    '.theme-builder-svg-card[data-svg-index], .theme-builder-svg-add-card'
                )
            ) {
                return;
            }

            dragging = true;

            const bounds =
                host.getBoundingClientRect();

            startX =
                event.clientX -
                bounds.left +
                host.scrollLeft;

            startY =
                event.clientY -
                bounds.top +
                host.scrollTop;

            marquee =
                document.createElement(
                    'div'
                );

            marquee.className =
                'theme-image-selection-marquee-v37';

            host.appendChild(
                marquee
            );

            if (
                !event.shiftKey &&
                !event.ctrlKey &&
                !event.metaKey
            ) {
                ensureThemeImageSelectionV37(
                    modal
                ).clear();
            }

            host.setPointerCapture?.(
                event.pointerId
            );
        }
    );

    host.addEventListener(
        'pointermove',
        event => {
            if (
                !dragging ||
                !marquee
            ) {
                return;
            }

            const bounds =
                host.getBoundingClientRect();

            const currentX =
                event.clientX -
                bounds.left +
                host.scrollLeft;

            const currentY =
                event.clientY -
                bounds.top +
                host.scrollTop;

            const left =
                Math.min(
                    startX,
                    currentX
                );

            const top =
                Math.min(
                    startY,
                    currentY
                );

            const width =
                Math.abs(
                    currentX -
                    startX
                );

            const height =
                Math.abs(
                    currentY -
                    startY
                );

            Object.assign(
                marquee.style,
                {
                    left:
                        `${left}px`,
                    top:
                        `${top}px`,
                    width:
                        `${width}px`,
                    height:
                        `${height}px`
                }
            );

            const marqueeRect =
                marquee.getBoundingClientRect();

            const selected =
                ensureThemeImageSelectionV37(
                    modal
                );

            host
                .querySelectorAll(
                    '.theme-builder-svg-card[data-svg-index]'
                )
                .forEach(
                    card => {
                        const rect =
                            card.getBoundingClientRect();

                        const intersects =
                            !(
                                rect.right <
                                    marqueeRect.left ||
                                rect.left >
                                    marqueeRect.right ||
                                rect.bottom <
                                    marqueeRect.top ||
                                rect.top >
                                    marqueeRect.bottom
                            );

                        const index =
                            Number(
                                card.dataset
                                    .svgIndex
                            );

                        if (intersects) {
                            selected.add(
                                index
                            );
                        } else if (
                            !event.shiftKey &&
                            !event.ctrlKey &&
                            !event.metaKey
                        ) {
                            selected.delete(
                                index
                            );
                        }
                    }
                );

            refreshThemeImageSelectionV37(
                modal
            );
        }
    );

    const finishDrag =
        event => {
            if (!dragging) {
                return;
            }

            dragging = false;

            marquee?.remove();

            marquee = null;

            try {
                host.releasePointerCapture?.(
                    event.pointerId
                );
            } catch {}
        };

    host.addEventListener(
        'pointerup',
        finishDrag
    );

    host.addEventListener(
        'pointercancel',
        finishDrag
    );
}

