// ============================================================
// V38 — CLICKABLE @DAY REFERENCES IN DAILY LOG NOTES
// Type @Day 14 or @ Day 14, then press Space. It becomes a clickable link.
// ============================================================

function insertDayReferenceAtRangeV38(
    range,
    dayNumber,
    displayText
) {
    if (
        !range ||
        !Number.isFinite(
            Number(
                dayNumber
            )
        ) ||
        Number(
            dayNumber
        ) <
            1
    ) {
        return null;
    }

    const day =
        Math.floor(
            Number(
                dayNumber
            )
        );

    const link =
        document.createElement(
            'a'
        );

    link.href =
        `#day-${day}`;

    link.className =
        'notes-day-link-v38';

    link.dataset.day =
        String(day);

    link.contentEditable =
        'false';

    link.title =
        `Open Day ${day}`;

    link.textContent =
        displayText ||
        `@Day ${day}`;

    range.deleteContents();
    range.insertNode(
        link
    );

    return link;
}

function tryConvertTypedDayMentionV38(
    event
) {
    if (
        event.key !==
            ' ' ||
        event.ctrlKey ||
        event.metaKey ||
        event.altKey
    ) {
        return;
    }

    const notes =
        document.getElementById(
            'log-notes'
        );

    if (!notes) {
        return;
    }

    const selection =
        window.getSelection();

    if (
        !selection ||
        !selection.rangeCount
    ) {
        return;
    }

    const activeRange =
        selection.getRangeAt(
            0
        );

    if (
        !activeRange.collapsed ||
        !notes.contains(
            activeRange.startContainer
        )
    ) {
        return;
    }

    const node =
        activeRange.startContainer;

    if (
        node.nodeType !==
        Node.TEXT_NODE
    ) {
        return;
    }

    const before =
        node.data.slice(
            0,
            activeRange.startOffset
        );

    const match =
        before.match(
            /(?:^|\s)(@(?:\s*)Day\s+(\d+))$/i
        );

    if (!match) {
        return;
    }

    const day =
        Number(
            match[2]
        );

    if (
        !Number.isFinite(day) ||
        day <
            1
    ) {
        return;
    }

    event.preventDefault();

    const mentionText =
        match[1]
            .replace(
                /^@\s*Day/i,
                '@Day'
            );

    const start =
        activeRange.startOffset -
        match[1].length;

    const mentionRange =
        document.createRange();

    mentionRange.setStart(
        node,
        start
    );

    mentionRange.setEnd(
        node,
        activeRange.startOffset
    );

    const link =
        insertDayReferenceAtRangeV38(
            mentionRange,
            day,
            mentionText
        );

    if (!link) {
        return;
    }

    const spacer =
        document.createTextNode(
            ' '
        );

    link.after(
        spacer
    );

    const nextRange =
        document.createRange();

    nextRange.setStartAfter(
        spacer
    );

    nextRange.collapse(
        true
    );

    selection.removeAllRanges();

    selection.addRange(
        nextRange
    );

    if (currentDay) {
        db.days[currentDay]
            .notes =
            notes.innerHTML;

        scheduleSaveDay();
    }
}

const logNotesV38 =
    document.getElementById(
        'log-notes'
    );

if (
    logNotesV38 &&
    logNotesV38.dataset
        .dayLinksV38 !==
        'true'
) {
    logNotesV38.dataset
        .dayLinksV38 =
        'true';

    logNotesV38.addEventListener(
        'keydown',
        tryConvertTypedDayMentionV38,
        true
    );

    logNotesV38.addEventListener(
        'click',
        event => {
            const link =
                event.target.closest(
                    '.notes-day-link-v38[data-day]'
                );

            if (!link) {
                return;
            }

            event.preventDefault();
            event.stopPropagation();

            const day =
                Number(
                    link.dataset.day
                );

            if (
                Number.isFinite(day) &&
                day >=
                    1
            ) {
                openDayLog(
                    day
                );
            }
        }
    );
}



