// V39 — TRASH IS A GLOBAL SIDE-NAV CONTROL
// Order above the divider:
// Home
// Theme Settings (palette)
// Trash
// divider
// ============================================================

function placeTrashAboveSideNavDividerV39() {
    const nav =
        document.querySelector(
            '.side-nav'
        );

    const palette =
        document.getElementById(
            'open-global-daily-settings-nav-btn'
        );

    const separator =
        document.getElementById(
            'side-nav-general-separator'
        );

    if (
        !nav ||
        !palette ||
        !separator
    ) {
        return null;
    }

    let trash =
        document.getElementById(
            'open-trash-view-btn'
        );

    if (!trash) {
        trash =
            document.createElement(
                'button'
            );

        trash.id =
            'open-trash-view-btn';

        trash.type =
            'button';

        trash.className =
            'icon-btn feature-trash-nav-btn';

        trash.title =
            'Trash';

        trash.setAttribute(
            'aria-label',
            'Trash'
        );

        trash.innerHTML =
            '<i class="ph ph-trash"></i>';

        trash.addEventListener(
            'click',
            openTrashViewV2
        );
    }

    // Keep it fixed directly beneath the palette and directly above the line.
    nav.insertBefore(
        trash,
        separator
    );

    return trash;
}

