function bindManualImageDraggingV40(
    modal
) {
    const canvas =
        modal?.querySelector(
            '.theme-builder-live-canvas'
        );

    if (!canvas) {
        return;
    }

    canvas
        .querySelectorAll(
            '.theme-builder-live-art-item[data-svg-index]'
        )
        .forEach(
            item => {
                if (
                    item.dataset
                        .manualDragV40 ===
                    'true'
                ) {
                    return;
                }

                item.dataset
                    .manualDragV40 =
                    'true';

                item.addEventListener(
                    'pointerdown',
                    event => {
                        const draft =
                            getThemeBuilderDraft(
                                modal
                            );

                        if (
                            draft
                                .svgDistribution !==
                            'manual-fixed'
                        ) {
                            return;
                        }

                        event.preventDefault();
                        event.stopPropagation();

                        const index =
                            Number(
                                item.dataset
                                    .svgIndex
                            );

                        if (
                            !Number.isFinite(
                                index
                            )
                        ) {
                            return;
                        }

                        item.classList.add(
                            'theme-image-manual-dragging-v40'
                        );

                        item.setPointerCapture?.(
                            event.pointerId
                        );

                        const move =
                            moveEvent => {
                                const rect =
                                    canvas
                                        .getBoundingClientRect();

                                const scale =
                                    Number(
                                        getComputedStyle(
                                            canvas
                                        )
                                            .getPropertyValue(
                                                '--theme-builder-preview-scale'
                                            )
                                    ) ||
                                    1;

                                const unscaledX =
                                    (
                                        moveEvent.clientX -
                                        rect.left
                                    ) /
                                    scale;

                                const unscaledY =
                                    (
                                        moveEvent.clientY -
                                        rect.top
                                    ) /
                                    scale;

                                const x =
                                    Math.max(
                                        2,
                                        Math.min(
                                            98,
                                            (
                                                unscaledX /
                                                canvas
                                                    .offsetWidth
                                            ) *
                                            100
                                        )
                                    );

                                const y =
                                    Math.max(
                                        3,
                                        Math.min(
                                            97,
                                            (
                                                unscaledY /
                                                canvas
                                                    .offsetHeight
                                            ) *
                                            100
                                        )
                                    );

                                const count =
                                    modal
                                        ._themeBackgroundSvgs
                                        ?.length ||
                                    0;

                                modal._manualPlacementSlotsV40 =
                                    normalizeManualSlotsV40(
                                        modal
                                            ._manualPlacementSlotsV40,
                                        count
                                    );

                                modal
                                    ._manualPlacementSlotsV40[
                                        index
                                    ] = {
                                        x,
                                        y
                                    };

                                item.style.left =
                                    `${x}%`;

                                item.style.top =
                                    `${y}%`;
                            };

                        const end =
                            endEvent => {
                                item.classList.remove(
                                    'theme-image-manual-dragging-v40'
                                );

                                item.removeEventListener(
                                    'pointermove',
                                    move
                                );

                                item.removeEventListener(
                                    'pointerup',
                                    end
                                );

                                item.removeEventListener(
                                    'pointercancel',
                                    end
                                );

                                try {
                                    item.releasePointerCapture?.(
                                        endEvent
                                            .pointerId
                                    );
                                } catch {}
                            };

                        item.addEventListener(
                            'pointermove',
                            move
                        );

                        item.addEventListener(
                            'pointerup',
                            end
                        );

                        item.addEventListener(
                            'pointercancel',
                            end
                        );
                    }
                );
            }
        );
}

