function ensureDashboardThemeControlsV40(
    modal,
    theme = {}
) {
    const controls =
        modal?.querySelector(
            '.theme-builder-controls'
        );

    if (!controls) {
        return;
    }

    let section =
        controls.querySelector(
            '.theme-builder-dashboard-colors-v40'
        );

    if (!section) {
        section =
            document.createElement(
                'section'
            );

        section.className =
            'theme-builder-control-section theme-builder-dashboard-colors-v40';

        section.dataset
            .themeBuilderPanelGroup =
            'colors';

        section.innerHTML = `
            <div class="theme-builder-control-heading">
                <strong>Dashboard Colors</strong>
                <small>
                    Optional dashboard-specific colors. Leave them matching the main theme for one consistent look.
                </small>
            </div>

            <div class="theme-builder-dashboard-color-grid-v40">
                ${[
                    [
                        'dashboardBackgroundV40',
                        'Dashboard Background'
                    ],
                    [
                        'dashboardCardV40',
                        'Log Cards'
                    ],
                    [
                        'dashboardTextV40',
                        'Dashboard Text'
                    ],
                    [
                        'dashboardAccentV40',
                        'Buttons / Accent'
                    ]
                ].map(
                    (
                        [
                            key,
                            label
                        ]
                    ) => `
                        <label class="theme-builder-color-control">
                            <span>${label}</span>
                            <div class="theme-builder-color-input-row">
                                <input
                                    type="color"
                                    data-theme-key="${key}"
                                >
                                <input
                                    type="text"
                                    data-theme-hex="${key}"
                                    maxlength="7"
                                    spellcheck="false"
                                >
                            </div>
                        </label>
                    `
                ).join('')}
            </div>
        `;

        const firstNonColor =
            Array.from(
                controls.children
            )
                .find(
                    child =>
                        child.dataset
                            ?.themeBuilderPanelGroup &&
                        child.dataset
                            .themeBuilderPanelGroup !==
                            'colors'
                );

        if (firstNonColor) {
            controls.insertBefore(
                section,
                firstNonColor
            );
        } else {
            controls.appendChild(
                section
            );
        }

        section
            .querySelectorAll(
                'input[type="color"][data-theme-key]'
            )
            .forEach(
                picker => {
                    picker.addEventListener(
                        'input',
                        () => {
                            const hex =
                                section.querySelector(
                                    `[data-theme-hex="${CSS.escape(
                                        picker.dataset
                                            .themeKey
                                    )}"]`
                                );

                            if (hex) {
                                hex.value =
                                    picker.value;
                            }

                            updateThemeBuilderPreview(
                                modal
                            );
                        }
                    );
                }
            );

        section
            .querySelectorAll(
                '[data-theme-hex]'
            )
            .forEach(
                input => {
                    input.addEventListener(
                        'change',
                        () => {
                            if (
                                !/^#[0-9a-f]{6}$/i.test(
                                    input.value
                                )
                            ) {
                                return;
                            }

                            const picker =
                                section.querySelector(
                                    `input[type="color"][data-theme-key="${CSS.escape(
                                        input.dataset
                                            .themeHex
                                    )}"]`
                                );

                            if (picker) {
                                picker.value =
                                    input.value;
                            }

                            updateThemeBuilderPreview(
                                modal
                            );
                        }
                    );
                }
            );
    }

    const values = {
        dashboardBackgroundV40:
            theme
                .dashboardBackgroundV40 ||
            theme.background ||
            '#f5f5f5',
        dashboardCardV40:
            theme
                .dashboardCardV40 ||
            theme.surface ||
            '#ffffff',
        dashboardTextV40:
            theme
                .dashboardTextV40 ||
            theme.text ||
            '#000000',
        dashboardAccentV40:
            theme
                .dashboardAccentV40 ||
            theme.accent ||
            '#777777'
    };

    Object.entries(
        values
    ).forEach(
        (
            [
                key,
                value
            ]
        ) => {
            const color =
                /^#[0-9a-f]{6}$/i.test(
                    String(
                        value
                    )
                )
                    ? value
                    : '#777777';

            const picker =
                section.querySelector(
                    `input[type="color"][data-theme-key="${CSS.escape(
                        key
                    )}"]`
                );

            const hex =
                section.querySelector(
                    `[data-theme-hex="${CSS.escape(
                        key
                    )}"]`
                );

            if (picker) {
                picker.value =
                    color;
            }

            if (hex) {
                hex.value =
                    color;
            }
        }
    );

    // Rebuild tab grouping after adding a Colors section.
    if (
        typeof installThemeBuilderSectionTabsV11 ===
        'function'
    ) {
        installThemeBuilderSectionTabsV11(
            modal
        );
    }
}


