// ------------------------------------------------------------
// Shared theme library: log pages publish custom themes/copies.
// ------------------------------------------------------------

function readSharedThemeLibraryV40() {
    try {
        const parsed =
            JSON.parse(
                localStorage.getItem(
                    SHARED_THEME_LIBRARY_KEY_V40
                ) ||
                '[]'
            );

        return Array.isArray(
            parsed
        )
            ? parsed
            : [];
    } catch {
        return [];
    }
}

function writeSharedThemeLibraryV40(
    themes
) {
    localStorage.setItem(
        SHARED_THEME_LIBRARY_KEY_V40,
        JSON.stringify(
            Array.isArray(
                themes
            )
                ? themes
                : []
        )
    );
}

function publishSharedThemeV40({
    id,
    name,
    theme,
    sourceThemeId = ''
}) {
    if (
        !id ||
        !theme
    ) {
        return;
    }

    const library =
        readSharedThemeLibraryV40();

    const entry = {
        id,
        name:
            name ||
            theme.name ||
            'Custom Theme',
        sourceThemeId:
            sourceThemeId ||
            '',
        theme:
            cloneThemeDataV30(
                theme
            ),
        updatedAt:
            new Date()
                .toISOString()
    };

    const index =
        library.findIndex(
            item =>
                item.id ===
                id
        );

    if (
        index >=
        0
    ) {
        library[index] =
            entry;
    } else {
        library.push(
            entry
        );
    }

    writeSharedThemeLibraryV40(
        library
    );
}

function removeSharedThemeV40(
    id
) {
    writeSharedThemeLibraryV40(
        readSharedThemeLibraryV40()
            .filter(
                item =>
                    item.id !==
                    id
            )
    );
}

function syncSharedThemesIntoLogV40() {
    if (
        !db.settings
    ) {
        return;
    }

    const copies =
        ensureThemeCopiesV30();

    readSharedThemeLibraryV40()
        .forEach(
            shared => {
                if (
                    !shared?.id ||
                    !shared?.theme
                ) {
                    return;
                }

                const existing =
                    copies.find(
                        copy =>
                            copy.id ===
                            shared.id
                    );

                const next = {
                    id:
                        shared.id,
                    name:
                        shared.name ||
                        'Shared Theme',
                    sourceThemeId:
                        shared.sourceThemeId ||
                        '',
                    theme:
                        cloneThemeDataV30(
                            shared.theme
                        ),
                    sharedV40:
                        true,
                    createdAt:
                        shared.updatedAt ||
                        new Date()
                            .toISOString()
                };

                if (existing) {
                    if (
                        existing
                            .sharedV40
                    ) {
                        Object.assign(
                            existing,
                            next
                        );
                    }
                } else {
                    copies.push(
                        next
                    );
                }
            }
        );
}

function publishCurrentLogThemesV40() {
    const custom =
        getCustomThemeSettings();

    if (
        custom &&
        db.settings
            ?.customThemeDeleted !==
            true
    ) {
        if (
            !db.settings
                .customThemeSharedIdV40
        ) {
            db.settings
                .customThemeSharedIdV40 =
                'theme-custom-builder-shared-' +
                Math.random()
                    .toString(36)
                    .slice(
                        2,
                        10
                    );
        }

        publishSharedThemeV40({
            id:
                db.settings
                    .customThemeSharedIdV40,
            name:
                custom.name ||
                'My Custom Theme',
            theme:
                custom
        });
    }

    ensureThemeCopiesV30()
        .filter(
            copy =>
                !copy.sharedV40
        )
        .forEach(
            copy =>
                publishSharedThemeV40({
                    id:
                        copy.id,
                    name:
                        copy.name,
                    theme:
                        copy.theme,
                    sourceThemeId:
                        copy.sourceThemeId
                })
        );
}

const syncThemeCopyOptionsBeforeSharedV40 =
    syncThemeCopyOptionsV30;

syncThemeCopyOptionsV30 =
    function() {
        syncSharedThemesIntoLogV40();

        syncThemeCopyOptionsBeforeSharedV40();
    };

const applyThemeBeforeSharedPublishV40 =
    applyTheme;

applyTheme =
    async function(
        themeValue,
        opts = {}
    ) {
        await applyThemeBeforeSharedPublishV40(
            themeValue,
            opts
        );

        if (
            themeValue ===
            'theme-custom-builder'
        ) {
            publishCurrentLogThemesV40();
        } else {
            const copy =
                getThemeCopyV30(
                    themeValue
                );

            if (
                copy &&
                !copy.sharedV40
            ) {
                publishSharedThemeV40({
                    id:
                        copy.id,
                    name:
                        copy.name,
                    theme:
                        copy.theme,
                    sourceThemeId:
                        copy.sourceThemeId
                });
            }
        }

        if (
            window
                ._returnDashboardAfterThemeSaveV40
        ) {
            window
                ._returnDashboardAfterThemeSaveV40 =
                false;

            setTimeout(
                () => {
                    window.location.href =
                        '/';
                },
                100
            );
        }
    };

const moveThemeToTrashBeforeSharedV40 =
    moveThemeToTrashV31;

moveThemeToTrashV31 =
    async function(
        themeValue,
        themeName
    ) {
        const copy =
            getThemeCopyV30(
                themeValue
            );

        await moveThemeToTrashBeforeSharedV40(
            themeValue,
            themeName
        );

        if (
            copy?.sharedV40 ||
            readSharedThemeLibraryV40()
                .some(
                    item =>
                        item.id ===
                        themeValue
                )
        ) {
            removeSharedThemeV40(
                themeValue
            );
        }
    };


