async function runDashboardThemeActionV42() {
    const params =
        new URLSearchParams(
            window.location.search
        );

    const legacyCreate =
        params.get(
            'openThemeBuilder'
        ) ===
        '1';

    const action =
        params.get(
            'dashboardThemeAction'
        ) ||
        (
            legacyCreate
                ? 'create'
                : ''
        );

    if (!action) {
        return;
    }

    for (
        let attempt = 0;
        attempt <
            120;
        attempt++
    ) {
        const ready =
            document.getElementById(
                'theme-builder-modal'
            ) &&
            db
                ?.settings &&
            typeof openNewThemeBuilderCleanV34 ===
                'function';

        if (ready) {
            break;
        }

        await new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    80
                )
        );
    }

    if (
        !document.getElementById(
            'theme-builder-modal'
        )
    ) {
        showFeatureToast(
            'Theme Builder could not open.'
        );

        return;
    }

    window
        ._returnDashboardAfterThemeSaveV40 =
        params.get(
            'returnDashboard'
        ) ===
        '1';

    syncSharedThemesIntoLogV40?.();

    const themeId =
        params.get(
            'themeId'
        ) ||
        '';

    if (
        action ===
        'create'
    ) {
        openNewThemeBuilderCleanV34();

        return;
    }

    if (
        action ===
        'edit'
    ) {
        const copy =
            getThemeCopyV30(
                themeId
            );

        if (copy) {
            await openThemeCopyInBuilderV30(
                themeId
            );

            return;
        }

        if (
            themeId ===
            'theme-custom-builder'
        ) {
            openExistingCustomThemeFromPickerV7();

            return;
        }

        await openAnyThemeInBuilderV25(
            themeId,
            getThemeDisplayNameV30(
                themeId
            )
        );

        return;
    }

    if (
        action ===
        'duplicate'
    ) {
        const before =
            ensureThemeCopiesV30()
                .map(
                    item =>
                        item.id
                );

        await duplicateThemeV30(
            themeId,
            getThemeDisplayNameV30(
                themeId
            )
        );

        const created =
            ensureThemeCopiesV30()
                .find(
                    item =>
                        !before.includes(
                            item.id
                        )
                );

        publishCurrentLogThemesV40();

        if (created?.id) {
            localStorage.setItem(
                'dashboard-theme',
                created.id
            );
        }

        if (
            params.get(
                'returnDashboard'
            ) ===
            '1'
        ) {
            window.location.href =
                '/';
        }
    }
}

setTimeout(
    runDashboardThemeActionV42,
    0
);


