const runDashboardThemeActionBeforeStudioV43 =
    runDashboardThemeActionV42;

runDashboardThemeActionV42 =
    async function() {
        if (
            !isDashboardThemeStudioV43()
        ) {
            return runDashboardThemeActionBeforeStudioV43();
        }

        const params =
            new URLSearchParams(
                window.location.search
            );

        const action =
            params.get(
                'dashboardThemeAction'
            ) ||
            'create';

        const themeId =
            params.get(
                'themeId'
            ) ||
            '';

        // Wait for the host log's app runtime, but do not navigate to it.
        for (
            let attempt = 0;
            attempt <
                120;
            attempt++
        ) {
            if (
                db?.settings &&
                typeof openNewThemeBuilderCleanV34 ===
                    'function'
            ) {
                break;
            }

            await new Promise(
                resolve =>
                    setTimeout(
                        resolve,
                        80
                    )
            );
        }

        window._returnDashboardAfterThemeSaveV40 =
            false;

        if (
            action ===
            'create'
        ) {
            openNewThemeBuilderCleanV34();

            return;
        }

        if (
            action ===
            'edit' &&
            await openDashboardSharedThemeInStudioV43(
                themeId
            )
        ) {
            return;
        }

        if (
            action ===
            'duplicate'
        ) {
            const shared =
                readSharedThemeLibraryForStudioV43()
                    .find(
                        item =>
                            item.id ===
                            themeId
                    );

            if (shared?.theme) {
                const copy = {
                    ...shared,
                    id:
                        makeDashboardStudioThemeIdV43(),
                    name:
                        `${
                            shared.name ||
                            'Theme'
                        } Copy`,
                    theme:
                        {
                            ...cloneThemeDataV30(
                                shared.theme
                            ),
                            name:
                                `${
                                    shared.name ||
                                    'Theme'
                                } Copy`
                        },
                    updatedAt:
                        new Date()
                            .toISOString()
                };

                saveSharedThemeFromStudioV43(
                    copy
                );

                window.parent
                    ?.postMessage(
                        {
                            type:
                                'dashboard-theme-studio-saved-v43',
                            themeId:
                                copy.id,
                            apply:
                                false
                        },
                        window.location.origin
                    );

                return;
            }
        }

        return runDashboardThemeActionBeforeStudioV43();
    };



// ============================================================
// V44 — TRUE MANUAL DRAGGING / ONE-STEP THEME DELETE
// @DAY AUTOCOMPLETE / RELIABLE DASHBOARD PREVIEW
// ============================================================


// ------------------------------------------------------------
// ONE RIGHT-CLICK DELETE: remove shared backing BEFORE V31 sync.
// ------------------------------------------------------------

const moveThemeToTrashBeforeOneStepV44 =
    moveThemeToTrashV31;

moveThemeToTrashV31 =
    async function(
        themeId,
        themeName
    ) {
        const libraryBefore =
            readSharedThemeLibraryV40();

        const sharedEntry =
            libraryBefore.find(
                item =>
                    item.id ===
                    themeId
            ) ||
            null;

        const trashBefore =
            getThemeTrashV31()
                .length;

        // Important: V31 deletion calls syncThemeCopyOptionsV30 internally.
        // If the shared entry still exists at that moment, V40 re-imports the
        // just-deleted theme. Remove it first so deletion is genuinely atomic.
        if (sharedEntry) {
            removeSharedThemeV40(
                themeId
            );
        }

        await moveThemeToTrashBeforeOneStepV44(
            themeId,
            themeName
        );

        const actuallyDeleted =
            getThemeTrashV31()
                .length >
                trashBefore ||
            db.settings
                ?.customThemeDeleted ===
                true ||
            (
                db.settings
                    ?.deletedThemes ||
                []
            ).includes(
                themeId
            ) ||
            !ensureThemeCopiesV30()
                .some(
                    copy =>
                        copy.id ===
                        themeId
                );

        if (
            sharedEntry &&
            !actuallyDeleted
        ) {
            // User cancelled the confirmation: restore shared entry exactly.
            const current =
                readSharedThemeLibraryV40();

            if (
                !current.some(
                    item =>
                        item.id ===
                        sharedEntry.id
                )
            ) {
                current.push(
                    sharedEntry
                );

                writeSharedThemeLibraryV40(
                    current
                );
            }

            return;
        }

        if (actuallyDeleted) {
            db.settings.themeCopiesV30 =
                ensureThemeCopiesV30()
                    .filter(
                        copy =>
                            copy.id !==
                            themeId
                    );

            removeSharedThemeV40(
                themeId
            );

            await saveDb();

            syncThemeCopyOptionsV30();
            renderThemePicker();
        }
    };

// Stale shared copies are also removed automatically when their shared
// backing entry no longer exists.
const syncSharedThemesIntoLogBeforePruneV44 =
    syncSharedThemesIntoLogV40;

syncSharedThemesIntoLogV40 =
    function() {
        const sharedIds =
            new Set(
                readSharedThemeLibraryV40()
                    .map(
                        item =>
                            item.id
                    )
            );

        if (
            Array.isArray(
                db.settings
                    ?.themeCopiesV30
            )
        ) {
            db.settings.themeCopiesV30 =
                db.settings
                    .themeCopiesV30
                    .filter(
                        copy =>
                            !copy
                                ?.sharedV40 ||
                            sharedIds.has(
                                copy.id
                            )
                    );
        }

        syncSharedThemesIntoLogBeforePruneV44();
    };


// ------------------------------------------------------------
// @DAY AUTOCOMPLETE — opens the moment @ is typed.
// ------------------------------------------------------------

let dayMentionMenuV44 =
    null;

let dayMentionRangeV44 =
    null;

let dayMentionStartOffsetV44 =
    null;

let dayMentionSelectedIndexV44 =
    0;

let dayMentionSuggestionsV44 =
    [];

function ensureDayMentionMenuV44() {
    if (dayMentionMenuV44) {
        return dayMentionMenuV44;
    }

    const menu =
        document.createElement(
            'div'
        );

    menu.id =
        'daily-day-mention-menu-v44';

    menu.className =
        'daily-day-mention-menu-v44 hidden';

    document.body.appendChild(
        menu
    );

    dayMentionMenuV44 =
        menu;

    menu.addEventListener(
        'pointerdown',
        event => {
            const option =
                event.target.closest(
                    '[data-day-mention-v44]'
                );

            if (!option) {
                return;
            }

            event.preventDefault();

            insertDayMentionSuggestionV44(
                Number(
                    option.dataset
                        .dayMentionV44
                )
            );
        }
    );

    return menu;
}

function closeDayMentionMenuV44() {
    dayMentionMenuV44
        ?.classList.add(
            'hidden'
        );

    dayMentionRangeV44 =
        null;

    dayMentionStartOffsetV44 =
        null;

    dayMentionSuggestionsV44 =
        [];

    dayMentionSelectedIndexV44 =
        0;
}

function getAllAvailableDaysV44() {
    const saved =
        Object.keys(
            db.days ||
            {}
        )
            .map(
                Number
            )
            .filter(
                day =>
                    Number.isFinite(
                        day
                    ) &&
                    day >=
                        1
            );

    const maximum =
        Math.max(
            Number(
                typeof TOTAL_CURRICULUM_DAYS !==
                    'undefined'
                    ? TOTAL_CURRICULUM_DAYS
                    : 0
            ) ||
                0,
            ...saved,
            currentDay ||
                0,
            1
        );

    return Array.from(
        {
            length:
                maximum
        },
        (
            _,
            index
        ) =>
            index +
            1
    );
}

function getDayMentionContextV44(
    notes
) {
    const selection =
        window.getSelection();

    if (
        !selection ||
        !selection.rangeCount
    ) {
        return null;
    }

    const range =
        selection.getRangeAt(
            0
        );

    if (
        !range.collapsed ||
        !notes.contains(
            range.startContainer
        ) ||
        range.startContainer.nodeType !==
            Node.TEXT_NODE
    ) {
        return null;
    }

    const node =
        range.startContainer;

    const offset =
        range.startOffset;

    const before =
        node.data.slice(
            0,
            offset
        );

    const match =
        before.match(
            /@([^@\n]*)$/
        );

    if (!match) {
        return null;
    }

    const raw =
        match[1];

    // Stop treating it as a mention after normal prose begins.
    if (
        raw.length >
        18
    ) {
        return null;
    }

    const compact =
        raw
            .trim()
            .toLowerCase();

    if (
        compact &&
        !(
            /^d(a(y)?)?(\s+\d*)?$/.test(
                compact
            ) ||
            /^\d*$/.test(
                compact
            )
        )
    ) {
        return null;
    }

    return {
        node,
        offset,
        start:
            offset -
            raw.length -
            1,
        raw,
        range:
            range.cloneRange()
    };
}

function getDayMentionMatchesV44(
    raw
) {
    const query =
        String(
            raw ||
            ''
        )
            .trim()
            .toLowerCase()
            .replace(
                /^day\s*/,
                ''
            )
            .replace(
                /^d\s*/,
                ''
            );

    let days =
        getAllAvailableDaysV44();

    if (
        /^\d+$/.test(
            query
        )
    ) {
        days =
            days.filter(
                day =>
                    String(
                        day
                    ).startsWith(
                        query
                    )
            );
    }

    return days.slice(
        0,
        18
    );
}

function positionDayMentionMenuV44(
    range,
    notes
) {
    const menu =
        ensureDayMentionMenuV44();

    let rect =
        range
            .getBoundingClientRect();

    if (
        !rect ||
        (
            !rect.width &&
            !rect.height
        )
    ) {
        rect =
            notes.getBoundingClientRect();
    }

    const menuWidth =
        220;

    const left =
        Math.max(
            8,
            Math.min(
                window.innerWidth -
                    menuWidth -
                    8,
                rect.left
            )
        );

    const top =
        Math.min(
            window.innerHeight -
                260,
            rect.bottom +
                8
        );

    menu.style.left =
        `${left}px`;

    menu.style.top =
        `${Math.max(
            8,
            top
        )}px`;
}

function renderDayMentionMenuV44(
    notes
) {
    const context =
        getDayMentionContextV44(
            notes
        );

    if (!context) {
        closeDayMentionMenuV44();

        return;
    }

    const suggestions =
        getDayMentionMatchesV44(
            context.raw
        );

    if (!suggestions.length) {
        closeDayMentionMenuV44();

        return;
    }

    dayMentionRangeV44 =
        context.range;

    dayMentionStartOffsetV44 =
        context.start;

    dayMentionSuggestionsV44 =
        suggestions;

    dayMentionSelectedIndexV44 =
        Math.min(
            dayMentionSelectedIndexV44,
            suggestions.length -
                1
        );

    const menu =
        ensureDayMentionMenuV44();

    menu.innerHTML = `
        <div class="daily-day-mention-title-v44">
            Link a Daily Log
        </div>

        <div class="daily-day-mention-results-v44">
            ${suggestions.map(
                (
                    day,
                    index
                ) => `
                    <button
                        type="button"
                        data-day-mention-v44="${day}"
                        class="${index === dayMentionSelectedIndexV44 ? 'selected' : ''}"
                    >
                        <i class="ph ph-calendar-blank"></i>
                        <span>Day ${day}</span>
                    </button>
                `
            ).join('')}
        </div>
    `;

    menu.classList.remove(
        'hidden'
    );

    positionDayMentionMenuV44(
        context.range,
        notes
    );
}

function insertDayMentionSuggestionV44(
    day
) {
    const notes =
        document.getElementById(
            'log-notes'
        );

    const selection =
        window.getSelection();

    if (
        !notes ||
        !dayMentionRangeV44 ||
        !selection ||
        !Number.isFinite(
            day
        )
    ) {
        closeDayMentionMenuV44();

        return;
    }

    const node =
        dayMentionRangeV44
            .startContainer;

    if (
        node.nodeType !==
        Node.TEXT_NODE
    ) {
        closeDayMentionMenuV44();

        return;
    }

    const end =
        dayMentionRangeV44
            .startOffset;

    const start =
        Number(
            dayMentionStartOffsetV44
        );

    if (
        !Number.isFinite(
            start
        ) ||
        start <
            0 ||
        start >
            end
    ) {
        closeDayMentionMenuV44();

        return;
    }

    const replace =
        document.createRange();

    replace.setStart(
        node,
        start
    );

    replace.setEnd(
        node,
        end
    );

    const link =
        makeDayLinkV41(
            day,
            `@Day ${day}`
        );

    replace.deleteContents();

    replace.insertNode(
        link
    );

    const space =
        document.createTextNode(
            '\u00A0'
        );

    link.after(
        space
    );

    const caret =
        document.createRange();

    caret.setStartAfter(
        space
    );

    caret.collapse(
        true
    );

    selection.removeAllRanges();

    selection.addRange(
        caret
    );

    closeDayMentionMenuV44();

    if (currentDay) {
        db.days[currentDay]
            .notes =
            notes.innerHTML;

        scheduleSaveDay();
    }

    notes.focus();
}

function bindDayMentionAutocompleteV44() {
    const notes =
        document.getElementById(
            'log-notes'
        );

    if (
        !notes ||
        notes.dataset
            .dayMentionAutocompleteV44 ===
            'true'
    ) {
        return;
    }

    notes.dataset
        .dayMentionAutocompleteV44 =
        'true';

    notes.addEventListener(
        'input',
        () => {
            dayMentionSelectedIndexV44 =
                0;

            renderDayMentionMenuV44(
                notes
            );
        }
    );

    notes.addEventListener(
        'keyup',
        event => {
            if (
                [
                    'ArrowDown',
                    'ArrowUp',
                    'Enter',
                    'Escape'
                ].includes(
                    event.key
                )
            ) {
                return;
            }

            renderDayMentionMenuV44(
                notes
            );
        }
    );

    notes.addEventListener(
        'keydown',
        event => {
            const menuOpen =
                dayMentionMenuV44 &&
                !dayMentionMenuV44
                    .classList
                    .contains(
                        'hidden'
                    );

            if (!menuOpen) {
                return;
            }

            if (
                event.key ===
                'ArrowDown'
            ) {
                event.preventDefault();

                dayMentionSelectedIndexV44 =
                    (
                        dayMentionSelectedIndexV44 +
                        1
                    ) %
                    dayMentionSuggestionsV44
                        .length;

                renderDayMentionMenuV44(
                    notes
                );

                return;
            }

            if (
                event.key ===
                'ArrowUp'
            ) {
                event.preventDefault();

                dayMentionSelectedIndexV44 =
                    (
                        dayMentionSelectedIndexV44 -
                        1 +
                        dayMentionSuggestionsV44
                            .length
                    ) %
                    dayMentionSuggestionsV44
                        .length;

                renderDayMentionMenuV44(
                    notes
                );

                return;
            }

            if (
                event.key ===
                'Enter' ||
                event.key ===
                'Tab'
            ) {
                event.preventDefault();
                event.stopImmediatePropagation();

                const day =
                    dayMentionSuggestionsV44[
                        dayMentionSelectedIndexV44
                    ];

                if (day) {
                    insertDayMentionSuggestionV44(
                        day
                    );
                }

                return;
            }

            if (
                event.key ===
                'Escape'
            ) {
                event.preventDefault();

                closeDayMentionMenuV44();
            }
        },
        true
    );

    notes.addEventListener(
        'blur',
        () =>
            setTimeout(
                closeDayMentionMenuV44,
                160
            )
    );
}

bindDayMentionAutocompleteV44();

const openDayLogBeforeDayMentionV44 =
    openDayLog;

openDayLog =
    function(
        dayNumber
    ) {
        closeDayMentionMenuV44();

        const result =
            openDayLogBeforeDayMentionV44(
                dayNumber
            );

        requestAnimationFrame(
            bindDayMentionAutocompleteV44
        );

        return result;
    };


// ------------------------------------------------------------
// TRUE MANUAL DRAG — modal-level capture, above preview content.
// ------------------------------------------------------------

function syncManualDragModeV44(
    modal
) {
    const canvas =
        modal?.querySelector(
            '.theme-builder-live-canvas'
        );

    if (!canvas) {
        return;
    }

    const manual =
        modal
            ?.querySelector(
                '.theme-builder-svg-distribution'
            )
            ?.value ===
            'manual-fixed';

    canvas.classList.toggle(
        'theme-manual-placement-active-v44',
        manual
    );

    canvas
        .querySelectorAll(
            '.theme-builder-live-art-item'
        )
        .forEach(
            (
                item,
                index
            ) => {
                item.dataset
                    .manualSlotV44 =
                    String(
                        index
                    );

                item.classList.toggle(
                    'theme-manual-draggable-v44',
                    manual
                );
            }
        );
}

function bindTrueManualDragV44(
    modal
) {
    if (
        !modal ||
        modal.dataset
            .manualDragV44 ===
            'true'
    ) {
        syncManualDragModeV44(
            modal
        );

        return;
    }

    modal.dataset
        .manualDragV44 =
        'true';

    modal.addEventListener(
        'pointerdown',
        event => {
            const item =
                event.target.closest(
                    '.theme-builder-live-art-item'
                );

            if (!item) {
                return;
            }

            const select =
                modal.querySelector(
                    '.theme-builder-svg-distribution'
                );

            if (
                select?.value !==
                'manual-fixed'
            ) {
                return;
            }

            const canvas =
                modal.querySelector(
                    '.theme-builder-live-canvas'
                );

            if (!canvas) {
                return;
            }

            const slot =
                Number(
                    item.dataset
                        .manualSlotV44
                );

            if (
                !Number.isFinite(
                    slot
                )
            ) {
                return;
            }

            event.preventDefault();
            event.stopImmediatePropagation();

            item.classList.add(
                'theme-image-manual-dragging-v40'
            );

            const move =
                moveEvent => {
                    const rect =
                        canvas.getBoundingClientRect();

                    if (
                        !rect.width ||
                        !rect.height
                    ) {
                        return;
                    }

                    const x =
                        Math.max(
                            2,
                            Math.min(
                                98,
                                (
                                    (
                                        moveEvent.clientX -
                                        rect.left
                                    ) /
                                    rect.width
                                ) *
                                    100
                            )
                        );

                    const y =
                        Math.max(
                            3,
                            Math.min(
                                97,
                                (
                                    (
                                        moveEvent.clientY -
                                        rect.top
                                    ) /
                                    rect.height
                                ) *
                                    100
                            )
                        );

                    const count =
                        modal
                            ._themeBackgroundSvgs
                            ?.length ||
                        0;

                    modal._manualPlacementSlotsV40 =
                        normalizeManualSlotsV40(
                            modal
                                ._manualPlacementSlotsV40,
                            count
                        );

                    modal
                        ._manualPlacementSlotsV40[
                            slot
                        ] = {
                            x,
                            y
                        };

                    item.style.left =
                        `${x}%`;

                    item.style.top =
                        `${y}%`;
                };

            const finish =
                () => {
                    item.classList.remove(
                        'theme-image-manual-dragging-v40'
                    );

                    document.removeEventListener(
                        'pointermove',
                        move,
                        true
                    );

                    document.removeEventListener(
                        'pointerup',
                        finish,
                        true
                    );

                    document.removeEventListener(
                        'pointercancel',
                        finish,
                        true
                    );

                    renderDashboardThemePreviewV40(
                        modal
                    );
                };

            document.addEventListener(
                'pointermove',
                move,
                true
            );

            document.addEventListener(
                'pointerup',
                finish,
                true
            );

            document.addEventListener(
                'pointercancel',
                finish,
                true
            );
        },
        true
    );

    modal.addEventListener(
        'change',
        event => {
            if (
                !event.target.matches(
                    '.theme-builder-svg-distribution'
                )
            ) {
                return;
            }

            // V42 already captured the old layout. Make it visible immediately.
            requestAnimationFrame(
                () => {
                    syncManualDragModeV44(
                        modal
                    );

                    installTrueManualDragV42?.(
                        modal
                    );
                }
            );
        },
        true
    );

    syncManualDragModeV44(
        modal
    );
}


// ------------------------------------------------------------
// DASHBOARD PREVIEW — a real preview mode inside the same viewport.
// ------------------------------------------------------------

function ensureReliableDashboardPreviewV44(
    modal
) {
    if (!modal) {
        return null;
    }

    ensureThemeBuilderDashboardPreviewV40(
        modal
    );

    const viewport =
        modal.querySelector(
            '.theme-builder-live-preview-viewport'
        );

    if (!viewport) {
        return null;
    }

    viewport.classList.add(
        'theme-builder-preview-viewport-v44'
    );

    const dashboard =
        viewport.querySelector(
            '.theme-builder-dashboard-preview-v40'
        );

    if (dashboard) {
        dashboard.classList.add(
            'theme-builder-dashboard-preview-v44'
        );
    }

    const button =
        modal.querySelector(
            '.theme-builder-dashboard-preview-button-v40'
        );

    if (button) {
        button.title =
            'Preview Dashboard';

        button.innerHTML =
            '<i class="ph ph-house"></i> Dashboard';

        if (
            button.dataset
                .dashboardPreviewV44 !==
            'true'
        ) {
            button.dataset
                .dashboardPreviewV44 =
                'true';

            button.addEventListener(
                'click',
                event => {
                    event.preventDefault();
                    event.stopImmediatePropagation();

                    showReliableDashboardPreviewV44(
                        modal
                    );
                },
                true
            );
        }
    }

    return dashboard;
}

function showReliableDashboardPreviewV44(
    modal
) {
    const dashboard =
        ensureReliableDashboardPreviewV44(
            modal
        );

    const viewport =
        modal?.querySelector(
            '.theme-builder-live-preview-viewport'
        );

    const stage =
        viewport?.querySelector(
            '.theme-builder-live-preview-stage'
        );

    if (
        !dashboard ||
        !viewport
    ) {
        return;
    }

    modal._dashboardPreviewActiveV40 =
        true;

    stage?.classList.add(
        'hidden'
    );

    dashboard.classList.remove(
        'hidden'
    );

    dashboard.style.removeProperty(
        'display'
    );

    renderDashboardThemePreviewV40(
        modal
    );

    modal
        .querySelector(
            '.theme-builder-dashboard-preview-button-v40'
        )
        ?.classList.add(
            'active'
        );
}

function hideReliableDashboardPreviewV44(
    modal
) {
    const viewport =
        modal?.querySelector(
            '.theme-builder-live-preview-viewport'
        );

    modal._dashboardPreviewActiveV40 =
        false;

    viewport
        ?.querySelector(
            '.theme-builder-live-preview-stage'
        )
        ?.classList.remove(
            'hidden'
        );

    viewport
        ?.querySelector(
            '.theme-builder-dashboard-preview-v40'
        )
        ?.classList.add(
            'hidden'
        );

    modal
        ?.querySelector(
            '.theme-builder-dashboard-preview-button-v40'
        )
        ?.classList.remove(
            'active'
        );
}

function bindPreviewNavigationV44(
    modal
) {
    if (
        !modal ||
        modal.dataset
            .previewNavigationV44 ===
            'true'
    ) {
        return;
    }

    modal.dataset
        .previewNavigationV44 =
        'true';

    modal.addEventListener(
        'click',
        event => {
            const home =
                event.target.closest(
                    '.theme-builder-live-canvas a[href="/"]'
                );

            if (home) {
                event.preventDefault();
                event.stopImmediatePropagation();

                showReliableDashboardPreviewV44(
                    modal
                );

                return;
            }

            const previewNav =
                event.target.closest(
                    '.theme-builder-live-side-nav button, .theme-builder-live-side-nav a.icon-btn'
                );

            if (
                previewNav &&
                !home
            ) {
                hideReliableDashboardPreviewV44(
                    modal
                );
            }
        },
        true
    );
}


// ------------------------------------------------------------
// Final Theme Builder render hooks.
