const populateThemeBuilderBeforeV44 =
    populateThemeBuilder;

populateThemeBuilder =
    function(
        modal,
        theme
    ) {
        populateThemeBuilderBeforeV44(
            modal,
            theme
        );

        const distribution =
            modal.querySelector(
                '.theme-builder-svg-distribution'
            );

        const manualOption =
            distribution?.querySelector(
                'option[value="manual-fixed"]'
            );

        if (manualOption) {
            manualOption.textContent =
                'Manual scatter · fixed positions';
        }

        bindTrueManualDragV44(
            modal
        );

        ensureReliableDashboardPreviewV44(
            modal
        );

        bindPreviewNavigationV44(
            modal
        );
    };

const updateThemeBuilderPreviewBeforeV44 =
    updateThemeBuilderPreview;

updateThemeBuilderPreview =
    function(
        modal
    ) {
        updateThemeBuilderPreviewBeforeV44(
            modal
        );

        bindTrueManualDragV44(
            modal
        );

        syncManualDragModeV44(
            modal
        );

        ensureReliableDashboardPreviewV44(
            modal
        );

        if (
            modal
                ?._dashboardPreviewActiveV40
        ) {
            showReliableDashboardPreviewV44(
                modal
            );
        }
    };



// ============================================================
// V45 — CURSOR / TRUE MANUAL DRAG / @ POPUP / DASHBOARD PREVIEW
// CREATE VS CREATE & APPLY TEXT ACTIONS
// ============================================================


// ------------------------------------------------------------
// CUSTOM CURSOR: keep tracking through Theme Builder event guards.
// V13 intentionally stops bubbling mousemove/pointermove events inside the
// editor, so cursor tracking must run in the capture phase.
// ------------------------------------------------------------

trackCustomCursor =
    function(
        el
    ) {
        stopTrackingCustomCursor();

        customCursorMoveHandler =
            event => {
                if (!el) {
                    return;
                }

                el.style.transform =
                    `translate3d(${event.clientX}px, ${event.clientY}px, 0)`;
            };

        window.addEventListener(
            'pointermove',
            customCursorMoveHandler,
            true
        );

        window.addEventListener(
            'mousemove',
            customCursorMoveHandler,
            true
        );
    };

stopTrackingCustomCursor =
    function() {
        if (
            customCursorMoveHandler
        ) {
            // Remove both the historical bubbling listener and V45 capture
            // listeners so switching cursors never stacks handlers.
            document.removeEventListener(
                'mousemove',
                customCursorMoveHandler
            );

            window.removeEventListener(
                'pointermove',
                customCursorMoveHandler,
                true
            );

            window.removeEventListener(
                'mousemove',
                customCursorMoveHandler,
                true
            );

            customCursorMoveHandler =
                null;
        }
    };

const syncThemeBuilderOpenStateBeforeCursorV45 =
    syncThemeBuilderOpenStateV13;

syncThemeBuilderOpenStateV13 =
    function(
        modal
    ) {
        syncThemeBuilderOpenStateBeforeCursorV45(
            modal
        );

        const open =
            !!modal &&
            !modal.classList.contains(
                'hidden'
            );

        if (open) {
            requestAnimationFrame(
                () => {
                    applyCursorChoice?.();

                    const visual =
                        document.getElementById(
                            'custom-cursor-visual'
                        );

                    if (visual) {
                        visual.style.setProperty(
                            'z-index',
                            '2147483647',
                            'important'
                        );

                        visual.style.setProperty(
                            'pointer-events',
                            'none',
                            'important'
                        );
                    }
                }
            );
        }
    };


// ------------------------------------------------------------
// @ DAY: use the same interaction model as the backslash link popup.
// Pressing @ immediately opens a searchable popup and moves focus there.
// ------------------------------------------------------------

let daySlashRangeV45 =
    null;

let dayPopupSelectedV45 =
    0;

function ensureNotesDayPopupV45() {
    let popup =
        document.getElementById(
            'notes-day-popup-v45'
        );

    if (popup) {
        return popup;
    }

    popup =
        document.createElement(
            'div'
        );

    popup.id =
        'notes-day-popup-v45';

    popup.className =
        'notes-day-popup-v45 hidden';

    popup.innerHTML = `
        <div class="notes-day-popup-search-v45">
            <i class="ph ph-magnifying-glass"></i>
            <input
                type="search"
                id="notes-day-search-input-v45"
                placeholder="Search Day 1, Day 2…"
                autocomplete="off"
            >
        </div>

        <div class="notes-day-popup-results-v45"></div>
    `;

    const linkPopup =
        document.getElementById(
            'notes-link-popup'
        );

    if (linkPopup) {
        linkPopup.insertAdjacentElement(
            'afterend',
            popup
        );
    } else {
        document
            .getElementById(
                'log-notes'
            )
            ?.insertAdjacentElement(
                'afterend',
                popup
            );
    }

    const input =
        popup.querySelector(
            '#notes-day-search-input-v45'
        );

    input.addEventListener(
        'input',
        () => {
            dayPopupSelectedV45 =
                0;

            renderNotesDayPopupV45();
        }
    );

    input.addEventListener(
        'keydown',
        event => {
            const choices =
                Array.from(
                    popup.querySelectorAll(
                        '[data-day-choice-v45]'
                    )
                );

            if (
                event.key ===
                'ArrowDown'
            ) {
                event.preventDefault();

                if (
                    choices.length
                ) {
                    dayPopupSelectedV45 =
                        (
                            dayPopupSelectedV45 +
                            1
                        ) %
                        choices.length;

                    renderNotesDayPopupV45();
                }

                return;
            }

            if (
                event.key ===
                'ArrowUp'
            ) {
                event.preventDefault();

                if (
                    choices.length
                ) {
                    dayPopupSelectedV45 =
                        (
                            dayPopupSelectedV45 -
                            1 +
                            choices.length
                        ) %
                        choices.length;

                    renderNotesDayPopupV45();
                }

                return;
            }

            if (
                event.key ===
                'Enter'
            ) {
                event.preventDefault();

                const choice =
                    popup.querySelectorAll(
                        '[data-day-choice-v45]'
                    )[
                        dayPopupSelectedV45
                    ];

                if (choice) {
                    insertNotesDayChoiceV45(
                        Number(
                            choice.dataset
                                .dayChoiceV45
                        )
                    );
                }

                return;
            }

            if (
                event.key ===
                'Escape'
            ) {
                event.preventDefault();

                closeNotesDayPopupV45();

                document
                    .getElementById(
                        'log-notes'
                    )
                    ?.focus();
            }
        }
    );

    popup.addEventListener(
        'pointerdown',
        event => {
            const choice =
                event.target.closest(
                    '[data-day-choice-v45]'
                );

            if (!choice) {
                return;
            }

            event.preventDefault();

            insertNotesDayChoiceV45(
                Number(
                    choice.dataset
                        .dayChoiceV45
                )
            );
        }
    );

    return popup;
}

function notesDayChoicesV45(
    query
) {
    const saved =
        Object.keys(
            db.days ||
            {}
        )
            .map(
                Number
            )
            .filter(
                day =>
                    Number.isFinite(
                        day
                    ) &&
                    day >=
                        1
            );

    const maxDay =
        Math.max(
            Number(
                typeof TOTAL_CURRICULUM_DAYS !==
                    'undefined'
                    ? TOTAL_CURRICULUM_DAYS
                    : 0
            ) ||
                0,
            ...saved,
            Number(
                currentDay
            ) ||
                0,
            1
        );

    const normalized =
        String(
            query ||
            ''
        )
            .trim()
            .toLowerCase()
            .replace(
                /^@/,
                ''
            )
            .replace(
                /^day\s*/,
                ''
            );

    let days =
        Array.from(
            {
                length:
                    maxDay
            },
            (
                _,
                index
            ) =>
                index +
                1
        );

    if (
        normalized
    ) {
        days =
            days.filter(
                day =>
                    `day ${day}`
                        .includes(
                            normalized
                        ) ||
                    String(
                        day
                    ).startsWith(
                        normalized
                    )
            );
    }

    return days.slice(
        0,
        24
    );
}

function renderNotesDayPopupV45() {
    const popup =
        ensureNotesDayPopupV45();

    const input =
        popup.querySelector(
            '#notes-day-search-input-v45'
        );

    const results =
        popup.querySelector(
            '.notes-day-popup-results-v45'
        );

    const days =
        notesDayChoicesV45(
            input.value
        );

    if (
        dayPopupSelectedV45 >=
        days.length
    ) {
        dayPopupSelectedV45 =
            Math.max(
                0,
                days.length -
                    1
            );
    }

    results.innerHTML =
        days.length
            ? days.map(
                (
                    day,
                    index
                ) => `
                    <button
                        type="button"
                        data-day-choice-v45="${day}"
                        class="${index === dayPopupSelectedV45 ? 'selected' : ''}"
                    >
                        <i class="ph ph-calendar-blank"></i>
                        <span>Day ${day}</span>
                    </button>
                `
            ).join('')
            : `
                <div class="notes-day-popup-empty-v45">
                    No matching day.
                </div>
            `;
}

function openNotesDayPopupV45(
    range
) {
    daySlashRangeV45 =
        range;

    dayPopupSelectedV45 =
        0;

    closeDayMentionMenuV44?.();

    const popup =
        ensureNotesDayPopupV45();

    const input =
        popup.querySelector(
            '#notes-day-search-input-v45'
        );

    input.value =
        '';

    renderNotesDayPopupV45();

    popup.classList.remove(
        'hidden'
    );

    requestAnimationFrame(
        () =>
            input.focus()
    );
}

function closeNotesDayPopupV45() {
    document
        .getElementById(
            'notes-day-popup-v45'
        )
        ?.classList.add(
            'hidden'
        );

    daySlashRangeV45 =
        null;
}

function insertNotesDayChoiceV45(
    day
) {
    if (
        !daySlashRangeV45 ||
        !Number.isFinite(
            Number(
                day
            )
        )
    ) {
        return;
    }

    const range =
        daySlashRangeV45
            .cloneRange();

    const link =
        makeDayLinkV41(
            Number(
                day
            ),
            `@Day ${Number(
                day
            )}`
        );

    range.insertNode(
        link
    );

    const space =
        document.createTextNode(
            '\u00A0'
        );

    link.after(
        space
    );

    const selection =
        window.getSelection();

    const caret =
        document.createRange();

    caret.setStartAfter(
        space
    );

    caret.collapse(
        true
    );

    selection.removeAllRanges();

    selection.addRange(
        caret
    );

    closeNotesDayPopupV45();

    const notes =
        document.getElementById(
            'log-notes'
        );

    if (
        currentDay &&
        notes
    ) {
        db.days[currentDay]
            .notes =
            notes.innerHTML;

        scheduleSaveDay();
    }

    notes?.focus();
}

function bindSlashStyleDayPopupV45() {
    const notes =
        document.getElementById(
            'log-notes'
        );

    if (
        !notes ||
        notes.dataset
            .dayPopupV45 ===
            'true'
    ) {
        return;
    }

    notes.dataset
        .dayPopupV45 =
        'true';

    notes.addEventListener(
        'keydown',
        event => {
            if (
                event.key !==
                '@'
            ) {
                return;
            }

            const selection =
                window.getSelection();

            if (
                !selection ||
                !selection.rangeCount
            ) {
                return;
            }

            const range =
                selection.getRangeAt(
                    0
                );

            if (
                !range.collapsed ||
                !notes.contains(
                    range.startContainer
                )
            ) {
                return;
            }

            event.preventDefault();
            event.stopImmediatePropagation();

            openNotesDayPopupV45(
                range.cloneRange()
            );
        },
        true
    );
}

bindSlashStyleDayPopupV45();

const openDayLogBeforePopupV45 =
    openDayLog;

openDayLog =
    function(
        dayNumber
    ) {
        closeNotesDayPopupV45();

        const result =
            openDayLogBeforePopupV45(
                dayNumber
            );

        requestAnimationFrame(
            bindSlashStyleDayPopupV45
        );

        return result;
    };


