// ============================================================
// V47 — INDEPENDENT NEW THEMES / CURRENT CUSTOM THEME SELECTION
// DASHBOARD PLACEMENT PARITY
// ============================================================


// ------------------------------------------------------------
// Save the actual preview positions with every Theme Builder draft.
// Dashboard can then use the same coordinate set instead of its older,
// separate fallback distribution.
// ------------------------------------------------------------

const getThemeBuilderDraftBeforePlacementSnapshotV47 =
    getThemeBuilderDraft;

getThemeBuilderDraft =
    function(
        modal
    ) {
        const draft =
            getThemeBuilderDraftBeforePlacementSnapshotV47(
                modal
            );

        try {
            const assignments =
                getPreviewSvgAssignmentsV10(
                    modal,
                    draft
                );

            if (
                Array.isArray(
                    assignments
                ) &&
                assignments.length
            ) {
                draft.dashboardPlacementSlotsV47 =
                    assignments.map(
                        assignment => ({
                            x:
                                Number(
                                    assignment.left
                                ) ||
                                50,
                            y:
                                Number(
                                    assignment.top
                                ) ||
                                50
                        })
                    );
            }
        } catch {}

        return draft;
    };


// ------------------------------------------------------------
// Opening Theme Settings always centers/selects the ACTUAL current theme,
// including copied/shared/custom theme IDs.
// ------------------------------------------------------------

const openGlobalThemeSettingsBeforeCurrentCustomV47 =
    openGlobalThemeSettings;

openGlobalThemeSettings =
    function() {
        const current =
            db.settings
                ?.theme ||
            'default';

        // Shared Dashboard-created themes may need to be imported into this
        // log before the select/gallery can recognize their IDs.
        syncSharedThemesIntoLogV40?.();

        syncThemeCopyOptionsV30?.();

        if (
            dailyThemeSelect
        ) {
            dailyThemeSelect.value =
                current;

            // If this exact shared/custom ID has not yet been represented,
            // create its option before rendering.
            if (
                dailyThemeSelect.value !==
                    current &&
                getThemeCopyV30?.(
                    current
                )
            ) {
                syncThemeCopyOptionsV30?.();

                dailyThemeSelect.value =
                    current;
            }
        }

        themePickerSelected =
            current;

        openGlobalThemeSettingsBeforeCurrentCustomV47();

        requestAnimationFrame(
            () => {
                syncSharedThemesIntoLogV40?.();
                syncThemeCopyOptionsV30?.();

                if (
                    dailyThemeSelect
                ) {
                    dailyThemeSelect.value =
                        current;
                }

                themePickerSelected =
                    current;

                renderThemePicker();

                themePickerSelected =
                    current;

                updateThemePickerSelection();

                filterThemePicker(
                    ''
                );

                const card =
                    themePicker
                        ?.querySelector(
                            `.theme-picker-card[data-theme="${CSS.escape(
                                current
                            )}"]`
                        );

                card?.classList.add(
                    'selected'
                );

                card?.scrollIntoView({
                    block:
                        'center',
                    behavior:
                        'instant'
                });
            }
        );
    };


// ------------------------------------------------------------
// A NEW theme is always a unique Theme Copy.
// It never overwrites db.settings.customTheme or the theme currently active.
// ------------------------------------------------------------

async function createIndependentThemeV47(
    modal,
    applyAfterCreate =
        false
) {
    if (
        !modal ||
        !validateThemeBuilderBeforeSaveV25(
            modal
        )
    ) {
        return;
    }

    ensureChosenThemeAccessoriesEnabledV46?.(
        modal
    );

    const oldThemeId =
        db.settings
            ?.theme ||
        'default';

    const draft =
        getThemeBuilderDraft(
            modal
        );

    const id =
        makeThemeCopyIdV30();

    const name =
        String(
            draft.name ||
            'Custom Theme'
        ).trim() ||
        'Custom Theme';

    const themeData =
        cloneThemeDataV30({
            ...FEATURE_SUITE_DEFAULT_THEME,
            ...CUSTOM_THEME_MEDIA_DEFAULTS_V3,
            ...CUSTOM_THEME_VISUAL_DEFAULTS_V4,
            ...CUSTOM_THEME_ACCESSORY_DEFAULTS_V32,
            ...draft,
            name
        });

    const copy = {
        id,
        name,
        sourceThemeId:
            '',
        theme:
            themeData,
        createdAt:
            new Date()
                .toISOString()
    };

    ensureThemeCopiesV30()
        .push(
            copy
        );

    // Publish this SAME ID to the cross-dashboard theme library. This avoids
    // the old custom-theme + imported-shared-copy duplication.
    publishSharedThemeV40?.({
        id,
        name,
        theme:
            themeData,
        sourceThemeId:
            ''
    });

    await saveDb();

    syncThemeCopyOptionsV30();

    if (
        applyAfterCreate
    ) {
        window._forceThemeAccessoriesOnceV32 =
            true;

        primeThemeAudioV41?.(
            themeData
        );

        await applyTheme(
            id,
            {
                persist:
                    true
            }
        );

        if (
            dailyThemeSelect
        ) {
            dailyThemeSelect.value =
                id;
        }

        themePickerSelected =
            id;
    } else {
        // Creating without applying must leave the active theme entirely alone.
        db.settings.theme =
            oldThemeId;

        if (
            dailyThemeSelect
        ) {
            dailyThemeSelect.value =
                oldThemeId;
        }

        themePickerSelected =
            oldThemeId;

        await saveDb();
    }

    renderThemePicker();

    modal.classList.add(
        'hidden'
    );

    dailySettingsModal
        ?.classList.add(
            'hidden'
        );

    showFeatureToast(
        applyAfterCreate
            ? `Created and applied “${name}”.`
            : `Created “${name}”.`
    );
}

function installIndependentCreateButtonsV47(
    modal
) {
    if (
        !modal ||
        isDashboardThemeStudioV43?.() ||
        modal.dataset
            .themeBuilderMode !==
            'create'
    ) {
        return;
    }

    const save =
        modal.querySelector(
            '.theme-builder-save'
        );

    if (!save) {
        return;
    }

    let apply =
        modal.querySelector(
            '.theme-builder-create-apply-v45'
        );

    save.textContent =
        'Create';

    save.onclick =
        () =>
            createIndependentThemeV47(
                modal,
                false
            );

    if (!apply) {
        apply =
            document.createElement(
                'button'
            );

        apply.type =
            'button';

        apply.className =
            'icon-btn custom-tab-primary-btn theme-builder-create-apply-v45';

        save.insertAdjacentElement(
            'afterend',
            apply
        );
    }

    apply.textContent =
        'Create & Apply';

    apply.onclick =
        () =>
            createIndependentThemeV47(
                modal,
                true
            );
}


// Dashboard Theme Studio creation uses one shared object as well.
// Do not also manufacture a second host-log custom theme/copy.
const saveDashboardThemeStudioBeforeNoDuplicateV47 =
    saveDashboardThemeStudioV43;

saveDashboardThemeStudioV43 =
    async function(
        modal,
        applyAfterSave
    ) {
        if (
            !modal ||
            !validateThemeBuilderBeforeSaveV25(
                modal
            )
        ) {
            return;
        }

        ensureChosenThemeAccessoriesEnabledV46?.(
            modal
        );

        const draft =
            getThemeBuilderDraft(
                modal
            );

        const requestedId =
            getDashboardThemeStudioIdV43();

        const action =
            getDashboardThemeStudioActionV43();

        const library =
            readSharedThemeLibraryForStudioV43();

        const existing =
            library.find(
                item =>
                    item.id ===
                    requestedId
            );

        let id =
            action ===
                'edit' &&
            existing?.id
                ? existing.id
                : makeDashboardStudioThemeIdV43();

        const name =
            String(
                draft.name ||
                existing?.name ||
                'Custom Theme'
            ).trim() ||
            'Custom Theme';

        const entry = {
            id,
            name,
            sourceThemeId:
                existing
                    ?.sourceThemeId ||
                '',
            theme:
                cloneThemeDataV30({
                    ...draft,
                    name
                }),
            updatedAt:
                new Date()
                    .toISOString()
        };

        saveSharedThemeFromStudioV43(
            entry
        );

        window.parent
            ?.postMessage(
                {
                    type:
                        'dashboard-theme-studio-saved-v43',
                    themeId:
                        id,
                    apply:
                        !!applyAfterSave
                },
                window.location.origin
            );
    };


