async function saveBuiltInThemeOnlyV49(
    modal
) {
    if (
        !validateThemeBuilderBeforeSaveV25(
            modal
        )
    ) {
        return;
    }

    ensureChosenThemeAccessoriesEnabledV46?.(
        modal
    );

    const themeId =
        modal.dataset
            .themeBuilderEditingThemeV25;

    if (
        !themeId ||
        themeId ===
            'theme-custom-builder'
    ) {
        return;
    }

    const previousTheme =
        modal
            ._themeEditPreviousThemeV25 ||
        db.settings.theme ||
        'default';

    const draft =
        getThemeBuilderDraft(
            modal
        );

    ensureThemeOverridesV25()[
        themeId
    ] = {
        ...draft
    };

    // Save the edit without changing which theme is active.
    db.settings.theme =
        previousTheme;

    await saveDb();

    modal._themeEditSavedV25 =
        true;

    themeOverrideApplySuppressedV25 =
        false;

    // Restore the theme that was active before entering the editor.
    // If that same theme was being edited, this naturally refreshes it
    // with the newly saved override without switching themes.
    await applyTheme(
        previousTheme,
        {
            persist:
                false
        }
    );

    db.settings.theme =
        previousTheme;

    if (dailyThemeSelect) {
        dailyThemeSelect.value =
            previousTheme;
    }

    themePickerSelected =
        previousTheme;

    renderThemePicker();

    closeThemeBuilderAfterSaveOnlyV49(
        modal
    );

    showFeatureToast(
        `Saved “${draft.name || 'theme'}”.`
    );
}

function writeThemeCopyDraftV49(
    modal,
    copy
) {
    const draft =
        getThemeBuilderDraft(
            modal
        );

    copy.name =
        draft.name ||
        copy.name ||
        'Theme Copy';

    copy.theme =
        cloneThemeDataV30(
            draft
        );

    if (
        modal.dataset
            .themeBuilderBuiltInSourceV30
    ) {
        if (
            !modal
                ._builtInArtDirtyV30
        ) {
            copy.theme
                .backgroundSvgs =
                [];

            copy.theme
                .replaceBuiltInDecorationsV30 =
                false;
        } else {
            copy.theme
                .replaceBuiltInDecorationsV30 =
                true;

            copy.theme
                .backgroundSvgs =
                (
                    copy.theme
                        .backgroundSvgs ||
                    []
                ).map(
                    svg => {
                        const clean = {
                            ...svg
                        };

                        delete clean
                            .inheritedBuiltInV30;

                        return clean;
                    }
                );
        }

        if (
            !modal
                ._builtInAudioDirtyV30 &&
            copy.theme
                .introAudio ===
                modal
                    ._builtInInheritedAudioV30
        ) {
            copy.theme
                .introAudio =
                '';

            copy.theme
                .introAudioName =
                '';
        }
    }

    return draft;
}

async function saveThemeCopyOnlyV49(
    modal,
    copyId
) {
    if (
        !validateThemeBuilderBeforeSaveV25(
            modal
        )
    ) {
        return;
    }

    ensureChosenThemeAccessoriesEnabledV46?.(
        modal
    );

    const copy =
        getThemeCopyV30(
            copyId
        );

    if (!copy) {
        return;
    }

    const previousTheme =
        modal
            ._themeEditPreviousThemeV25 ||
        db.settings.theme ||
        'default';

    writeThemeCopyDraftV49(
        modal,
        copy
    );

    publishSharedThemeV40?.({
        id:
            copy.id,
        name:
            copy.name,
        theme:
            copy.theme,
        sourceThemeId:
            copy.sourceThemeId ||
            ''
    });

    db.settings.theme =
        previousTheme;

    await saveDb();

    syncThemeCopyOptionsV30();

    await applyTheme(
        previousTheme,
        {
            persist:
                false
        }
    );

    db.settings.theme =
        previousTheme;

    if (dailyThemeSelect) {
        dailyThemeSelect.value =
            previousTheme;
    }

    themePickerSelected =
        previousTheme;

    renderThemePicker();

    closeThemeBuilderAfterSaveOnlyV49(
        modal
    );

    showFeatureToast(
        `Saved “${copy.name}”.`
    );
}

async function saveLegacyCustomThemeOnlyV49(
    modal
) {
    if (
        !validateThemeBuilderBeforeSaveV25(
            modal
        )
    ) {
        return;
    }

    ensureChosenThemeAccessoriesEnabledV46?.(
        modal
    );

    const previousTheme =
        modal
            ._themeEditPreviousThemeV49 ||
        db.settings.theme ||
        'default';

    const draft =
        getThemeBuilderDraft(
            modal
        );

    const start =
        Math.max(
            0,
            Math.min(
                20,
                Number(
                    draft.audioStart
                ) ||
                0
            )
        );

    const end =
        Math.max(
            start +
                .5,
            Math.min(
                20,
                Number(
                    draft.audioEnd
                ) ||
                20
            )
        );

    draft.audioStart =
        start;

    draft.audioEnd =
        end;

    db.settings.customTheme = {
        ...FEATURE_SUITE_DEFAULT_THEME,
        ...CUSTOM_THEME_MEDIA_DEFAULTS_V3,
        ...CUSTOM_THEME_VISUAL_DEFAULTS_V4,
        ...CUSTOM_THEME_ACCESSORY_DEFAULTS_V32,
        ...draft
    };

    db.settings.customThemeDeleted =
        false;

    db.settings.deletedThemes =
        (
            db.settings.deletedThemes ||
            []
        ).filter(
            value =>
                value !==
                'theme-custom-builder'
        );

    ensureCustomThemePickerOption();

    db.settings.theme =
        previousTheme;

    await saveDb();

    publishCurrentLogThemesV40?.();

    if (dailyThemeSelect) {
        dailyThemeSelect.value =
            previousTheme;
    }

    themePickerSelected =
        previousTheme;

    renderThemePicker();

    closeThemeBuilderAfterSaveOnlyV49(
        modal
    );

    showFeatureToast(
        `Saved “${draft.name || 'Custom Theme'}”.`
    );
}

function installLogEditSaveButtonsV49(
    modal
) {
    if (
        !isLogThemeBuilderEditV49(
            modal
        )
    ) {
        return;
    }

    const actions =
        modal.querySelector(
            '.theme-builder-actions'
        );

    const primary =
        modal.querySelector(
            '.theme-builder-save'
        );

    if (
        !actions ||
        !primary
    ) {
        return;
    }

    // Create-mode controls must never leak into edit mode.
    actions
        .querySelectorAll(
            '.theme-builder-create-apply-v45'
        )
        .forEach(
            button =>
                button.remove()
        );

    const editingThemeId =
        modal.dataset
            .themeBuilderEditingThemeV25 ||
        '';

    const editingCopyId =
        modal.dataset
            .themeBuilderEditingCopyV30 ||
        '';

    const editingLegacyCustom =
        modal.dataset
            .themeBuilderMode ===
        'edit-custom-theme-v49';

    // Preserve the authoritative existing edit handler as Save & Apply.
    if (
        !modal
            ._saveAndApplyHandlerV49
    ) {
        modal._saveAndApplyHandlerV49 =
            primary.onclick;
    }

    primary.textContent =
        'Save';

    primary.onclick =
        () => {
            if (editingCopyId) {
                return saveThemeCopyOnlyV49(
                    modal,
                    editingCopyId
                );
            }

            if (editingThemeId) {
                return saveBuiltInThemeOnlyV49(
                    modal
                );
            }

            if (editingLegacyCustom) {
                return saveLegacyCustomThemeOnlyV49(
                    modal
                );
            }
        };

    let apply =
        actions.querySelector(
            '.theme-builder-save-apply-v49'
        );

    if (!apply) {
        apply =
            document.createElement(
                'button'
            );

        apply.type =
            'button';

        apply.className =
            'icon-btn custom-tab-primary-btn theme-builder-save-apply-v49';

        primary.insertAdjacentElement(
            'afterend',
            apply
        );
    }

    apply.textContent =
        'Save & Apply';

    apply.onclick =
        async () => {
            ensureChosenThemeAccessoriesEnabledV46?.(
                modal
            );

            window._forceThemeAccessoriesOnceV32 =
                true;

            const handler =
                modal
                    ._saveAndApplyHandlerV49;

            if (handler) {
                return handler.call(
                    primary
                );
            }

            // Safety fallback if an older wrapper replaced the handler.
            if (editingCopyId) {
                return saveThemeCopyV30(
                    modal,
                    editingCopyId
                );
            }

            if (editingThemeId) {
                return saveThemeOverrideV25(
                    modal
                );
            }
        };
}


// ------------------------------------------------------------
// Make every log-page edit opener finish with the V49 action pair.
// ------------------------------------------------------------

const openAnyThemeInBuilderBeforeSavePairV49 =
    openAnyThemeInBuilderV25;

openAnyThemeInBuilderV25 =
    async function(
        themeId,
        themeName
    ) {
        await openAnyThemeInBuilderBeforeSavePairV49(
            themeId,
            themeName
        );

        const modal =
            document.getElementById(
                'theme-builder-modal'
            );

        if (
            modal &&
            !isDashboardThemeStudioV43?.()
        ) {
            // Capture whatever the full wrapper chain assigned as the
            // built-in Save & Apply behavior.
            modal._saveAndApplyHandlerV49 =
                modal.querySelector(
                    '.theme-builder-save'
                )?.onclick ||
                null;

            installLogEditSaveButtonsV49(
                modal
            );
        }
    };

const openThemeCopyInBuilderBeforeSavePairV49 =
    openThemeCopyInBuilderV30;

openThemeCopyInBuilderV30 =
    async function(
        copyId
    ) {
        const previousTheme =
            db.settings.theme ||
            'default';

        await openThemeCopyInBuilderBeforeSavePairV49(
            copyId
        );

        const modal =
            document.getElementById(
                'theme-builder-modal'
            );

        if (
            modal &&
            !isDashboardThemeStudioV43?.()
        ) {
            modal._themeEditPreviousThemeV25 =
                previousTheme;

            modal.dataset
                .themeBuilderMode =
                'edit-copy-v49';

            modal._saveAndApplyHandlerV49 =
                modal.querySelector(
                    '.theme-builder-save'
                )?.onclick ||
                null;

            installLogEditSaveButtonsV49(
                modal
            );
        }
    };

const openExistingCustomThemeBeforeSavePairV49 =
    openExistingCustomThemeFromPickerV7;

openExistingCustomThemeFromPickerV7 =
    function() {
        const previousTheme =
            db.settings.theme ||
            'default';

        openExistingCustomThemeBeforeSavePairV49();

        const modal =
            document.getElementById(
                'theme-builder-modal'
            );

        if (
            !modal ||
            isDashboardThemeStudioV43?.()
        ) {
            return;
        }

        modal._themeEditPreviousThemeV49 =
            previousTheme;

        modal.dataset
            .themeBuilderMode =
            'edit-custom-theme-v49';

        modal._saveAndApplyHandlerV49 =
            modal.querySelector(
                '.theme-builder-save'
            )?.onclick ||
            null;

        installLogEditSaveButtonsV49(
            modal
        );
    };


// Final populate hook catches edit-mode re-population from later wrappers.
const populateThemeBuilderBeforeSavePairV49 =
    populateThemeBuilder;

populateThemeBuilder =
    function(
        modal,
        theme
    ) {
        populateThemeBuilderBeforeSavePairV49(
            modal,
            theme
        );

        if (
            isLogThemeBuilderEditV49(
                modal
            )
        ) {
            requestAnimationFrame(
                () =>
                    installLogEditSaveButtonsV49(
                        modal
                    )
            );
        }
    };



// ============================================================
// V51 — STABLE DASHBOARD COLOR PICKERS
// Do not destroy/recreate dashboard color inputs while the native color
// picker is open. Replacing the <input type="color"> on every input event
// was what made the picker close as soon as the mouse was pressed/dragged.
// ============================================================

function stableDashboardThemeControlsV51(
    modal,
    theme = {}
) {
    const controls =
        modal?.querySelector(
            '.theme-builder-controls'
        );

    if (!controls) {
        return;
    }

    let section =
        controls.querySelector(
            '.theme-builder-dashboard-colors-v42'
        );

    const fields = [
        [
            'Dashboard Background',
            'dashboardBackgroundV40',
            theme.dashboardBackgroundV40 ||
                theme.background ||
                '#f5f5f5'
        ],
        [
            'Log Cards',
            'dashboardCardV40',
            theme.dashboardCardV40 ||
                theme.surface ||
                '#ffffff'
        ],
        [
            'Dashboard Text',
            'dashboardTextV40',
            theme.dashboardTextV40 ||
                theme.text ||
                '#000000'
        ],
        [
            'Buttons / Accent',
            'dashboardAccentV40',
            theme.dashboardAccentV40 ||
                theme.accent ||
                '#777777'
        ]
    ];

    if (!section) {
        // Remove only obsolete pre-V42 dashboard color sections once.
        controls
            .querySelectorAll(
                '.theme-builder-dashboard-colors-v40:not(.theme-builder-dashboard-colors-v42)'
            )
            .forEach(
                old =>
                    old.remove()
            );

        section =
            document.createElement(
                'section'
            );

        section.className =
            'theme-builder-control-section theme-builder-dashboard-colors-v40 theme-builder-dashboard-colors-v42';

        section.dataset
            .themeBuilderPanelGroup =
            'colors';

        section.innerHTML = `
            <div class="theme-builder-control-heading">
                <strong>Dashboard Colors</strong>
                <small>Dashboard-specific colors.</small>
            </div>

            <div class="theme-builder-color-grid theme-builder-dashboard-color-grid-v42">
                ${fields.map(
                    (
                        [
                            label,
                            key,
                            value
                        ]
                    ) =>
                        themeBuilderField(
                            label,
                            key,
                            value
                        )
                ).join('')}
            </div>
        `;

        const tabs =
            controls.querySelector(
                '.theme-builder-section-tabs-v11'
            );

        const firstNonColor =
            Array.from(
                controls.children
            ).find(
                child =>
                    child !==
                        tabs &&
                    child.dataset
                        ?.themeBuilderPanelGroup &&
                    child.dataset
                        .themeBuilderPanelGroup !==
                        'colors'
            );

        if (firstNonColor) {
            controls.insertBefore(
                section,
                firstNonColor
            );
        } else {
            controls.appendChild(
                section
            );
        }

        section
            .querySelectorAll(
                'input[type="color"][data-theme-key]'
            )
            .forEach(
                picker => {
                    picker.addEventListener(
                        'pointerdown',
                        () => {
                            modal._dashboardColorPickerOpenV51 =
                                true;
                        },
                        true
                    );

                    picker.addEventListener(
                        'input',
                        () => {
                            const key =
                                picker.dataset
                                    .themeKey;

                            const hex =
                                section.querySelector(
                                    `[data-theme-hex="${CSS.escape(
                                        key
                                    )}"]`
                                );

                            if (hex) {
                                hex.value =
                                    picker.value;
                            }

                            // Update the live preview without replacing this
                            // color input node.
                            updateThemeBuilderPreview(
                                modal
                            );
                        }
                    );

                    const finish =
                        () => {
                            setTimeout(
                                () => {
                                    modal._dashboardColorPickerOpenV51 =
                                        false;
                                },
                                0
                            );
                        };

                    picker.addEventListener(
                        'change',
                        finish
                    );

                    picker.addEventListener(
                        'blur',
                        finish
                    );
                }
            );

        section
            .querySelectorAll(
                '[data-theme-hex]'
            )
            .forEach(
                input => {
                    input.addEventListener(
                        'input',
                        () => {
                            const value =
                                input.value
                                    .trim();

                            if (
                                !/^#[0-9a-f]{6}$/i.test(
                                    value
                                )
                            ) {
                                return;
                            }

                            const picker =
                                section.querySelector(
                                    `input[type="color"][data-theme-key="${CSS.escape(
                                        input.dataset
                                            .themeHex
                                    )}"]`
                                );

                            if (picker) {
                                picker.value =
                                    value;
                            }

                            updateThemeBuilderPreview(
                                modal
                            );
                        }
                    );
                }
            );

        installThemeBuilderSectionTabsV11(
            modal
        );
    }

    // Reuse the SAME controls. Only sync their values while a native color
    // picker is not actively being dragged/open.
    if (
        !modal._dashboardColorPickerOpenV51
    ) {
        fields.forEach(
            (
                [
                    ,
                    key,
                    value
                ]
            ) => {
                const color =
                    /^#[0-9a-f]{6}$/i.test(
                        String(
                            value
                        )
                    )
                        ? String(
                            value
                        )
                        : '#777777';

                const picker =
                    section.querySelector(
                        `input[type="color"][data-theme-key="${CSS.escape(
                            key
                        )}"]`
                    );

                const hex =
                    section.querySelector(
                        `[data-theme-hex="${CSS.escape(
                            key
                        )}"]`
                    );

                if (
                    picker &&
                    document.activeElement !==
                        picker
                ) {
                    picker.value =
                        color;
                }

                if (
                    hex &&
                    document.activeElement !==
                        hex
                ) {
                    hex.value =
                        color;
                }
            }
        );
    }

    return section;
}

// Older V40/V42 update paths call both names. Make both point to the stable,
// non-destructive implementation.
ensureDashboardThemeControlsV42 =
    stableDashboardThemeControlsV51;

ensureDashboardThemeControlsV40 =
    stableDashboardThemeControlsV51;



// ============================================================
// V52 — REORDERABLE LOG-SPECIFIC SIDE NAV + OPTIONAL BUILT-IN TABS
// Everything below the divider beneath Trash can be dragged above/below
// another log-specific tab. Toolbox and Weekly Review can be removed.
// ============================================================

const LOG_NAV_BUILTINS_V52 = {
    daily: {
        buttonId: 'open-daily-logs-nav-btn',
        label: 'Daily Logs'
    },
    tools: {
        buttonId: 'open-tools-btn',
        label: 'Toolbox'
    },
    knowledge: {
        buttonId: 'open-phrases-btn',
        label: 'Knowledge Base'
    },
    quizzes: {
        buttonId: 'open-quizzes-btn',
        label: 'Quizzes'
    },
    'weekly-review': {
        buttonId: 'open-weekly-review-btn',
        label: 'Weekly Review'
    }
};

const LOG_NAV_DEFAULT_ORDER_V52 = [
    'daily',
    'tools',
    'knowledge',
    'quizzes',
    'weekly-review'
];

function ensureLogNavSettingsV52() {
    if (!db.settings) {
        db.settings = {};
    }

    if (
        !Array.isArray(
            db.settings.logNavOrderV52
        )
    ) {
        db.settings.logNavOrderV52 =
            [];
    }

    if (
        !Array.isArray(
            db.settings.hiddenBuiltInTabsV52
        )
    ) {
        db.settings.hiddenBuiltInTabsV52 =
            [];
    }

    return db.settings;
}

function isBuiltInTabHiddenV52(
    key
) {
    ensureLogNavSettingsV52();

    return db.settings
        .hiddenBuiltInTabsV52
        .includes(
            key
        );
}

function navKeyForElementV52(
    element
) {
    if (!element) {
        return '';
    }

    const customId =
        element.dataset
            ?.customTabId;

    if (customId) {
        return `custom:${customId}`;
    }

    const entry =
        Object.entries(
            LOG_NAV_BUILTINS_V52
        ).find(
            (
                [
                    ,
                    config
                ]
            ) =>
                config.buttonId ===
                element.id
        );

    return entry
        ? entry[0]
        : '';
}

function elementForLogNavKeyV52(
    key
) {
    if (
        String(
            key
        ).startsWith(
            'custom:'
        )
    ) {
        const id =
            String(
                key
            ).slice(
                'custom:'.length
            );

        return document.querySelector(
            `.custom-tab-nav-btn[data-custom-tab-id="${CSS.escape(
                id
            )}"]`
        );
    }

    const config =
        LOG_NAV_BUILTINS_V52[
            key
        ];

    return config
        ? document.getElementById(
            config.buttonId
        )
        : null;
}

function currentAvailableLogNavKeysV52() {
    const customKeys =
        getCustomTabs()
            .map(
                tab =>
                    `custom:${tab.id}`
            );

    return [
        ...LOG_NAV_DEFAULT_ORDER_V52,
        ...customKeys
    ];
}

function normalizedLogNavOrderV52() {
    const settings =
        ensureLogNavSettingsV52();

    const available =
        currentAvailableLogNavKeysV52();

    const availableSet =
        new Set(
            available
        );

    const saved =
        settings
            .logNavOrderV52
            .filter(
                key =>
                    availableSet.has(
                        key
                    )
            );

    available.forEach(
        key => {
            if (
                !saved.includes(
                    key
                )
            ) {
                saved.push(
                    key
                );
            }
        }
    );

    settings.logNavOrderV52 =
        saved;

    return saved;
}

function ensureUnifiedLogNavHostV52() {
    const scrollRegion =
        document.getElementById(
            'side-nav-log-scroll'
        );

    if (!scrollRegion) {
        return null;
    }

    let host =
        document.getElementById(
            'log-tab-order-host-v52'
        );

    if (!host) {
        host =
            document.createElement(
                'div'
            );

        host.id =
            'log-tab-order-host-v52';

        host.className =
            'log-tab-order-host-v52';

        scrollRegion.prepend(
            host
        );
    }

    return host;
}

function updateUnifiedLogNavScrollV52() {
    const scrollRegion =
        document.getElementById(
            'side-nav-log-scroll'
        );

    const host =
        document.getElementById(
            'log-tab-order-host-v52'
        );

    if (
        !scrollRegion ||
        !host
    ) {
        return;
    }

    const visibleButtons =
        Array.from(
            host.querySelectorAll(
                ':scope > .icon-btn:not(.log-nav-hidden-v52)'
            )
        );

    // Preserve the old behavior: normal sets do not scroll; a larger list does.
    const shouldScroll =
        visibleButtons.length >
        8;

    scrollRegion.classList.toggle(
        'is-scrollable',
        shouldScroll
    );

    if (!shouldScroll) {
        scrollRegion.style.removeProperty(
            '--log-nav-scroll-height'
        );

        return;
    }

    const eighth =
        visibleButtons[
            7
        ];

    if (!eighth) {
        return;
    }

    const hostStyle =
        getComputedStyle(
            host
        );

    const gap =
        parseFloat(
            hostStyle.rowGap ||
            hostStyle.gap ||
            '25'
        ) ||
        25;

    const height =
        Math.max(
            100,
            eighth.offsetTop +
            eighth.offsetHeight -
            gap / 2
        );

    scrollRegion.style.setProperty(
        '--log-nav-scroll-height',
        `${Math.ceil(
            height
        )}px`
    );
}

function saveLogNavOrderFromDomV52() {
    const host =
        document.getElementById(
            'log-tab-order-host-v52'
        );

    if (!host) {
        return;
    }

    const keys =
        Array.from(
            host.children
        )
            .map(
                navKeyForElementV52
            )
            .filter(
                Boolean
            );

    ensureLogNavSettingsV52()
        .logNavOrderV52 =
        keys;

    saveDb();
}

function clearLogNavDragUiV52() {
    document
        .querySelectorAll(
            '.log-nav-dragging-v52, .log-nav-drop-before-v52, .log-nav-drop-after-v52'
        )
        .forEach(
            element => {
                element.classList.remove(
                    'log-nav-dragging-v52',
                    'log-nav-drop-before-v52',
                    'log-nav-drop-after-v52'
                );
            }
        );
}

function bindUnifiedLogNavDragV52(
    button,
    key
) {
    if (
        !button ||
        button.dataset
            .unifiedNavDragV52 ===
            'true'
    ) {
        return;
    }

    button.dataset
        .unifiedNavDragV52 =
        'true';

    button.dataset
        .logNavKeyV52 =
        key;

    button.draggable =
        true;

    button.addEventListener(
        'dragstart',
        event => {
            event.dataTransfer
                .setData(
                    'text/log-nav-key-v52',
                    key
                );

            event.dataTransfer
                .setData(
                    'text/plain',
                    key
                );

            event.dataTransfer.effectAllowed =
                'move';

            button.classList.add(
                'log-nav-dragging-v52'
            );
        }
    );

    button.addEventListener(
        'dragend',
        clearLogNavDragUiV52
    );

    button.addEventListener(
        'dragover',
        event => {
            const draggedKey =
                event.dataTransfer
                    .getData(
                        'text/log-nav-key-v52'
                    ) ||
                event.dataTransfer
                    .getData(
                        'text/plain'
                    );

            if (
                !draggedKey ||
                draggedKey ===
                    key
            ) {
                return;
            }

            event.preventDefault();

            const rect =
                button.getBoundingClientRect();

            const after =
                event.clientY >
                rect.top +
                    rect.height /
                        2;

            button.classList.toggle(
                'log-nav-drop-before-v52',
                !after
            );

            button.classList.toggle(
                'log-nav-drop-after-v52',
                after
            );
        }
    );

    button.addEventListener(
        'dragleave',
        () => {
            button.classList.remove(
                'log-nav-drop-before-v52',
                'log-nav-drop-after-v52'
            );
        }
    );

    button.addEventListener(
        'drop',
        event => {
            const draggedKey =
                event.dataTransfer
                    .getData(
                        'text/log-nav-key-v52'
                    ) ||
                event.dataTransfer
                    .getData(
                        'text/plain'
                    );

            if (
                !draggedKey ||
                draggedKey ===
                    key
            ) {
                return;
            }

            event.preventDefault();
            event.stopPropagation();

            const dragged =
                elementForLogNavKeyV52(
                    draggedKey
                );

            const host =
                document.getElementById(
                    'log-tab-order-host-v52'
                );

            if (
                !dragged ||
                !host ||
                button.parentElement !==
                    host
            ) {
                clearLogNavDragUiV52();

                return;
            }

            const rect =
                button.getBoundingClientRect();

            const after =
                event.clientY >
                rect.top +
                    rect.height /
                        2;

            if (after) {
                button.after(
                    dragged
                );
            } else {
                button.before(
                    dragged
                );
            }

            clearLogNavDragUiV52();

            saveLogNavOrderFromDomV52();

            updateUnifiedLogNavScrollV52();
        }
    );
}

async function deleteBuiltInLogTabV52(
    key
) {
    if (
        ![
            'tools',
            'weekly-review'
        ].includes(
            key
        )
    ) {
        return;
    }

    const config =
        LOG_NAV_BUILTINS_V52[
            key
        ];

    const confirmed =
        await showAppConfirm({
            title:
                `Delete ${config.label} tab?`,
            message:
                '',
            confirmLabel:
                'Delete Tab'
        });

    if (!confirmed) {
        return;
    }

    const settings =
        ensureLogNavSettingsV52();

    if (
        !settings
            .hiddenBuiltInTabsV52
            .includes(
                key
            )
    ) {
        settings
            .hiddenBuiltInTabsV52
            .push(
                key
            );
    }

    await saveDb();

    const button =
        document.getElementById(
            config.buttonId
        );

    button?.classList.add(
        'log-nav-hidden-v52'
    );

    // If the removed tab was open, return to Daily Logs.
    if (
        (
            key ===
                'tools' &&
            toolboxView
                ?.classList
                .contains(
                    'active'
                )
        ) ||
        (
            key ===
                'weekly-review' &&
            document
                .getElementById(
                    'weekly-review-view'
                )
                ?.classList
                .contains(
                    'active'
                )
        )
    ) {
        initGrid();

        switchView(
            gridView
        );
    }

    updateUnifiedLogNavScrollV52();

    showFeatureToast(
        `${config.label} tab deleted.`,
        'Undo',
        () =>
            restoreBuiltInLogTabV52(
                key
            )
    );
}

function restoreBuiltInLogTabV52(
    key
) {
    const settings =
        ensureLogNavSettingsV52();

    settings.hiddenBuiltInTabsV52 =
        settings
            .hiddenBuiltInTabsV52
            .filter(
                item =>
                    item !==
                    key
            );

    saveDb();

    if (
        key ===
        'weekly-review'
    ) {
        ensureWeeklyReviewNavButton?.(
            document.getElementById(
                'side-nav-log-scroll'
            )
        );
    }

    applyUnifiedLogNavOrderV52();
}

function bindBuiltInTabDeleteV52(
    button,
    key
) {
    if (
        !button ||
        ![
            'tools',
            'weekly-review'
        ].includes(
            key
        ) ||
        button.dataset
            .builtInDeleteV52 ===
            'true'
    ) {
        return;
    }

    button.dataset
        .builtInDeleteV52 =
        'true';

    button.addEventListener(
        'contextmenu',
        event => {
            event.preventDefault();
            event.stopPropagation();

            const config =
                LOG_NAV_BUILTINS_V52[
                    key
                ];

            showCustomItemContextMenu(
                event.clientX,
                event.clientY,
                [
                    {
                        label:
                            `Delete ${config.label} tab`,
                        icon:
                            'ph-trash',
                        danger:
                            true,
                        action:
                            () =>
                                deleteBuiltInLogTabV52(
                                    key
                                )
                    }
                ]
            );
        }
    );
}

function applyUnifiedLogNavOrderV52() {
    const host =
        ensureUnifiedLogNavHostV52();

    if (!host) {
        return;
    }

    const customFactoryHost =
        document.getElementById(
            'custom-tab-nav-host'
        );

    const pinnedFactoryHost =
        document.getElementById(
            'custom-tab-pinned-host'
        );

    // Custom-tab renderers still create buttons inside their historical hosts.
    // Pull each button into the new shared ordered list after every render.
    [
        customFactoryHost,
        pinnedFactoryHost
    ].forEach(
        factory => {
            Array.from(
                factory?.querySelectorAll(
                    ':scope > .custom-tab-nav-btn'
                ) ||
                []
            ).forEach(
                button =>
                    host.appendChild(
                        button
                    )
            );
        }
    );

    Object.entries(
        LOG_NAV_BUILTINS_V52
    ).forEach(
        (
            [
                key,
                config
            ]
        ) => {
            const button =
                document.getElementById(
                    config.buttonId
                );

            if (
                button &&
                button.parentElement !==
                    host
            ) {
                host.appendChild(
                    button
                );
            }

            if (button) {
                button.classList.toggle(
                    'log-nav-hidden-v52',
                    isBuiltInTabHiddenV52(
                        key
                    )
                );

                bindUnifiedLogNavDragV52(
                    button,
                    key
                );

                bindBuiltInTabDeleteV52(
                    button,
                    key
                );
            }
        }
    );

    getCustomTabs()
        .forEach(
            tab => {
                const key =
                    `custom:${tab.id}`;

                const button =
                    document.querySelector(
                        `.custom-tab-nav-btn[data-custom-tab-id="${CSS.escape(
                            String(
                                tab.id
                            )
                        )}"]`
                    );

                if (!button) {
                    return;
                }

                if (
                    button.parentElement !==
                    host
                ) {
                    host.appendChild(
                        button
                    );
                }

                bindUnifiedLogNavDragV52(
                    button,
                    key
                );
            }
        );

    const order =
        normalizedLogNavOrderV52();

    order.forEach(
        key => {
            const element =
                elementForLogNavKeyV52(
                    key
                );

            if (
                element &&
                element.parentElement ===
                    host
            ) {
                host.appendChild(
                    element
                );
            }
        }
    );

    // The old grouping hosts are now only factories used by existing renderers.
    customFactoryHost
        ?.classList.add(
            'log-nav-factory-host-v52'
        );

    pinnedFactoryHost
        ?.classList.add(
            'log-nav-factory-host-v52'
        );

    updateUnifiedLogNavScrollV52();
}

// Keep the user's order after all existing nav render wrappers complete.
const renderCustomTabNavigationBeforeUnifiedV52 =
    renderCustomTabNavigation;

renderCustomTabNavigation =
    function() {
        renderCustomTabNavigationBeforeUnifiedV52();

        requestAnimationFrame(
            applyUnifiedLogNavOrderV52
        );
    };

const ensureCustomSideNavControlsBeforeUnifiedV52 =
    ensureCustomSideNavControls;

ensureCustomSideNavControls =
    function() {
        ensureCustomSideNavControlsBeforeUnifiedV52();

        requestAnimationFrame(
            applyUnifiedLogNavOrderV52
        );
    };

const ensureWeeklyReviewNavButtonBeforeUnifiedV52 =
    ensureWeeklyReviewNavButton;

ensureWeeklyReviewNavButton =
    function(
        ...args
    ) {
        const button =
            ensureWeeklyReviewNavButtonBeforeUnifiedV52(
                ...args
            );

        if (button) {
            button.classList.toggle(
                'log-nav-hidden-v52',
                isBuiltInTabHiddenV52(
                    'weekly-review'
                )
            );
        }

        requestAnimationFrame(
            applyUnifiedLogNavOrderV52
        );

        return button;
    };

// The old custom-only scroll counter no longer sees buttons after we flatten
// the nav, so make the shared ordered host authoritative.
const updateLogSpecificSideNavScrollStateBeforeUnifiedV52 =
    updateLogSpecificSideNavScrollState;

updateLogSpecificSideNavScrollState =
    function() {
        if (
            document.getElementById(
                'log-tab-order-host-v52'
            )
        ) {
            updateUnifiedLogNavScrollV52();

            return;
        }

        updateLogSpecificSideNavScrollStateBeforeUnifiedV52();
    };

// Do not reopen a built-in page from session state after its nav tab was deleted.
const restoreLastTopLevelViewBeforeHiddenBuiltInsV52 =
    restoreLastTopLevelView;

restoreLastTopLevelView =
    function() {
        const saved =
            sessionStorage.getItem(
                LAST_APP_TAB_STORAGE_KEY
            );

        if (
            (
                saved ===
                    'tools' &&
                isBuiltInTabHiddenV52(
                    'tools'
                )
            ) ||
            (
                saved ===
                    'weekly-review' &&
                isBuiltInTabHiddenV52(
                    'weekly-review'
                )
            )
        ) {
            sessionStorage.setItem(
                LAST_APP_TAB_STORAGE_KEY,
                'daily'
            );

            initGrid();

            switchView(
                gridView
            );

            return;
        }

        restoreLastTopLevelViewBeforeHiddenBuiltInsV52();
    };

requestAnimationFrame(
    () => {
        applyUnifiedLogNavOrderV52();

        setTimeout(
            applyUnifiedLogNavOrderV52,
            80
        );
    }
);



