function renderWeeklyReviewTemplateV53(
    tab,
    component,
    content
) {
    const {
        start,
        end
    } =
        getWeeklyReviewRange();

    const dayNumbers =
        Array.from(
            {
                length:
                    end -
                    start +
                    1
            },
            (
                _,
                index
            ) =>
                start +
                index
        );

    const loggedDays =
        dayNumbers.filter(
            day =>
                featureDayHasContent(
                    db.days?.[
                        day
                    ]
                )
        ).length;

    let noteWords =
        0;

    let mediaCount =
        0;

    const knowledge =
        new Set();

    dayNumbers.forEach(
        day => {
            const data =
                db.days?.[
                    day
                ] ||
                {};

            const noteText =
                featureStripHtml(
                    data.notes ||
                    ''
                );

            if (
                noteText
            ) {
                noteWords +=
                    noteText
                        .split(
                            /\s+/
                        )
                        .filter(
                            Boolean
                        ).length;
            }

            mediaCount +=
                (
                    data.resources ||
                    []
                ).length;

            mediaCount +=
                (
                    data.noteImages ||
                    []
                ).length;

            mediaCount +=
                (
                    data.noteAudios ||
                    []
                ).length;

            mediaCount +=
                data.video
                    ? 1
                    : 0;

            mediaCount +=
                data.video2
                    ? 1
                    : 0;

            collectPdfValuesFromDay(
                data
            ).forEach(
                () =>
                    mediaCount +=
                        1
            );

            (
                data.phrases ||
                []
            ).forEach(
                item =>
                    knowledge.add(
                        item
                    )
            );
        }
    );

    const customDone =
        getWeeklyCustomCompletionCount(
            start,
            end
        );

    const key =
        `${start}-${end}`;

    if (
        !component.focusByRange ||
        typeof component
            .focusByRange !==
            'object'
    ) {
        component.focusByRange =
            {};
    }

    content.innerHTML = `
        <div class="custom-collection-header weekly-review-template-heading-v53">
            <div>
                <h2>${escapeCustomHtml(
                    component.title ||
                    'Weekly Review'
                )}</h2>
                <span class="weekly-review-eyebrow">
                    ${escapeCustomHtml(
                        `${formatDate(
                            start
                        )} — ${formatDate(
                            end
                        )}`
                    )}
                </span>
            </div>
        </div>

        <div class="weekly-review-stats weekly-review-stats-template-v53">
            <article>
                <i class="ph ph-calendar-check"></i>
                <strong>${loggedDays}/${dayNumbers.length}</strong>
                <span>Days logged</span>
            </article>

            <article>
                <i class="ph ph-text-aa"></i>
                <strong>${noteWords}</strong>
                <span>Note words</span>
            </article>

            <article>
                <i class="ph ph-images"></i>
                <strong>${mediaCount}</strong>
                <span>Media</span>
            </article>

            <article>
                <i class="ph ph-books"></i>
                <strong>${knowledge.size}</strong>
                <span>Learned</span>
            </article>

            <article>
                <i class="ph ph-check-circle"></i>
                <strong>${customDone}</strong>
                <span>Completed</span>
            </article>
        </div>

        <section class="weekly-review-section weekly-review-template-section-v53">
            <div class="section-header">
                <h3>Your Week</h3>
            </div>

            <div class="weekly-review-days"></div>
        </section>

        <section class="weekly-review-section weekly-review-template-section-v53">
            <div class="section-header">
                <h3>Focus for next week</h3>
                <span class="weekly-review-saved"></span>
            </div>

            <textarea
                class="weekly-review-focus"
                rows="4"
                placeholder="What do you want to focus on next week?"
            ></textarea>
        </section>
    `;

    const daysHost =
        content.querySelector(
            '.weekly-review-days'
        );

    dayNumbers
        .slice()
        .reverse()
        .forEach(
            day => {
                const data =
                    db.days?.[
                        day
                    ] ||
                    {};

                const notes =
                    featureStripHtml(
                        data.notes ||
                        ''
                    );

                const resources =
                    (
                        data.resources ||
                        []
                    ).length +
                    (
                        data.noteImages ||
                        []
                    ).length +
                    (
                        data.noteAudios ||
                        []
                    ).length +
                    (
                        data.video
                            ? 1
                            : 0
                    ) +
                    (
                        data.video2
                            ? 1
                            : 0
                    );

                const learned =
                    (
                        data.phrases ||
                        []
                    ).length;

                const card =
                    document.createElement(
                        'button'
                    );

                card.type =
                    'button';

                card.className =
                    `weekly-review-day${
                        featureDayHasContent(
                            data
                        )
                            ? ''
                            : ' empty'
                    }`;

                card.innerHTML = `
                    <span class="weekly-review-day-number">
                        Day ${day}
                    </span>

                    <strong>
                        ${escapeCustomHtml(
                            formatDate(
                                day
                            )
                        )}
                    </strong>

                    <span>
                        ${
                            notes
                                ? `${notes
                                    .split(
                                        /\s+/
                                    )
                                    .filter(
                                        Boolean
                                    ).length} note words`
                                : 'No notes'
                        }
                        · ${resources} media/resource${resources === 1 ? '' : 's'}
                        · ${learned} learned
                    </span>

                    <i class="ph ph-arrow-right"></i>
                `;

                card.addEventListener(
                    'click',
                    () =>
                        openDayLog(
                            day
                        )
                );

                daysHost.appendChild(
                    card
                );
            }
        );

    const textarea =
        content.querySelector(
            '.weekly-review-focus'
        );

    const saved =
        content.querySelector(
            '.weekly-review-saved'
        );

    textarea.value =
        component
            .focusByRange[
                key
            ] ||
        '';

    textarea.addEventListener(
        'input',
        () => {
            component
                .focusByRange[
                    key
                ] =
                textarea.value;

            clearTimeout(
                textarea
                    ._weeklyTemplateSaveV53
            );

            textarea
                ._weeklyTemplateSaveV53 =
                setTimeout(
                    () => {
                        saveDb();

                        saved.textContent =
                            'Saved ✓';

                        setTimeout(
                            () => {
                                saved.textContent =
                                    '';
                            },
                            1100
                        );
                    },
                    400
                );
        }
    );
}


// ------------------------------------------------------------
// SENTENCE BUILDER FROM KNOWLEDGE BASE
// ------------------------------------------------------------

function sentenceBuilderItemsV53(
    query =
        ''
) {
    const normalized =
        String(
            query ||
            ''
        )
            .trim()
            .toLowerCase();

    return (
        db.phrases ||
        []
    )
        .filter(
            phrase => {
                if (
                    !normalized
                ) {
                    return true;
                }

                const meta =
                    db.phrase_meta?.[
                        phrase
                    ] ||
                    {};

                const customText =
                    Object.values(
                        meta.custom_fields ||
                        {}
                    )
                        .map(
                            value =>
                                String(
                                    value ||
                                    ''
                                )
                        )
                        .join(
                            ' '
                        );

                return `${phrase} ${meta.type || ''} ${customText}`
                    .toLowerCase()
                    .includes(
                        normalized
                    );
            }
        )
        .slice(
            0,
            120
        );
}

function sentenceBuilderTextV53(
    tokens
) {
    return (
        tokens ||
        []
    )
        .map(
            token =>
                String(
                    token ||
                    ''
                ).trim()
        )
        .filter(
            Boolean
        )
        .join(
            ' '
        )
        .replace(
            /\s+([,.!?;:])/g,
            '$1'
        );
}

function renderKnowledgeSentenceBuilderV53(
    tab,
    component,
    content
) {
    if (
        !Array.isArray(
            component.tokens
        )
    ) {
        component.tokens =
            [];
    }

    if (
        !Array.isArray(
            component.savedSentences
        )
    ) {
        component.savedSentences =
            [];
    }

    content.innerHTML = `
        <div class="custom-collection-header">
            <div>
                <h2>${escapeCustomHtml(
                    component.title ||
                    'Sentence Builder'
                )}</h2>

                <small class="sentence-builder-source-v53">
                    Uses items from this log's Knowledge Base
                </small>
            </div>
        </div>

        <div class="sentence-builder-current-v53">
            <div class="sentence-builder-current-line-v53"></div>

            <div class="sentence-builder-actions-v53">
                <button
                    type="button"
                    class="small-icon-btn sentence-builder-clear-v53"
                    title="Clear sentence"
                >
                    <i class="ph ph-eraser"></i>
                </button>

                <button
                    type="button"
                    class="icon-btn sentence-builder-save-v53"
                >
                    Save Sentence
                </button>
            </div>
        </div>

        <div class="sentence-builder-search-v53">
            <i class="ph ph-magnifying-glass"></i>
            <input
                type="text"
                placeholder="Search Knowledge Base…"
                aria-label="Search Knowledge Base"
            >
        </div>

        <div class="sentence-builder-bank-v53"></div>

        <div class="sentence-builder-saved-wrap-v53">
            <div class="custom-collection-header">
                <h3>Saved Sentences</h3>
            </div>

            <div class="sentence-builder-saved-v53"></div>
        </div>
    `;

    const current =
        content.querySelector(
            '.sentence-builder-current-line-v53'
        );

    const bank =
        content.querySelector(
            '.sentence-builder-bank-v53'
        );

    const savedHost =
        content.querySelector(
            '.sentence-builder-saved-v53'
        );

    const search =
        content.querySelector(
            '.sentence-builder-search-v53 input'
        );

    const renderCurrent =
        () => {
            current.innerHTML =
                component.tokens.length
                    ? component.tokens
                        .map(
                            (
                                token,
                                index
                            ) => `
                                <button
                                    type="button"
                                    class="sentence-builder-token-v53"
                                    data-token-index-v53="${index}"
                                    title="Remove this chunk"
                                >
                                    ${escapeCustomHtml(
                                        token
                                    )}
                                    <i class="ph ph-x"></i>
                                </button>
                            `
                        )
                        .join('')
                    : `
                        <span class="sentence-builder-empty-v53">
                            Click Knowledge Base items below to build a sentence.
                        </span>
                    `;

            current
                .querySelectorAll(
                    '[data-token-index-v53]'
                )
                .forEach(
                    button => {
                        button.addEventListener(
                            'click',
                            () => {
                                component.tokens.splice(
                                    Number(
                                        button.dataset
                                            .tokenIndexV53
                                    ),
                                    1
                                );

                                saveDb();

                                renderCurrent();
                            }
                        );
                    }
                );
        };

    const renderBank =
        () => {
            const items =
                sentenceBuilderItemsV53(
                    search.value
                );

            bank.innerHTML =
                items.length
                    ? items.map(
                        phrase => {
                            const meta =
                                db.phrase_meta?.[
                                    phrase
                                ] ||
                                {};

                            return `
                                <button
                                    type="button"
                                    class="sentence-builder-bank-item-v53"
                                    data-phrase-v53="${escapeCustomHtml(
                                        phrase
                                    )}"
                                >
                                    <span>${escapeCustomHtml(
                                        phrase
                                    )}</span>
                                    ${
                                        meta.type
                                            ? `<small>${escapeCustomHtml(
                                                meta.type
                                            )}</small>`
                                            : ''
                                    }
                                </button>
                            `;
                        }
                    ).join('')
                    : `
                        <div class="feature-empty-state sentence-builder-no-items-v53">
                            <i class="ph ph-books"></i>
                            <strong>No matching Knowledge Base items</strong>
                            <span>Add items to Knowledge Base, then they will appear here automatically.</span>
                        </div>
                    `;

            bank
                .querySelectorAll(
                    '[data-phrase-v53]'
                )
                .forEach(
                    button => {
                        button.addEventListener(
                            'click',
                            () => {
                                component.tokens.push(
                                    button.dataset
                                        .phraseV53
                                );

                                saveDb();

                                renderCurrent();
                            }
                        );
                    }
                );
        };

    const renderSaved =
        () => {
            savedHost.innerHTML =
                component
                    .savedSentences
                    .length
                    ? component
                        .savedSentences
                        .map(
                            item => `
                                <article
                                    class="sentence-builder-saved-item-v53"
                                    data-saved-sentence-v53="${escapeCustomHtml(
                                        item.id
                                    )}"
                                >
                                    <button
                                        type="button"
                                        class="sentence-builder-use-saved-v53"
                                        title="Load this sentence"
                                    >
                                        ${escapeCustomHtml(
                                            item.text
                                        )}
                                    </button>

                                    <button
                                        type="button"
                                        class="small-icon-btn sentence-builder-remove-saved-v53"
                                        title="Remove saved sentence"
                                    >
                                        <i class="ph ph-x"></i>
                                    </button>
                                </article>
                            `
                        )
                        .join('')
                    : `
                        <div class="sentence-builder-empty-saved-v53">
                            Saved sentences will appear here.
                        </div>
                    `;

            savedHost
                .querySelectorAll(
                    '[data-saved-sentence-v53]'
                )
                .forEach(
                    row => {
                        const id =
                            row.dataset
                                .savedSentenceV53;

                        const item =
                            component
                                .savedSentences
                                .find(
                                    entry =>
                                        entry.id ===
                                        id
                                );

                        row
                            .querySelector(
                                '.sentence-builder-use-saved-v53'
                            )
                            ?.addEventListener(
                                'click',
                                () => {
                                    component.tokens =
                                        [
                                            item?.text ||
                                            ''
                                        ].filter(
                                            Boolean
                                        );

                                    saveDb();

                                    renderCurrent();
                                }
                            );

                        row
                            .querySelector(
                                '.sentence-builder-remove-saved-v53'
                            )
                            ?.addEventListener(
                                'click',
                                () => {
                                    component.savedSentences =
                                        component
                                            .savedSentences
                                            .filter(
                                                entry =>
                                                    entry.id !==
                                                    id
                                            );

                                    saveDb();

                                    renderSaved();
                                }
                            );
                    }
                );
        };

    content
        .querySelector(
            '.sentence-builder-clear-v53'
        )
        .addEventListener(
            'click',
            () => {
                component.tokens =
                    [];

                saveDb();

                renderCurrent();
            }
        );

    content
        .querySelector(
            '.sentence-builder-save-v53'
        )
        .addEventListener(
            'click',
            () => {
                const text =
                    sentenceBuilderTextV53(
                        component.tokens
                    );

                if (!text) {
                    showFeatureToast(
                        'Build a sentence first.'
                    );

                    return;
                }

                component
                    .savedSentences
                    .unshift({
                        id:
                            customId(
                                'sentence'
                            ),
                        text,
                        createdAt:
                            new Date()
                                .toISOString()
                    });

                saveDb();

                renderSaved();
            }
        );

    search.addEventListener(
        'input',
        renderBank
    );

    renderCurrent();
    renderBank();
    renderSaved();
}


