function renderPrebuiltTabCardsV53(
    section
) {
    const grid =
        section.querySelector(
            '.custom-tab-template-grid-v53'
        );

    if (!grid) {
        return;
    }

    grid.innerHTML =
        CUSTOM_TAB_TEMPLATES_V53
            .map(
                template => `
                    <button
                        type="button"
                        class="custom-tab-template-card-v53"
                        data-custom-tab-template-v53="${template.id}"
                    >
                        <span class="custom-tab-template-icon-v53">
                            <i class="ph ${template.icon}"></i>
                        </span>

                        <span class="custom-tab-template-copy-v53">
                            <strong>${escapeCustomHtml(
                                template.name
                            )}</strong>
                            <small>${escapeCustomHtml(
                                template.description
                            )}</small>
                        </span>

                        <i class="ph ph-check-circle custom-tab-template-check-v53"></i>
                    </button>
                `
            )
            .join('');
}

function selectTemplateIconV53(
    modal,
    icon
) {
    const picker =
        modal.querySelector(
            '#custom-tab-icon-picker'
        );

    if (!picker) {
        return;
    }

    const choices =
        Array.from(
            picker.querySelectorAll(
                '.custom-tab-icon-choice'
            )
        );

    choices.forEach(
        choice =>
            choice.classList.remove(
                'selected'
            )
    );

    const match =
        choices.find(
            choice =>
                choice.dataset
                    .icon ===
                icon
        );

    (
        match ||
        choices[0]
    )
        ?.classList.add(
            'selected'
        );
}

function ensurePrebuiltTabSectionV53() {
    const modal =
        document.getElementById(
            'custom-tab-create-modal'
        );

    if (!modal) {
        return null;
    }

    let section =
        modal.querySelector(
            '.custom-tab-template-section-v53'
        );

    if (!section) {
        section =
            document.createElement(
                'div'
            );

        section.className =
            'modal-section custom-tab-template-section-v53';

        section.innerHTML = `
            <span class="field-label">
                Or start with a pre-built tab
            </span>

            <p class="custom-tab-create-hint">
                Pick one to create a ready-made page. You can still edit, reorder, add, or remove its sections afterward.
            </p>

            <div class="custom-tab-template-grid-v53"></div>
        `;

        const daily =
            modal.querySelector(
                '.custom-tab-daily-source-section'
            );

        if (daily) {
            daily.insertAdjacentElement(
                'afterend',
                section
            );
        } else {
            modal
                .querySelector(
                    '#custom-tab-create-confirm'
                )
                ?.insertAdjacentElement(
                    'beforebegin',
                    section
                );
        }

        renderPrebuiltTabCardsV53(
            section
        );

        section.addEventListener(
            'click',
            event => {
                const card =
                    event.target.closest(
                        '[data-custom-tab-template-v53]'
                    );

                if (!card) {
                    return;
                }

                const id =
                    card.dataset
                        .customTabTemplateV53;

                const wasSelected =
                    card.classList
                        .contains(
                            'selected'
                        );

                section
                    .querySelectorAll(
                        '.custom-tab-template-card-v53'
                    )
                    .forEach(
                        item =>
                            item.classList.remove(
                                'selected'
                            )
                    );

                modal.dataset
                    .selectedTemplateV53 =
                    wasSelected
                        ? ''
                        : id;

                if (
                    wasSelected
                ) {
                    return;
                }

                card.classList.add(
                    'selected'
                );

                const template =
                    customTemplateV53(
                        id
                    );

                if (!template) {
                    return;
                }

                const nameInput =
                    modal.querySelector(
                        '#custom-tab-name-input'
                    );

                const previousTemplateName =
                    modal.dataset
                        .lastTemplateNameV53 ||
                    '';

                if (
                    nameInput &&
                    (
                        !nameInput.value
                            .trim() ||
                        nameInput.value ===
                            previousTemplateName
                    )
                ) {
                    nameInput.value =
                        template.name;
                }

                modal.dataset
                    .lastTemplateNameV53 =
                    template.name;

                selectTemplateIconV53(
                    modal,
                    template.icon
                );
            }
        );
    }

    return section;
}

function patchCustomTabCreateButtonV53() {
    const modal =
        document.getElementById(
            'custom-tab-create-modal'
        );

    const old =
        modal?.querySelector(
            '#custom-tab-create-confirm'
        );

    if (
        !old ||
        old.dataset
            .prebuiltPatchedV53 ===
            'true'
    ) {
        return;
    }

    const button =
        old.cloneNode(
            true
        );

    button.dataset
        .prebuiltPatchedV53 =
        'true';

    old.replaceWith(
        button
    );

    button.addEventListener(
        'click',
        createCustomTabFromModalV53
    );
}

function createCustomTabFromModalV53() {
    const modal =
        document.getElementById(
            'custom-tab-create-modal'
        );

    const input =
        modal?.querySelector(
            '#custom-tab-name-input'
        );

    if (
        !modal ||
        !input
    ) {
        return;
    }

    const templateId =
        modal.dataset
            .selectedTemplateV53 ||
        '';

    const template =
        customTemplateV53(
            templateId
        );

    const name =
        input.value
            .trim() ||
        template?.name ||
        'My Tab';

    const icon =
        modal
            .querySelector(
                '.custom-tab-icon-choice.selected'
            )
            ?.dataset.icon ||
        template?.icon ||
        'ph-squares-four';

    const chosenDailySources =
        Array.from(
            modal.querySelectorAll(
                '.custom-tab-daily-source-grid input[type="checkbox"]:checked'
            )
        ).map(
            input =>
                input.value
        );

    const tab = {
        id:
            customId(
                'tab'
            ),
        name,
        icon,
        templateIdV53:
            templateId ||
            '',
        components:
            template
                ? buildPrebuiltTabComponentsV53(
                    template.id
                )
                : []
    };

    if (
        chosenDailySources.length
    ) {
        const existingCollection =
            tab.components.find(
                component =>
                    component.type ===
                    'dailyLogCollection'
            );

        if (
            existingCollection
        ) {
            existingCollection.sources =
                Array.from(
                    new Set([
                        ...(
                            existingCollection.sources ||
                            []
                        ),
                        ...chosenDailySources
                    ])
                );
        } else {
            tab.components.push({
                ...defaultCustomComponent(
                    'dailyLogCollection'
                ),
                sources:
                    chosenDailySources
            });
        }
    }

    if (
        modal
            .querySelector(
                '#custom-tab-add-connections-map'
            )
            ?.checked &&
        !tab.components.some(
            component =>
                component.type ===
                'dailyConnectionsGraph'
        )
    ) {
        tab.components.push({
            id:
                customId(
                    'component'
                ),
            type:
                'dailyConnectionsGraph',
            title:
                'Daily Log Connections',
            titleBackground:
                'none'
        });
    }

    getCustomTabs().push(
        tab
    );

    saveDb();

    closeCustomTabCreateModal();

    renderCustomTabNavigation();

    const view =
        buildCustomTabView(
            tab
        );

    document.body.insertBefore(
        view,
        document.getElementById(
            'companion-stage'
        ) ||
        null
    );

    activeCustomTabId =
        tab.id;

    customTabEditMode =
        false;

    renderCustomTabView(
        tab.id
    );

    switchView(
        view
    );
}

