// ------------------------------------------------------------
// NEW DEFAULT TAB ORDER:
// Daily Logs → Knowledge Base → Quizzes → Toolbox.
// Weekly Review remains optional through the V53 pre-built tab picker.
// ------------------------------------------------------------

const LOG_NAV_DEFAULT_ORDER_V54 = [
    'daily',
    'knowledge',
    'quizzes',
    'tools'
];

const currentAvailableLogNavKeysBeforeV54 =
    currentAvailableLogNavKeysV52;

currentAvailableLogNavKeysV52 =
    function() {
        const customKeys =
            getCustomTabs()
                .map(
                    tab =>
                        `custom:${tab.id}`
                );

        return [
            ...LOG_NAV_DEFAULT_ORDER_V54,
            ...customKeys
        ];
    };

const normalizedLogNavOrderBeforeV54 =
    normalizedLogNavOrderV52;

normalizedLogNavOrderV52 =
    function() {
        const settings =
            ensureLogNavSettingsV52();

        const rawBefore =
            Array.isArray(
                settings.logNavOrderV52
            )
                ? [
                    ...settings.logNavOrderV52
                ]
                : [];

        let order =
            normalizedLogNavOrderBeforeV54();

        if (
            !settings
                .logNavDefaultOrderV54Migrated
        ) {
            const customKeys =
                getCustomTabs()
                    .map(
                        tab =>
                            `custom:${tab.id}`
                    );

            const available =
                new Set([
                    ...LOG_NAV_DEFAULT_ORDER_V54,
                    ...customKeys
                ]);

            const oldDefault =
                [
                    'daily',
                    'tools',
                    'knowledge',
                    'quizzes',
                    ...customKeys
                ];

            const cleanedRaw =
                rawBefore
                    .filter(
                        key =>
                            key !==
                                'weekly-review' &&
                            available.has(
                                key
                            )
                    );

            const looksExactlyLikeOldDefault =
                cleanedRaw.length ===
                    oldDefault.length &&
                cleanedRaw.every(
                    (
                        key,
                        index
                    ) =>
                        key ===
                        oldDefault[
                            index
                        ]
                );

            // New logs, or logs still using the untouched old default,
            // receive the requested Toolbox-below-Quizzes order.
            if (
                !cleanedRaw.length ||
                looksExactlyLikeOldDefault
            ) {
                order = [
                    ...LOG_NAV_DEFAULT_ORDER_V54,
                    ...customKeys
                ];

                settings.logNavOrderV52 =
                    [
                        ...order
                    ];
            }

            settings
                .logNavDefaultOrderV54Migrated =
                true;

            setTimeout(
                saveDb,
                0
            );
        }

        return order;
    };


// ------------------------------------------------------------
// PRESS + DRAG REORDERING.
// Replaces browser-native HTML5 dragging with direct pointer movement.
// ------------------------------------------------------------

let logNavPointerDragV54 =
    null;

function visibleOrderedNavButtonsV54(
    host
) {
    return Array.from(
        host?.children ||
        []
    ).filter(
        element =>
            element.matches?.(
                '.icon-btn[data-log-nav-key-v52]'
            ) &&
            !element.classList
                .contains(
                    'log-nav-hidden-v52'
                )
    );
}

function clearPressDragStateV54() {
    const state =
        logNavPointerDragV54;

    if (
        state?.button
    ) {
        state.button.classList.remove(
            'log-nav-pointer-dragging-v54'
        );
    }

    document.body.classList.remove(
        'log-nav-pointer-drag-active-v54'
    );

    logNavPointerDragV54 =
        null;
}

function reorderDraggedTabAtPointerV54(
    state,
    clientY
) {
    const host =
        state.host;

    const button =
        state.button;

    if (
        !host ||
        !button
    ) {
        return;
    }

    const candidates =
        visibleOrderedNavButtonsV54(
            host
        ).filter(
            item =>
                item !==
                button
        );

    if (
        !candidates.length
    ) {
        return;
    }

    let closest =
        null;

    let closestDistance =
        Infinity;

    candidates.forEach(
        candidate => {
            const rect =
                candidate
                    .getBoundingClientRect();

            const center =
                rect.top +
                rect.height /
                    2;

            const distance =
                Math.abs(
                    clientY -
                    center
                );

            if (
                distance <
                closestDistance
            ) {
                closest =
                    candidate;

                closestDistance =
                    distance;
            }
        }
    );

    if (!closest) {
        return;
    }

    const rect =
        closest
            .getBoundingClientRect();

    const after =
        clientY >
        rect.top +
            rect.height /
                2;

    const beforeIndex =
        visibleOrderedNavButtonsV54(
            host
        ).indexOf(
            button
        );

    if (after) {
        closest.after(
            button
        );
    } else {
        closest.before(
            button
        );
    }

    const afterIndex =
        visibleOrderedNavButtonsV54(
            host
        ).indexOf(
            button
        );

    if (
        afterIndex !==
        beforeIndex
    ) {
        state.changed =
            true;
    }
}

function installPressDragTabReorderV54() {
    const host =
        document.getElementById(
            'log-tab-order-host-v52'
        );

    if (!host) {
        return;
    }

    // Disable the browser's old ghost-image drag behavior.
    visibleOrderedNavButtonsV54(
        host
    ).forEach(
        button => {
            button.draggable =
                false;

            button.setAttribute(
                'draggable',
                'false'
            );
        }
    );

    if (
        host.dataset
            .pressDragTabsV54 ===
            'true'
    ) {
        return;
    }

    host.dataset
        .pressDragTabsV54 =
        'true';

    host.addEventListener(
        'pointerdown',
        event => {
            if (
                event.button !==
                    0
            ) {
                return;
            }

            const button =
                event.target.closest(
                    '.icon-btn[data-log-nav-key-v52]'
                );

            if (
                !button ||
                button.parentElement !==
                    host ||
                button.classList
                    .contains(
                        'log-nav-hidden-v52'
                    )
            ) {
                return;
            }

            const ordered =
                visibleOrderedNavButtonsV54(
                    host
                );

            logNavPointerDragV54 = {
                host,
                button,
                pointerId:
                    event.pointerId,
                startX:
                    event.clientX,
                startY:
                    event.clientY,
                startIndex:
                    ordered.indexOf(
                        button
                    ),
                dragging:
                    false,
                changed:
                    false
            };
        },
        true
    );

    host.addEventListener(
        'click',
        event => {
            const button =
                event.target.closest(
                    '.icon-btn[data-log-nav-key-v52]'
                );

            if (
                !button ||
                button.parentElement !==
                    host
            ) {
                return;
            }

            const until =
                Number(
                    button
                        ._suppressTabClickUntilV54 ||
                    0
                );

            if (
                performance.now() <
                until
            ) {
                event.preventDefault();
                event.stopImmediatePropagation();
            }
        },
        true
    );
}

document.addEventListener(
    'pointermove',
    event => {
        const state =
            logNavPointerDragV54;

        if (
            !state ||
            event.pointerId !==
                state.pointerId
        ) {
            return;
        }

        const distance =
            Math.hypot(
                event.clientX -
                    state.startX,
                event.clientY -
                    state.startY
            );

        if (
            !state.dragging &&
            distance >=
                6
        ) {
            state.dragging =
                true;

            state.button.classList.add(
                'log-nav-pointer-dragging-v54'
            );

            document.body.classList.add(
                'log-nav-pointer-drag-active-v54'
            );
        }

        if (
            !state.dragging
        ) {
            return;
        }

        event.preventDefault();

        reorderDraggedTabAtPointerV54(
            state,
            event.clientY
        );
    },
    {
        capture:
            true,
        passive:
            false
    }
);

function finishPressDragTabsV54(
    event
) {
    const state =
        logNavPointerDragV54;

    if (
        !state ||
        event.pointerId !==
            state.pointerId
    ) {
        return;
    }

    if (
        !state.dragging
    ) {
        // No movement: do not interfere. The button's normal click handler
        // fires and opens the tab exactly like a regular click.
        clearPressDragStateV54();

        return;
    }

    event.preventDefault();
    event.stopPropagation();

    state.button
        ._suppressTabClickUntilV54 =
        performance.now() +
        450;

    const finalIndex =
        visibleOrderedNavButtonsV54(
            state.host
        ).indexOf(
            state.button
        );

    const moved =
        state.changed &&
        finalIndex !==
            state.startIndex;

    if (moved) {
        saveLogNavOrderFromDomV52();

        ensureLogNavSettingsV52()
            .logNavUserReorderedV54 =
            true;

        saveDb();
    }

    clearPressDragStateV54();

    updateUnifiedLogNavScrollV52();
}

document.addEventListener(
    'pointerup',
    finishPressDragTabsV54,
    true
);

document.addEventListener(
    'pointercancel',
    event => {
        const state =
            logNavPointerDragV54;

        if (
            !state ||
            event.pointerId !==
                state.pointerId
        ) {
            return;
        }

        clearPressDragStateV54();
    },
    true
);


// ------------------------------------------------------------
// Reinstall pointer behavior every time V52/V53 rebuilds the nav.
// ------------------------------------------------------------

const applyUnifiedLogNavOrderBeforePressDragV54 =
    applyUnifiedLogNavOrderV52;

applyUnifiedLogNavOrderV52 =
    function() {
        applyUnifiedLogNavOrderBeforePressDragV54();

        installPressDragTabReorderV54();
    };

const renderCustomTabNavigationBeforePressDragV54 =
    renderCustomTabNavigation;

renderCustomTabNavigation =
    function() {
        renderCustomTabNavigationBeforePressDragV54();

        requestAnimationFrame(
            () => {
                applyUnifiedLogNavOrderV52();

                installPressDragTabReorderV54();
            }
        );
    };

requestAnimationFrame(
    () => {
        applyUnifiedLogNavOrderV52();

        installPressDragTabReorderV54();

        setTimeout(
            () => {
                applyUnifiedLogNavOrderV52();

                installPressDragTabReorderV54();
            },
            100
        );
    }
);



// ============================================================
// V55 — TABS APPEND AT BOTTOM / CONNECTION MAP FROM @DAY
// KNOWLEDGE BASE TAGS + DROPDOWN FIELDS + PATTERN SENTENCE BUILDER
// ============================================================


// ------------------------------------------------------------
// NEW TABS ALWAYS APPEND AFTER THE LAST TAB (BEFORE +).
// ------------------------------------------------------------

function ensureNewCustomTabsAtBottomV55() {
    const settings =
        ensureLogNavSettingsV52();

    const customKeys =
        getCustomTabs()
            .map(
                tab =>
                    `custom:${tab.id}`
            );

    const validKeys =
        new Set([
            'daily',
            'knowledge',
            'quizzes',
            'tools',
            ...customKeys
        ]);

    const current =
        Array.isArray(
            settings.logNavOrderV52
        )
            ? settings.logNavOrderV52
                .filter(
                    key =>
                        validKeys.has(
                            key
                        )
                )
            : [];

    const existing =
        new Set(
            current
        );

    // A missing key is a newly-created/duplicated tab. Always put it last.
    customKeys.forEach(
        key => {
            if (
                !existing.has(
                    key
                )
            ) {
                current.push(
                    key
                );

                existing.add(
                    key
                );
            }
        }
    );

    settings.logNavOrderV52 =
        current;

    return current;
}

const normalizedLogNavOrderBeforeBottomAppendV55 =
    normalizedLogNavOrderV52;

normalizedLogNavOrderV52 =
    function() {
        normalizedLogNavOrderBeforeBottomAppendV55();

        const appended =
            ensureNewCustomTabsAtBottomV55();

        const available =
            currentAvailableLogNavKeysV52();

        available.forEach(
            key => {
                if (
                    !appended.includes(
                        key
                    )
                ) {
                    // Built-ins missing from an older saved order keep their
                    // built-in relative position; new custom tabs were already
                    // appended above.
                    const builtInOrder = [
                        'daily',
                        'knowledge',
                        'quizzes',
                        'tools'
                    ];

                    if (
                        builtInOrder.includes(
                            key
                        )
                    ) {
                        const desired =
                            builtInOrder.indexOf(
                                key
                            );

                        let insertAt =
                            appended.length;

                        for (
                            let index =
                                desired +
                                1;
                            index <
                                builtInOrder.length;
                            index++
                        ) {
                            const next =
                                appended.indexOf(
                                    builtInOrder[
                                        index
                                    ]
                                );

                            if (
                                next >=
                                0
                            ) {
                                insertAt =
                                    next;

                                break;
                            }
                        }

                        appended.splice(
                            insertAt,
                            0,
                            key
                        );
                    }
                }
            }
        );

        ensureLogNavSettingsV52()
            .logNavOrderV52 =
            appended;

        return appended;
    };


// ------------------------------------------------------------
// DAILY LOG CONNECTIONS: remove the per-day editing section.
// The optional custom-tab map now derives connections automatically from
// @Day references, while still understanding legacy saved links.
// ------------------------------------------------------------

function removeDailyConnectionsSectionV55() {
    document
        .getElementById(
            'daily-connections-section-v32'
        )
        ?.remove();
}

ensureDailyConnectionsUIV32 =
    function() {
        removeDailyConnectionsSectionV55();

        return null;
    };

renderDailyConnectionsV32 =
    function() {
        removeDailyConnectionsSectionV55();
    };

requestAnimationFrame(
    removeDailyConnectionsSectionV55
);

function extractDayMentionsV55(
    html
) {
    const source =
        String(
            html ||
            ''
        );

    const days =
        new Set();

    const patterns = [
        /data-day=["'](\d+)["']/gi,
        /@day\s*(\d+)/gi,
        /@(\d+)/g
    ];

    patterns.forEach(
        pattern => {
            let match;

            while (
                (
                    match =
                        pattern.exec(
                            source
                        )
                )
            ) {
                const day =
                    Number(
                        match[1]
                    );

                if (
                    Number.isFinite(
                        day
                    ) &&
                    day >
                        0
                ) {
                    days.add(
                        day
                    );
                }
            }
        }
    );

    return Array.from(
        days
    );
}

function getDailyConnectionMapDataV55() {
    const nodes =
        new Set();

    const edgeMap =
        new Map();

    const addEdge =
        (
            source,
            target,
            label,
            kind
        ) => {
            source =
                Number(
                    source
                );

            target =
                Number(
                    target
                );

            if (
                !Number.isFinite(
                    source
                ) ||
                !Number.isFinite(
                    target
                ) ||
                source <=
                    0 ||
                target <=
                    0 ||
                source ===
                    target
            ) {
                return;
            }

            nodes.add(
                source
            );

            nodes.add(
                target
            );

            const key =
                `${source}->${target}`;

            const existing =
                edgeMap.get(
                    key
                );

            if (existing) {
                if (
                    label &&
                    !existing.labels.includes(
                        label
                    )
                ) {
                    existing.labels.push(
                        label
                    );
                }

                if (
                    kind &&
                    !existing.kinds.includes(
                        kind
                    )
                ) {
                    existing.kinds.push(
                        kind
                    );
                }

                return;
            }

            edgeMap.set(
                key,
                {
                    source,
                    target,
                    labels:
                        label
                            ? [
                                label
                            ]
                            : [],
                    kinds:
                        kind
                            ? [
                                kind
                            ]
                            : []
                }
            );
        };

    Object.entries(
        db.days ||
        {}
    ).forEach(
        (
            [
                sourceValue,
                dayData
            ]
        ) => {
            const source =
                Number(
                    sourceValue
                );

            if (
                !Number.isFinite(
                    source
                ) ||
                source <=
                    0
            ) {
                return;
            }

            extractDayMentionsV55(
                dayData?.notes ||
                ''
            ).forEach(
                target =>
                    addEdge(
                        source,
                        target,
                        '@Day',
                        'mention'
                    )
            );

            (
                dayData
                    ?.connections ||
                []
            ).forEach(
                raw => {
                    const connection =
                        normalizeDailyConnectionV32(
                            raw
                        );

                    addEdge(
                        source,
                        connection.targetDay,
                        getDailyConnectionRelationLabelV32(
                            connection.relation
                        ),
                        'saved'
                    );
                }
            );
        }
    );

    const edges =
        Array.from(
            edgeMap.values()
        ).sort(
            (
                a,
                b
            ) =>
                a.source -
                    b.source ||
                a.target -
                    b.target
        );

    return {
        nodes:
            Array.from(
                nodes
            ).sort(
                (
                    a,
                    b
                ) =>
                    a -
                    b
            ),
        edges
    };
}

function dailyConnectionChildrenV55(
    edges
) {
    const map =
        new Map();

    edges.forEach(
        edge => {
            if (
                !map.has(
                    edge.source
                )
            ) {
                map.set(
                    edge.source,
                    []
                );
            }

            map.get(
                edge.source
            ).push(
                edge
            );
        }
    );

    map.forEach(
        list =>
            list.sort(
                (
                    a,
                    b
                ) =>
                    a.target -
                    b.target
            )
    );

    return map;
}

function renderConnectionTreeBranchV55(
    day,
    childMap,
    path =
        new Set()
) {
    const nextPath =
        new Set(
            path
        );

    nextPath.add(
        day
    );

    const children =
        childMap.get(
            day
        ) ||
        [];

    return `
        <li class="daily-connection-tree-node-v55">
            <button
                type="button"
                class="daily-connection-day-button-v55"
                data-open-day-v55="${day}"
            >
                Day ${day}
            </button>

            ${
                children.length
                    ? `
                        <ul>
                            ${children.map(
                                edge => {
                                    const cycle =
                                        nextPath.has(
                                            edge.target
                                        );

                                    return `
                                        <li class="daily-connection-tree-edge-v55">
                                            <span class="daily-connection-tree-label-v55">
                                                ${escapeCustomHtml(
                                                    edge.labels.join(
                                                        ' · '
                                                    ) ||
                                                    'Connected'
                                                )}
                                            </span>

                                            ${
                                                cycle
                                                    ? `
                                                        <button
                                                            type="button"
                                                            class="daily-connection-day-button-v55 cycle"
                                                            data-open-day-v55="${edge.target}"
                                                        >
                                                            Day ${edge.target}
                                                            <i class="ph ph-arrow-counter-clockwise"></i>
                                                        </button>
                                                    `
                                                    : renderConnectionTreeBranchV55(
                                                        edge.target,
                                                        childMap,
                                                        nextPath
                                                    )
                                            }
                                        </li>
                                    `;
                                }
                            ).join('')}
                        </ul>
                    `
                    : ''
            }
        </li>
    `;
}

function renderDailyConnectionsMapV55(
    tab,
    component,
    content
) {
    const {
        nodes,
        edges
    } =
        getDailyConnectionMapDataV55();

    if (
        !component.connectionViewV55
    ) {
        component.connectionViewV55 =
            'tree';
    }

    const view =
        component
            .connectionViewV55 ===
            'list'
            ? 'list'
            : 'tree';

    content.innerHTML = `
        <div class="custom-collection-header daily-connections-map-header-v55">
            <div>
                <h2>${escapeCustomHtml(
                    component.title ||
                    'Daily Log Connections Map'
                )}</h2>
                <small>
                    Automatically tracks @Day references in Daily Log notes.
                    ${edges.length} connection${edges.length === 1 ? '' : 's'}.
                </small>
            </div>

            <div class="daily-connections-view-toggle-v55">
                <button
                    type="button"
                    class="small-icon-btn ${view === 'tree' ? 'active' : ''}"
                    data-connection-view-v55="tree"
                    title="Tree view"
                >
                    <i class="ph ph-tree-structure"></i>
                </button>

                <button
                    type="button"
                    class="small-icon-btn ${view === 'list' ? 'active' : ''}"
                    data-connection-view-v55="list"
                    title="List view"
                >
                    <i class="ph ph-list-bullets"></i>
                </button>
            </div>
        </div>

        <div class="daily-connections-map-body-v55"></div>
    `;

    const body =
        content.querySelector(
            '.daily-connections-map-body-v55'
        );

    if (
        !edges.length
    ) {
        body.innerHTML = `
            <div class="feature-empty-state daily-connections-map-empty-v55">
                <i class="ph ph-share-network"></i>
                <strong>No @Day connections yet</strong>
                <span>
                    Type @ in Daily Log notes and link another Day. Those links will appear here automatically.
                </span>
            </div>
        `;
    } else if (
        view ===
        'list'
    ) {
        body.innerHTML = `
            <div class="daily-connections-list-view-v55">
                ${edges.map(
                    edge => `
                        <article class="daily-connection-list-row-v55">
                            <button
                                type="button"
                                class="daily-connection-day-button-v55"
                                data-open-day-v55="${edge.source}"
                            >
                                Day ${edge.source}
                            </button>

                            <span class="daily-connection-list-arrow-v55">
                                <i class="ph ph-arrow-right"></i>
                                <small>${escapeCustomHtml(
                                    edge.labels.join(
                                        ' · '
                                    ) ||
                                    'Connected'
                                )}</small>
                            </span>

                            <button
                                type="button"
                                class="daily-connection-day-button-v55"
                                data-open-day-v55="${edge.target}"
                            >
                                Day ${edge.target}
                            </button>
                        </article>
                    `
                ).join('')}
            </div>
        `;
    } else {
        const incoming =
            new Map();

        nodes.forEach(
            day =>
                incoming.set(
                    day,
                    0
                )
        );

        edges.forEach(
            edge =>
                incoming.set(
                    edge.target,
                    (
                        incoming.get(
                            edge.target
                        ) ||
                        0
                    ) +
                    1
                )
        );

        let roots =
            nodes.filter(
                day =>
                    (
                        incoming.get(
                            day
                        ) ||
                        0
                    ) ===
                    0
            );

        if (
            !roots.length &&
            nodes.length
        ) {
            roots = [
                nodes[0]
            ];
        }

        const childMap =
            dailyConnectionChildrenV55(
                edges
            );

        body.innerHTML = `
            <div class="daily-connections-tree-view-v55">
                <ul class="daily-connections-tree-root-v55">
                    ${roots.map(
                        day =>
                            renderConnectionTreeBranchV55(
                                day,
                                childMap
                            )
                    ).join('')}
                </ul>
            </div>
        `;
    }

    content
        .querySelectorAll(
            '[data-connection-view-v55]'
        )
        .forEach(
            button => {
                button.addEventListener(
                    'click',
                    () => {
                        component.connectionViewV55 =
                            button.dataset
                                .connectionViewV55;

                        saveDb();

                        renderCustomTabView(
                            tab.id
                        );
                    }
                );
            }
        );

    content
        .querySelectorAll(
            '[data-open-day-v55]'
        )
        .forEach(
            button => {
                button.addEventListener(
                    'click',
                    () =>
                        openDayLog(
                            Number(
                                button.dataset
                                    .openDayV55
                            )
                        )
                );
            }
        );
}

