const bindKnowledgeItemFieldBehaviorBeforeDropdownV55 =
    bindKnowledgeItemFieldBehavior;

bindKnowledgeItemFieldBehavior =
    function(
        container,
        categoryName,
        mode,
        itemId =
            null
    ) {
        bindKnowledgeItemFieldBehaviorBeforeDropdownV55(
            container,
            categoryName,
            mode,
            itemId
        );

        if (
            mode !==
                'edit' ||
            !itemId
        ) {
            return;
        }

        container
            ?.querySelectorAll(
                '.kb-select-field-v55.dynamic-edit-field'
            )
            .forEach(
                select => {
                    if (
                        select.dataset
                            .dropdownBoundV55 ===
                        'true'
                    ) {
                        return;
                    }

                    select.dataset
                        .dropdownBoundV55 =
                        'true';

                    select.addEventListener(
                        'change',
                        () => {
                            if (
                                !db.phrase_meta[
                                    itemId
                                ]
                                    .custom_fields
                            ) {
                                db.phrase_meta[
                                    itemId
                                ].custom_fields =
                                    {};
                            }

                            db.phrase_meta[
                                itemId
                            ].custom_fields[
                                select.dataset
                                    .key
                            ] =
                                select.value;

                            saveDb();
                        }
                    );
                }
            );
    };


// Replace the remaining native field-delete confirmation with the site's
// normal confirmation modal while this settings feature is being updated.
deleteKnowledgeField =
    async function(
        categoryName,
        fieldId
    ) {
        const config =
            getCategoryConfig(
                categoryName
            );

        const field =
            config.fields.find(
                entry =>
                    entry.id ===
                    fieldId
            );

        if (!field) {
            return;
        }

        const confirmed =
            await showAppConfirm({
                title:
                    `Delete “${field.name}” field?`,
                message:
                    'Existing saved values for this field will also be removed.',
                confirmLabel:
                    'Delete Field'
            });

        if (!confirmed) {
            return;
        }

        config.fields =
            config.fields.filter(
                entry =>
                    entry.id !==
                    fieldId
            );

        Object.values(
            db.phrase_meta ||
            {}
        ).forEach(
            meta => {
                if (
                    meta?.type ===
                        categoryName &&
                    meta.custom_fields &&
                    Object.prototype
                        .hasOwnProperty
                        .call(
                            meta.custom_fields,
                            field.name
                        )
                ) {
                    delete meta
                        .custom_fields[
                            field.name
                        ];
                }
            }
        );

        saveDb();

        renderSettings();
    };


// ------------------------------------------------------------
// PATTERN-BASED KNOWLEDGE BASE SENTENCE BUILDER
// ------------------------------------------------------------

const PATTERN_SLOT_REGEX_V55 =
    /(\{(?:VERB|NOUN|ADJECTIVE|ADJ|ADVERB|ADV|PRONOUN|PRON|PREPOSITION|PREP|V|N|A)\}|\[(?:VERB|NOUN|ADJECTIVE|ADJ|ADVERB|ADV|PRONOUN|PRON|PREPOSITION|PREP|V|N|A)\]|\b(?:VERB|NOUN|ADJECTIVE|ADJ|ADVERB|ADV|PRONOUN|PRON|PREPOSITION|PREP|V|N|A)\b)/g;

function patternSlotTagV55(
    token
) {
    const clean =
        String(
            token ||
            ''
        )
            .replace(
                /[\{\}\[\]]/g,
                ''
            )
            .toUpperCase();

    const map = {
        V:
            'verb',
        VERB:
            'verb',
        N:
            'noun',
        NOUN:
            'noun',
        A:
            'adjective',
        ADJ:
            'adjective',
        ADJECTIVE:
            'adjective',
        ADV:
            'adverb',
        ADVERB:
            'adverb',
        PRON:
            'pronoun',
        PRONOUN:
            'pronoun',
        PREP:
            'preposition',
        PREPOSITION:
            'preposition'
    };

    return map[
        clean
    ] ||
    normalizeKnowledgeTagV55(
        clean
    );
}

function patternTextForItemV55(
    itemId
) {
    const meta =
        db.phrase_meta?.[
            itemId
        ] ||
        {};

    const candidates = [
        itemId,
        ...Object.values(
            meta.custom_fields ||
            {}
        ).map(
            value =>
                String(
                    value ||
                    ''
                )
        )
    ];

    return candidates.find(
        value => {
            PATTERN_SLOT_REGEX_V55.lastIndex =
                0;

            return PATTERN_SLOT_REGEX_V55.test(
                value
            );
        }
    ) ||
    String(
        itemId ||
        ''
    );
}

function parsePatternSlotsV55(
    text
) {
    const slots =
        [];

    PATTERN_SLOT_REGEX_V55.lastIndex =
        0;

    String(
        text ||
        ''
    ).replace(
        PATTERN_SLOT_REGEX_V55,
        token => {
            slots.push({
                token,
                tag:
                    patternSlotTagV55(
                        token
                    )
            });

            return token;
        }
    );

    return slots;
}

function knowledgePatternItemsV55() {
    return (
        db.phrases ||
        []
    )
        .filter(
            itemId => {
                const meta =
                    db.phrase_meta?.[
                        itemId
                    ] ||
                    {};

                const category =
                    normalizeKnowledgeTagV55(
                        meta.type
                    );

                const tags =
                    getKnowledgeItemTagsV55(
                        itemId
                    );

                const text =
                    patternTextForItemV55(
                        itemId
                    );

                const slots =
                    parsePatternSlotsV55(
                        text
                    );

                return (
                    category.includes(
                        'pattern'
                    ) ||
                    tags.includes(
                        'pattern'
                    ) ||
                    slots.length >
                        0
                );
            }
        )
        .filter(
            itemId =>
                parsePatternSlotsV55(
                    patternTextForItemV55(
                        itemId
                    )
                ).length >
                0
        )
        .sort(
            (
                a,
                b
            ) =>
                a.localeCompare(
                    b
                )
        );
}

function itemsForPatternSlotV55(
    tag,
    query =
        '',
    patternId =
        ''
) {
    const parsed =
        parseKnowledgeSearchV55(
            query
        );

    const requiredTags =
        Array.from(
            new Set([
                normalizeKnowledgeTagV55(
                    tag
                ),
                ...parsed.tags
            ])
        ).filter(
            Boolean
        );

    const text =
        parsed.text
            .toLowerCase();

    return (
        db.phrases ||
        []
    )
        .filter(
            itemId =>
                itemId !==
                patternId
        )
        .filter(
            itemId => {
                const tags =
                    getKnowledgeItemTagsV55(
                        itemId
                    );

                if (
                    !requiredTags.every(
                        wanted =>
                            tags.includes(
                                wanted
                            )
                    )
                ) {
                    return false;
                }

                if (
                    !text
                ) {
                    return true;
                }

                const meta =
                    db.phrase_meta?.[
                        itemId
                    ] ||
                    {};

                const haystack =
                    `${itemId} ${Object.values(
                        meta.custom_fields ||
                        {}
                    ).join(' ')}`
                        .toLowerCase();

                return haystack.includes(
                    text
                );
            }
        )
        .slice(
            0,
            36
        );
}

function compilePatternSentenceV55(
    patternText,
    values
) {
    let index =
        0;

    PATTERN_SLOT_REGEX_V55.lastIndex =
        0;

    return String(
        patternText ||
        ''
    ).replace(
        PATTERN_SLOT_REGEX_V55,
        token => {
            const tag =
                patternSlotTagV55(
                    token
                );

            const value =
                values?.[
                    index
                ];

            index +=
                1;

            return value ||
                `[${tag}]`;
        }
    )
        .replace(
            /\s+([,.!?;:])/g,
            '$1'
        )
        .replace(
            /\s{2,}/g,
            ' '
        )
        .trim();
}

renderKnowledgeSentenceBuilderV53 =
    function(
        tab,
        component,
        content
    ) {
        if (
            !Array.isArray(
                component.savedSentences
            )
        ) {
            component.savedSentences =
                [];
        }

        if (
            !Array.isArray(
                component.slotValuesV55
            )
        ) {
            component.slotValuesV55 =
                [];
        }

        const patterns =
            knowledgePatternItemsV55();

        if (
            !patterns.length
        ) {
            content.innerHTML = `
                <div class="custom-collection-header">
                    <div>
                        <h2>${escapeCustomHtml(
                            component.title ||
                            'Sentence Builder'
                        )}</h2>
                        <small>
                            Pattern-based Knowledge Base sentence builder
                        </small>
                    </div>
                </div>

                <div class="feature-empty-state sentence-pattern-empty-v55">
                    <i class="ph ph-brackets-curly"></i>
                    <strong>No sentence patterns yet</strong>
                    <span>
                        Add a Knowledge Base category such as “Patterns”, then create items containing placeholders like V, N, or A. Tag your vocabulary #verb, #noun, #adjective, or use a dropdown field such as Part of Speech.
                    </span>
                </div>
            `;

            return;
        }

        if (
            !patterns.includes(
                component.patternIdV55
            )
        ) {
            component.patternIdV55 =
                patterns[0];

            component.slotValuesV55 =
                [];
        }

        const patternId =
            component
                .patternIdV55;

        const patternText =
            patternTextForItemV55(
                patternId
            );

        const slots =
            parsePatternSlotsV55(
                patternText
            );

        component.slotValuesV55 =
            Array.from(
                {
                    length:
                        slots.length
                },
                (
                    _,
                    index
                ) =>
                    component
                        .slotValuesV55[
                            index
                        ] ||
                    ''
            );

        const sentence =
            compilePatternSentenceV55(
                patternText,
                component
                    .slotValuesV55
            );

        content.innerHTML = `
            <div class="custom-collection-header">
                <div>
                    <h2>${escapeCustomHtml(
                        component.title ||
                        'Sentence Builder'
                    )}</h2>

                    <small>
                        Choose a pattern, then fill its tagged word slots.
                    </small>
                </div>
            </div>

            <div class="sentence-pattern-picker-v55">
                <label>
                    <span>Pattern</span>
                    <select class="sentence-pattern-select-v55">
                        ${patterns.map(
                            id => `
                                <option
                                    value="${escapeKnowledgeAttr(
                                        id
                                    )}"
                                    ${
                                        id ===
                                            patternId
                                            ? 'selected'
                                            : ''
                                    }
                                >
                                    ${escapeKnowledgeHtml(
                                        id
                                    )}
                                </option>
                            `
                        ).join('')}
                    </select>
                </label>

                <div class="sentence-pattern-template-v55">
                    ${escapeKnowledgeHtml(
                        patternText
                    )}
                </div>
            </div>

            <div class="sentence-pattern-slots-v55">
                ${slots.map(
                    (
                        slot,
                        index
                    ) => `
                        <section
                            class="sentence-pattern-slot-v55"
                            data-pattern-slot-index-v55="${index}"
                        >
                            <div class="sentence-pattern-slot-heading-v55">
                                <span class="sentence-pattern-slot-letter-v55">
                                    ${escapeKnowledgeHtml(
                                        slot.token
                                            .replace(
                                                /[\{\}\[\]]/g,
                                                ''
                                            )
                                    )}
                                </span>

                                <div>
                                    <strong>
                                        ${escapeKnowledgeHtml(
                                            slot.tag
                                                .charAt(
                                                    0
                                                )
                                                .toUpperCase() +
                                            slot.tag
                                                .slice(
                                                    1
                                                )
                                        )}
                                    </strong>

                                    <small>
                                        #${escapeKnowledgeHtml(
                                            slot.tag
                                        )}
                                    </small>
                                </div>

                                ${
                                    component
                                        .slotValuesV55[
                                            index
                                        ]
                                        ? `
                                            <button
                                                type="button"
                                                class="small-icon-btn sentence-pattern-clear-slot-v55"
                                                title="Clear slot"
                                            >
                                                <i class="ph ph-x"></i>
                                            </button>
                                        `
                                        : ''
                                }
                            </div>

                            <div class="sentence-pattern-slot-value-v55">
                                ${
                                    component
                                        .slotValuesV55[
                                            index
                                        ]
                                        ? escapeKnowledgeHtml(
                                            component
                                                .slotValuesV55[
                                                    index
                                                ]
                                        )
                                        : `Choose a ${escapeKnowledgeHtml(
                                            slot.tag
                                        )}`
                                }
                            </div>

                            <div class="sentence-pattern-search-v55">
                                <i class="ph ph-magnifying-glass"></i>
                                <input
                                    type="text"
                                    placeholder="Search #${escapeKnowledgeAttr(
                                        slot.tag
                                    )}…"
                                >
                            </div>

                            <div class="sentence-pattern-results-v55"></div>
                        </section>
                    `
                ).join('')}
            </div>

            <div class="sentence-pattern-output-v55">
                <span>Sentence</span>
                <strong class="sentence-pattern-output-text-v55">
                    ${escapeKnowledgeHtml(
                        sentence
                    )}
                </strong>

                <button
                    type="button"
                    class="icon-btn sentence-pattern-save-v55"
                >
                    Save Sentence
                </button>
            </div>

            <div class="sentence-builder-saved-wrap-v53">
                <div class="custom-collection-header">
                    <h3>Saved Sentences</h3>
                </div>

                <div class="sentence-builder-saved-v53">
                    ${
                        component
                            .savedSentences
                            .length
                            ? component
                                .savedSentences
                                .map(
                                    item => `
                                        <article
                                            class="sentence-builder-saved-item-v53"
                                            data-saved-pattern-sentence-v55="${escapeKnowledgeAttr(
                                                item.id
                                            )}"
                                        >
                                            <span>
                                                ${escapeKnowledgeHtml(
                                                    item.text
                                                )}
                                            </span>

                                            <button
                                                type="button"
                                                class="small-icon-btn sentence-pattern-remove-saved-v55"
                                                title="Remove"
                                            >
                                                <i class="ph ph-x"></i>
                                            </button>
                                        </article>
                                    `
                                )
                                .join('')
                            : `
                                <div class="sentence-builder-empty-saved-v53">
                                    Saved sentences will appear here.
                                </div>
                            `
                    }
                </div>
            </div>
        `;

        const rerender =
            () => {
                saveDb();

                renderCustomTabView(
                    tab.id
                );
            };

        content
            .querySelector(
                '.sentence-pattern-select-v55'
            )
            ?.addEventListener(
                'change',
                event => {
                    component.patternIdV55 =
                        event.target
                            .value;

                    component.slotValuesV55 =
                        [];

                    rerender();
                }
            );

        content
            .querySelectorAll(
                '[data-pattern-slot-index-v55]'
            )
            .forEach(
                section => {
                    const index =
                        Number(
                            section.dataset
                                .patternSlotIndexV55
                        );

                    const slot =
                        slots[
                            index
                        ];

                    const search =
                        section.querySelector(
                            '.sentence-pattern-search-v55 input'
                        );

                    const results =
                        section.querySelector(
                            '.sentence-pattern-results-v55'
                        );

                    const renderResults =
                        () => {
                            const items =
                                itemsForPatternSlotV55(
                                    slot.tag,
                                    search.value,
                                    patternId
                                );

                            results.innerHTML =
                                items.length
                                    ? items.map(
                                        itemId => `
                                            <button
                                                type="button"
                                                data-pattern-choice-v55="${escapeKnowledgeAttr(
                                                    itemId
                                                )}"
                                            >
                                                <span>
                                                    ${escapeKnowledgeHtml(
                                                        itemId
                                                    )}
                                                </span>

                                                <small>
                                                    ${getKnowledgeItemTagsV55(
                                                        itemId
                                                    )
                                                        .filter(
                                                            tag =>
                                                                tag !==
                                                                normalizeKnowledgeTagV55(
                                                                    db
                                                                        .phrase_meta?.[
                                                                            itemId
                                                                        ]?.type
                                                                )
                                                        )
                                                        .slice(
                                                            0,
                                                            3
                                                        )
                                                        .map(
                                                            tag =>
                                                                `#${escapeKnowledgeHtml(
                                                                    tag
                                                                )}`
                                                        )
                                                        .join(
                                                            ' '
                                                        )}
                                                </small>
                                            </button>
                                        `
                                    ).join('')
                                    : `
                                        <div class="sentence-pattern-no-results-v55">
                                            No #${escapeKnowledgeHtml(
                                                slot.tag
                                            )} items match.
                                        </div>
                                    `;

                            results
                                .querySelectorAll(
                                    '[data-pattern-choice-v55]'
                                )
                                .forEach(
                                    button => {
                                        button.addEventListener(
                                            'click',
                                            () => {
                                                component
                                                    .slotValuesV55[
                                                        index
                                                    ] =
                                                    button.dataset
                                                        .patternChoiceV55;

                                                rerender();
                                            }
                                        );
                                    }
                                );
                        };

                    search.addEventListener(
                        'input',
                        renderResults
                    );

                    section
                        .querySelector(
                            '.sentence-pattern-clear-slot-v55'
                        )
                        ?.addEventListener(
                            'click',
                            () => {
                                component
                                    .slotValuesV55[
                                        index
                                    ] =
                                    '';

                                rerender();
                            }
                        );

                    renderResults();
                }
            );

        content
            .querySelector(
                '.sentence-pattern-save-v55'
            )
            ?.addEventListener(
                'click',
                () => {
                    const complete =
                        slots.every(
                            (
                                _,
                                index
                            ) =>
                                !!component
                                    .slotValuesV55[
                                        index
                                    ]
                        );

                    if (!complete) {
                        showFeatureToast(
                            'Fill every pattern slot first.'
                        );

                        return;
                    }

                    component
                        .savedSentences
                        .unshift({
                            id:
                                customId(
                                    'sentence'
                                ),
                            text:
                                compilePatternSentenceV55(
                                    patternText,
                                    component
                                        .slotValuesV55
                                ),
                            patternId,
                            createdAt:
                                new Date()
                                    .toISOString()
                        });

                    rerender();
                }
            );

        content
            .querySelectorAll(
                '[data-saved-pattern-sentence-v55]'
            )
            .forEach(
                row => {
                    row
                        .querySelector(
                            '.sentence-pattern-remove-saved-v55'
                        )
                        ?.addEventListener(
                            'click',
                            () => {
                                const id =
                                    row.dataset
                                        .savedPatternSentenceV55;

                                component.savedSentences =
                                    component
                                        .savedSentences
                                        .filter(
                                            item =>
                                                item.id !==
                                                id
                                        );

                                rerender();
                            }
                        );
                }
            );
    };


