// ------------------------------------------------------------
// 3) PER-COMPONENT SOFT BACKDROP TOGGLE.
// Icon sits directly beside the pencil while editing the component.
// ------------------------------------------------------------

function applyComponentBackdropStateV61(
    tab,
    canvas
) {
    if (
        !tab ||
        !canvas
    ) {
        return;
    }

    canvas
        .querySelectorAll(
            '.custom-tab-component'
        )
        .forEach(
            wrapper => {
                const component =
                    (
                        tab.components ||
                        []
                    ).find(
                        item =>
                            item.id ===
                            wrapper.dataset
                                .componentId
                    );

                wrapper.classList.toggle(
                    'keep-component-backdrop-v61',
                    !!component
                        ?.keepBackdropV61
                );

                const controls =
                    wrapper.querySelector(
                        '.custom-component-controls'
                    );

                if (
                    !controls ||
                    !customTabEditMode
                ) {
                    return;
                }

                controls
                    .querySelector(
                        '.custom-component-title-style'
                    )
                    ?.remove();

                let toggle =
                    controls.querySelector(
                        '.custom-component-backdrop-toggle-v61'
                    );

                if (!toggle) {
                    toggle =
                        document.createElement(
                            'button'
                        );

                    toggle.type =
                        'button';

                    toggle.className =
                        'custom-component-backdrop-toggle-v61';

                    toggle.title =
                        'Keep this component background outside edit mode';

                    toggle.setAttribute(
                        'aria-label',
                        'Toggle persistent component background'
                    );

                    toggle.innerHTML =
                        '<i class="ph ph-square-half"></i>';

                    const edit =
                        controls.querySelector(
                            '.custom-component-edit'
                        );

                    if (edit) {
                        edit.insertAdjacentElement(
                            'afterend',
                            toggle
                        );
                    } else {
                        controls.prepend(
                            toggle
                        );
                    }

                    toggle.addEventListener(
                        'click',
                        event => {
                            event.preventDefault();
                            event.stopPropagation();

                            const currentTab =
                                getCustomTab(
                                    tab.id
                                );

                            const currentComponent =
                                currentTab
                                    ?.components
                                    ?.find(
                                        item =>
                                            item.id ===
                                            wrapper.dataset
                                                .componentId
                                    );

                            if (
                                !currentComponent
                            ) {
                                return;
                            }

                            currentComponent
                                .keepBackdropV61 =
                                !currentComponent
                                    .keepBackdropV61;

                            saveDb();

                            renderCustomTabView(
                                tab.id
                            );
                        }
                    );
                }

                toggle.classList.toggle(
                    'active',
                    !!component
                        ?.keepBackdropV61
                );
            }
        );
}

