// ------------------------------------------------------------
// 8) THEME BUILDER ARTWORK PREVIEW — RENDER INSIDE THE REAL PAGE,
// BEHIND COMPONENTS, WITH THE SAME MOTION SHELL + BOP CLASSES.
// ------------------------------------------------------------

function renderThemeArtworkPreviewV61(
    modal
) {
    if (!modal) {
        return;
    }

    const canvas =
        modal.querySelector(
            '.theme-builder-live-canvas'
        );

    if (!canvas) {
        return;
    }

    const dashboard =
        modal.querySelector(
            '.theme-builder-dashboard-preview-v45'
        );

    if (
        dashboard &&
        !dashboard.classList.contains(
            'hidden'
        )
    ) {
        normalizeDashboardArtworkLayerV60?.(
            modal
        );

        return;
    }

    const page =
        canvas.querySelector(
            '.theme-builder-live-page'
        );

    if (!page) {
        return;
    }

    page
        .querySelectorAll(
            '.theme-builder-live-art-stage-v61'
        )
        .forEach(
            node =>
                node.remove()
        );

    canvas
        .querySelectorAll(
            ':scope > .theme-builder-live-art-stage-v59, :scope > .theme-builder-live-art-stage-v60'
        )
        .forEach(
            node =>
                node.remove()
        );

    const assets =
        Array.isArray(
            modal._themeBackgroundSvgs
        )
            ? modal._themeBackgroundSvgs
            : [];

    if (!assets.length) {
        return;
    }

    const draft =
        getThemeBuilderDraft(
            modal
        );

    let assignments =
        [];

    try {
        assignments =
            getPreviewSvgAssignmentsV10(
                modal,
                draft
            ) ||
            [];
    } catch {}

    const stage =
        document.createElement(
            'div'
        );

    stage.className =
        'theme-builder-live-art-stage theme-svg-effects-stage-v10 theme-builder-live-art-stage-v61';

    const maxPreview =
        Math.min(
            24,
            assets.length
        );

    for (
        let index =
            0;
        index <
            maxPreview;
        index++
    ) {
        const assignment =
            assignments.find(
                item =>
                    Number(
                        item.originalIndex
                    ) ===
                    index
            ) ||
            assignments[index] ||
            {};

        const rawAsset =
            assignment.svg ||
            assets[index];

        const asset =
            ensureSvgAdvancedDefaultsV10(
                rawAsset
            );

        if (!asset) {
            continue;
        }

        const item =
            document.createElement(
                'div'
            );

        item.className =
            `theme-builder-live-art-item theme-svg-anim-${asset.animation || 'float'}`;

        item.dataset.svgIndex =
            String(
                index
            );

        item.style.left =
            `${
                Number.isFinite(
                    Number(
                        assignment.left
                    )
                )
                    ? Number(
                        assignment.left
                    )
                    : 8 +
                        (
                            index *
                            29
                        ) %
                        84
            }%`;

        item.style.top =
            `${
                Number.isFinite(
                    Number(
                        assignment.top
                    )
                )
                    ? Number(
                        assignment.top
                    )
                    : 10 +
                        (
                            index *
                            41
                        ) %
                        78
            }%`;

        item.style
            .setProperty(
                '--theme-svg-delay',
                `${(index % 13) * -0.41}s`
            );

        item.innerHTML = `
            <div class="theme-svg-motion-shell theme-image-motion-shell-v36">
                ${renderThemeImageAssetV36(
                    asset
                )}
            </div>
        `;

        item
            .querySelectorAll(
                'img'
            )
            .forEach(
                image => {
                    image.loading =
                        'eager';

                    image.decoding =
                        'async';
                }
            );

        stage.appendChild(
            item
        );
    }

    page.style
        .setProperty(
            'background-color',
            'transparent',
            'important'
        );

    page.style
        .setProperty(
            'background-image',
            'none',
            'important'
        );

    page.prepend(
        stage
    );

    applyAutomaticIntroBoppersV60(
        stage,
        assets,
        draft.introSvgBopMode ||
        'some'
    );

    if (
        draft.introSvgBounceEnabled
    ) {
        stage.classList.add(
            'theme-svg-intro-bop-enabled'
        );
    }
}

