// The V60 bop helper now recognizes Dashboard-preview artwork too.
const applyAutomaticIntroBoppersBeforeDashboardV63 =
    applyAutomaticIntroBoppersV60;

applyAutomaticIntroBoppersV60 =
    function(
        stage,
        assets =
            [],
        mode =
            'some'
    ) {
        if (!stage) {
            return;
        }

        const items =
            Array.from(
                stage.querySelectorAll(
                    [
                        '.theme-builder-live-art-item',
                        '.custom-theme-background-svg',
                        '.theme-builder-dashboard-art-item-v40'
                    ].join(',')
                )
            );

        stage.classList.toggle(
            'theme-svg-intro-bop-all',
            mode ===
                'all'
        );

        const auto =
            [];

        const forced =
            [];

        items.forEach(
            (
                item,
                displayIndex
            ) => {
                item.classList.remove(
                    'theme-svg-intro-bop-selected'
                );

                item.removeAttribute(
                    'data-auto-intro-bop'
                );

                const sourceIndex =
                    Number(
                        item.dataset
                            .svgIndex
                    );

                const asset =
                    assets?.[
                        Number.isFinite(
                            sourceIndex
                        )
                            ? sourceIndex
                            : displayIndex
                    ] ||
                    assets?.[
                        displayIndex
                    ] ||
                    {};

                const preference =
                    String(
                        asset.bopModeV60 ||
                        'auto'
                    );

                if (
                    asset.hiddenOnScreenV63 ===
                    true ||
                    preference ===
                    'never'
                ) {
                    return;
                }

                if (
                    preference ===
                    'always'
                ) {
                    forced.push(
                        item
                    );

                    return;
                }

                auto.push(
                    item
                );
            }
        );

        forced.forEach(
            item => {
                item.classList.add(
                    'theme-svg-intro-bop-selected'
                );

                item.dataset.autoIntroBop =
                    'forced';
            }
        );

        const autoSelected =
            mode ===
                'all'
                ? auto
                : chooseSpreadSvgBoppersV23(
                    auto
                );

        autoSelected.forEach(
            item => {
                item.classList.add(
                    'theme-svg-intro-bop-selected'
                );

                item.dataset.autoIntroBop =
                    'true';
            }
        );
    };


