function prepareThemeBackdropControlsV63(
    modal
) {
    if (
        !modal ||
        modal.dataset
            .backdropDefaultsV63 ===
            'true'
    ) {
        return;
    }

    modal.dataset
        .backdropDefaultsV63 =
        'true';

    [
        [
            '.theme-builder-daily-backdrop-enabled',
            '.theme-builder-daily-backdrop-opacity',
            'dailyLogBackgroundColor'
        ],
        [
            '.theme-builder-other-backdrop-enabled',
            '.theme-builder-other-backdrop-opacity',
            'contentBackdropColor'
        ]
    ].forEach(
        (
            [
                toggleSelector,
                opacitySelector,
                colorKey
            ]
        ) => {
            const toggle =
                modal.querySelector(
                    toggleSelector
                );

            if (!toggle) {
                return;
            }

            toggle.addEventListener(
                'change',
                () => {
                    if (!toggle.checked) {
                        return;
                    }

                    const opacity =
                        modal.querySelector(
                            opacitySelector
                        );

                    if (
                        opacity &&
                        Number(
                            opacity.value
                        ) <=
                            0
                    ) {
                        opacity.value =
                            '90';

                        opacity.dispatchEvent(
                            new Event(
                                'input',
                                {
                                    bubbles:
                                        true
                                }
                            )
                        );
                    }

                    const color =
                        modal.querySelector(
                            `[data-theme-key="${colorKey}"]`
                        );

                    if (
                        color &&
                        !String(
                            color.value ||
                            ''
                        ).trim()
                    ) {
                        color.value =
                            modal.querySelector(
                                '[data-theme-key="surface"]'
                            )?.value ||
                            '#ffffff';
                    }

                    updateThemeBuilderPreview(
                        modal
                    );
                }
            );
        }
    );
}


function applyThemeBackdropPreviewV63(
    modal
) {
    const canvas =
        modal?.querySelector(
            '.theme-builder-live-canvas'
        );

    const page =
        canvas?.querySelector(
            '.theme-builder-live-page'
        );

    if (
        !canvas ||
        !page
    ) {
        return;
    }

    const draft =
        getThemeBuilderDraft(
            modal
        );

    const sourceId =
        canvas.dataset
            .previewSourceId ||
        page.dataset
            .previewOriginalId ||
        '';

    const isDaily =
        sourceId ===
            'grid-view' ||
        sourceId ===
            'log-view';

    const enabled =
        isDaily
            ? !!draft
                .dailyLogBackgroundEnabled
            : !!draft
                .contentBackdropEnabled;

    const color =
        isDaily
            ? (
                draft
                    .dailyLogBackgroundColor ||
                draft.surface ||
                '#ffffff'
            )
            : (
                draft
                    .contentBackdropColor ||
                draft.surface ||
                '#ffffff'
            );

    const opacity =
        Math.max(
            0,
            Math.min(
                100,
                Number(
                    isDaily
                        ? draft
                            .dailyLogBackgroundOpacity
                        : draft
                            .contentBackdropOpacity
                ) ||
                0
            )
        );

    page.style
        .setProperty(
            'background',
            enabled
                ? hexToRgbaV4(
                    color,
                    opacity /
                        100
                )
                : 'transparent',
            'important'
        );

    page.style
        .setProperty(
            'background-color',
            enabled
                ? hexToRgbaV4(
                    color,
                    opacity /
                        100
                )
                : 'transparent',
            'important'
        );

    page.style
        .setProperty(
            'border-radius',
            `${Math.max(
                0,
                Number(
                    draft.radius
                ) ||
                0
            )}px`,
            'important'
        );

    page.style
        .setProperty(
            'padding',
            enabled
                ? '18px'
                : '0px',
            'important'
        );
}


