// ------------------------------------------------------------
// PREVIEW BACKDROP: USE THE EXACT SAME color-mix() EXPRESSION AS RUNTIME.
// No separate rgba conversion, so preview and real page composite identically.
// ------------------------------------------------------------

function applyThemeBackdropPreviewV65(
    modal
) {
    const canvas =
        modal?.querySelector(
            '.theme-builder-live-canvas'
        );

    const page =
        canvas?.querySelector(
            '.theme-builder-live-page'
        );

    if (
        !canvas ||
        !page
    ) {
        return;
    }

    const draft =
        getThemeBuilderDraft(
            modal
        );

    const sourceId =
        canvas.dataset
            .previewSourceId ||
        page.dataset
            .previewOriginalId ||
        '';

    const isDaily =
        sourceId ===
            'grid-view' ||
        sourceId ===
            'log-view';

    const enabled =
        isDaily
            ? !!draft
                .dailyLogBackgroundEnabled
            : !!draft
                .contentBackdropEnabled;

    const color =
        isDaily
            ? (
                draft
                    .dailyLogBackgroundColor ||
                draft.surface ||
                '#ffffff'
            )
            : (
                draft
                    .contentBackdropColor ||
                draft.surface ||
                '#ffffff'
            );

    const opacity =
        Math.max(
            0,
            Math.min(
                100,
                Number(
                    isDaily
                        ? draft
                            .dailyLogBackgroundOpacity
                        : draft
                            .contentBackdropOpacity
                ) ||
                0
            )
        );

    const runtimeBackground =
        enabled
            ? `color-mix(in srgb, ${color} ${opacity}%, transparent)`
            : 'transparent';

    // Clear all previous preview backdrop declarations first so there
    // cannot be a doubled/darker background from an earlier preview pass.
    page.style
        .removeProperty(
            'background'
        );

    page.style
        .removeProperty(
            'background-color'
        );

    page.style
        .removeProperty(
            'background-image'
        );

    page.style
        .setProperty(
            'background',
            runtimeBackground,
            'important'
        );

    page.style
        .setProperty(
            'background-image',
            'none',
            'important'
        );

    page.style
        .setProperty(
            'border-radius',
            `${Math.max(
                0,
                Number(
                    draft.radius
                ) ||
                0
            )}px`,
            'important'
        );

    page.style
        .setProperty(
            'padding',
            enabled
                ? '18px'
                : '0px',
            'important'
        );

    page.dataset
        .backdropPreviewV65 =
        isDaily
            ? 'daily'
            : 'other';
}


