// ------------------------------------------------------------
// 2) Daily Logs and Quizzes are fixed viewport pages.
// The browser/body never becomes their scroll container.
// ------------------------------------------------------------

function syncFixedViewportPageV67(
    view =
        null
) {
    const current =
        view ||
        document.querySelector(
            '.view.active'
        );

    const lock =
        current ===
            gridView ||
        current ===
            quizzesView;

    document.body.classList.toggle(
        'fixed-viewport-page-v67',
        lock
    );

    document.documentElement.classList.toggle(
        'fixed-viewport-page-v67',
        lock
    );

    if (
        current ===
        gridView
    ) {
        const days =
            document.getElementById(
                'days-grid'
            );

        if (days) {
            const rect =
                days.getBoundingClientRect();

            const available =
                Math.max(
                    160,
                    Math.floor(
                        window.innerHeight -
                        rect.top -
                        20
                    )
                );

            days.style
                .setProperty(
                    '--daily-days-scroll-height-v67',
                    `${available}px`
                );
        }
    }

    if (
        current ===
        quizzesView
    ) {
        const extra =
            document.getElementById(
                'quiz-extra-practice-host-v59'
            );

        if (extra) {
            const rect =
                extra.getBoundingClientRect();

            const available =
                Math.max(
                    120,
                    Math.floor(
                        window.innerHeight -
                        rect.top -
                        18
                    )
                );

            extra.style
                .setProperty(
                    '--quiz-extra-scroll-height-v67',
                    `${available}px`
                );
        }
    }
}


