                    // has had a chance to paint.
                    requestAnimationFrame(() => {
                        const live = document.getElementById('theme-builder-modal') || modal;
                        try { forceGalleryV126?.(live); } catch {}
                        try { updateThemeBuilderPreview(live); } catch {}
                    });
